(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,462036,(a,n,e)=>{n.exports=JSON.parse('{"nameplate.???":"???","nameplate.Dark Figure":"Sosok Gelap","nameplate.Eerie Voice":"Suara Seram","nameplate.Elder Grah":"Elder Grah","nameplate.Eriole":"Eriole","nameplate.Grahdens":"Grahdens","nameplate.Kar & Seria":"Kar & Seria","nameplate.Karl":"Karl","nameplate.Lin":"Lin","nameplate.Lugina":"Lugina","nameplate.Man\'s Voice":"Suara Pria","nameplate.Mare":"Mare","nameplate.Mysterious Man":"Pria Misterius","nameplate.Mysterious Woman":"Wanita Misterius","nameplate.Paris":"Paris","nameplate.Seria":"Seria","nameplate.Seria & Karl":"Seria & Karl","nameplate.Seria & Lugina":"Seria & Lugina","nameplate.Seria・Lugina":"Seria・Lugina","nameplate.Tilith":"Tilith","nameplate.Tilith & Seria":"Tilith & Seria","nameplate.Woman\'s Voice":"Suara Wanita","nameplate.Zebra":"Zebra","nameplate.静かな男の声":"Suara Pria yang Tenang","story.map1-dungeon0-1end.001":"Sekarang kamu bisa mendapatkan material dari <color=00FF00>Ladang</color> di Village of the Venturer!","story.map1-dungeon0-2end.001":"Sekarang kamu bisa mendapatkan material dari <color=00FF00>Gunung</color> di Village of the Venturer!","story.map1-dungeon0-3end.001":"Sekarang kamu bisa mengakses <color=00FF00>Rumah Sphere</color> di Village of the Venturer!","story.map1-dungeon0-3end.002":"Di Rumah Sphere, kamu bisa memakai Material untuk menempa <color=00FFFF>Sphere</color> yang bisa dipasang pada Unit-mu.","story.map1-dungeon0-3end.003":"Tempa Sphere yang kuat untuk meningkatkan kekuatan Unit-mu!","story.map1-dungeon1.001":"<size=13>Panas banget! <wait=40>Aku mau pulang! <wait=40>Nggak tahan lagi...","story.map1-dungeon1.002":"<size=20>Oh! <wait=20><rep_handlename>!","story.map1-dungeon1.003":"Hei, kamu telat! <wait=40>Dari mana saja kamu?!","story.map1-dungeon1.004":"Teganya kamu membuatku menunggu di gua sepanas ini!","story.map1-dungeon1.005":"Aku mulai khawatir soal perjalanan kita...","story.map1-dungeon1.006":"Yah, <wait=40>aku sudah janji akan menjelaskan apa yang sebenarnya terjadi...","story.map1-dungeon1.007":"Ini serius, jadi dengarkan baik-baik, ya?","story.map1-dungeon1.008":"Grand Gaia sedang dilanda krisis besar...","story.map1-dungeon1.009":"Penyebabnya, di antara para dewa perkasa yang menjaga kita, ada yang telah dikuasai kejahatan.","story.map1-dungeon1.010":"Mereka menentang Kaisar Suci Karna Masta, <wait=19>dan kini membuat kekacauan.","story.map1-dungeon1.011":"Di antara kekuatan jahat itu, <wait=40>beberapa yang memiliki kekuatan paling luar biasa dikenal sebagai...","story.map1-dungeon1.012":".<wait=10>.<wait=10>.<wait=10>Empat Dewa yang Jatuh.","story.map1-dungeon1.013":"Dulu mereka adalah dewa-dewa berpangkat tinggi...","story.map1-dungeon1.014":"...<wait=20>Tapi sekarang mereka berusaha merebut Grand Gaia untuk diri mereka sendiri.","story.map1-dungeon1.015":"Empat Dewa yang Jatuh tidak hanya menjadikan monster dan roh sebagai bawahan mereka,","story.map1-dungeon1.016":"...mereka juga memakai kekuatannya untuk memanggil dan mengendalikan para pahlawan legendaris Grand Gaia.","story.map1-dungeon1.017":"Kalau kita tidak menghentikan mereka, <wait=40>Grand Gaia akan hancur...","story.map1-dungeon1.018":"Bahkan Kaisar Suci Karna Masta bersama para dewa lainnya...","story.map1-dungeon1.019":"...<wait=20>hanya bisa menahan mereka untuk sementara.","story.map1-dungeon1.020":"Karena itulah Lord Lucius membuka Gerbang menuju dunia ini.","story.map1-dungeon1.021":"Beliau ingin meminjam kekuatanmu.","story.map1-dungeon1.022":"Itulah sebabnya hanya orang-orang terpilih yang bisa melihat gerbang itu.","story.map1-dungeon1.023":"Lord Lucius menaruh harapan besar padamu.","story.map1-dungeon1.024":"Jadi jangan kecewakan kami, ya, <wait=20><rep_handlename>!","story.map1-dungeon1.025":"Nah, <wait=40>target pertamamu adalah salah satu dari Empat Dewa yang Jatuh...","story.map1-dungeon1.026":"Dewi Penciptaan, <wait=20>Maxwell!","story.map1-dungeon1.027":"Maxwell <wait=20>telah merebut St. Lamia. Dulu tanah suci, kini menjadi bentengnya.","story.map1-dungeon1.028":"Dari tempat kita di Mistral, <wait=40>kamu harus pergi melewati Morgan untuk sampai ke sana.","story.map1-dungeon1.029":"Perjalanannya cukup jauh, <wait=40>tapi aku yakin kamu pasti bisa!","story.map1-dungeon1.030":"Kita jalani pelan-pelan sampai kamu terbiasa menjadi Summoner!","story.map1-dungeon1.031":"Pertama, untuk sampai ke Morgan kita harus menuju Menara Mistral.","story.map1-dungeon1.032":"Untuk itu, <wait=20>kita harus melewati Gua Api.","story.map1-dungeon1.033":"Konon, <wait=20>gua ini dipenuhi binatang buas yang ganas.","story.map1-dungeon1.034":"Tapi tetap saja, <wait=20>kamu pasti baik-baik saja!","story.map1-dungeon1.035":"<size=20>Argh! <wait=40>Aku nggak tahan lagi sama panas ini!","story.map1-dungeon1.036":"Aku mau pulang dulu buat mandi. Hati-hati, ya, kamu duluan saja!","story.map1-dungeon2.001":"...Brr <wait=60><size=24>...Brr!","story.map1-dungeon2.002":"<size=36>Hacyih!!","story.map1-dungeon2.003":"...Aduh,<wait=30> dingin sekali!","story.map1-dungeon2.004":"Hei! <wait=40>Berani-beraninya kamu membuat seorang gadis menunggu di tempat sedingin ini!","story.map1-dungeon2.005":"Brr... <wait=30>dingin banget!!","story.map1-dungeon2.006":"Jadi, <wait=20>untuk sampai ke Menara Mistral <wait=40>kamu harus menyeberangi Padang Salju Egor lalu melewati hutan...","story.map1-dungeon2.007":"Lalu melewati rawa, <wait=30>kemudian melewati reruntuhan...","story.map1-dungeon2.008":"Membayangkannya saja sudah terasa jauh, <wait=40>apalagi kalau memikirkan cuacanya yang bisa sangat ekstrem!","story.map1-dungeon2.009":"Pokoknya, <wait=20>perjalananmu ke menara masih panjang.","story.map1-dungeon2.010":"Tapi hati-hati. <wait=20>Musuh makin kuat semakin dekat kamu ke sana.","story.map1-dungeon2.011":"Kalau kamu bertemu musuh yang tak bisa kamu kalahkan, <wait=20>sebaiknya kembali ke dungeon sebelumnya dan berlatih sedikit.","story.map1-dungeon2.012":"Oh iya, <wait=20>sudah waktunya kamu mengatur Squad-mu dengan memperhatikan elemen mereka.","story.map1-dungeon2.013":"Kebanyakan musuh di gua itu berelemen api, jadi Squad berisi Unit elemen air akan sangat menguntungkan!","story.map1-dungeon2.014":"Kali ini kita ada di padang salju. <wait=40>Sepertinya kita akan banyak bertemu musuh berelemen air.","story.map1-dungeon2.015":"Jadi... <wait=20>kuis dadakan! <wait=40>Elemen apa yang kuat melawan air?","story.map1-dungeon2.016":"Ya, <wait=40>benar sekali!","story.map1-dungeon2.017":"Sepertinya kamu sudah belajar. <wait=40>Yap, petir mengalahkan air.","story.map1-dungeon2.018":"Sebaliknya, Unit elemen api akan dirugikan melawan musuh dari padang salju, jadi hati-hati.","story.map1-dungeon2.019":"...Brr <wait=60><size=24>...Brr!","story.map1-dungeon2.020":"<size=36>Hacyih!!","story.map1-dungeon2.021":"Ya ampun, <wait=20>aku nggak tahan lagi. <wait=40>Aku pulang!","story.map1-dungeon2.022":"...Ah, <wait=20>hampir saja lupa.","story.map1-dungeon2.023":"Sepertinya seorang ksatria yang dipanggil Maxwell sedang membuat kekacauan di dekat ujung padang salju ini.","story.map1-dungeon2.024":"Dia kelihatannya cukup kuat. Hati-hati!","story.map1-dungeon3.001":"Oh, <wait=20><rep_handlename>! <wait=40>Hebat, kamu berhasil menyeberangi padang salju itu.","story.map1-dungeon3.002":"Hmm, <wait=40>harus kuakui kamu terlihat lebih berwibawa sekarang dibanding saat pertama kita bertemu.","story.map1-dungeon3.003":"Baiklah, <wait=20>saatnya menerobos Hutan Buas!","story.map1-dungeon3.004":"Sesuai namanya, hutan ini dipenuhi binatang liar...","story.map1-dungeon3.005":"Tapi musuhmu yang sebenarnya <wait=20>adalah sosok yang berkeliaran memburu mereka.","story.map1-dungeon3.006":"Oh, <wait=40>kamu sudah memasang Sphere?","story.map1-dungeon3.007":"Kamu bisa meningkatkan kemampuan Unit-mu dengan memasang Sphere pada mereka.","story.map1-dungeon3.008":"Sebagai Summoner, kamu wajib tahu ini kalau mau bertahan lama.","story.map1-dungeon3.009":"Sphere bisa ditempa di Rumah Sphere di duniamu.","story.map1-dungeon3.010":"Pasang Sphere pada Unit-mu untuk membentuk Squad yang lebih kuat!","story.map1-dungeon3.011":"Membuat Sphere butuh material tertentu yang harus kamu kumpulkan dulu.","story.map1-dungeon3.012":"Yah, pokoknya, <wait=20>semoga berhasil dan bertarunglah sekuat tenaga!<br>","story.map1-dungeon4.001":"<size=18>Argh, <wait=20>ini mengerikan!! Kenapa lembapnya parah begini?!","story.map1-dungeon4.002":"Rambut dan bajuku jadi lengket dan menjijikkan!!","story.map1-dungeon4.003":"Ah... <wait=20><rep_handlename>.","story.map1-dungeon4.004":"Kamu berhasil melewati hutan. Setidaknya aku tidak sia-sia mengajarimu.","story.map1-dungeon4.005":"Oh, <wait=20>benar juga. <wait=40>Kamu sudah memanfaatkan Spark dengan baik?","story.map1-dungeon4.006":"Saat Unit-mu menyerang bersamaan dan menghasilkan Spark, damage yang kamu berikan meningkat drastis.","story.map1-dungeon4.007":"Ini teknik yang sangat penting. Terutama berguna melawan musuh yang sulit.","story.map1-dungeon4.008":"Terus berlatih sampai timing-mu pas dan hasilkan banyak Spark!","story.map1-dungeon4.009":"<wait=20>Nah, ayo cepat lewati Rawa Magutagal! Di sini menjijikkan sekali...","story.map1-dungeon4.010":"Argh, <wait=20>aku digigit serangga. Kakiku yang mulus bakal penuh bentol kalau aku lama-lama di sini.","story.map1-dungeon4.011":"Cukup! <wait=40>Aku tunggu kamu di reruntuhan!","story.map1-dungeon5.001":"Oh, <wait=20><rep_handlename>! <wait=40>Akhirnya kamu sampai di reruntuhan!","story.map1-dungeon5.002":"Jujur saja, <wait=20>waktu pertama kita bertemu kamu kelihatan tidak bisa diandalkan, <wait=20>tidak tahu apa-apa, <wait=20>dan sama sekali tidak sadar dengan apa yang terjadi di sekitarmu...","story.map1-dungeon5.003":"Aku benar-benar bertanya-tanya... <wait=40>apa orang ini sungguh seorang Summoner?","story.map1-dungeon5.004":"Tapi ternyata Lord Lucius benar. <wait=20>Kamu memang punya potensi!","story.map1-dungeon5.005":"Ngomong-ngomong, <wait=20>kamu sudah tahu soal Skill Leader, kan?","story.map1-dungeon5.006":"Untuk unggul dari lawan atau menutupi kelemahan Squad-mu...","story.map1-dungeon5.007":"penting untuk mencoba mengganti Leader dan menguji berbagai Skill Leader.","story.map1-dungeon5.008":"Selain itu, <wait=40>saat ada Summoner lain yang membantumu...","story.map1-dungeon5.009":"...Skill Leader miliknya juga ikut aktif.","story.map1-dungeon5.010":"Ini penting, jadi ingat baik-baik!","story.map1-dungeon5.011":"Ayo, <wait=20>Menara Mistral tinggal selangkah lagi!","story.map1-dungeon5.012":"Reruntuhan Mirza ini <wait=40>adalah sisa bangunan yang didirikan ribuan tahun lalu...","story.map1-dungeon5.013":"Tapi belakangan aku tidak pernah dengar ada makhluk yang berkeliaran di sini.","story.map1-dungeon5.014":"Mungkin, <wait=20>siapa tahu, <wait=20>kamu bisa lewat tanpa masalah!","story.map1-dungeon5.015":"Yah... <wait=20>kita tidak akan tahu sebelum kamu mencobanya.","story.map1-dungeon5.016":"Tapi melihat semua yang sudah kamu capai, <wait=20>kurasa tidak ada yang bisa menghalangimu!","story.map1-dungeon5.017":"Percaya diri! Semoga berhasil!","story.map1-dungeon6.001":"Oh, <wait=20><rep_handlename>.<br><wait=40>Kamu keluar dari reruntuhan hidup-hidup...","story.map1-dungeon6.002":"Brr... <wait=20>Tempat ini dingin dan seram. <wait=40>Lihat saja bangunan mencurigakan di sana itu.","story.map1-dungeon6.003":"Kudengar tempat itu disebut Sarang Monster...","story.map1-dungeon6.004":"Tempat itu bikin merinding!","story.map1-dungeon6.005":"Dan belakangan ada laporan soal pendekar pedang misterius yang berkeliaran di sekitar sini.","story.map1-dungeon6.006":"<size=20>A-<wait=10>aku <size=19>bukan<size=18>nya <size=17>bi-<size=16>bilang <size=15>aku <size=14>t-<size=13>ta-<size=12>takut, <size=11>ya<size=9>?!","story.map1-dungeon6.007":"P-Pokoknya, <wait=20>katanya dia memakai pakaian aneh dan menyandang pedang yang ganjil. <wait=20>Tapi kekuatannya tidak boleh diremehkan.","story.map1-dungeon6.008":"Pastikan kamu tetap waspada...","story.map1-dungeon6.009":"<size=20>Kyaa!!<br><wait=20><size=18>A-<size=20>ada <size=16>sesuatu <size=19>men<size=17>da<size=18>rat <size=15>di <size=17>le<size=19>nganku...","story.map1-dungeon6.010":"Oh, <wait=20>cuma daun?<br><wait=60>Apa... <wait=20>kenapa wajahmu begitu?","story.map1-dungeon6.011":"P-Pokoknya, <wait=20>hati-hati!","story.map1-dungeon6.012":"Setelah melewati ini, <wait=20>kita akan sampai di kaki Menara Mistral!","story.map1-dungeon6.013":"Semoga berhasil, <wait=20><rep_handlename>!","story.map1-dungeon7.001":"Akhirnya kita tiba di Menara Mistral.","story.map1-dungeon7.002":"Meskipun menara ini masih di Mistral, Maxwell sudah menguasainya.","story.map1-dungeon7.003":"Jujur saja, <wait=20>musuh-musuh yang kita hadapi sejauh ini tidak ada apa-apanya dibanding bawahan Maxwell.","story.map1-dungeon7.004":"Kita harus benar-benar siap untuk memenangkan pertempuran ini dan membebaskan menara dari kendali Maxwell.","story.map1-dungeon7.005":"Di lantai teratas <wait=20>menunggu monster yang konon diciptakan oleh Maxwell sendiri.","story.map1-dungeon7.006":"Tapi kami tidak boleh membiarkanmu tumbang di sini.","story.map1-dungeon7.007":"St. Lamia, tempat Maxwell menunggu, masih jauh.","story.map1-dungeon7.008":"Aku yakin kamu pasti bisa. <wait=40>Aku bahkan menghormatimu sekarang. <wait=20>Percayalah pada dirimu sendiri!","story.map1-dungeon7.009":"Ayo, <wait=40><rep_handlename>!","story.map1-dungeon7.010":"Lepaskan kekuatanmu <wait=20>dan bebaskan Mistral dari cengkeraman kejahatan!","story.map1-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map1-dungeon_ex_clear.002":"<size=21>Ketemu juga!</size>","story.map1-dungeon_ex_clear.003":"<rep_handlename>! <wait=40>Anda berhasil!","story.map1-dungeon_ex_clear.004":"Kami telah memastikan lenyapnya sebuah kekuatan yang dahsyat.","story.map1-dungeon_ex_clear.005":"Sepertinya Anda telah mengalahkan Skramya.","story.map1-dungeon_ex_clear.006":"Saya tahu, kalau ada yang bisa melakukannya, itu pasti Anda!","story.map1-dungeon_ex_clear.007":"Oh, <wait=20>Anda tidak terluka, kan?","story.map1-dungeon_ex_clear.008":"Nanti saya rawat setelah kita kembali!","story.map1-dungeon_ex_clear.009":"Hehe, bercanda kok.","story.map1-dungeon_ex_clear.010":"Umm, <wait=20>berkat Anda, kami mendapatkan berbagai informasi baru.","story.map1-dungeon_ex_clear.011":"Sepertinya dahulu kala sebuah negeri kecil di Wilayah Mystral pernah mencoba memakai kekuatan Skramya.","story.map1-dungeon_ex_clear.012":"Rencana mereka berbalik, dan negeri itu dihancurkan oleh amukan Skramya.","story.map1-dungeon_ex_clear.013":"Amarah Skramya terus berlanjut dan ia bergerak menuju negeri-negeri lain.","story.map1-dungeon_ex_clear.014":"Namun, seorang pahlawan muncul dan dengan gagah menyegel Skramya. ","story.map1-dungeon_ex_clear.015":"Setelah itu, sepertinya Skramya terus tertidur di Pegunungan Egor tanpa pernah diusik. ","story.map1-dungeon_ex_clear.016":"Saya sangat ingin tahu pahlawan seperti apa itu, tapi kami tidak punya informasi lagi.","story.map1-dungeon_ex_clear.017":"Semoga suatu hari kami mendapat informasi lebih banyak soal orang itu.","story.map1-dungeon_ex_clear.018":"Baiklah, <wait=40>saya akan memberi tahu Anda kalau ada informasi baru!","story.map1-dungeon_ex_clear.019":"Semoga sukses dalam penyelidikan Anda tentang Grand Gaia!","story.map1-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map1-dungeon_ex_open.002":"H-<wait=20>Halo...","story.map1-dungeon_ex_open.003":"Apa ada yang bisa mendengar saya?","story.map1-dungeon_ex_open.004":"Apa Anda bisa mendengar saya, <wait=40>Tuan?","story.map1-dungeon_ex_open.005":"Ah! <wait=40>Akhirnya tersambung!","story.map1-dungeon_ex_open.006":"<rep_handlename>!","story.map1-dungeon_ex_open.007":"Anda sudah sampai di Pegunungan Egor!","story.map1-dungeon_ex_open.008":"Saya tahu Anda pasti bisa!","story.map1-dungeon_ex_open.009":"Oh, <wait=20>izinkan saya memperkenalkan diri sekali lagi.","story.map1-dungeon_ex_open.010":"Saya Lin Merylham dari Dukungan Logistik...","story.map1-dungeon_ex_open.011":"...Biro Investigasi Kantor Survei Grand Gaia, siap melayani Anda.","story.map1-dungeon_ex_open.012":"Untuk hari ini...","story.map1-dungeon_ex_open.013":"...<rep_handlename>, sebagai anggota Pasukan Summoner Balai Summoner Akras...","story.map1-dungeon_ex_open.014":"...kami meminta Anda menyelidiki Pegunungan Egor!","story.map1-dungeon_ex_open.015":"Meskipun berada di Wilayah Mystral, penyelidikannya tertunda karena tempat itu dikuasai Maxwell...","story.map1-dungeon_ex_open.016":"...sejak dia dikalahkan, kami akhirnya bisa masuk dan menyelidikinya lebih menyeluruh!","story.map1-dungeon_ex_open.017":"Benar-benar ada Summoner yang hebat di luar sana, ya?","story.map1-dungeon_ex_open.018":"Anda juga, berjuanglah sebaik mungkin!","story.map1-dungeon_ex_open.019":"Oh, <wait=20>kembali ke pembicaraan tadi.","story.map1-dungeon_ex_open.020":"Soal Pegunungan Egor...","story.map1-dungeon_ex_open.021":"Menurut penyelidikan kami, ada iblis yang sangat kuat sedang tertidur di sana. ","story.map1-dungeon_ex_open.022":"Kami belum sepenuhnya yakin, tapi...","story.map1-dungeon_ex_open.023":"...kemungkinan besar itu adalah iblis es yang konon ada di Wilayah Mystral.","story.map1-dungeon_ex_open.024":"Hah?","story.map1-dungeon_ex_open.025":"Anda tidak tahu soal Skramya si iblis es?","story.map1-dungeon_ex_open.026":"Saya sangat terkejut mendengarnya...","story.map1-dungeon_ex_open.027":"Baiklah! <wait=40>Kalau begitu biar saya jelaskan!","story.map1-dungeon_ex_open.028":"Dahulu kala, di Wilayah Mystral...","story.map1-dungeon_ex_open.029":"...sepertinya ada beberapa negeri kecil lain selain kerajaan lama St. Lamia.","story.map1-dungeon_ex_open.030":"Konon semuanya dihancurkan oleh para dewa setelah mereka menyerbu.","story.map1-dungeon_ex_open.031":"Namun, konon ada satu negeri yang dihancurkan bukan oleh dewa, melainkan oleh Skramya.","story.map1-dungeon_ex_open.032":"Sekecil apa pun negeri itu, sebuah kerajaan dihancurkan oleh satu iblis saja...","story.map1-dungeon_ex_open.033":"......","story.map1-dungeon_ex_open.034":".........","story.map1-dungeon_ex_open.035":"Um, <wait=20>hanya itu informasi yang saya punya.","story.map1-dungeon_ex_open.036":"Hanya itu yang perlu Anda ketahui!","story.map1-dungeon_ex_open.037":"Ia punya kekuatan untuk menghancurkan kerajaan!","story.map1-dungeon_ex_open.038":"Ia sangat berbahaya!","story.map1-dungeon_ex_open.039":"Sebagai Summoner, Anda tidak bisa membiarkannya begitu saja!","story.map1-dungeon_ex_open.040":"Wah, Anda sama sekali tidak terlihat khawatir soal bahayanya.","story.map1-dungeon_ex_open.041":"Tapi iblis ini benar-benar kejam, <wait=20>jadi tolong jangan memaksakan diri!","story.map1-dungeon_ex_open.042":"Baiklah, saya menantikan laporan yang bagus dari Anda!","story.map1-ending.001":"<size=24><rep_handlename>!!<br>Kamu berhasil!!</size>","story.map1-ending.002":"Pertarunganmu melawan Juggernaut tadi <wait=40>keren banget!","story.map1-ending.003":"Sekarang kamu bisa dengan bangga menyebut dirimu Summoner yang hebat.","story.map1-ending.004":"Mungkin... <wait=40>kamu memang musuh bebuyutan Maxwell sejak lahir...","story.map1-ending.005":"Bukan, <wait=40>bukan mungkin lagi!","story.map1-ending.006":"Kamu pasti Summoner yang ditakdirkan menyelamatkan Grand Gaia!","story.map1-ending.007":"...<wait=20>Hei! <wait=40>Kamu bisa sedikit lebih menghargai orang yang memujimu, kan!","story.map1-ending.008":"Masa kamu nggak bisa sedikit bersemangat? <wait=40>Malu tahu, cuma aku yang heboh sendiri.","story.map1-ending.009":"Oh! <wait=40>Lord Lucius memanggil kita!","story.map1-ending.010":"<speed=12>Akhirnya, kita bisa menuju Morgan<wait=10>.<wait=20>.<wait=30>.","story.map1-ending.011":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Akulah Lucius...<br><wait=40>Dewa Gerbang ini...","story.map1-ending.012":"<anchor=center><br><br><br><br><br><speed=8><size=15><rep_handlename>... <wait=40>Penyelamat St. Lamia...","story.map1-ending.013":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Gunakan kekuatanku <wait=40>dan jelajahilah negeri-negeri baru...","story.map1-ending.014":"<anchor=center><br><br><br><br><br><br><br><speed=8><size=15>Majulah <wait=20>dan gunakan kekuatanmu untuk membawa kedamaian ke dunia ini...","story.map1-ending.015":"<anchor=center><color=000000><speed=5><size=12>...Bangun!","story.map1-ending.016":"<anchor=center><color=000000><speed=7><size=18>...Kamu dengar aku?","story.map1-ending.017":"<anchor=center><color=000000><speed=15><size=40><rep_handlename>, bangun!!","story.map1-ending.018":"Ya ampun, <wait=40>kamu tidur kelamaan!!","story.map1-ending.019":"Apa? <wait=40>Kita di mana? Ini Morgan... <wait=20>Morgan!","story.map1-ending.020":"Hebat, kan! <wait=20>Gerbang menuju Morgan akhirnya terbuka.","story.map1-ending.021":"Akhirnya, ya... <wait=20>Morgan...","story.map1-ending.022":"Tempat ini dulu terkenal karena pemandangannya yang indah...","story.map1-ending.023":"Tapi bertahun-tahun telah berlalu, <wait=20> dan tempat ini sudah jatuh ke tangan Maxwell.","story.map1-ending.024":"Monster di sini jauh lebih kuat daripada di Mistral...","story.map1-ending.025":"Kita tidak tahu apa yang menunggu kita, <wait=40>jadi sebaiknya kamu kembali ke desamu dan bersiap-siap.","story.map1-ending.026":"Aku akan menunggu di sini.","story.map1-ending.027":"Setelah kamu kembali, ayo kita menuju Menara Morgan, <wait=19>dan di sana kita bebaskan negeri ini!","story.map1-ending.028":"Baiklah, <wait=20>sampai nanti!","story.map10-dungeon1.001":"<size=20>Kamu telat! <wait=40>Dari mana saja kamu, <rep_handlename>!</size>","story.map10-dungeon1.002":"Aku sedang bekerja keras menyelamatkan temanmu, berani-beraninya kamu membuatku menunggu!","story.map10-dungeon1.003":"Dasar <size=20>lamban </size>bodoh!","story.map10-dungeon1.004":"Aku tahu ini permintaan para Tetua Summoner, tapi tetap saja, kenapa aku yang harus mengejarnya?","story.map10-dungeon1.005":"Hei, kenapa mukamu begitu?","story.map10-dungeon1.006":"Kamu nggak mengira aku bakal kabur dari misi ini, kan?","story.map10-dungeon1.007":"<size=20>Jangan main-main denganku!</size>","story.map10-dungeon1.008":"Setelah aku menjalankan tugasku dengan sempurna, Karl si gadungan itu yang akan terlihat bodoh.","story.map10-dungeon1.009":"Kesempatan seperti ini nggak akan sering datang.","story.map10-dungeon1.010":"Makanya, perbaiki sikapmu dan bantu aku!","story.map10-dungeon1.011":"Kalau begitu, mungkin penyelidikan kita di sini bisa cepat beres.","story.map10-dungeon1.012":"Entah ini dulu ibu kota kekaisaran Agni atau bukan, reruntuhan kota tua berdebu ini semuanya sama saja.","story.map10-dungeon1.013":"<size=20>Hei!</size>","story.map10-dungeon1.014":"Berhenti main-main dan mulai cari Karl si pemalas itu!","story.map10-dungeon1.015":"Hmm?","story.map10-dungeon1.016":"Harus mulai dari mana?","story.map10-dungeon1.017":"Kamu benar-benar bodoh!","story.map10-dungeon1.018":"Aku jadi bertanya-tanya apa kepala di atas bahumu itu cuma hiasan.","story.map10-dungeon1.019":"Tapi murid bernama Mare itu masih mengejarmu, bukan?","story.map10-dungeon1.020":"Kalau kamu bikin keributan di sini, dia pasti datang dengan Karl sebagai alat tawar-menawar.","story.map10-dungeon1.021":"Itulah kesempatan kita untuk menyelamatkan Karl si tolol itu.","story.map10-dungeon1.022":"Kalau kamu paham maksudku, terus saja pura-pura menyelidiki seperti orang bodoh dan bikin keributan sebesar mungkin!","story.map10-dungeon2.001":"<size=20>Sial! </size><wait=40><size=22>Menyebalkan sekali!","story.map10-dungeon2.002":"Apa maksud wanita berwajah pucat itu, bersembunyi dari kita!","story.map10-dungeon2.003":"Hei! <wait=40><rep_handlename>!","story.map10-dungeon2.004":"Kamu bisa bikin keributan sedikit lebih besar, kan?","story.map10-dungeon2.005":"Sana, lari-lari di tempat terbuka seperti biasa supaya lebih gampang terlihat!","story.map10-dungeon2.006":"Payah sekali kamu, jadi umpan saja nggak becus!","story.map10-dungeon2.007":"Nngh! <wait=40>Sesabar apa pun aku, kamu sudah membuatku hampir habis kesabaran.","story.map10-dungeon2.008":"Aku nggak bisa menunggu murid itu lebih lama lagi.","story.map10-dungeon2.009":"Aku akan mengejar Karl sendiri!","story.map10-dungeon2.010":"Kamu juga cari dia sendiri!","story.map10-dungeon2.011":"Aku nggak sebaik itu sampai mau melindungi orang yang nggak berguna bagiku.","story.map10-dungeon2.012":"Jadi jangan ikuti aku, paham?","story.map10-dungeon2.013":"<size=20>Hei! <rep_handlename>!</size>","story.map10-dungeon2.014":"Aku hampir lupa memberitahumu.","story.map10-dungeon2.015":"Kamu sama sekali nggak boleh sampai tertangkap murid itu.","story.map10-dungeon2.016":"Aku yakin kalau kamu sampai tertangkap, entah bagaimana aku juga yang ditugaskan menyelamatkanmu.","story.map10-dungeon2.017":"Aku nggak sanggup lagi menerima permintaan merepotkan.","story.map10-dungeon2.018":"Maksudku, kalau kamu sampai tertangkap, lebih baik dia menghancurkanmu berkeping-keping saja.","story.map10-dungeon2.019":"<size=20>Kamu paham, kan!?</size>","story.map10-dungeon3.001":"Sepertinya akhirnya aku terbebas dari para pengganggu itu.","story.map10-dungeon3.002":"Hmm. <wait=40>Kenapa wajahmu terkejut begitu?","story.map10-dungeon3.003":"Sepertinya akhirnya kamu sendirian.","story.map10-dungeon3.004":"Manusia bodoh pun bisa menebak bahwa aku akan muncul di hadapanmu, mangsaku.","story.map10-dungeon3.005":"Atau mungkin kamu terlalu bodoh sampai tidak menyadarinya?","story.map10-dungeon3.006":"......","story.map10-dungeon3.007":"Kamu mencari makhluk hijau kecil yang menyedihkan itu?","story.map10-dungeon3.008":"Dia pasti tertipu oleh informasi palsu yang kutinggalkan tentang keberadaan Karl.","story.map10-dungeon3.009":"Saat ini dia mungkin sedang berlarian panik di seluruh Agni.","story.map10-dungeon3.010":"Semulut besar apa pun dia, dia tetap hanya manusia.","story.map10-dungeon3.011":"Teman-teman kecilmu cukup merepotkan sebelumnya, karena aku tidak tahu tentang mereka.","story.map10-dungeon3.012":"Namun, sepertinya kini tidak ada lagi yang tersisa untuk membantumu.","story.map10-dungeon3.013":"Aku ingin sekali lagi mencoba merenggut nyawamu.","story.map10-dungeon3.014":"......","story.map10-dungeon3.015":"Namun, kamu adalah Summoner yang sudah mengalahkan banyak dewa.","story.map10-dungeon3.016":"Sebaiknya kubiarkan kamu melemahkan dirimu sedikit lagi.","story.map10-dungeon3.017":"Kalau kamu ingin menyelamatkan Karl, kejarlah aku.","story.map10-dungeon3.018":"Kalau tidak, nyawanya berakhir.","story.map10-dungeon3.019":"Meski tahu jalannya penuh jebakan, aku penasaran apa kamu tetap akan mengejarku.","story.map10-dungeon3.020":"Hmph. <wait=40>Kalian manusia memang makhluk yang bodoh.","story.map10-dungeon3.021":"Teruslah berjuang maju supaya nanti kamu lebih mudah kuhabisi.","story.map10-dungeon3.022":"Aku tak sabar melihatmu dalam keadaan lemah.","story.map10-dungeon4.001":"Jadi kamu berhasil melewati Dataran Tinggi Granasta.","story.map10-dungeon4.002":"Memang sudah kuduga dari orang yang menumbangkan Maxwell dan Cardes.","story.map10-dungeon4.003":"......","story.map10-dungeon4.004":"Melihatmu, aku teringat perang ketika umat manusia dihancurkan.","story.map10-dungeon4.005":"Manusia-manusia yang cukup bodoh untuk mengira mereka bisa menentang para dewa.","story.map10-dungeon4.006":"Omong-omong, saat itu ada manusia lain yang sama gigihnya denganmu.","story.map10-dungeon4.007":"Sepertinya manusia lain menyebut orang itu pahlawan.","story.map10-dungeon4.008":"Namun, dia tetap sama tak berdaya dan ketakutan seperti kamu sekarang.","story.map10-dungeon4.009":"Sekuat apa pun dia sebagai manusia...","story.map10-dungeon4.010":"...itu tak bisa menutupi kenyataan bahwa dia hanyalah manusia yang bodoh.","story.map10-dungeon4.011":"Kamu pun akan memasang wajah seperti itu.","story.map10-dungeon4.012":"Aku tak sabar menikmatinya.","story.map10-dungeon4.013":"......","story.map10-dungeon4.014":"Hmph. <wait=40>Aku tak tertarik dengan tatapanmu itu.","story.map10-dungeon4.015":"Sepertinya aku harus membuatmu menderita sedikit lagi.","story.map10-dungeon4.016":"Bagaimana menurutmu?","story.map10-dungeon4.017":"Coba tunjukkan sejauh mana kamu bisa maju sendirian.","story.map10-dungeon5.001":"<rep_handlename>. Jadi kamu masih memilih melawan.","story.map10-dungeon5.002":"Aku tak suka matamu itu, <wait=40>yang sama sekali tak menunjukkan keputusasaan.","story.map10-dungeon5.003":"Bagaimana kamu masih bisa menyimpan harapan dalam situasi seperti ini?","story.map10-dungeon5.004":"Tak satu pun sekutu yang mendukungmu masih ada di sini.","story.map10-dungeon5.005":"Bahkan teman masa kecilmu pun tidak.","story.map10-dungeon5.006":"Atau gadis Summoner yang terus-menerus memakimu.","story.map10-dungeon5.007":"Atau pak tua dengan harapan konyolnya padamu.","story.map10-dungeon5.008":"Atau makhluk yang luar biasa kasar itu.","story.map10-dungeon5.009":"Bahkan dewa rendahan yang selama ini memanfaatkanmu pun tidak.","story.map10-dungeon5.010":"......","story.map10-dungeon5.011":"Atau kamu mau bilang bahwa sejak awal kamu memang tak pernah bergantung pada siapa pun?","story.map10-dungeon5.012":"Dan meski begitu, kamu memilih mati-matian menyelamatkan teman-temanmu?","story.map10-dungeon5.013":"Gagasan yang sungguh tak bisa kupahami.","story.map10-dungeon5.014":"......","story.map10-dungeon5.015":"Begitu, sekarang aku ingat.","story.map10-dungeon5.016":"Omong-omong, <wait=20>suatu ketika, saat pria itu terjepit dalam masalah besar...","story.map10-dungeon5.017":"...dia membangkitkan kekuatan baru dalam dirinya.","story.map10-dungeon5.018":"Dia mengenakan sayap api yang besar di punggungnya.","story.map10-dungeon5.019":"Sudah lama aku ingin melupakan aib dari kekuatan yang dia miliki.","story.map10-dungeon5.020":"Kalau kamu memiliki kekuatan yang sama dalam dirimu, aku tak punya waktu lagi untuk bermain-main.","story.map10-dungeon5.021":"Hmph...","story.map10-dungeon5.022":"Tapi aku tak bisa terus membiarkanmu berdiri di situ membuang-buang waktuku.","story.map10-dungeon5.023":"Pertempuran Lord Zefalhua dan Afla Dilith sudah di depan mata.","story.map10-dungeon5.024":"Aku harus menghabisimu sebelum kamu sempat mengganggu ramalanku.","story.map10-dungeon5.025":"Kamu siap?","story.map10-dungeon5.026":"Akan kutunjukkan padamu dunia keputusasaan yang belum pernah kamu lihat.","story.map10-dungeon5.027":"Aku tak akan menahan diri, jadi saksikanlah kekuatan sejatiku!","story.map10-dungeon5.028":"Terimalah dengan sekuat tenagamu!","story.map10-dungeon6.001":"Cukup sampai di situ, <wait=40><rep_handlename>.","story.map10-dungeon6.002":"Kamu sudah bertarung dengan baik melawan para dewa sampai sekarang.","story.map10-dungeon6.003":"Namun, dari luka di sekujur tubuhmu, aku tahu kamu sudah tak mampu bertarung lagi.","story.map10-dungeon6.004":"Takkan kubiarkan Lucius dan ramalannya maju lebih jauh lagi!","story.map10-dungeon6.005":"Matilah!","story.map10-dungeon6.006":"<size=18>*Kliiiing*","story.map10-dungeon6.007":"Nngh!","story.map10-dungeon6.008":"Kok bisa-bisanya kamu dibuat repot sebegininya oleh wanita seperti itu?","story.map10-dungeon6.009":"Benar-benar, <wait=20>kamu ini bodoh sekali.","story.map10-dungeon6.010":"Hei, sadarlah!","story.map10-dungeon6.011":"Jangan sampai kalah sebelum kita sempat menyelamatkan Karl!","story.map10-dungeon6.012":"Bodoh! <wait=20>Kamu masih mau bergerak dengan luka seperti itu?","story.map10-dungeon6.013":"Jangan main-main denganku.","story.map10-dungeon6.014":"Kamu benar-benar mengira serangan seperti itu bisa menjatuhkanku?","story.map10-dungeon6.015":"Untuk ukuran seorang murid, kamu bodoh sekali.","story.map10-dungeon6.016":"Benar-benar khas manusia.","story.map10-dungeon6.017":"<size=18>*Klaaaang*","story.map10-dungeon6.018":"Nngh!","story.map10-dungeon6.019":"Kenapa kamu cuma berdiri di situ?","story.map10-dungeon6.020":"Apa pertarunganmu dengan <rep_handlename> membuatmu tak bisa bergerak?","story.map10-dungeon6.021":"Oh iya, <wait=20>soal Karl, <wait=20>Lugina sudah dalam perjalanan untuk menyelamatkannya dari Kuil Samudra.","story.map10-dungeon6.022":"Padahal kamu kira sudah menipunya dengan cerdik. <wait=20>Sayang sekali.","story.map10-dungeon6.023":"Tidak mungkin.","story.map10-dungeon6.024":"Nngh, <rep_handlename>. <wait=20>Sepertinya kali ini kamu nyaris lolos dari maut.","story.map10-dungeon6.025":"Padahal yang kembali padamu hanyalah seorang Summoner penuh luka.","story.map10-dungeon6.026":"Akan kuhancurkan kalian berdua setelah kubereskan makhluk kasar itu.","story.map10-dungeon6.027":"......","story.map10-dungeon6.028":"......<wait=40>Aku sudah tak merasakan kehadirannya lagi.","story.map10-dungeon6.029":"Nngh.","story.map10-dungeon6.030":"*Hah* <wait=20>*hah* <wait=20>*Hah* ","story.map10-dungeon6.031":"A-<wait=20>Aku baik-baik saja.","story.map10-dungeon6.032":"Cuma rasa sakitnya kembali sedikit setelah dia pergi.","story.map10-dungeon6.033":"Tapi, syukurlah kita berhasil menipunya.","story.map10-dungeon6.034":"Dengar...<wait=40>Kita nggak bisa diam saja, kita harus menuju Kuil Samudra.","story.map10-dungeon6.035":"Aku yakin di sanalah Karl ditahan.","story.map10-dungeon6.036":"Kenapa mukamu begitu?","story.map10-dungeon6.037":"Aku nggak punya waktu untuk duduk-duduk mengobrol denganmu.","story.map10-dungeon6.038":"Aku janji kita bicara nanti, jadi sekarang ayo kejar Karl.","story.map10-dungeon7.001":"*Hah* *hah* *hah*","story.map10-dungeon7.002":"Akhirnya kita sampai di Kuil Samudra.","story.map10-dungeon7.003":"Sepertinya kamu sudah hampir mencapai batasmu.","story.map10-dungeon7.004":"Dia lagi.","story.map10-dungeon7.005":"Kuakui butuh keberanian untuk berdiri di hadapanku dalam keadaan babak belur seperti itu.","story.map10-dungeon7.006":"Hmph. <wait=40>Sombong sekali kamu.","story.map10-dungeon7.007":"Padahal aku sudah menipumu sampai kamu memberitahuku di mana kamu menahan Karl.","story.map10-dungeon7.008":"...Dasar bodoh.","story.map10-dungeon7.009":"Rupanya kalian berjuang menembus Teluk Lognea untuk sampai padaku.","story.map10-dungeon7.010":"Kalian pikir bisa lolos dariku dengan luka seperti itu?","story.map10-dungeon7.011":"Nngh...","story.map10-dungeon7.012":"Para pelayanku!","story.map10-dungeon7.013":"Berkumpullah dan musnahkan serangga-serangga ini dari dunia!","story.map10-dungeon7.014":"A-Apa ini? <wait=20>Dari mana mereka semua datang!?","story.map10-dungeon7.015":"Apa nggak memalukan bagi dewa sepertimu memanggil sebanyak ini hanya untuk melawan kami manusia?","story.map10-dungeon7.016":"Hentikan ocehan bodohmu.","story.map10-dungeon7.017":"Di sinilah akhirnya aku akan menyingkirkan kalian.","story.map10-dungeon7.018":"Itu saja.","story.map10-dungeon7.019":"<rep_handlename>!","story.map10-dungeon7.020":"Sesalilah perlawanan bodohmu terhadap para dewa, lalu matilah!","story.map10-dungeon7.021":"Nngh... <wait=40>Gawat, <wait=40>jumlah mereka terlalu banyak.","story.map10-dungeon7.022":"Nggak biasanya kamu sepenakut ini dalam situasi seperti ini.","story.map10-dungeon7.023":"Suara itu!","story.map10-dungeon7.024":"B-Bagaimana kamu...","story.map10-dungeon7.025":"Halo. <wait=40>Maaf sudah membuat kalian menunggu.","story.map10-dungeon7.026":"Karl!","story.map10-dungeon7.027":"Bagaimana kamu...","story.map10-dungeon7.028":"Terakhir kuperiksa, kamu masih terkunci di ruangan itu...","story.map10-dungeon7.029":"Justru saat kamu datang memeriksa, aku jadi sadar di mana aku berada.","story.map10-dungeon7.030":"Wahai dewa yang begitu dangkal akalnya.","story.map10-dungeon7.031":"Beraninya kamu...","story.map10-dungeon7.032":"Lugina! <wait=20>Kenapa lama sekali!","story.map10-dungeon7.033":"Diam!","story.map10-dungeon7.034":"Butuh waktu lama untuk menyelamatkannya gara-gara dia malas sekali!","story.map10-dungeon7.035":"Kan sudah kubilang, aku minta maaf.","story.map10-dungeon7.036":"Oh iya, dan Seria...","story.map10-dungeon7.037":"Kok kamu bisa sampai begitu?","story.map10-dungeon7.038":"Bukan salahku, ada seseorang yang menghambatku!","story.map10-dungeon7.039":"Sudahlah, lupakan saja!","story.map10-dungeon7.040":"Ada yang harus kita bereskan di sini.","story.map10-dungeon7.041":"Benar, kan, Mare?","story.map10-dungeon7.042":"Rencanamu sudah berantakan.","story.map10-dungeon7.043":"Apa yang akan kamu lakukan sekarang?","story.map10-dungeon7.044":"Manusia, beraninya kalian mengira kalian berdiri di atas para dewa?","story.map10-dungeon7.045":"Kupuji kalian karena telah melampaui perkiraanku.","story.map10-dungeon7.046":"Tapi meski aku menghormati kalian, kini aku akan membuang rencanaku dan menghancurkan kalian begitu saja.","story.map10-dungeon7.047":"Aku, Mare, murid Lord Zevalhua, memerintahkan kalian!","story.map10-dungeon7.048":"Para pelayanku!","story.map10-dungeon7.049":"Berkumpullah padaku dan hancurkan musuh-musuhku!","story.map10-dungeon7.050":"Bunuh semua manusia di hadapanku!","story.map10-dungeon7.051":"Sepertinya sudah banyak sekali yang berkumpul di sini.","story.map10-dungeon7.052":"Jumlahnya jauh lebih banyak dari sebelumnya.","story.map10-dungeon7.053":"Manusia. <wait=40>Kalian sudah bertarung dengan baik.","story.map10-dungeon7.054":"Aku pasti akan mengingat kalian...","story.map10-dungeon7.055":"...dan akhir tragis yang sebentar lagi kalian temui.","story.map10-dungeon7.056":"Mau ke mana kamu!","story.map10-dungeon7.057":"Kalian semua, minggir!","story.map10-dungeon7.058":"Banyak sekali mereka.","story.map10-dungeon7.059":"Karl, <wait=40>kamu terluka...","story.map10-dungeon7.060":"Haha, <wait=20>murid itu cuma sedikit menghajarku, itu saja...","story.map10-dungeon7.061":"Jangan pura-pura nggak apa-apa!","story.map10-dungeon7.062":"Tapi Seria, kamu juga terluka...","story.map10-dungeon7.063":"I-Ini sih...","story.map10-dungeon7.064":"Lihat saja semua makhluk menyedihkan ini!","story.map10-dungeon7.065":"Hei! <wait=40><rep_handlename>!","story.map10-dungeon7.066":"Aku muak cuma berlarian ke sana kemari.","story.map10-dungeon7.067":"Kamu kejar wanita pucat itu dan kalahkan dia!","story.map10-dungeon7.068":"Aku yang urus dua orang ini selama kamu pergi!","story.map10-dungeon7.069":"Kami nggak perlu kamu urus!","story.map10-dungeon7.070":"Maaf sudah membuatmu khawatir, <rep_handlename>.","story.map10-dungeon7.071":"Serahkan urusan di sini pada kami dan kejar murid itu.","story.map10-dungeon7.072":"Nanti pasti akan kubalas kebaikanmu.","story.map10-dungeon7.073":"Kami mengandalkanmu, <wait=20><rep_handlename>.","story.map10-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map10-dungeon_ex_clear.002":"<size=18>Bisakah Anda...</size> <wait=20><size=20> *Bzz...zzz*</size>","story.map10-dungeon_ex_clear.003":"<size=20>*Bzz*</size> <size=18>...Tuan...?</size> <wait=20>*Bzz*</size>","story.map10-dungeon_ex_clear.004":"<size=18>*Bzz*</size><wait=20><size=20> Ah, nah begitu!</size>","story.map10-dungeon_ex_clear.005":"Susah sekali dapat sinyal di dalam dungeon seperti itu.","story.map10-dungeon_ex_clear.006":"Pokoknya, <wait=20>izinkan saya menceritakan apa yang saya temukan.","story.map10-dungeon_ex_clear.007":"Menurut literatur kuno...","story.map10-dungeon_ex_clear.008":"...tempat itu sudah disegel sejak periode akhir Kekaisaran Agni.","story.map10-dungeon_ex_clear.009":"Tapi 100 tahun sebelumnya, ada seorang kaisar yang diam-diam dipenjara di sana.","story.map10-dungeon_ex_clear.010":"Waktu yang lama berlalu tanpa ada yang tahu dia ada di bawah sana. ","story.map10-dungeon_ex_clear.011":"Kaisar itu ditakuti orang-orang di sekitarnya dan dianggap tiran.","story.map10-dungeon_ex_clear.012":"Kenyataannya, <wait=20>bukan hanya rakyatnya yang takut padanya, tapi juga anak-anak mereka.","story.map10-dungeon_ex_clear.013":"Suatu hari, seorang anak yang menderita di tangannya jatuh sakit dan meninggal.","story.map10-dungeon_ex_clear.014":"Karena itulah dia diam-diam dipenjara.","story.map10-dungeon_ex_clear.015":"Seiring waktu berlalu di dungeon yang gelap gulita, amarah sang kaisar tumbuh bersama kesepiannya.","story.map10-dungeon_ex_clear.016":"Dia terlahir kembali sebagai hantu yang sangat kuat, membalas dendam pada kekaisaran selama 100 tahun.","story.map10-dungeon_ex_clear.017":"Akibatnya, <wait=20>hantu sang kaisar disegel bersama dungeon itu.","story.map10-dungeon_ex_clear.018":"Dia masih ada di suatu tempat di bawah sana, <wait=20>amarahnya terus tumbuh setiap detik.","story.map10-dungeon_ex_clear.019":"Membayangkannya saja sudah menakutkan.","story.map10-dungeon_ex_clear.020":"Tuan, <wait=20>Anda tidak perlu memaksakan diri mencari hantu itu!","story.map10-dungeon_ex_clear.021":"Anda cukup menyelidiki dengan saksama seberapa berbahaya tempat itu.","story.map10-dungeon_ex_clear.022":"A-<wait=20>Apa itu?<wait=40> Apa yang barusan Anda katakan?","story.map10-dungeon_ex_clear.023":"Tidak mungkin!","story.map10-dungeon_ex_clear.024":"Anda sudah mengalahkan hantu sang kaisar selagi saya masih meneliti!?","story.map10-dungeon_ex_clear.025":"Wah, Tuan...<wait=20>Anda luar biasa.","story.map10-dungeon_ex_clear.026":"Tapi tunggu! <wait=40>Tunggu sebentar!","story.map10-dungeon_ex_clear.027":"Saya sungguh ingin Anda menunggu sedikit lebih lama sampai penelitian saya selesai...","story.map10-dungeon_ex_clear.028":"Hmm...<wait=20> Yah, pokoknya!","story.map10-dungeon_ex_clear.029":"Lain kali saya akan berusaha sebaik mungkin agar informasinya sampai di tangan Anda secepatnya!","story.map10-dungeon_ex_clear.030":"Akan saya buktikan bahwa bukan hanya Anda yang kemampuannya meningkat!","story.map10-dungeon_ex_clear.031":"Saya akan segera menghubungi Anda lagi, jadi tunggu saja!","story.map10-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map10-dungeon_ex_open.002":"<size=18>Tu...</size> <wait=20><size=20>*Bzz...zzz*</size>","story.map10-dungeon_ex_open.003":"<size=20>*Bzz*</size> <size=18>...dengar...saya?</size> <wait=20>*Bzz*</size>","story.map10-dungeon_ex_open.004":"<size=18>*Bzz*</size><wait=20><size=20>Tuan!</size>","story.map10-dungeon_ex_open.005":"Akhirnya, tersambung juga!","story.map10-dungeon_ex_open.006":"Sepertinya Anda berada di tempat yang sinyalnya cukup buruk.","story.map10-dungeon_ex_open.007":"Pokoknya, <wait=20>izinkan saya mulai lagi.","story.map10-dungeon_ex_open.008":"Saya Lin Merylham dari Dukungan Logistik...","story.map10-dungeon_ex_open.009":"...Biro Investigasi Kantor Survei Grand Gaia, siap melayani Anda.","story.map10-dungeon_ex_open.010":"Kami telah memastikan lenyapnya sebuah kekuatan besar di wilayah Agni beberapa hari lalu. ","story.map10-dungeon_ex_open.011":"Sepertinya hal ini membuat sebuah bangunan bawah tanah yang dulu disegel jadi terbuka. ","story.map10-dungeon_ex_open.012":"Menurut catatan kami, <wait=20>sesuatu yang cukup jahat pernah dikurung di sana.","story.map10-dungeon_ex_open.013":"Misi Anda kali ini adalah pergi ke sana dan menghentikannya...","story.map10-dungeon_ex_open.014":"...sebelum ia sempat keluar dan menimbulkan kerusakan!","story.map10-dungeon_ex_open.015":"Sepertinya bangunan itu dulunya adalah sebuah dungeon, sudah lama sekali.","story.map10-dungeon_ex_open.016":"Eh? <wait=40>Anda sudah sampai di sana?","story.map10-dungeon_ex_open.017":"Saya tidak heran!","story.map10-dungeon_ex_open.018":"Baiklah, <wait=20>saya akan berusaha mencari tahu lebih banyak tentang dungeon itu.","story.map10-dungeon_ex_open.019":"Saya akan punya informasi baru untuk Anda sebelum penyelidikan Anda selesai.","story.map10-dungeon_ex_open.020":"Bertahanlah sebentar lagi!","story.map10-ending.001":"K-<wait=20>Kalian bodoh...","story.map10-ending.002":"Bagaimana mungkin dewa sepertiku dikalahkan oleh manusia...","story.map10-ending.003":"K-Kalau begitu, biarlah!","story.map10-ending.004":"<size=20>Akan kukubur kalian semua bersama kuil ini!</size>","story.map10-ending.005":"<size=14>*Gemuruh* *gemuruh*</size>","story.map10-ending.006":"<size=21>Takkan kubiarkan itu terjadi!</size>","story.map10-ending.007":"Nngh, <wait=40>jadi kamu juga selamat!","story.map10-ending.008":"Tilith, murid Lucius!","story.map10-ending.009":"Aku di sini, <rep_handlename>!","story.map10-ending.010":"Baiklah, ayo kita semua keluar dari sini!","story.map10-ending.011":"Tunggu, <rep_handlename>!","story.map10-ending.012":"Jangan kira kalian sudah menang!","story.map10-ending.013":"Berapa pun banyaknya kalian berkumpul, tak ada bedanya.","story.map10-ending.014":"Di hadapan Lord Zevalhua, kalian bukan apa-apa!","story.map10-ending.015":"Lagi pula, pemain kunci di antara kalian adalah...","story.map10-ending.016":"<size=15>*Gemuruh* *gemuruh*</size>","story.map10-ending.017":"Mare! <wait=40>Terimalah, kamu sudah kalah!","story.map10-ending.018":"<rep_handlename>! <wait=40>Semuanya sudah menunggu!","story.map10-ending.019":"Ayo pergi!","story.map10-ending.020":"<size=16>*Gemuruh* *gemuruh*</size>","story.map10-ending.021":"Nngh...","story.map10-ending.022":"<size=19>Lord Zevalhua...</size>","story.map10-ending.023":"<size=18>*Gemuruh* *gemuruh*</size>","story.map10-ending.024":"<rep_handlename>!","story.map10-ending.025":"Kamu berhasil!","story.map10-ending.026":"Aku tahu kamu bisa mengalahkan Mare, <rep_handlename>-ku!","story.map10-ending.027":"A-Aduh...","story.map10-ending.028":"Terbangnya ugal-ugalan seperti biasa, ya, <wait=40> Dewi.","story.map10-ending.029":"Nggak bisa sedikit lebih hati-hati?","story.map10-ending.030":"Hei, <wait=20>kalian berdua berhenti mengeluh!","story.map10-ending.031":"Tapi, aku senang kalian berdua baik-baik saja, Karl dan Seria.","story.map10-ending.032":"Aku khawatir sekali waktu menggendongmu, Seria, dengan luka separah itu!","story.map10-ending.033":"Terima kasih untuk itu...","story.map10-ending.034":"Iya, <wait=20>aku juga berterima kasih padamu, Dewi.","story.map10-ending.035":"Dan tentu saja padamu juga, <rep_handlename>!","story.map10-ending.036":"Tapi jangan jadi besar kepala, nanti kami yang kelihatan payah.","story.map10-ending.037":"Maaf aku butuh waktu lama untuk pulih.","story.map10-ending.038":"Pokoknya, kamu hebat seperti biasa, <rep_handlename>!","story.map10-ending.039":"Kamu mengalahkan Mare!","story.map10-ending.040":"Iya, <wait=20>benar.","story.map10-ending.041":"<rep_handlename>, <wait=40>aku sungguh bangga bisa menyebutmu sahabatku.","story.map10-ending.042":"Benar, Karl.","story.map10-ending.043":"Umm...","story.map10-ending.044":"Bukannya mau merusak suasana, tapi bukankah kita melupakan seseorang?","story.map10-ending.045":"Benar juga! <wait=40>Lugina!","story.map10-ending.046":"Di mana dia?","story.map10-ending.047":"Lugina itu siapa?","story.map10-ending.048":"Oh begitu, jadi Dewi belum pernah bertemu langsung dengan Lugina, ya?","story.map10-ending.049":"Yang benar saja, <wait=40>jadi maksudmu kamu cuma membawa kami?","story.map10-ending.050":"Umm, <wait=40>pertama-tama, aku bahkan nggak tahu ada orang lain.","story.map10-ending.051":"Apa jangan-jangan yang kalian maksud orang yang setengah terkubur di tanah itu?","story.map10-ending.052":"<size=21>Lugina!</size>","story.map10-ending.053":"<size=22>Dasar tolol! <wait=40>Akan kuhajar kalian semua!</size>","story.map10-ending.054":"Hei, setidaknya kamu sampai di sini dengan selamat.","story.map10-ending.055":"Heh... <wait=20>Kamu kelihatan berantakan sekali tadi, Lugina.","story.map10-ending.056":"<size=20>Gadis bodoh! <wait=40>Kamu yang akan kena paling parah!","story.map10-ending.057":"Seria, sudah kubilang hentikan!","story.map10-ending.058":"Lugina, <wait=40>kali ini kamu benar-benar menyelamatkan kami.","story.map10-ending.059":"Terima kasih.","story.map10-ending.060":"Heh, <wait=20>aku menolongmu cuma karena diminta Balai Summoner.","story.map10-ending.061":"Jujur saja, siapa pun orangnya juga nggak ada bedanya.","story.map10-ending.062":"Tapi tetap saja, bagaimana kamu tahu di mana aku ditahan?","story.map10-ending.063":"Itu gampang.","story.map10-ending.064":"Aku tahu wanita itu akan berusaha membuat si kepala batu ini sendirian.","story.map10-ending.065":"Jadi aku tahu kalau aku menciptakan situasi seperti itu, dia pasti datang berlari.","story.map10-ending.066":"Tapi, dia sangat berhati-hati.","story.map10-ending.067":"Karl, <wait=20>aku sudah menduga dia akan memakaimu sebagai umpan sambil perlahan mendekat.","story.map10-ending.068":"Sisanya sudah kuatur sebelum aku meninggalkan Elgaia.","story.map10-ending.069":"Aku tinggal menyuruh gadis bodoh ini menyelamatkan si tolol itu.","story.map10-ending.070":"<size=20>Siapa yang kamu sebut bodoh!</size>","story.map10-ending.071":"Yah, <wait=40>saranmu memang akhirnya menyelamatkanku.","story.map10-ending.072":"Begitu sampai di sana, aku menyebut nama tempat di dekat situ yang kamu ceritakan pada murid itu.","story.map10-ending.073":"Begitu aku menyebutnya, persis seperti katamu, dia pergi.","story.map10-ending.074":"Heh, <wait=40>gampang ditebak, karena aku tahu kapan kamu akan tiba.","story.map10-ending.075":"Memang nggak banyak tempat untuk menyembunyikan seseorang.","story.map10-ending.076":"Murid bodoh itu, <wait=20>dia melakukan persis seperti dugaanku.","story.map10-ending.077":"Dia pergi ke Kuil Samudra untuk memeriksa tawanannya.","story.map10-ending.078":"Dan dengan begitu, dia menuntunku langsung kepadanya.","story.map10-ending.079":"Wah, hebat sekali, Lugina.","story.map10-ending.080":"<size=19>Sulit dipercaya orang sepertimu bisa melakukan hal seperti itu.</size>","story.map10-ending.081":"<size=21>Beraninya kamu!<\\\\size>","story.map10-ending.082":"Jadi kamu Lugina!","story.map10-ending.083":"Senang berkenalan denganmu!","story.map10-ending.084":"Aku Tilith, dewi yang menjaga <rep_handlename>.","story.map10-ending.085":"Aku murid Lucius.","story.map10-ending.086":"Dewi yang jadi murid Lucius?","story.map10-ending.087":"Hei, <rep_handlename>!","story.map10-ending.088":"Gadis ini sudah gila atau bagaimana?","story.map10-ending.089":"Jahat sekali kamu!","story.map10-ending.090":"Padahal aku yang membawamu pulang dari Kuil Samudra!","story.map10-ending.091":"Jadi itu kamu?","story.map10-ending.092":"Yah, kalau memang begitu...","story.map10-ending.093":"Iya, dia dewi sungguhan.","story.map10-ending.094":"<size=18>Nggak mungkin...</size>","story.map10-ending.095":"Si pak tua bodoh Grahdens itu.","story.map10-ending.096":"Sebenarnya dia ngomong apa sih...","story.map10-ending.097":"Oh, dan Lugina...","story.map10-ending.098":"Grahdens yang memintamu menyelamatkan kami, bukan?","story.map10-ending.099":"Pak tua itu sedang apa sekarang?","story.map10-ending.100":"Apa!? <wait=20>Mana aku tahu?","story.map10-ending.101":"Paling dia sedang berkeliaran di suatu tempat.","story.map10-ending.102":"Kalau yang kalian maksud Tetua Grahdens, dia telah ditangkap oleh Zevalhua.","story.map10-ending.103":"Kamu...","story.map10-ending.104":"Lama tak jumpa, <rep_handlename>.","story.map10-ending.105":"Sepertinya aku belum pernah bertemu teman-temanmu di sana.","story.map10-ending.106":"Aku sudah menantikan pertemuan dengan kalian semua.","story.map10-ending.107":"Apa yang dilakukan pengawal kekaisaran rendahan sepertimu di sini?","story.map10-ending.108":"Sebelum itu, apa maksudmu pak tua itu ditangkap?","story.map10-ending.109":"Hehehe, <wait=20>jangan tidak sabaran.","story.map10-ending.110":"Aku juga punya beberapa hal yang ingin kutanyakan.","story.map10-ending.111":"Misalnya, kenapa kamu masih hidup padahal sudah ditangkap murid itu.","story.map10-ending.112":"Tapi kita bisa membahas detailnya di Milvana.","story.map10-ending.113":"Apa kalian berdua tidak keberatan...","story.map10-ending.114":"<rep_handlename> dan Tilith, murid Lord Lucius?","story.map10-ending.115":"Ya, aku tidak keberatan.","story.map10-ending.116":"Lord Lucius pasti akan segera membukakan jalan bagi kita ke Milvana.","story.map10-ending.117":"Ini sudah mulai merepotkan.","story.map10-ending.118":"Karl, <wait=40>kamu baik-baik saja?","story.map10-ending.119":"Grahdens...","story.map10-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Akulah Lucius...<br><wait=40>Dewa Gerbang ini...","story.map10-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Kamu, <rep_handlename>,<wait=39> yang telah membuka Ryvern...","story.map10-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Gunakan kekuatanku <wait=40>dan jelajahilah negeri-negeri baru...","story.map10-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Demi membawa harapan baru ke dunia tanpa tatanan ini...","story.map10-open.005":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Percayalah pada kekuatanmu, <wait=20>dan teruslah melangkah maju...","story.map10-open.006":"<size=21><rep_handlename>! <wait=40>Kenapa lama sekali!</size>","story.map10-open.007":"Membuat orang yang menyelamatkan nyawamu menunggu, seperti biasa, aku nggak percaya.","story.map10-open.008":"Terserahlah.","story.map10-open.009":"Aku akan berbaik hati menjelaskan padamu, dasar tolol.","story.map10-open.010":"Kenapa kamu menemukanku di sana, tentu saja!","story.map10-open.011":"Aku mendapat penglihatan.","story.map10-open.012":"Dengan otak jeniusku, aku bisa meramalkan kesulitan yang akhirnya akan menimpamu.","story.map10-open.013":"......","story.map10-open.014":"Kamu nggak percaya padaku, <wait=20>ya?","story.map10-open.015":"Hmph, <wait=20>terserahlah.","story.map10-open.016":"Si pak tua Grahdens.","story.map10-open.017":"Dia memintaku membuntuti kalian semua.","story.map10-open.018":"Itu permintaan langsung para Tetua Summoner kepadaku.","story.map10-open.019":"Itu bukti bahwa Balai Summoner percaya pada kekuatanku!","story.map10-open.020":"<size=21>Ha ha ha ha!</size>","story.map10-open.021":"Pokoknya, <wait=20>yang sebenarnya mereka mau adalah aku menyelamatkan Karl si gelandangan itu.","story.map10-open.022":"......","story.map10-open.023":"Kamu akan membantuku melakukannya.","story.map10-open.024":"Kamu nggak akan berani menolak keinginan orang yang sudah menyelamatkan nyawamu, kan?","story.map10-open.025":"Baiklah, aku akan berangkat ke Kekaisaran Agni.","story.map10-open.026":"Kalau informasi yang kudapat akurat, Karl ditahan di sana.","story.map10-open.027":"Ini nggak akan mudah, tapi semuanya dimulai dari kekaisaran.","story.map10-open.028":"Ini bukan saatnya ragu-ragu! Kamu dengar?","story.map10-open.029":"Oh iya!","story.map10-open.030":"Murid bernama Mare itu masih mengincarmu, kan?","story.map10-open.031":"Sebaiknya kamu berdoa supaya dia nggak berhasil menyusulmu!","story.map10-open.032":"<size=22>Ha ha ha ha!</size>","story.map11-dungeon1.001":"<rep_handlename>...<wait=40>kamu telat!! ","story.map11-dungeon1.002":"Jangan malas begitu!","story.map11-dungeon1.003":"Astaga...","story.map11-dungeon1.004":"Kenapa kamu membuat kami menunggu selama itu di tempat sepanas ini?","story.map11-dungeon1.005":"Wah, wah! <wait=20>Sepertinya kalian berdua akur sekali.","story.map11-dungeon1.006":"<speed=15><size=21>Jangan main-main denganku! Berhenti main-main denganku!</size></speed>","story.map11-dungeon1.007":"Wah...<wait=20>kalian bahkan bilang hal yang persis sama!","story.map11-dungeon1.008":"<speed=15><size=21>Kamu bilang apa?! Bilang apa kamu?!</size></speed>","story.map11-dungeon1.009":"Dewi, <wait=40>apa itu Paris dari Pengawal Kekaisaran?","story.map11-dungeon1.010":"Kumohon, jangan tambah lagi beban di pundakku...","story.map11-dungeon1.011":"Orang tua yang membesarkanku sudah cukup kesulitan...","story.map11-dungeon1.012":"Hehe... <wait=20>Maaf soal itu.","story.map11-dungeon1.013":"Dan<wait=20><rep_handlename> juga ikut datang.","story.map11-dungeon1.014":"Bisa kamu ceritakan sisanya secepat mungkin?","story.map11-dungeon1.015":"Benarkah Tetua Grahdens ditangkap oleh Zevalhua?","story.map11-dungeon1.016":"Ya, itu benar.","story.map11-dungeon1.017":"Aku tidak bisa memberi kalian banyak detail,","story.map11-dungeon1.018":"tapi aku mendapat informasi ini dari anggota Pengawal Kekaisaran yang terpercaya, jadi kebenarannya cukup tinggi.","story.map11-dungeon1.019":"Begitu ya...","story.map11-dungeon1.020":"Cih.<wait=40> Kenapa Summoner tua itu sampai harus tertangkap segala? ","story.map11-dungeon1.021":"Menyebalkan.","story.map11-dungeon1.022":"Lugy! <wait=40> Jangan ngomong begitu!","story.map11-dungeon1.023":"Kamu tahu Elder Grah bekerja keras demi kita semua!","story.map11-dungeon1.024":"Lugy?!","story.map11-dungeon1.025":"Lugy... <wait=80> Hehe...","story.map11-dungeon1.026":"Julukan yang menjijikkan...","story.map11-dungeon1.027":"Anda memang punya sifat yang tak bisa dipahami manusia, Dewi.","story.map11-dungeon1.028":"Nona Pengawal Kekaisaran, kamu salah.","story.map11-dungeon1.029":"Dia cuma agak gila, itu saja.","story.map11-dungeon1.030":"Kalian berdua jahat sekali!!!","story.map11-dungeon1.031":"Seria, <wait=40>sudah cukup, ya?","story.map11-dungeon1.032":"Kalau begini terus, kita nggak akan ke mana-mana.","story.map11-dungeon1.033":"Dan kamu...<wait=20> Boleh kami panggil Paris saja?","story.map11-dungeon1.034":"Hehe.<wait=20> Dipanggil namanya saja sudah suatu kehormatan bagiku, wahai Summoner Karl yang termasyhur.","story.map11-dungeon1.035":"Jangan mengejekku.","story.map11-dungeon1.036":"Pokoknya, kita yakin sang tetua ada di suatu tempat di Mirvana ini, kan?","story.map11-dungeon1.037":"Ya. <wait=40>Sayangnya begitu.","story.map11-dungeon1.038":"Menurutku kalau Elder Grah ditangkap Zevalhua, dia mungkin juga ada di suatu tempat di Mirvana.","story.map11-dungeon1.039":"Soalnya berkat semua usaha <rep_handlename>, ","story.map11-dungeon1.040":"satu-satunya tempat yang masih dikuasai Zevalhua hanya tempat ini.","story.map11-dungeon1.041":"Kalau begitu, <wait=40> akan lebih cepat kalau kita berpencar dan mencari tempat-tempat yang mencurigakan.","story.map11-dungeon1.042":"Sepertinya membagi kekuatan memang tak bisa dihindari, ya?","story.map11-dungeon1.043":"Kalau begitu kalian jangan menghalangiku!","story.map11-dungeon1.044":"Iya, iya. Kami sudah paham.","story.map11-dungeon1.045":"Semangat, Lugy!","story.map11-dungeon1.046":"Gadis bodoh! <wait=40>Akan kuhajar kamu sampai babak belur!","story.map11-dungeon1.047":"Sepertinya ada kerjaan bakal bikin semuanya seru lagi!","story.map11-dungeon1.048":"Merepotkan saja...","story.map11-dungeon1.049":"<rep_handlename>, <wait=40><br>kami mengandalkanmu untuk yang satu ini.","story.map11-dungeon1.050":"Tolong sang tetua dengan kekuatan yang sama yang kamu pakai untuk menolongku!","story.map11-dungeon2.001":"Hmm...","story.map11-dungeon2.002":"Sepertinya nggak ada tempat yang mencurigakan di sekitar sini...","story.map11-dungeon2.003":"Eh...?","story.map11-dungeon2.004":"Ah, Karl!","story.map11-dungeon2.005":"Halo, Dewi.","story.map11-dungeon2.006":"Kamu menemukan petunjuk di sana?","story.map11-dungeon2.007":"Sayangnya, nggak.","story.map11-dungeon2.008":"Serius deh, <wait=20>di mana sih sang tetua...?","story.map11-dungeon2.009":"Gara-gara dia melakukan hal-hal gila begini di usianya itulah dia sampai tertangkap.","story.map11-dungeon2.011":"Ah, masa. Aku tahu kamu cuma khawatir padanya, Karl.","story.map11-dungeon2.012":"Haha. Sepertinya aku memang kalah dari seorang dewi.","story.map11-dungeon2.013":"Kamu nggak perlu mengkhawatirkannya!","story.map11-dungeon2.014":"Aku yakin Elder Grah baik-baik saja!","story.map11-dungeon2.015":"Kamu juga baik-baik saja waktu tertangkap, kan?","story.map11-dungeon2.016":"Jadi sudah jelas orang yang lebih hebat seperti Elder Grah juga pasti baik-baik saja.","story.map11-dungeon2.017":"Ada beberapa bagian dari ucapan itu yang nggak bisa kusetujui...","story.map11-dungeon2.018":"Tapi biarpun aku mengkhawatirkannya, sepertinya dia nggak akan mati dalam waktu dekat.","story.map11-dungeon2.019":"Terima kasih, Dewi!","story.map11-dungeon2.020":"Tapi ini agak aneh.","story.map11-dungeon2.021":"Kamu...","story.map11-dungeon2.022":"Paris-beruang.","story.map11-dungeon2.023":"B-Beruang?!","story.map11-dungeon2.024":"Sungguh sulit mengatakan ini kepada seorang dewi, tapi...","story.map11-dungeon2.025":"...bisakah Anda tidak memanggilku \\"beruang\\" lagi?","story.map11-dungeon2.026":"Panggil saja aku \\"Paris\\". Aku tidak keberatan.","story.map11-dungeon2.027":"Oke, baiklah.","story.map11-dungeon2.028":"Jadi, Paris, sebenarnya kenapa kamu ada di sini?","story.map11-dungeon2.029":"Yah, <wait=20>aku juga sedang mencari Tetua Grahdens.","story.map11-dungeon2.030":"Jadi tidak aneh kalau aku bertemu kalian.","story.map11-dungeon2.031":"Baiklah, terserah.","story.map11-dungeon2.032":"Jadi, menurutmu apa yang aneh dari semua ini?","story.map11-dungeon2.033":"Wah, <wait=20>orang seperti Karl dari Nyonne tidak tahu apa yang kumaksud?","story.map11-dungeon2.034":"Aku nggak punya waktu untuk permainan konyolmu. Cepat katakan.","story.map11-dungeon2.035":"Hehe, <wait=20>sepertinya kamu memang berbeda dari Lugina.","story.map11-dungeon2.036":"Yah, baiklah kalau begitu.","story.map11-dungeon2.037":"Aku yakin kamu juga merasa ini aneh, bukan?","story.map11-dungeon2.038":"Kenapa para dewa menangkapnya dan membiarkannya hidup?","story.map11-dungeon2.039":"...","story.map11-dungeon2.040":"Kalau Tetua Grahdens bertarung di sisi kalian melawan Zevalhua, lalu tertangkap","story.map11-dungeon2.041":"kenapa mereka tidak punya cukup alasan untuk membunuhnya?","story.map11-dungeon2.042":"...","story.map11-dungeon2.043":"Mungkinkah semua ini menggiring kita ke dalam jebakan?","story.map11-dungeon2.044":"...","story.map11-dungeon2.045":"Bisa nggak kita pikirkan itu nanti saja?! Kita harus menyelamatkan Elder Grah!","story.map11-dungeon2.046":"Kamu benar.","story.map11-dungeon2.047":"Karl, <wait=20><rep_handlename>, ","story.map11-dungeon2.048":"sang Dewi benar. Aku juga akan melanjutkan pencarianku terhadap sang tetua.","story.map11-dungeon2.049":"Mari kita berusaha bersama.","story.map11-dungeon2.050":"Iya, kamu benar juga. Terima kasih atas bantuanmu.","story.map11-dungeon2.051":"Hehe, <wait=20>lagi pula mungkin Grahdens bisa menjawab teka-teki kecil itu untuk kita.","story.map11-dungeon2.052":"Iya, mungkin saja...","story.map11-dungeon2.053":"Hehe...","story.map11-dungeon3.001":"Oh, <wait=20><rep_handlename>.","story.map11-dungeon3.002":"Apa kamu sedang sendirian?","story.map11-dungeon3.003":"Hehe, <wait=20>aku kasihan pada semua Summoner yang dilindungi Dewi itu.","story.map11-dungeon3.004":"Waktu itu aku tidak sempat mendengar jawabanmu gara-gara Lugina, tapi","story.map11-dungeon3.005":"bukan berarti aku sudah menyerah padamu.","story.map11-dungeon3.006":"Aku senang bisa bertarung bersamamu lagi seperti ini.","story.map11-dungeon3.007":"Karena itulah--","story.map11-dungeon3.008":"<size=23>Nggak boleh!!!</size>","story.map11-dungeon3.009":"<size=21>Paris! <wait=20><br>Hentikan!</size>","story.map11-dungeon3.010":"<size=21><rep_handlename> itu Summoner-ku!</size>","story.map11-dungeon3.011":"Ah, jadi <rep_handlename> adalah Summoner Anda?","story.map11-dungeon3.012":"Yah, <wait=20>lalu apa sebenarnya maksudnya?","story.map11-dungeon3.013":"<size=20>Maksudnya persis seperti yang kamu dengar!</size>","story.map11-dungeon3.014":"<size=20><rep_handlename> itu Summoner-ku! <wait=20> Titik!</size>","story.map11-dungeon3.015":"B-<wait=20>Begitu ya...","story.map11-dungeon3.016":"<rep_handlename>...<wait=40><br>kamu <wait=20>sedang menanggung banyak hal sekarang, ya?","story.map11-dungeon3.017":"Yah, <wait=20>bagaimanapun, kita akan mengobrol lagi nanti.","story.map11-dungeon3.018":"Untuk sekarang aku akan pergi mencari Tetua Grahdens.","story.map11-dungeon3.019":"Seharusnya akan ada informasi baru juga, jadi tolong perhatikan baik-baik.","story.map11-dungeon3.020":"Ah! <wait=40>Paris, itu curang!","story.map11-dungeon3.021":"Aku nggak akan kalah darimu, tahu!","story.map11-dungeon3.022":"<rep_handlename>!","story.map11-dungeon3.023":"Akan kutunjukkan padanya bahwa dewi cantik nan tak terkalahkan inilah yang akan menemukanmu, Elder Grah!","story.map11-dungeon3.024":"Jadi jangan khawatir, tunggu saja aku!","story.map11-dungeon3.025":"<rep_handlename>, <wait=40><br>aku sungguh kasihan padamu....","story.map11-dungeon4.001":"Cih, kamu rupanya.","story.map11-dungeon4.002":"Kalau kamu masih berkeliaran di sini, berarti kamu masih sama bodohnya seperti biasa.","story.map11-dungeon4.003":"Hah? <wait=40>Kamu bilang kita berdua masih di tempat yang sama?","story.map11-dungeon4.004":"Cih, <wait=20>makanya aku benci orang tolol.","story.map11-dungeon4.005":"Aku punya alasan yang jelas kenapa aku ada di sini.","story.map11-dungeon4.006":"Tapi yang lebih penting, <rep_handlename>.","story.map11-dungeon4.007":"Hati-hati sekali dengan si Pengawal Kekaisaran itu, Paris.","story.map11-dungeon4.008":"Perempuan itu, <wait=20>dia pasti sedang merencanakan sesuatu.","story.map11-dungeon4.009":"Katanya bangsawan Kekaisaran Randall bekerja sama dengan Balai Summoner Akras dan semacamnya...","story.map11-dungeon4.010":"itu sama sekali nggak mungkin benar.","story.map11-dungeon4.011":"Dan aku yakin dia juga punya alasan di balik ketertarikannya padamu...","story.map11-dungeon4.012":"<size=23>Hei, para tolol!</size>","story.map11-dungeon4.013":"<size=23>Kenapa kalian cuma berdiri di situ?!</size>","story.map11-dungeon4.014":"Cih, sekarang malah datang perempuan yang lebih menyebalkan.","story.map11-dungeon4.015":"<size=20>Siapa yang kamu sebut perempuan menyebalkan?!</size>","story.map11-dungeon4.016":"<size=16>Ini bukan waktunya mengoceh! Tetua Grahdens butuh bantuan kita!</size>","story.map11-dungeon4.017":"Kalian akrab sekali sampai aku merinding...","story.map11-dungeon4.018":"<size=21>Siapa yang kamu sebut akrab?! <wait=40><br>Tolol!</size>","story.map11-dungeon4.019":"<size=22>Siapa yang kamu sebut tolol?!</size>","story.map11-dungeon4.020":"<size=21>Jangan sok hebat, padahal tadi kepalamu nyangkut di tanah!</size>","story.map11-dungeon4.021":"Grr, <wait=20>itu salah Dewi aneh itu...","story.map11-dungeon4.022":"Lugy, kamu harus berusaha sedikit lebih keras!","story.map11-dungeon4.023":"<size=23>Akan kuhajar gadis bodoh ini habis-habisan!</size>","story.map11-dungeon4.024":"<size=21>Hei, <rep_handlename>!</size>","story.map11-dungeon4.025":"<size=21>Mau kabur ke mana kamu?!</size>","story.map11-dungeon4.026":"<size=18>Tunggu, <rep_handlename>! Mau ke mana?!</size>","story.map11-dungeon4.027":"<size=16>Jangan tinggalkan aku dengan dua orang aneh ini!</size>","story.map11-dungeon4.028":"<size=14>Aku nggak tahu apa yang bakal mereka lakukan padaku!</size>","story.map11-dungeon4.029":"<size=12>Memangnya aku mau melakukan apa padamu!</size>","story.map11-dungeon4.030":"<size=10>Dan apa maksudnya itu?!</size>","story.map11-dungeon4.031":"<size=9>Kamu nggak ngerti?!</size><wait=20><br><size=9>Dasar bodoh!</size>","story.map11-dungeon4.032":"<size=8>Diam!</size><wait=20><br><size=8>Dasar pecundang!</size>","story.map11-dungeon5.001":"<rep_handlename>!!<wait=40> Dengar, dengar!!","story.map11-dungeon5.002":"Aku tahu <wait=20>di mana Elder Grah!","story.map11-dungeon5.003":"Jadi, umm... <wait=20>Sepertinya dia ada di tempat bernama \\"Menara Para Dewa\\".","story.map11-dungeon5.004":"Zevalhua menjadikan Menara Para Dewa sebagai markasnya.","story.map11-dungeon5.005":"Jadi, singkatnya, <wait=20>kalau kita pergi ke menara itu","story.map11-dungeon5.006":"kita bisa mengalahkan Zevalhua, <wait=20>sekaligus menyelamatkan Elder Grah.","story.map11-dungeon5.007":"Jadi bilang pada Karl dan yang lain untuk menuju Menara Para Dewa!","story.map11-dungeon5.008":"Memang sudah kuduga dari pelayan Lord Lucius, Nona Tilith.","story.map11-dungeon5.009":"Ah, <wait=20>Paris!","story.map11-dungeon5.010":"Hehehe, <wait=20>aku memang hebat, kan?","story.map11-dungeon5.011":"Ya, tentu.<wait=20><br>Memang pantas untuk seorang dewi.","story.map11-dungeon5.012":"Tapi <wait=20>bagaimana Anda menemukan lokasi Tetua Grahdens?","story.map11-dungeon5.013":"Yah...","story.map11-dungeon5.014":"Ada pelayan Lord Lucius yang lain, sepertiku, yang sedang mengawasi Zevalhua.","story.map11-dungeon5.015":"Pelayan itu pergi ke Menara Para Dewa, lalu melaporkan melihat seorang pria tua terkurung di sebuah ruangan di sana.","story.map11-dungeon5.016":"Begitu. <wait=20><br>Sekarang aku mengerti...","story.map11-dungeon5.017":"Lord Lucius <wait=20>terus mengumpulkan banyak pelayan dewa yang hebat!","story.map11-dungeon5.018":"Tentu saja, aku juga termasuk di dalamnya.","story.map11-dungeon5.019":"Ya, aku tahu betul Anda memiliki kekuatan yang luar biasa, Dewi.","story.map11-dungeon5.020":"Tapi, <wait=20>itu aneh.","story.map11-dungeon5.021":"Eh? <wait=20>Apanya?","story.map11-dungeon5.022":"Kalau dia punya begitu banyak makhluk ilahi yang hebat di pihaknya,","story.map11-dungeon5.023":"kenapa dia tidak memburu sendiri para Dewa yang Jatuh?","story.map11-dungeon5.024":"Umm, <wait=20>yah...","story.map11-dungeon5.025":"Dan juga, <wait=20>utusan dewa utama,","story.map11-dungeon5.026":"Kaisar Suci Karna Masta, dia juga membuatku penasaran.","story.map11-dungeon5.027":"Meski Grand Gaia sedang dalam masalah, dia tidak menunjukkan tanda-tanda ingin berbuat apa-apa.","story.map11-dungeon5.028":"Kalau Lord Lucius dan Karna Masta bekerja sama, mereka tidak butuh kami manusia.","story.map11-dungeon5.029":"Rasanya mereka bisa dengan mudah mengalahkan dua Dewa yang Jatuh yang tersisa sendirian.","story.map11-dungeon5.030":"Yah... <wait=40><br>Eh, <wait=20>umm...","story.map11-dungeon5.031":"Mungkinkah Lord Lucius dan yang lainnya tidak bisa bergerak bebas sendiri?","story.map11-dungeon5.032":"Misalnya, <wait=20>mungkin setelah dikalahkan Empat Dewa yang Jatuh dulu, dia disegel oleh suatu kekuatan, atau--","story.map11-dungeon5.033":"Bu... <wait=20>Bukan begitu!","story.map11-dungeon5.034":"Lord Lucius baik-baik saja, kok!","story.map11-dungeon5.035":"Aku nggak bisa menceritakan semuanya, tapi sekarang dia memang belum bisa bergerak...","story.map11-dungeon5.036":"Dan...<wait=20>Dan Karna Masta juga punya masalah yang sama!","story.map11-dungeon5.037":"Tapi bukan berarti mereka disegel di suatu tempat!","story.map11-dungeon5.038":"Maafkan aku.","story.map11-dungeon5.039":"Mohon maafkanlah manusia bodoh yang penuh curiga ini.","story.map11-dungeon5.040":"Orang bodoh sepertiku tak mungkin memahami gagasan agung para dewa.","story.map11-dungeon5.041":"Aku hanyalah orang yang selalu ketakutan.","story.map11-dungeon5.042":"Nggak, <wait=20>nggak apa-apa.","story.map11-dungeon5.043":"Aku nggak menyangka kamu akan menanyakan hal seperti itu, jadi aku kaget.","story.map11-dungeon5.044":"Kata-kata Anda saja sudah sangat membantuku.","story.map11-dungeon5.045":"Nah, <wait=20>sebaiknya kita berangkat menyelamatkan Tetua Grahdens.","story.map11-dungeon5.046":"Sepertinya Karl dan yang lain baru saja berangkat lebih dulu, menuju kota reruntuhan Mirvana.","story.map11-dungeon5.047":"O-<wait=20>Oke. <wait=40><br>Benar juga!","story.map11-dungeon5.048":"Kita harus memberi tahu Karl dan yang lain di mana Elder Grah secepat mungkin!","story.map11-dungeon5.049":"Baiklah, <rep_handlename>! <wait=40> Ayo berangkat!","story.map11-dungeon6.001":"Ah, <wait=20>Karl!","story.map11-dungeon6.002":"Halo, <wait=20>Dewi dan <rep_handlename>.","story.map11-dungeon6.003":"Kami sudah menunggu kalian.","story.map11-dungeon6.004":"Sepertinya kalian sudah tahu di mana Tetua Grahdens, ya?","story.map11-dungeon6.005":"Terima kasih banyak.","story.map11-dungeon6.006":"Eh, <wait=20>kok kamu tahu?","story.map11-dungeon6.007":"Paris mampir tadi <wait=20>dan memberi tahu kami.","story.map11-dungeon6.008":"Apaaa?!<wait=40> Paris, dasar bodoh!!","story.map11-dungeon6.009":"Padahal aku yang mau memberi mereka kejutan!!","story.map11-dungeon6.010":"Tapi, <wait=20>di mana Paris sekarang?","story.map11-dungeon6.011":"Iya, <wait=20>katanya ada sesuatu yang membuatnya penasaran, jadi dia berangkat ke Menara Para Dewa lebih dulu.","story.map11-dungeon6.012":"Begitu ya...","story.map11-dungeon6.013":"Kira-kira apa <wait=20> yang membuatnya begitu penasaran...?","story.map11-dungeon6.014":"Dewi, <wait=40>ada apa?","story.map11-dungeon6.015":"Wajahmu kelihatan kurang sehat.<wait=20> Ada sesuatu yang terjadi?","story.map11-dungeon6.016":"N-<wait=20>Nggak, nggak ada apa-apa!","story.map11-dungeon6.017":"Aku selalu bersemangat, kok!","story.map11-dungeon6.018":"Iya kan, <wait=20><rep_handlename>?","story.map11-dungeon6.019":"Baiklah.","story.map11-dungeon6.020":"Yah, <wait=20>setelah kita menyelamatkan Tetua Grahdens, aku berencana membuatnya menceritakan semuanya.","story.map11-dungeon6.021":"Pak tua itu... <wait=20>Aku punya firasat dia masih menyembunyikan banyak hal dari kita.","story.map11-dungeon6.022":"Membebaskan sang Dewi dari kekhawatirannya mungkin akan berguna bagi kita dalam jangka panjang.","story.map11-dungeon6.023":"Karl memang orang yang baik.","story.map11-dungeon6.024":"Tapi ya, begitulah teman-teman <rep_handlename>!","story.map11-dungeon6.025":"Haha. <wait=20>Kalau kamu bilang begitu di depanku, aku jadi agak malu.","story.map11-dungeon6.026":"Oh iya, <wait=20>ganti topik nih, tapi...","story.map11-dungeon6.027":"Bagaimana kabar hal itu?","story.map11-dungeon6.028":"Hal itu...?","story.map11-dungeon6.029":"Yah, <wait=20>sama seperti biasanya. <wait=40><br>Jadi, jangan khawatir soal itu...","story.map11-dungeon6.030":"Begitu ya! <wait=20><br>Jadi, masih sama seperti biasa, ya?","story.map11-dungeon6.031":"Kalau begitu, <wait=20>aku nggak akan khawatir.","story.map11-dungeon6.032":"Sudah kubilang! <wait=20>Aku yang bakal pertama sampai di Menara Para Dewa!","story.map11-dungeon6.033":"Belum tentu!","story.map11-dungeon6.034":"Kamu jaga di pintu masuk saja sebagai pengintai!","story.map11-dungeon6.035":"<size=18>Kenapa harus aku yang berjaga?!</size>","story.map11-dungeon6.036":"Karena itu tugas yang pas untuk gadis bodoh sepertimu.","story.map11-dungeon6.037":"<size=18>Aku nggak bodoh!</size>","story.map11-dungeon6.038":"Lagi pula, berjaga itu tetap tugas yang penting!","story.map11-dungeon6.039":"Kalau kamu nggak paham itu, kamu bakal gagal di banyak misi nanti!","story.map11-dungeon6.040":"<size=18>Kamu bilang apa barusan?!</size>","story.map11-dungeon6.041":"Kalau berjaga itu tugas sepenting itu, kenapa nggak kamu saja yang melakukannya?!","story.map11-dungeon6.042":"Itu dua hal yang berbeda!","story.map11-dungeon6.043":"Astaga. <wait=20>orang-orang ini benar-benar bikin aku tegang...","story.map11-dungeon7.001":"Akhirnya, <wait=40><br><rep_handlename>!","story.map11-dungeon7.002":"Elder Grah ada di sini,","story.map11-dungeon7.003":"begitu juga salah satu dari Empat Dewa yang Jatuh, \\"Sang Kaisar Ilahi Zevalhua.\\"","story.map11-dungeon7.004":"Aku bisa merasakan kekuatan yang luar biasa di luar sana...","story.map11-dungeon7.005":"Yah, nggak mengejutkan kalau itu dari salah satu Dewa yang Jatuh.","story.map11-dungeon7.006":"Cih, <wait=20>aku nggak peduli sebesar apa dia, kalau dia bikin aku kesal, akan kuhancurkan jadi berkeping-keping.","story.map11-dungeon7.007":"Tapi hei, <wait=20>di mana nona Pengawal Kekaisaran itu?","story.map11-dungeon7.008":"Sepertinya dia nggak ada di sekitar sini.","story.map11-dungeon7.009":"Hah, <wait=20>ternyata prajurit Pasukan Kekaisaran Randall memang nggak bisa diandalkan.","story.map11-dungeon7.010":"Tapi, <wait=20>dia juga punya misinya sendiri yang harus diurus.","story.map11-dungeon7.011":"Sepertinya dia sibuk ke sana kemari mengurus banyak hal.","story.map11-dungeon7.012":"Dia bahkan tertarik dengan alasan sang Tetua ditangkap...","story.map11-dungeon7.013":"Karl!","story.map11-dungeon7.014":"Kita nggak punya waktu untuk memikirkan hal itu sekarang!","story.map11-dungeon7.015":"Kita harus cepat menyelamatkan Elder Grah sebelum terlambat!","story.map11-dungeon7.016":"Kamu benar. <wait=40><br>Persis seperti yang dikatakan sang Dewi.","story.map11-dungeon7.017":"Nggak ada gunanya memikirkannya sekarang!","story.map11-dungeon7.018":"Kalau begitu, <wait=20>ayo berpencar dan cari sang Tetua!","story.map11-dungeon7.019":"Sebenarnya aku ingin kita semua berkumpul kembali sebelum melawan Zevalhua, tapi","story.map11-dungeon7.020":"tergantung situasinya, mungkin kita nggak bisa. Kalau terpaksa, kita mungkin harus melawannya sendirian.","story.map11-dungeon7.021":"Nggak masalah.","story.map11-dungeon7.022":"Meskipun ternyata itu bukan yang asli, atau ternyata jebakan, aku tetap akan bertarung!","story.map11-dungeon7.023":"Hah! <wait=20>Aku memang nggak pernah berharap banyak soal kekuatan kalian.","story.map11-dungeon7.024":"<rep_handlename>, <wait=20>kami mengandalkan kekuatanmu lagi.","story.map11-dungeon7.025":"Baiklah, <wait=20>jangan sampai kalian mati di luar sana!","story.map11-dungeon7.026":"Ini...","story.map11-dungeon7.027":"Sepertinya aku nggak punya pilihan selain mengubah rencana awalku...","story.map11-ending.001":"Kita berhasil, <wait=40><br><rep_handlename>!","story.map11-ending.002":"Kamu bahkan mengalahkan Zevalhua! Kamu luar biasa, <rep_handlename>!","story.map11-ending.003":"Lalu Karl dan sang Tetua...","story.map11-ending.005":"*Hah* *hah* *hah* <wait=40><br><rep_handlename>...","story.map11-ending.006":"*Fuh*<wait=40><br>*Hah*","story.map11-ending.007":"Wah, kamu berhasil!","story.map11-ending.008":"Aku merasakan kekuatan dahsyat itu makin kuat, jadi aku bergegas ke sini,","story.map11-ending.009":"tapi sepertinya aku nggak perlu lari-lari juga...","story.map11-ending.010":"Sial, <wait=20>sepertinya aku nggak sempat.","story.map11-ending.011":"<rep_handlename>!","story.map11-ending.012":"Dasar kamu, <wait=20>kamu bersenang-senang sendirian, ya?!","story.map11-ending.013":"Itulah kenapa aku nggak suka kamu!","story.map11-ending.014":"Oh, <wait=20>sepertinya semuanya selamat tanpa luka!","story.map11-ending.015":"<rep_handlename>!","story.map11-ending.016":"Aku tahu kamu pasti mengalahkan Zevalhua! Lagi pula, kamu kan temanku.","story.map11-ending.017":"Aku lega melihat semuanya selamat.","story.map11-ending.018":"Jadi, <wait=20>kalian berhasil menemukan Elder Grah?","story.map11-ending.019":"Dia nggak ada di sini?","story.map11-ending.020":"Dia nggak ada di ruangan lain","story.map11-ending.021":"jadi aku yakin dia ada di sini, karena cuma ruangan ini yang belum diperiksa. Makanya aku lari ke sini.","story.map11-ending.022":"Ugh, <wait=20>sekarang kita harus mengurus hal menyebalkan lagi.","story.map11-ending.023":"Semoga Tetua Grahdens <wait=20>selamat di suatu tempat...","story.map11-ending.024":"Oh, <wait=20>maaf Karl. <wait=20> Aku nggak bermaksud bilang begitu...","story.map11-ending.025":"Nggak, nggak apa-apa.","story.map11-ending.026":"Nggak ada jejak yang menunjukkan <wait=20>dia pernah datang ke sini, jadi","story.map11-ending.027":"mungkin dia berhasil kabur sendiri.","story.map11-ending.028":"Ho ho ho. <wait=40><br>Tepat sekali.","story.map11-ending.029":"Suara itu!","story.map11-ending.030":"Elder Grah!","story.map11-ending.031":"Ho ho ho.","story.map11-ending.032":"Sepertinya aku sudah banyak merepotkan kalian semua.","story.map11-ending.033":"Tetua Grahdens...","story.map11-ending.034":"Jangan pasang wajah kekanak-kanakan begitu.","story.map11-ending.035":"Mungkin aku sudah membuatmu khawatir, <wait=20><br>tapi aku belum jadi lemah.","story.map11-ending.036":"S-Siapa yang khawatir padamu?!","story.map11-ending.037":"Lagi pula, <wait=20>apa yang kamu lakukan selama ini, dan di mana?!","story.map11-ending.038":"Jelaskan pada semua orang kenapa kami harus repot mencarimu!","story.map11-ending.039":"Hmph, <wait=20>yah, aku memang berbuat salah.","story.map11-ending.040":"Ada sesuatu tentang menara ini yang mengganjal pikiranku, <wait=20>sedikit saja.","story.map11-ending.041":"Aku berpura-pura ditangkap oleh Dewa yang Jatuh bernama Mare-entah-siapa itu, dan membiarkannya membawaku ke sini.","story.map11-ending.042":"Mungkin <wait=20>dia berharap dengan menangkapku, dia bisa unggul atas kalian semua dalam pertempuran.","story.map11-ending.043":"Tapi sebelum Mare sempat memanfaatkannya, dia sudah kalian kalahkan.","story.map11-ending.044":"Karena dia sudah mendapat pengetahuan tentang Zevalhua dan Afla Dilith setelah bertarung dengan mereka","story.map11-ending.045":"aku nggak ingin melawannya sendiri.","story.map11-ending.046":"Dan benar saja, <wait=20>membiarkannya menangkapku membuat kalian datang membantu.","story.map11-ending.047":"Berkat itu, aku punya cukup waktu untuk melakukan penelitianku dengan tenang.","story.map11-ending.048":"Kalau begitu, <wait=20>harusnya kamu bilang saja pada kami.","story.map11-ending.049":"Dasar kakek tua merepotkan.","story.map11-ending.050":"Ho ho ho. <wait=40>Maaf soal itu, Lugina.","story.map11-ending.051":"Aku berutang budi atas tindakanmu.","story.map11-ending.052":"Akan kuberi kamu imbalan yang pantas.","story.map11-ending.053":"Tentu saja harus.","story.map11-ending.054":"Dan bukan cuma itu, <wait=20>kamu juga harus memberi tahu orang-orang penting lainnya <wait=20>tentang semua yang sudah kulakukan.","story.map11-ending.055":"Serius deh, <wait=20>orang itu benar-benar nggak punya kelas.","story.map11-ending.056":"Lihat dirimu sendiri!","story.map11-ending.057":"Jadi, <wait=20>Tetua.<wait=40> Kamu tahu apa yang ingin kutanyakan, kan?","story.map11-ending.058":"Hmph. <wait=40>Tentang asal-usulmu, benar?","story.map11-ending.059":"Itu tertulis di surat wasiatku. Nggak bisakah kamu menunggu sampai saat itu untuk membacanya?","story.map11-ending.060":"Nggak bisa.","story.map11-ending.061":"Ho ho ho. <wait=40>Aku cuma bercanda. <wait=20>Nggak perlu marah begitu.","story.map11-ending.062":"Tapi, <wait=20>sebenarnya itu bukan rahasia besar.","story.map11-ending.063":"Karl.","story.map11-ending.064":"Aku menemukanmu saat masih bayi dan membesarkanmu. Kamu tahu itu, kan?","story.map11-ending.065":"Ya, <wait=20>dan aku berterima kasih untuk itu.","story.map11-ending.066":"Tapi, <wait=20>apa ada yang istimewa dari tempat kamu menemukanku?","story.map11-ending.067":"Hmph. <wait=20><br>Yah, ada.","story.map11-ending.068":"Kurasa kamu sendiri mungkin samar-samar merasakannya, <wait=20><br>tapi aku menemukanmu di Grand Gaia.","story.map11-ending.069":"Tunggu, <wait=20>apa?!","story.map11-ending.070":"Cih, <wait=20>jadi begitu ceritanya.","story.map11-ending.071":"...","story.map11-ending.072":"Tapi, <wait=20>bukannya nggak ada manusia yang selamat di Grand Gaia...?","story.map11-ending.073":"Bahkan aku sendiri nggak memahaminya.","story.map11-ending.074":"Aku cuma datang ke sini bersama Summoner lain, dan saat menyurvei daerah ini","story.map11-ending.075":"kami menemukan seorang bayi di reruntuhan Mistral.","story.map11-ending.076":"Lalu, <wait=40>kami membawanya kembali ke Elgaia.","story.map11-ending.077":"Cuma itu saja.","story.map11-ending.078":"Aku sama sekali nggak tahu makhluk seperti apa sebenarnya bayi itu.","story.map11-ending.079":"Karl.","story.map11-ending.080":"Aku nggak tahu apakah kamu anak yatim yang selamat dari Grand Gaia, ","story.map11-ending.081":"atau anak para dewa.","story.map11-ending.082":"Namun--","story.map11-ending.083":"Tetua. <wait=40><br>Kamu nggak perlu bilang apa-apa lagi.","story.map11-ending.084":"Karena aku benar-benar berterima kasih padamu, dan pada semua Summoner lainnya.","story.map11-ending.085":"...","story.map11-ending.086":"Karl...","story.map11-ending.087":"Wah, ternyata Karl menyimpan rahasia seperti itu, ya?","story.map11-ending.088":"Hmm... <wait=40>Seorang bayi yang ditinggalkan di Grand Gaia.","story.map11-ending.089":"Aku belum pernah dengar yang seperti itu.","story.map11-ending.090":"Apa Lord Lucius tahu sesuatu soal itu, ya?","story.map11-ending.091":"Kurasa <wait=20>aku akan pergi menanyakannya!","story.map11-ending.092":"<rep_handlename>!","story.map11-ending.093":"Nah, tinggal satu Dewa yang Jatuh lagi yang harus kita hadapi, yaitu Dewa Buas Afla Dilith!","story.map11-ending.094":"Aku yakin kita bisa mengalahkannya kalau kita bekerja sama!","story.map11-ending.095":"Dan tentu saja, <wait=20>kami juga mengandalkan kekuatanmu sebagai Summoner, <rep_handlename>.","story.map11-ending.096":"Kalau begitu, <wait=20>aku pergi tanya soal Karl dulu, nanti aku kabari kalian!","story.map11-ending.097":"Oh, <wait=20>tunggu! <wait=20><br>Dewi!","story.map11-ending.098":"Padahal aku ingin bilang kalau aku nggak terlalu peduli...","story.map11-ending.099":"Dia memang nggak pernah mendengarkan, ya?","story.map11-ending.100":"Ho ho ho. <wait=40><br>Itu karena Tilith gadis yang baik hati.","story.map11-ending.101":"Jadi, <wait=20>apa yang akan kita lakukan soal hawa jahat yang muncul setelah sang Dewi pergi?","story.map11-ending.102":"Aku sangat keras terhadap hawa jahat.","story.map11-ending.103":"Kamu...","story.map11-ending.104":"Aku Eriole.","story.map11-ending.105":"Aku berasal dari Kekaisaran Randall,","story.map11-ending.106":"dan menjabat sebagai komandan Pengawal Kekaisaran, yang melindungi keluarga kekaisaran.","story.map11-ending.107":"Heh, <wait=20>aku pernah dengar rumor tentang nama itu.","story.map11-ending.108":"Katanya dia orang licik yang jadi orang termuda yang pernah memegang gelar komandan.","story.map11-ending.109":"Kurang ajar!","story.map11-ending.110":"Oh, <wait=20>nona yang terlalu takut menghadapi Empat Dewa yang Jatuh sudah kembali!","story.map11-ending.111":"Pria ini adalah--","story.map11-ending.112":"Paris, mundurlah sedikit.","story.map11-ending.113":"Apa? <wait=20>T-<wait=20>Tapi--","story.map11-ending.114":"Paris.","story.map11-ending.115":"B-<wait=20>Baik...","story.map11-ending.116":"Jadi, <wait=20>sebenarnya apa yang diinginkan komandan Pengawal Kekaisaran dari kami?","story.map11-ending.117":"Aku juga akan berterima kasih kalau kamu bisa menjelaskan siapa orang menyeramkan di belakangmu itu.","story.map11-ending.118":"...","story.map11-ending.119":"Orang ini rekanku. <wait=40><br>Jangan khawatirkan dia.","story.map11-ending.120":"Kalian pasti sudah mendengar banyak hal dari bawahanku, Paris.","story.map11-ending.121":"Aku ingin berbicara dengan kalian setidaknya sekali","story.map11-ending.122":"tapi sebagai utusan Kaisar Randall","story.map11-ending.123":"kali ini aku datang khusus untuk berbicara dengan Summoner Grahdens.","story.map11-ending.124":"Ho ho ho.","story.map11-ending.125":"Kalau cuma ingin bicara denganku, <wait=20>kamu nggak perlu jauh-jauh datang ke sini, lho.","story.map11-ending.126":"Ha ha ha.","story.map11-ending.127":"Kami punya alasan sendiri melakukan ini.","story.map11-ending.128":"Akan kami jelaskan secara rinci nanti.","story.map11-ending.129":"Kamu berniat membawa sang Tetua bersamamu?","story.map11-ending.130":"Kamu pikir dia akan ikut begitu saja?","story.map11-ending.131":"Tolong jangan salah paham.","story.map11-ending.132":"Kami datang ke sini bukan untuk bertarung.","story.map11-ending.133":"Aku tahu itu.","story.map11-ending.134":"Lagi pula, kalau terjadi sesuatu padaku, kalian sendiri yang akan sangat repot.","story.map11-ending.135":"...","story.map11-ending.136":"Semuanya, <wait=20>permisi. <wait=40><br>Aku akan berbincang sebentar dengan orang-orang ini.","story.map11-ending.137":"Aku ingin berterima kasih pada kalian semua dengan layak, tapi sepertinya harus menunggu lain kali.","story.map11-ending.138":"Karl.","story.map11-ending.139":"Kali ini aku senang melihat<wait=20> betapa kamu sudah tumbuh dewasa.","story.map11-ending.140":"Tetua Grahdens...","story.map11-ending.141":"Dan kamu, <rep_handlename>.","story.map11-ending.142":"Kerja bagus mengalahkan Zevalhua.","story.map11-ending.143":"Namun, <wait=20>berikutnya kamu akan menghadapi Afla Dilith.","story.map11-ending.144":"Dan tidak seperti Dewa yang Jatuh lainnya, aku yakin dia sudah siap bertarung melawanmu.","story.map11-ending.145":"Aku yakin itu akan jadi pertempuran yang sulit, tapi kamu harus menantang dirimu sendiri dan teman-temanmu.","story.map11-ending.146":"Satu lagi, <wait=20>aku titipkan Karl padamu.","story.map11-ending.147":"Mungkin kamu sudah tahu, tapi","story.map11-ending.148":"dia masih kurang di sana-sini, jadi aku khawatir padanya.","story.map11-ending.149":"Aku nggak butuh siapa pun untuk menjagaku...","story.map11-ending.150":"Ho ho ho.","story.map11-ending.151":"Nah, utusan Kekaisaran Randall, <wait=40><br>bagaimana kalau kita berangkat?","story.map11-ending.152":"Terima kasih<wait=20> atas pertimbangan dan pengertian Anda.","story.map11-ending.153":"Paris, <wait=40>ayo pergi.","story.map11-ending.154":"Siap, Tuan!","story.map11-ending.155":"Dia pergi begitu saja, ya?","story.map11-ending.156":"Karena ini Tetua Grahdens, aku yakin dia akan baik-baik saja. Tapi, tetap saja...","story.map11-ending.157":"Hmph. <wait=20>orang-orang Kekaisaran Randall itu nggak akan bisa menyentuh Summoner tua itu.","story.map11-ending.158":"Kamu benar.","story.map11-ending.159":"Lagi pula ini Tetua Grahdens. <wait=40><br>Dia pasti baik-baik saja.","story.map11-ending.160":"Yang lebih penting, <wait=20>kita harus fokus pada apa yang bisa kita bantu dari pihak kita.","story.map11-ending.161":"<rep_handlename>,","story.map11-ending.162":"kamu akan melawan Afla Dilith, <wait=20> yang terakhir dari Empat Dewa yang Jatuh, <wait=20>kan?","story.map11-ending.163":"Sebenarnya aku dan Seria ingin membantumu, tapi kami juga nggak bisa mengabaikan iblis Graham.","story.map11-ending.164":"Benar juga! <wait=40><br>Aku benar-benar lupa soal dia!","story.map11-ending.165":"Kalau kita nggak mengalahkannya...","story.map11-ending.166":"<rep_handlename>!","story.map11-ending.167":"Kita harus berpisah, <wait=20><br>tapi kamu pasti baik-baik saja, kan?","story.map11-ending.168":"Kami akan mengalahkan Graham lalu segera kembali, jadi jaga dirimu!","story.map11-ending.169":"Wah, wah... <wait=20>Ternyata iblis hebat Seria juga punya sisi baik.","story.map11-ending.170":"Bo-- <wait=20>Bodo-- <wait=20>Memang itu yang harus diucapkan di saat seperti ini!","story.map11-ending.171":"Hei, <rep_handlename>!","story.map11-ending.172":"Jangan coba-coba mengambil semua pujian <wait=20>karena mengalahkan Zevalhua sendirian.","story.map11-ending.173":"Jangan lupakan juga semua hal <wait=40><br>yang sudah kulakukan.","story.map11-ending.174":"Lain kali aku mau menyelamatkanmu atau nggak, mungkin tergantung seberapa berterima kasih kamu padaku.","story.map11-ending.175":"Haha, <wait=20>Lugina memang begitu.","story.map11-ending.176":"<rep_handlename>, <wait=40><br>kami harus berangkat sekarang.","story.map11-ending.177":"Kalau kamu bertemu sang Dewi lagi, tolong sampaikan bahwa aku sangat berterima kasih atas bantuannya.","story.map11-ending.178":"Dan <wait=20>kalau kamu mendengar sesuatu tentangku dan ingin membicarakannya denganku, terserah kamu.","story.map11-ending.179":"Karena kalau kamu yang memberitahuku, <wait=20>aku yakin aku sanggup menerima kebenaran apa pun.","story.map11-ending.180":"Kalau begitu, <wait=20>sampai jumpa lagi lain kali.","story.map11-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Akulah Lucius...<wait=40><br>Dewa Gerbang ini...","story.map11-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Pembebas Agni...<wait=40><br><rep_handlename>...","story.map11-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Gunakanlah kekuatanku...<wait=40><br>dan berangkatlah menuju negeri baru...","story.map11-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>demi membawa sabda kami<wait=40><br>ke dunia yang jatuh dalam kekacauan ini...","story.map11-open.005":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Percayalah pada dirimu<wait=20><br>dan teruslah melangkah maju...","story.map11-open.006":"<rep_handlename>! <wait=40><br>Sudah waktunya!","story.map11-open.007":"Inilah Mirvana, wilayah yang dijadikan markas oleh Zevalhua selama perang melawan para dewa.","story.map11-open.008":"Sepertinya karena itulah <wait=20>wilayah Agni menjadi medan perang terbesar dalam perang itu.","story.map11-open.009":"Pemandangan di sekitar sini suram sekali...","story.map11-open.010":"Oh! <wait=20>Maaf, maaf!","story.map11-open.011":"Ini bukan saatnya untuk jadi sentimental!","story.map11-open.013":"Nah, <wait=20>ayo kalahkan Zevalhua dan selamatkan Elder Grah!","story.map11-open.014":"Aku tahu kami pasti bisa mengandalkanmu, <rep_handlename>. Aku percaya padamu!","story.map2-dungeon1.001":"<size=22>Lho?! <rep_handlename>!!","story.map2-dungeon1.002":"Masa, <wait=20>aku tak pernah menyangka kita bakal bertemu di tempat seperti ini!","story.map2-dungeon1.003":"Begitu, <wait=40>kamu juga mau ke Menara Morgan, ya?","story.map2-dungeon1.004":"Kamu pasti juga bersama Pasukan Summoner yang memburu Empat Dewa yang Jatuh...","story.map2-dungeon1.005":"Bukan? <wait=40>Tilith yang menyuruhmu datang?","story.map2-dungeon1.006":"Ah, <wait=20>dia pasti gadis yang pernah kamu ceritakan itu.","story.map2-dungeon1.007":"Sepertinya kamu dirawat dengan baik.  <wait=20>Aku harus sopan dan menyapanya kalau bertemu nanti. <wait=19>Kenalkan kami, ya?","story.map2-dungeon1.008":"Hah? <wait=20>Dia tidak di sini? <wait=40>Kamu juga sedang mencarinya?","story.map2-dungeon1.009":"Hmm... <wait=40>Yah, <wait=40>kurasa tak perlu kutanya lebih jauh.","story.map2-dungeon1.010":"Kami Pembasmi Iblis sedang memburu iblis Graham.","story.map2-dungeon1.011":"Kami sudah beberapa kali menyudutkannya, <wait=20>tapi dia selalu berhasil lolos...","story.map2-dungeon1.012":"Dia kabur ke arah gurun, jadi kami akan masuk untuk mencarinya.","story.map2-dungeon1.013":"Nah, <wait=20>bagaimana kalau kita berangkat?","story.map2-dungeon1.014":"Omong-omong, <wait=40>gurun ini panasnya luar biasa, jadi berhati-hatilah.","story.map2-dungeon1.015":"Dan waspadalah, belakangan ada yang melihat orang dungu yang mengayun-ayunkan pedang berapi!","story.map2-dungeon1.016":"Hati-hati, <wait=20>sampai jumpa lagi nanti!","story.map2-dungeon2.001":"Oh, <rep_handlename>!!","story.map2-dungeon2.002":"Kamu merasakannya? <wait=40>Angin laut di sini luar biasa, kan?","story.map2-dungeon2.003":"Eh? <wait=40>Kenapa kita di sini?","story.map2-dungeon2.004":"Soalnya di sana tadi terlalu panas...","story.map2-dungeon2.005":"<size=22>Ah! <wait=40>Aku tarik ucapanku!!","story.map2-dungeon2.006":"Kita di sini bukan cuma karena panas...","story.map2-dungeon2.007":"Aku sungguh ada urusan di sini! <wait=40>Dan berhenti memasang tampang curiga begitu!","story.map2-dungeon2.008":"Baiklah, aku harus pergi! <wait=40>Aku akan menyusulmu setelah urusanku selesai.","story.map2-dungeon2.009":"Kamu duluan saja, <rep_handlename>!<br><wait=40>Jangan menunda-nunda, ya?","story.map2-dungeon2.010":"Omong-omong, <wait=40>katanya ada pendekar pedang wanita musuh di pantai ini, dan kudengar dia bisa mengendalikan udara dingin!","story.map2-dungeon2.011":"Kudengar dia juga cantik, tapi aku tahu aku jauh lebih imut darinya!","story.map2-dungeon2.012":"Pastikan kamu mengalahkannya, <wait=20>dan cepat, ya!","story.map2-dungeon2.013":"Pokoknya, <wait=20>aku tunggu di sini! <wait=40>Semoga berhasil!","story.map2-dungeon3.001":"Kamukah itu, <rep_handlename>?!<br><wait=40>Kamu melihat Graham?!","story.map2-dungeon3.002":"Oh, <wait=20>tidak, ya... <wait=40>Sial... <wait=40>Argh...","story.map2-dungeon3.003":"Ah, <wait=20>jangan khawatir. <wait=40>Ini cuma luka gores, bukan apa-apa...","story.map2-dungeon3.004":"Tapi yang lebih parah, <wait=20>sebagian besar rekanku tewas...","story.map2-dungeon3.005":"Graham... <wait=30>Dia sekarang ada di Hutan Malam.","story.map2-dungeon3.006":"Rupanya hutan ini adalah wilayah salah satu ksatria Graham.","story.map2-dungeon3.007":"Ksatria ini mengenal bayang-bayang hutan seperti telapak tangannya sendiri, dan memanfaatkan pandangan yang buruk untuk keuntungannya.","story.map2-dungeon3.008":"Dia menjatuhkan para Summoner satu per satu.","story.map2-dungeon3.009":"Asal kita bisa mengalahkan ksatria ini, mungkin kita bisa mengusir Graham dari hutan.","story.map2-dungeon3.010":"Yang kutahu hanyalah ksatria ini bersenjata tombak.","story.map2-dungeon3.011":"Dengan keadaan Pembasmi Iblis sekarang, kami tak bisa berbuat banyak selain mengepung Graham...","story.map2-dungeon3.012":"Dan aku tak mungkin cuma berdiam diri melihat rekan-rekanku dihabisi satu per satu.","story.map2-dungeon3.013":"Bagaimanapun, akan kuseret dia keluar dari hutan ini, sekalipun harus kulakukan sendiri!","story.map2-dungeon3.014":"Nah, sebaiknya kita bergerak.<br><wait=40>Aku harap kamu juga mengerahkan segalanya!","story.map2-dungeon4.001":"Hei, <wait=20><rep_handlename>!<br><wait=40>Syukurlah kamu masih utuh!","story.map2-dungeon4.002":"Yah, <wait=20>bukannya aku mengira kamu bakal kalah dari orang seperti itu!","story.map2-dungeon4.003":"Kamu menuju Menara Morgan, kan?","story.map2-dungeon4.004":"Kalau begitu, kamu harus melewati Tanah Tandus Asekutt.","story.map2-dungeon4.005":"Binatang buas yang berkeliaran di Tanah Tandus Asekutt cukup kuat.","story.map2-dungeon4.006":"Bakal berbahaya kalau Unit-mu lemah secara elemen terhadap binatang-binatang itu, jadi hati-hati.","story.map2-dungeon4.007":"Hmm? <wait=40>Kamu mencemaskan keadaan di pihak kami?","story.map2-dungeon4.008":"Yah, entah bagaimana aku berhasil menyeret Graham keluar dari hutan.","story.map2-dungeon4.009":"Tapi tidak seperti Hutan Malam, Asekutt adalah padang terbuka.","story.map2-dungeon4.010":"Dia tak akan bisa lari dan bersembunyi seperti di Hutan Malam.","story.map2-dungeon4.011":"Meski kekuatan tim Pembasmi Iblis kami tinggal separuh...","story.map2-dungeon4.012":"Aku berniat menuntaskan semuanya di Asekutt untuk selamanya.","story.map2-dungeon4.013":"Ini demi rekan-rekanku, <wait=40>demi pengorbanan mereka.","story.map2-dungeon4.014":"Jadi sayangnya, <wait=40>aku tak bisa ikut denganmu.","story.map2-dungeon4.015":"Tapi tenang saja, aku sangat yakin kamu akan mengalahkan Maxwell.","story.map2-dungeon4.016":"Sampai jumpa!","story.map2-dungeon5.001":"Hai, <rep_handlename>.<br><wait=40>Graham lolos lagi...","story.map2-dungeon5.002":"Sial, <wait=40>padahal sudah begitu dekat!","story.map2-dungeon5.003":"Dan aku kehilangan lebih banyak rekan... <wait=40>Aku bersumpah akan menghancurkannya begitu dia kutangkap.","story.map2-dungeon5.004":"...<wait=20>Tapi sekarang, jumlah kami Pembasmi Iblis terlalu sedikit.","story.map2-dungeon5.005":"Jadi kami kembali ke Balai Summoner untuk minta bala bantuan.","story.map2-dungeon5.006":"Aku seharusnya bertemu dia di sini juga, tapi...","story.map2-dungeon5.007":"Oh, <wait=20>itu dia!","story.map2-dungeon5.008":"Hai, Seria, <wait=40>kelihatan segar, ya?","story.map2-dungeon5.009":"Karl! <wait=40>Ini bukan waktunya basa-basi!","story.map2-dungeon5.010":"Sedang apa <rep_handlename> di sini?!","story.map2-dungeon5.011":"Kamu bukan anggota Pembasmi Iblis, kan?!","story.map2-dungeon5.012":"Oh, <wait=40>aku dan <rep_handlename> kebetulan bertemu di sini.","story.map2-dungeon5.013":"Tujuanmu berikutnya <wait=20>Kuil Lystia, kutebak?","story.map2-dungeon5.014":"Kalau kamu bukan anggota Pembasmi Iblis, kamu tak punya alasan berada di sini.","story.map2-dungeon5.015":"Hei, <wait=20>Seria. <wait=40>Tak perlu bicara sekeras itu!","story.map2-dungeon5.016":"<size=12>...<wait=40>Kenapa malah aku yang dimarahi??","story.map2-dungeon5.017":"Yang lebih penting, aku punya kabar untukmu, Karl.","story.map2-dungeon5.018":"Menurut informasi dari Balai Summoner, <wait=20>sepertinya Graham adalah salah satu kesayangan Abaddon.","story.map2-dungeon5.019":"Dia disayang Abaddon? <wait=40>Maksudnya apa itu.","story.map2-dungeon5.020":"Sepertinya dia sangat populer, bahkan di antara para dewa lain...","story.map2-dungeon5.021":"Jadi kalau Graham dalam bahaya, kamu bisa yakin masalah lain akan segera menyusul.","story.map2-dungeon5.022":"Mungkin bahkan Abaddon sendiri akan muncul...","story.map2-dungeon5.023":"Kalau itu benar, kita harus membunuh Graham untuk memancing Abaddon keluar.","story.map2-dungeon5.024":"Itulah sebabnya kami menerima perintah dari Balai Summoner untuk maju ke Menara Morgan. ","story.map2-dungeon5.025":"Begitu.","story.map2-dungeon5.026":"Pasti itu alasannya permintaan bala bantuan kami diterima begitu cepat.","story.map2-dungeon5.027":"Pokoknya, bukankah sudah saatnya kita berhenti mengobrol!?","story.map2-dungeon5.028":"Kamu mestinya sedang menuju Menara Morgan, kan?","story.map2-dungeon5.029":"Kami masih punya banyak rencana yang harus diurus...","story.map2-dungeon5.030":"...jadi kenapa kamu tidak cepat-cepat pergi sendiri saja!","story.map2-dungeon5.031":"Eh? <wait=20>H-<wait=20>Hei, Seria! <wait=40><rep_handlename>!!","story.map2-dungeon6.001":"<rep_handlename>! <wait=40>Kamu baik-baik saja?!","story.map2-dungeon6.002":"Kamu langsung pergi setelah dibentak Seria. <wait=20>Kukira kamu marah.","story.map2-dungeon6.003":"Yah, <wait=20>syukurlah kamu baik-baik saja.","story.map2-dungeon6.004":"Kami sendiri baru saja melewati Kuil Lystia.","story.map2-dungeon6.005":"Hei, <wait=40>kenapa kamu selalu muncul di mana pun kami pergi?!","story.map2-dungeon6.006":"Kamu tidak sedang menguntit kami, kan?!","story.map2-dungeon6.007":"Bisa tidak berhenti bersikap galak tanpa alasan?!","story.map2-dungeon6.008":"Kenapa kamu selalu cari gara-gara.","story.map2-dungeon6.009":"A-<wait=20>Aku tidak cari gara-gara!","story.map2-dungeon6.010":"Dia bahkan tidak sekuat itu...","story.map2-dungeon6.011":"Aku kesal sekali kamu bisa memuji orang seperti dia. Lihat saja dia!","story.map2-dungeon6.012":"*Huh* <wait=40>Kalau itu bukan cari gara-gara, <wait=20>entah apa namanya...","story.map2-dungeon6.013":"Entah kamu sadar atau tidak, <wait=20>tapi <rep_handlename> sampai di sini seorang diri.","story.map2-dungeon6.014":"<rep_handlename> membantu kami dengan mengalahkan anak buah Graham di Hutan Malam.","story.map2-dungeon6.015":"<rep_handlename> jelas bukan orang lemah.","story.map2-dungeon6.016":"Hmph. <wait=40>Yah, aku tak peduli bagaimanapun juga.","story.map2-dungeon6.017":"Silakan saja nikmati pujian salah alamat itu sepuasmu!","story.map2-dungeon6.018":"...<wait=40>Aku sungguh tak paham wanita.","story.map2-dungeon6.019":"Yah, <wait=20>pokoknya...","story.map2-dungeon6.020":"Kami akan melewati katedral hancur ini untuk mencapai Menara Morgan...","story.map2-dungeon6.021":"<rep_handlename>, mau ikut?","story.map2-dungeon6.022":"<size=24>Aku keberatan!","story.map2-dungeon6.023":"Heh, <wait=20>sudah kuduga kamu bakal bilang begitu.","story.map2-dungeon6.024":"Yah, <wait=20>kita tak bisa maju bertempur bersama sambil bertengkar begini. Sebaiknya tidak dipaksakan.","story.map2-dungeon6.025":"Kami jalan sendiri, kamu juga.","story.map2-dungeon6.026":"Sampai jumpa di Menara Morgan!","story.map2-dungeon7.001":"<rep_handlename>!! <wait=40>Cepat sekali, <wait=20>tak kusangka kamu sudah sampai.","story.map2-dungeon7.002":"Heh, <wait=40>setidaknya cuma itu yang bisa dia lakukan...","story.map2-dungeon7.003":"Seperti biasa, langsung cari gara-gara...","story.map2-dungeon7.004":"Jadi, <wait=20>pokoknya... <wait=40>Inilah markas Abaddon, <wait=20>Menara Morgan.","story.map2-dungeon7.005":"Abaddon dan Graham kemungkinan ada di sini.","story.map2-dungeon7.006":"Hanya ke sinilah Graham bisa melarikan diri.","story.map2-dungeon7.007":"Kami akan menangkap Graham. <wait=40><br>Dan <rep_handlename>, kamu hadapi Abaddon.","story.map2-dungeon7.008":"Kita sudah datang sejauh ini, <wait=40>ayo hancurkan mereka!","story.map2-dungeon7.009":"Tapi bisa saja kami mengalahkan Abaddon sebelum kamu sempat, lho!","story.map2-dungeon7.010":"Bagaimana kalau <rep_handlename> yang mengalahkan Graham lebih dulu dari kita?","story.map2-dungeon7.011":"Yah, <wait=40>wajar kalau kamu ingin menghadapi musuh temanmu sendiri...","story.map2-dungeon7.012":"Tapi menurutku lebih baik kita bekerja sama di medan masing-masing dan mengerahkan segalanya!","story.map2-dungeon7.013":"Hei... <wait=20>hei! <wait=40>Seperti ada getaran, kalian dengar?","story.map2-dungeon7.014":"Di sana!!","story.map2-dungeon7.015":"A-<wait=20>Apa itu!? <wait=40>Gerombolan... <wait=20>monster?!","story.map2-dungeon7.016":"...Maxwell. <wait=40>Jadi dia berniat menghentikan kita di sini...","story.map2-dungeon7.017":"Tak ada jalan mundur... <wait=40>Kita tak punya pilihan selain bertarung... <wait=40>Di sini, sekarang juga...","story.map2-dungeon7.018":"...<wait=40>Tunggu, <wait=40>mungkin ada cara lain.","story.map2-dungeon7.019":"Kita tinggal naik ke puncak Menara Morgan, <wait=40>lalu kalahkan Abaddon di sana.","story.map2-dungeon7.020":"Itu mustahil!","story.map2-dungeon7.021":"Tak mungkin kita bisa melawan semua monster itu dan Abaddon sekaligus...","story.map2-dungeon7.022":"Jangan berpikir begitu. <wait=40>Kita mungkin bahkan tak bisa cukup dekat untuk melihat Abaddon sekilas.","story.map2-dungeon7.023":"Kamu benar. <wait=40>Tapi <wait=20>monster-monster ini tak akan maju lebih jauh.","story.map2-dungeon7.024":"Aku akan menghentikan mereka di sini!","story.map2-dungeon7.025":"Karl!? <wait=40>Apa maksudmu!?","story.map2-dungeon7.026":"Kamu sungguh berniat menahan mereka di sini sementara kami pergi menghadapi Abaddon?!","story.map2-dungeon7.027":"Benar. <wait=40>Hanya itu pilihan kita...","story.map2-dungeon7.028":"Tapi lihat jumlah mereka. <wait=40>Tak mungkin ada yang sanggup melawan mereka sendirian!","story.map2-dungeon7.029":"Ya... <wait=40>Aku tahu itu.","story.map2-dungeon7.030":"Tapi kalau memang semuanya harus berakhir di sini, aku akan bertaruh pada apa pun yang memberi peluang terbaik untuk mengalahkan Abaddon.","story.map2-dungeon7.031":"Karl...","story.map2-dungeon7.032":"<rep_handlename>, <wait=40>pergilah bersama Seria.","story.map2-dungeon7.033":"Aku akan menghentikan monster-monster ini. <wait=40>Kamu harus pergi dan menumpas Abaddon.","story.map2-dungeon7.034":"...<wait=40>Aku tidak ikut.","story.map2-dungeon7.035":"Seria!!","story.map2-dungeon7.036":"Gerombolan ini <wait=20>terlalu banyak untuk kamu hadapi sendirian, Karl.","story.map2-dungeon7.037":"Kalau aku membantumu menahan mereka <wait=20>sedikit lebih lama...","story.map2-dungeon7.038":"Mungkin hanya itu tambahan waktu yang kita butuhkan <wait=20>untuk mengalahkan Abaddon.","story.map2-dungeon7.039":"Seria, <wait=40>kamu...","story.map2-dungeon7.040":"<rep_handlename>!","story.map2-dungeon7.041":"Kamu, <wait=40>para Summoner Terdahulu sudah mengakui kekuatanmu sebagai Summoner, bukan?","story.map2-dungeon7.042":"Kalau begitu, buktikan padaku.","story.map2-dungeon7.043":"Kuhajar kamu habis-habisan kalau kamu tidak mengalahkan Abaddon!!","story.map2-dungeon7.044":"...<wait=40>Nah, <wait=20>ayo kita lakukan!!","story.map2-dungeon7.045":"Cih... <wait=20>Gadis itu...","story.map2-dungeon7.046":"<rep_handlename>, <wait=40>kami akan mengerahkan segalanya untuk menahan mereka.","story.map2-dungeon7.047":"Kamu harus mengalahkan Abaddon.","story.map2-dungeon7.048":"Kami mengandalkanmu, <wait=40><rep_handlename>.","story.map2-dungeon7.049":"Sekarang, <wait=40>maju bertempur!!","story.map2-ending.001":"<size=20><rep_handlename>! Kamu baik-baik saja?!</size>","story.map2-ending.002":"Oh, <wait=20>apa kamu... <wait=40>sudah mengalahkan Abaddon?","story.map2-ending.003":"Wah... <wait=40>Kamu memang sangat kuat.","story.map2-ending.004":"Aku tak percaya kamu bisa mengalahkan Abaddon seorang diri...","story.map2-ending.005":"Oh, aku? <wait=20>Aku baik-baik saja.","story.map2-ending.006":"Setelah kita berpisah, <wait=20>aku mengerahkan segalanya untuk menjaga pintu masuk menara.","story.map2-ending.007":"Seria dan aku sama-sama memaksakan diri sampai batas, kami nyaris tumbang...","story.map2-ending.008":"Tapi untungnya, bala bantuan dari Balai Summoner tiba tepat waktu.","story.map2-ending.009":"Mereka mengerahkan segalanya untuk membantu kami...","story.map2-ending.010":"Hmm? <wait=20>Seria? <wait=40>Dia di sebelah sana... <wait=40>Lho? <wait=20>Seria?","story.map2-ending.011":"Ke mana dia? <wait=40>...<wait=40>Hmm, <wait=20>ya sudahlah.","story.map2-ending.012":"Omong-omong, <wait=20>dia cukup mencemaskanmu.","story.map2-ending.013":"Dia sudah compang-camping dan kelelahan, tapi dia bersikeras membantumu dan langsung naik ke menara...","story.map2-ending.014":"Hehe, <wait=20>entah apa yang akan dia lakukan kalau tahu aku menceritakan semua itu...","story.map2-ending.015":"Jadi jangan bilang aku yang cerita, ya?","story.map2-ending.016":"Tapi sungguh, <wait=40>kamu benar-benar sudah jadi kuat.","story.map2-ending.017":"Kami bergegas membantumu, <wait=40>tapi sepertinya kamu tak butuh bala bantuan.","story.map2-ending.018":"Bagiku, kamu sudah Summoner kelas atas.","story.map2-ending.019":"Oh, <wait=20>iya...","story.map2-ending.020":"Pada akhirnya kami tak berhasil menjatuhkan Graham.","story.map2-ending.021":"Tapi kami berhasil menangkap beberapa monster dan memaksa mereka membocorkan tempat persembunyian Graham.","story.map2-ending.022":"Tapi dia sudah kabur ke tempat yang tak bisa kami capai... <wait=20>Dasar bajingan... ","story.map2-ending.023":"Tak akan mudah melacaknya.","story.map2-ending.024":"Aku harus melapor kembali ke Balai Summoner Akras itu...","story.map2-ending.025":"Kamu... <wait=40>Yah, <wait=40>kurasa kamu punya urusanmu sendiri.","story.map2-ending.026":"...<wait=20>Sebaiknya aku segera pergi.","story.map2-ending.027":"Tujuan kita mungkin berbeda, <wait=40>tapi aku akan selalu ada di pihakmu.","story.map2-ending.028":"Pastikan kamu tetap hidup! <wait=40>Sampai jumpa!","story.map2-ending.029":"Hei! <wait=40><rep_handlename>!!","story.map2-ending.030":"Akhirnya aku menyusulmu!","story.map2-ending.031":"Kamu benar-benar hebat!!","story.map2-ending.032":"Sementara aku di Pantai Semilir, bersaing dengan Ratu Es Selena soal siapa yang lebih imut...","story.map2-ending.033":"...ternyata kamu mengalahkan Abaddon! Luar biasa!","story.map2-ending.034":"...Eh?!","story.map2-ending.035":"J-<wait=20>Jangan salah paham! <wait=40>Bukannya kami mengadakan kontes kecantikan atau semacamnya...","story.map2-ending.036":"Maksudku, Selena bahkan tidak muncul!","story.map2-ending.037":"Lagi pula <rep_handlename>, kamu tidak ada di sana, jadi tak ada yang menjurii kontesnya, kan?!","story.map2-ending.038":"...<wait=40>Kenapa tampangmu begitu!","story.map2-ending.039":"Aku sungguh ada urusan penting di Pantai Semilir!","story.map2-ending.040":"Ah! <wait=20>Kamu dengar itu?<br><wait=40>Sepertinya Lord Lucius memanggilmu?","story.map2-ending.041":"<speed=12>Selamat <wait=10>jalan, <wait=20>hati-hati<wait=30>...","story.map2-ending.042":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Akulah Lucius...<br><wait=40>Dewa Gerbang...","story.map2-ending.043":"<anchor=center><br><br><br><br><br><speed=8><size=15><rep_handlename>... <wait=40>Penyelamat Morgan...","story.map2-ending.044":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Gunakan kekuatanku <wait=40>dan jelajahilah negeri-negeri baru...","story.map2-ending.045":"<anchor=center><br><br><br><br><br><br><br><speed=8><size=15>Majulah <wait=20>dan gunakan kekuatanmu untuk membawa kedamaian ke dunia ini...","story.map2-ending.046":"Oh, <wait=20>kamu sudah bangun.","story.map2-ending.047":"Selamat pagi, <wait=20> <rep_handlename>.","story.map2-ending.048":"Lihat... <wait=40>Akhirnya kita tiba di St. Lamia.","story.map2-ending.049":"Inilah... <wait=40>wilayah kekuasaan Maxwell.","story.map2-ending.050":"...<wait=40><rep_handlename>, kamu juga merasakannya?","story.map2-ending.051":"Aku bisa merasakan riak kekuatan yang dahsyat...","story.map2-ending.052":"Monster-monsternya juga lebih kuat dari sebelumnya. <wait=40>Kita harus tetap fokus...","story.map2-ending.053":"Maxwell ada di Istana St. Lamia.","story.map2-ending.054":"Pertarungan berat menanti kita, <wait=40>ayo berjuang bersama!","story.map2-ending.055":"Apa? <wait=40>Kamu tanya aku ke mana waktu kamu bertarung di Morgan?","story.map2-ending.056":"Jangan picik begitu...","story.map2-ending.057":"Aku janji akan berusaha sebaik-baiknya di St. Lamia, <wait=40>oke?","story.map2-ending.058":"Baiklah, <wait=20>ayo berangkat!!","story.map3-dungeon1.001":"<size=13>Panas sekali di sini! <wait=40>Aku mau pulang... <wait=40>Kulitku yang malang sudah tak tahan lagi...","story.map3-dungeon1.002":"<size=20>Hei! <wait=20><rep_handlename>!","story.map3-dungeon1.003":"Kamu! <wait=20>Kamu terlambat lagi!!","story.map3-dungeon1.004":"Jangan bilang kamu bermalas-malasan di tempat yang lebih sejuk!?","story.map3-dungeon1.005":"Ini bukan waktunya main-main! <wait=40>Apa pembelaanmu?","story.map3-dungeon1.006":"Hah? <wait=20>Aku kenapa?","story.map3-dungeon1.007":"<size=15>Aku <size=14>sama <size=13>sekali <size=12>tidak <size=11>sedang <size=10>ber<size=9>malas<size=8>-malasan<size=7>...<size=6>","story.map3-dungeon1.008":"Pokoknya, <wait=40>mulai hari ini kita akan mendaki Gunung Api Eldent.","story.map3-dungeon1.009":"Gunung Api Eldent adalah gunung berapi aktif, jadi sangat berbahaya.","story.map3-dungeon1.010":"Kamu harus waspada terhadap aliran lava!","story.map3-dungeon1.011":"Nah, <wait=20>selamat jalan!","story.map3-dungeon1.012":"Apa? <wait=40>Kamu mau saran yang lebih berguna?","story.map3-dungeon1.013":"Terlalu panas... Aku sudah di batasku!","story.map3-dungeon1.014":"<size=20>Ah! <wait=40>Aku tak tahan lagi!","story.map3-dungeon1.015":"Aku pulang dulu untuk mandi,<wait=20> jangan sampai mati sebelum aku kembali!","story.map3-dungeon2.001":"<size=12>Brr...","story.map3-dungeon2.002":"Oh, <wait=20><rep_handlename>! <wait=40>Ya ampun, <wait=20>kenapa lama sekali!","story.map3-dungeon2.003":"Eh? <wait=40>Aku kenapa?","story.map3-dungeon2.004":"Tidak kenapa-kenapa. <wait=40>Aku Tilith yang bersemangat seperti biasa!","story.map3-dungeon2.005":"Iya, <wait=20>harus kuakui di sini memang mulai agak dingin.","story.map3-dungeon2.006":"Tapi itu cuma karena kamu membuatku menunggu lama sekali, <rep_handlename>!","story.map3-dungeon2.007":"Selain itu, <wait=20>sebaiknya aku cerita sedikit lagi tentang Gunung Suci Craylia.","story.map3-dungeon2.008":"Gunung suci ini, Gunung Craylia, adalah gunung tertinggi di St. Lamia.","story.map3-dungeon2.009":"Puncaknya konon menyimpan sumber kekuatan spiritual yang tampaknya menjadi asal badai salju abadi ini.","story.map3-dungeon2.010":"Selain itu, <wait=40>katanya Raja Laut Leviathan juga bersemayam di sana.","story.map3-dungeon2.011":"Kenapa ya dia meninggalkan laut untuk tinggal jauh di atas gunung...","story.map3-dungeon2.012":"Hmm<wait=20>...","story.map3-dungeon2.013":"<size=12><wait=20>Uh... <wait=20>Brr...","story.map3-dungeon2.014":"Apa? <wait=40>Sungguh, <wait=20>aku baik-baik saja!","story.map3-dungeon2.015":"Tapi sepertinya aku terlalu lama berdiri di tempat beku ini sampai masuk angin...","story.map3-dungeon2.016":"Aku duluan, ya. <wait=40>Semoga berhasil mendaki gunung bersalju ini!","story.map3-dungeon3.001":"*Huh* <wait=20>Hmph... <wait=40>Sedikit lagi...","story.map3-dungeon3.002":"Oh, <wait=20><rep_handlename>! <wait=40>Aku sudah menunggumu.","story.map3-dungeon3.003":"Untuk mencapai Maxwell, kita harus melewati tempat ini, <wait=40>Hutan Darah.","story.map3-dungeon3.004":"Hutan Darah, namanya seram sekali...","story.map3-dungeon3.005":"Konon, siapa pun yang mencoba melewati hutan ini akhirnya ditemukan berlumuran darah...","story.map3-dungeon3.006":"<size=20><size=18>Itu <size=20>benar-benar, <size=16>benar-benar, <size=19><size=17>benar-benar, <size=18>sangat, <size=15>sangat <size=17>seram<size=19>!","story.map3-dungeon3.007":"Apa? <wait=40>Menurutmu aku bertingkah aneh?","story.map3-dungeon3.008":"Aku tidak bertingkah aneh! <wait=40>Aku tetap anggun seperti biasa, kan?","story.map3-dungeon3.009":"Kamu khawatir... <wait=20>padaku?","story.map3-dungeon3.010":"Begitu, <wait=20>tapi kalau kamu sempat bicara konyol begitu, kenapa tidak cepat bergerak dan taklukkan hutan ini!","story.map3-dungeon3.011":"Semoga berhasil!!","story.map3-dungeon3.012":"<size=12><wait=20>Ugh<wait=20>...","story.map3-dungeon4.001":"*Uhuk* <wait=20>*Uhuk*... <wait=40>Ahh, <wait=20>ugh...","story.map3-dungeon4.002":"Oh, <wait=40><rep_handlename>... <wait=40>Kamu datang...","story.map3-dungeon4.003":"Aku... <wait=40>tak bisa <wait=40>menyembunyikannya darimu lagi...","story.map3-dungeon4.004":"Kondisiku, <wait=20>ini bukan penyakit. <wait=40>Aku tidak sakit.","story.map3-dungeon4.005":"Maxwell... <wait=40>Dia mengutukku.","story.map3-dungeon4.006":"Sejak... <wait=20>kita menginjakkan kaki di St. Lamia.","story.map3-dungeon4.007":"Sekarang kita makin dekat ke Istana St. Lamia, <wait=40>kutukannya makin parah...","story.map3-dungeon4.008":"Maxwell mungkin <wait=40>menganggapku pengganggu...","story.map3-dungeon4.009":"Hmm? <wait=40>Kamu tidak terkena karena...","story.map3-dungeon4.010":"Aku... <wait=40>melindungimu dari kutukan itu.","story.map3-dungeon4.011":"...<wait=40>Tidak apa-apa. <wait=40>Aku tak keberatan.","story.map3-dungeon4.012":"Terima kasih sudah peduli... <wait=40>tapi aku akan baik-baik saja.","story.map3-dungeon4.013":"Aku ini dewi, <wait=40>pemandumu...","story.map3-dungeon4.014":"Aku pasti <wait=40>akan melindungimu...","story.map3-dungeon4.015":"Sebentar lagi... <wait=40>kita akan mengalahkan Maxwell.","story.map3-dungeon4.016":"<wait=20>Ayo kita lakukan, <rep_handlename>!!","story.map3-dungeon4.017":"<size=12><wait=20>Ugh<wait=20>...","story.map3-dungeon5.001":"<speed=12>...Ugh. <wait=40>*Uhuk* <wait=20>*Hah*... <wait=40>*Hah*...","story.map3-dungeon5.002":"<speed=12><rep_handlename>... <wait=40>Maaf... <wait=40>Aku...","story.map3-dungeon5.003":"<speed=12>Aku tak bisa... <wait=40>melangkah lebih jauh lagi<wait=40>...","story.map3-dungeon5.004":"<speed=12><rep_handlename>, <wait=40>aku...","story.map3-dungeon5.005":"<speed=12>Aku melakukan ini bukan karena disuruh Lord Lucius...","story.map3-dungeon5.006":"<speed=12>Aku melakukannya karena kamu adalah <rep_handlename>... <wait=40>A-<wait=20>aku cuma ingin melindungimu.","story.map3-dungeon5.007":"<speed=12>Aku yang memohon pada Lord Lucius agar mengizinkanku... <wait=40>*Uhuk* <wait=20>*Uhuk*","story.map3-dungeon5.008":"<speed=12>Masih banyak tempat lain <wait=40>yang ingin kukunjungi bersamamu...","story.map3-dungeon5.009":"<speed=12>Aku ingin <wait=40>berkelana lebih jauh...","story.map3-dungeon5.010":"<speed=12>Tapi... <wait=40>sepertinya waktuku hampir habis...","story.map3-dungeon5.011":"<speed=12>Sekalipun aku tumbang... <wait=40>sihirku akan terus melindungimu.","story.map3-dungeon5.012":"<speed=12>Berjanjilah padaku<wait=20>.<wait=20>.<wait=40>.","story.map3-dungeon5.013":"<speed=10>...bahwa <wait=40>kamu <wait=40>pasti <wait=12>akan mengalahkan <wait=10>Max<wait=7>well<wait=5>...","story.map3-dungeon5.014":"<speed=10>Ugh...","story.map3-dungeon5.015":"<size=24>(Pingsan)","story.map3-dungeon5.016":"...<wait=40>...<wait=40>...","story.map3-dungeon5.017":"Hei! <wait=40>Benarkah itu kamu, <rep_handlename>!?","story.map3-dungeon5.018":"Kamu pasti cukup tangguh, <wait=40>bisa sampai sejauh ini sendirian...","story.map3-dungeon5.019":"Jadi bagaimana dengan Abaddon??<wait=40>","story.map3-dungeon5.020":"<size=18>Hei, <wait=20>gadis itu kenapa?! <wait=40>Dia jadi biru begitu!!","story.map3-dungeon5.021":"<rep_handlename>... <wait=40>Jangan bilang<wait=20>...","story.map3-dungeon5.022":"Jangan bilang kamu masih belum bisa meracik penawar racun?!","story.map3-dungeon5.023":"Iya, iya. <wait=40>Aku cuma bercanda.","story.map3-dungeon5.024":"...Kutukan? <wait=40>Apa maksudmu?","story.map3-dungeon5.025":"Ayolah, kamu ini bicara apa!?","story.map3-dungeon5.026":"...<wait=60>...<wait=60>...<wait=60>!","story.map3-dungeon5.027":"Tunggu... <wait=40>maksudmu, <wait=20>gadis ini seorang dewi?","story.map3-dungeon5.028":"Kamu...<wait=40> tidak sedang <wait=20>mempermainkanku, <wait=40>kan?","story.map3-dungeon5.029":"Lalu?","story.map3-dungeon5.030":"...<wait=60>...<wait=60>...","story.map3-dungeon5.031":"Jadi... <wait=40>ini ulah Maxwell, ya...","story.map3-dungeon5.032":"Aku ingin membantu, <wait=40>tapi ini di luar kemampuanku...","story.map3-dungeon5.033":"Ini bukan sesuatu yang bisa disembuhkan dengan meracik ramuan...","story.map3-dungeon5.034":"Tapi tunggu, <wait=40>kutukan ini dipasang oleh Maxwell, kan?","story.map3-dungeon5.035":"Berarti mengalahkan Maxwell semestinya mematahkan kutukannya, bukan?","story.map3-dungeon5.036":"Kalau mengalahkan Maxwell tidak berhasil, kamu tinggal menghajarnya sampai dia mau mencabutnya!","story.map3-dungeon5.037":"Hanya itu cara lain yang terpikir olehku sekarang.","story.map3-dungeon5.038":"...<wait=20>Tentu. <wait=40>Aku akan merawatnya.","story.map3-dungeon5.039":"Timku mendirikan kemah di dekat sini, akan kubawa dia ke sana.","story.map3-dungeon5.040":"Kamu harus bergegas.","story.map3-dungeon5.041":"<size=22>Jangan cuma berdiri bengong begitu!!","story.map3-dungeon5.042":"Dia menderita gara-gara kamu!","story.map3-dungeon5.043":"Ini bukan waktunya berlama-lama, kamu harus berlari ke Istana St. Lamia!","story.map3-dungeon5.044":"<size=14>...<wait=20>Dasar bodoh.","story.map3-dungeon7.001":"<size=20><rep_handlename>! <wait=40>Syukurlah kamu masih hidup!!","story.map3-dungeon7.002":"Kenapa aku di sini? <wait=40>Tentu saja, aku datang untuk membantumu!","story.map3-dungeon7.003":"<size=20>Sial!","story.map3-dungeon7.004":"<size=24>*Tebas*","story.map3-dungeon7.005":"<size=24>*Tebas*","story.map3-dungeon7.006":"...Astaga, <wait=40>banyak sekali gerombolan yang harus kita hadapi, ya?","story.map3-dungeon7.007":"Aku sudah dengar semuanya dari Seria.","story.map3-dungeon7.008":"Biar aku yang urus di sini.","story.map3-dungeon7.009":"Waktumu hampir habis, kan? <wait=40>Cepat maju!","story.map3-dungeon7.010":"<size=20>Ugh!","story.map3-dungeon7.011":"<size=24>*Tebas*","story.map3-dungeon7.012":"<size=20>Pergi dari sini!!","story.map3-dungeon7.013":"<rep_handlename>... <wait=40>kami mengandalkanmu...","story.map3-ending.001":"<size=20><rep_handlename>!!","story.map3-ending.002":"*Hah*... <wait=40>hmph...","story.map3-ending.003":"Astaga, <wait=40>Summoner itu berhasil...","story.map3-ending.004":"Maxwell, salah satu dari Empat Dewa yang Jatuh, telah dikalahkan!!","story.map3-ending.005":"Fiuh... <wait=40>Tapi nyaris sekali...","story.map3-ending.006":"<size=20><rep_handlename>, kerja bagus!!","story.map3-ending.007":"Sepertinya mengalahkan Maxwell memang mematahkan kutukannya.","story.map3-ending.008":"Benar sekali, <wait=40>syukurlah dewi muda yang manis ini pulih...","story.map3-ending.009":"Omong-omong, <wait=20>bagaimana kamu bisa sampai di sini lebih dulu dariku?!","story.map3-ending.010":"...<wait=20>Dia pasti memang seorang dewi. <wait=40>Kurasa kekuatannya kembali saat kutukannya terangkat.","story.map3-ending.011":"Aku tak percaya <rep_handlename> ternyata selama ini dibantu seorang dewi<wait=40>...","story.map3-ending.012":"Dan Seria, aku bahkan kagum padamu. Kamu benar-benar habis-habisan demi mereka berdua, ya?","story.map3-ending.013":"A-<wait=30>Aku tidak bertindak demi membela <rep_handlename>.","story.map3-ending.014":"Aku melakukannya demi sang dewi, dan juga demi dunia.","story.map3-ending.015":"Iya, iya... <wait=40>Sudahlah.","story.map3-ending.016":"<size=18>Kamu mengalahkan Maxwell! Itu baru <rep_handlename>-ku!!","story.map3-ending.017":"...<wait=40>Yah, <wait=20>baiklah.","story.map3-ending.018":"Pokoknya, <wait=40>untuk pemula yang berkembang secepat itu...","story.map3-ending.019":"Yah, <wait=40>itu sungguh luar biasa.","story.map3-ending.020":"<rep_handlename>! <wait=40>Aku akui kamu adalah seorang...","story.map3-ending.021":"<rep_handlename> berhasil!! <wait=40><rep_handlename> menang!!","story.map3-ending.022":"Abaddon, bahkan Maxwell, semuanya sudah dikalahkan!!","story.map3-ending.023":"Aku sempat agak khawatir waktu pertama kali kita bertemu...","story.map3-ending.024":"...tapi sekarang, <wait=20>tak diragukan lagi kamu adalah Summoner terkuat yang ada!!","story.map3-ending.025":"<size=18>P-<wait=20>Permisi! <wait=40>Kamu berisik sekali, bisa tenang sedikit tidak!","story.map3-ending.026":"Jangan salahkan aku. <wait=40>Summoner-ku sudah mengalahkan salah satu dari Empat Dewa yang Jatuh!","story.map3-ending.027":"Aku tak pernah sebahagia ini!","story.map3-ending.028":"Diam! <wait=40>Jangan menyela orang yang sedang bicara!!","story.map3-ending.029":"Dan apa-apaan omongan mesra <wait=40>\\"<rep_handlename>-ku\\" itu!?","story.map3-ending.030":"Kalian tidak pacaran, kan?!","story.map3-ending.031":"<rep_handlename>-ku ya <rep_handlename>-ku!","story.map3-ending.032":"Aku mempertaruhkan nyawaku agar <rep_handlename> tetap hidup.","story.map3-ending.033":"Lagi pula, <wait=20><rep_handlename> berjuang keras untuk menyelamatkanku...","story.map3-ending.034":"Aku dan <rep_handlename> terikat oleh takdir!","story.map3-ending.035":"Jadi kenapa? <wait=40>Kamu cemburu, ya?","story.map3-ending.036":"<size=20>S-Si-Siapa yang cemburu karena bocah seperti itu!?","story.map3-ending.037":"<size=18>Dan apa maksudmu takdir? <wait=40><size=24>Kamu bodoh, ya!?","story.map3-ending.038":"...Hei, <wait=20>tenanglah kalian berdua...","story.map3-ending.039":"Hanya orang bodoh yang mau menanggung kutukan demi orang seperti <rep_handlename>. <wait=20>Bodoh sekali!","story.map3-ending.040":"<rep_handlename> pasti baik-baik saja meski kamu biarkan sendiri!!","story.map3-ending.041":"Lagi pula, <wait=20>bukannya kamu ini seorang dewi?!","story.map3-ending.042":"Memangnya kamu tidak bisa mematahkan kutukan itu sendiri?!","story.map3-ending.043":"Apa maksudmu!? <wait=40>Kamu bilang aku tidak berusaha sekuat tenaga!?","story.map3-ending.044":"Kamu sudah di ambang kematian di Suaka Terpencil!","story.map3-ending.045":"Kalau aku tidak ada di sana, kamu pasti sudah dimangsa monster-monster itu!!","story.map3-ending.046":"Omong kosong! <wait=40><rep_handlename> pasti tetap melindungiku meski kamu tidak ada!","story.map3-ending.047":"Kamu cuma omong besar, kamu juga tidak melakukan apa-apa!","story.map3-ending.048":"T-<wait=10>Tunggu dulu!! <wait=40>Menurutmu siapa yang merawatmu!","story.map3-ending.049":"Aku pingsan, aku tidak ingat apa-apa...","story.map3-ending.050":"Dasar kamu ini!!","story.map3-ending.051":"Hei kalian berdua... <wait=40>Sudahlah.","story.map3-ending.052":"<size=24>Diam!!","story.map3-ending.053":"Waduh...","story.map3-ending.054":"Lagian, kenapa Seria selalu bersikap sok kuasa pada <rep_handlename>!?","story.map3-ending.055":"Dia bahkan tak bisa mengalahkan Graham, apalagi Abaddon!","story.map3-ending.056":"<size=12>Aduh... <wait=40>Aku juga ikut dalam pertempuran itu, lho...","story.map3-ending.057":"Berhenti meremehkan <rep_handlename>-ku!!","story.map3-ending.058":"A-<wait=20>Aku boleh bilang apa saja! <wait=40>Kamu mau cari gara-gara!?","story.map3-ending.059":"Kamu yang mulai!","story.map3-ending.060":"Asal tahu saja, aku cukup kuat kalau sedang tidak dikutuk!","story.map3-ending.061":"<size=24>Astaga! <wait=40>Cukup!!","story.map3-ending.062":"<rep_handlename> sudah mengalahkan Maxwell!","story.map3-ending.063":"Ini bukan waktunya bertengkar.","story.map3-ending.064":"...Hmph.","story.map3-ending.065":"Hmph.","story.map3-ending.066":"Kalian, <wait=20>kelakuan kalian berdua lebih parah dari Maxwell sendiri...","story.map3-ending.067":"Tapi pokoknya, <wait=20>aku sungguh salut padamu, <wait=20><rep_handlename>.","story.map3-ending.068":"Aku bangga menjadi temanmu.","story.map3-ending.069":"...<wait=40>Aku benci mengatakannya, <wait=40>tapi aku tak bisa menyangkal kamu memang mengalahkan Maxwell.","story.map3-ending.070":"<wait=40>Kerja bagus.","story.map3-ending.071":"Fiuh.","story.map3-ending.072":"Baiklah, <wait=20>Seria dan aku harus pergi sekarang.","story.map3-ending.073":"...Hah? <wait=40>Tak perlu berterima kasih padaku.","story.map3-ending.074":"Berjanjilah saja kamu akan membantu saat kami butuh nanti!","story.map3-ending.075":"Sampai jumpa lagi, kawan.","story.map3-ending.076":"Hmph, <wait=20>selamat tinggal.","story.map3-ending.077":"...Nah, <wait=40>biar kuucapkan sekali lagi.","story.map3-ending.078":"Selamat! <wait=40><rep_handlename>.","story.map3-ending.079":"Aku yakin kamu pasti akan mengalahkan Maxwell.","story.map3-ending.080":"Tapi bukannya aku yang membantumu... <wait=40>malah kamu yang menolongku.","story.map3-ending.081":"Aku sungguh bahagia. <wait=40>Terima kasih.","story.map3-ending.082":"Hehe. <wait=40>Duh, ini memalukan.","story.map3-ending.083":"Oh, <wait=20>iya. Kita sudah berjanji untuk mengunjungi banyak tempat bersama, kan?","story.map3-ending.084":"Kukira aku bakal mati, <wait=40>makanya aku memintamu berjanji.","story.map3-ending.085":"Tapi karena kamu sudah mengalahkan Maxwell, sepertinya kita akan makin sibuk sekarang.","story.map3-ending.086":"Meski Maxwell sudah dikalahkan, <wait=40>Dewa yang Jatuh ada empat semuanya.","story.map3-ending.087":"Tiga di antaranya masih berkeliaran di luar sana.","story.map3-ending.088":"Sampai kamu mengalahkan semua Dewa yang Jatuh, <wait=40>kedamaian tak akan datang ke Grand Gaia.","story.map3-ending.089":"Karena itu, <wait=40>petualangan yang kita janjikan harus ditunda dulu.","story.map3-ending.090":"Maaf sekali, <wait=40>tapi dewi itu sibuk sekali, tahu.","story.map3-ending.091":"Nah, <wait=40>sudah saatnya aku melapor pada Lord Lucius.","story.map3-ending.092":"Terus asah kemampuanmu, <wait=20>kamu harus jadi lebih kuat lagi kalau ingin mengalahkan sisa Dewa yang Jatuh.","story.map3-ending.093":"Oh, <wait=40>satu hal lagi...","story.map3-ending.094":"Kalau kamu bertemu mereka berdua lagi, sampaikan terima kasihku.","story.map3-ending.095":"Katakan pada mereka aku sungguh berterima kasih atas semua yang mereka lakukan untuk kita.","story.map3-ending.096":"Nah, <wait=20>aku pergi dulu, ya!","story.map3-ending.097":"Kita akan bertemu lagi sebentar lagi, <wait=20>aku yakin!","story.map3-ending.098":"Dadah!!!","story.map4-dungeon1.001":"Cih... Sejak sampai di sini, aku belum<br>ketemu satu monster pun!","story.map4-dungeon1.002":"Nggak bisa dipercaya... <wait=40>Kenapa aku, Lugina yang perkasa, harus dapat tugas remeh begini...","story.map4-dungeon1.003":"Hm?<wait=40><br>Hei, kamu! <wait=20>Sebutkan identitasmu!","story.map4-dungeon1.004":"Aha! <wait=20>Anggota Pasukan Akras, ya?<br>Siapa namamu?","story.map4-dungeon1.005":"<rep_handlename>?<wait=40><br>Cih... <wait=40>Nama yang aneh, menurutku.","story.map4-dungeon1.006":"Apa?<wait=40><br>Kamu mau tahu namaku?","story.map4-dungeon1.007":"Sebenarnya aku nggak wajib memperkenalkan diri<br>pada anggota pasukan reguler, tapi...","story.map4-dungeon1.008":"<wait=20>...Yah, kalau kamu memang ingin tahu, kurasa nggak ada ruginya memberitahumu.","story.map4-dungeon1.009":"Akulah Summoner Lugina yang perkasa,<wait=40><br>pemimpin terhormat Divisi Pembasmi Iblis ke-23,<wait=40>","story.map4-dungeon1.010":"yang juga dikenal sebagai Sky Garden!<br>Ingat itu baik-baik!","story.map4-dungeon1.011":"Jadi,<wait=40> kamu lagi cari sesuatu di sini atau apa?","story.map4-dungeon1.012":"Hah?<wait=40> Kamu sedang menjalankan misi mengalahkan Empat Dewa yang Jatuh?","story.map4-dungeon1.013":"Pft... Hehe... <size=24>Bwahaha!","story.map4-dungeon1.014":"Jadi para kakek tua di Akras benar-benar<br>sudah mulai pikun, ya!","story.map4-dungeon1.015":"Kamu nggak sungguh-sungguh mengira pasukan reguler<br>bisa mengalahkan Empat Dewa yang Jatuh, kan?","story.map4-dungeon1.016":"Sudah waktunya para tua bangka itu pensiun<br>dan menyerahkan urusan membasmi iblis ke profesional sepertiku.","story.map4-dungeon1.017":"Hmm? <wait=40>Kamu menerima perintah dari seorang dewi, katamu?<br>Bukan dari Balai Summoner?","story.map4-dungeon1.018":"...Ini lelucon, ya?<wait=40><br>Atau kamu memang sebodoh itu?","story.map4-dungeon1.019":"Kamu tahu nggak apa yang sedang<br>kukerjakan jauh-jauh di sini?","story.map4-dungeon1.020":"Nggak bisa dipercaya... <wait=40>Nah, inilah sebabnya aku selalu bilang","story.map4-dungeon1.021":"anggota pasukan reguler itu nggak bisa dipercaya.","story.map4-dungeon1.022":"Kamu tahu nggak, wilayah tempat kita berdiri<br>ini baru saja ditemukan oleh Balai Summoner Akras?","story.map4-dungeon1.023":"Belum diselidiki dengan benar,<br>jadi sebaiknya kamu hati-hati melangkah.","story.map4-dungeon1.024":"Kamu tahu sendirilah, monster dan sebagainya.","story.map4-dungeon1.025":"Pokoknya, tugas Summoner yang perkasa<br>dan hebat seperti aku inilah","story.map4-dungeon1.026":"untuk memastikan daerah berbahaya<br>seperti ini cukup aman bagi","story.map4-dungeon1.027":"Summoner pemula<br>sepertimu untuk diinjak.","story.map4-dungeon1.028":"Kalau kamu tahu diri,<br>pergilah ke tempat yang lebih aman sampai urusanku di sini selesai!","story.map4-dungeon1.029":"Masih banyak daerah di Grand Gaia<br>yang belum diselidiki dengan benar.","story.map4-dungeon1.030":"Apa? Omonganku kurang jelas?<wait=40><br>Ya ampun, kamu memang sebodoh tampangmu.","story.map4-dungeon1.031":"Nih, biar kuperjelas...<br><wait=40>Minggir dan biarkan aku bekerja dengan tenang!<wait=40>","story.map4-dungeon1.032":"Berhenti buang waktu melawan kroco-kroco ini dan cari di tempat lain!","story.map4-dungeon1.033":"Cih... Dengan orang dungu sepertimu di pasukan reguler, pantas saja Balai Summoner kesulitan...","story.map4-dungeon2.001":"Kamu lagi?!<wait=40><br>Sudah kubilang pergi dari sini!","story.map4-dungeon2.002":"Berani juga kamu<br>mengabaikanku begitu!","story.map4-dungeon2.003":"Atau kamu perlu seseorang menggandeng<br>tanganmu dan mengantarmu pulang?","story.map4-dungeon2.004":"Ya ampun... <wait=40>Anggota Pasukan Kekaisaran saja nggak seceroboh ini.","story.map4-dungeon2.005":"Hah?<wait=40><br>Kenapa tampangmu bingung begitu?","story.map4-dungeon2.006":"Tunggu sebentar... <wait=40>Jangan bilang kamu <br>belum pernah dengar soal Pasukan Kekaisaran Randall?","story.map4-dungeon2.007":"Wah. Benar-benar, deh...","story.map4-dungeon2.008":"Serius, aku jadi hampir<br>kasihan padamu.","story.map4-dungeon2.009":"Kalau begitu, apa boleh buat.","story.map4-dungeon2.010":"Aku, Lugina yang berhati murni dan mulia, akan mengajarimu semua yang perlu kamu tahu!","story.map4-dungeon2.011":"Hapus air mata terima kasihmu itu<br>dan ingat baik-baik apa yang akan kukatakan!","story.map4-dungeon2.012":"Kita mulai dari yang gampang. <wait=40>Kamu tentu tahu negeri kita, Elgaia, terpisah dari Grand Gaia.","story.map4-dungeon2.013":"Itu lho, Negeri Para Dewa,<br>kan?","story.map4-dungeon2.014":"Bagus,<wait=40> setidaknya kamu tahu sesuatu!","story.map4-dungeon2.015":"Nggak usah bangga begitu!<wait=40> Itu sih pengetahuan umum banget.","story.map4-dungeon2.016":"Ya ampun...","story.map4-dungeon2.017":"Oke, kita lanjut. <wait=40>Elgaia terdiri dari dua negara besar.","story.map4-dungeon2.018":"Salah satunya, Kekaisaran Randall, adalah tempat Balai Summoner Akras berada.","story.map4-dungeon2.019":"Balai Summoner Akras mengurus urusan ekonomi","story.map4-dungeon2.020":"dan militer negara, jadi soal kekaisaran itu sebenarnya cuma pajangan.","story.map4-dungeon2.021":"Kaum elite Randall adalah keturunan<br>orang-orang yang membangun kembali negeri itu setelah","story.map4-dungeon2.022":"terpisah dari Grand Gaia, makanya mereka bersikap begitu angkuh.","story.map4-dungeon2.023":"Sekarang mereka cuma sekumpulan tua bangka yang duduk-duduk menikmati hidup mewah.","story.map4-dungeon2.024":"Pasukan mereka jelas cuma pajangan, sekadar pamer kekuasaan, istilahnya.","story.map4-dungeon2.025":"Yah, kuakui sesekali ada satu dua prajurit berbakat yang pernah bergabung di sana.","story.map4-dungeon2.026":"Pokoknya, <wait=40>negara yang satu lagi adalah Federasi Elgaia,","story.map4-dungeon2.027":"tapi ceritanya kurang lebih sama.","story.map4-dungeon2.028":"Nggak ada satu pun dari kedua negara itu yang sanggup menandingi Balai Summoner Akras,","story.map4-dungeon2.029":"jadi praktis Balai itulah yang menguasai<br>seluruh Elgaia.","story.map4-dungeon2.030":"Dan karena aku Summoner terkuat<br>di Balai Summoner Akras,","story.map4-dungeon2.031":"berarti akulah yang terkuat di seluruh Elgaia!","story.map4-dungeon2.032":"Gimana?<wait=40><br>Kamu pasti mau minta tanda tanganku, kan?","story.map4-dungeon2.033":"<size=14>(Gemuruh, gemuruh)","story.map4-dungeon2.034":"A-<wait=20>Aduh!","story.map4-dungeon2.035":"G-<wait=20>Gempa bumi?!","story.map4-dungeon2.036":"Tapi rasanya bukan gempa<br>biasa...","story.map4-dungeon2.037":"Sekarang kamu ngerti maksudku?!","story.map4-dungeon2.038":"Cordelica nggak akan aman sampai kita tahu apa yang sebenarnya terjadi.","story.map4-dungeon2.039":"Sekarang dengarkan nasihat bijakku, dan pergi dari sini selagi masih bisa!","story.map4-dungeon2.040":"Kamu bakal menyesal kalau kita ketemu lagi!","story.map4-dungeon3.001":"<size=20>Kamu lagi?!<wait=40> <rep_handlename>!","story.map4-dungeon3.002":"Kenapa kamu masih di sini!?","story.map4-dungeon3.003":"Baiklah, cukup sudah!","story.map4-dungeon3.004":"Kalau kamu nggak mau dengar nasihatku,<wait=40> terpaksa kuhajar kamu sampai sadar!","story.map4-dungeon3.005":"Sekarang diam di tempat!","story.map4-dungeon3.006":"<size=14>(Gemuruh, gemuruh)","story.map4-dungeon3.007":"L-Lagi?!<wait=40><br>Kenapa sih belakangan ini gempa terus?","story.map4-dungeon3.008":"Hei!<wait=40> <rep_handlename>!","story.map4-dungeon3.009":"Sekarang kamu ngerti<br>maksudku?","story.map4-dungeon3.010":"Ini bukan tempat buat Summoner pemula sepertimu berkeliaran.","story.map4-dungeon3.011":"Sekarang pulang sana dan pastikan<br>ini bukan ulah Pasukan Kekaisaran!","story.map4-dungeon3.012":"...<wait=20>Kenapa tampangmu begitu?","story.map4-dungeon3.013":"Kenapa aku merasa kamu masih belum paham betapa hebatnya aku...","story.map4-dungeon3.014":"Baiklah, dengarkan.<wait=40><br>Tadi sudah kubilang,","story.map4-dungeon3.015":"di Elgaia ini ada beberapa faksi terpisah,<br>masing-masing dengan militernya sendiri.","story.map4-dungeon3.016":"Militer terkuat di antaranya milik Balai Summoner Akras.","story.map4-dungeon3.017":"Masuk akal, kan?<br>Maksudku, hampir semua","story.map4-dungeon3.018":"Summoner di Elgaia ada di sana...","story.map4-dungeon3.019":"Pokoknya, militer Akras terdiri<br>dari tiga jenis pasukan.","story.map4-dungeon3.020":"Pertama, <wait=40>ada Pasukan Summoner, alias Pasukan Reguler, tempat setiap Summoner pemula","story.map4-dungeon3.021":"memulai. Itu kesatuanmu, omong-omong.","story.map4-dungeon3.022":"Misi resmimu adalah mengalahkan Empat Dewa yang Jatuh, tapi... yah, gimana ya bilangnya?","story.map4-dungeon3.023":"Jujur saja, nggak ada yang benar-benar berharap<br>Pasukan Reguler bisa menghasilkan apa pun.","story.map4-dungeon3.024":"Lalu siapa yang diharapkan menyelesaikan tugas itu, tanyamu?<br>Tentu saja kami, para Pembasmi Iblis!","story.map4-dungeon3.025":"Kami regu jagoan berisi Summoner elite<br>yang dipilih khusus dari jajaran Pasukan Reguler.","story.map4-dungeon3.026":"Yang terkuat di antaranya, contohnya aku, lalu diberi komando atas regu-regu yang lebih kecil.","story.map4-dungeon3.027":"Tentu saja, yang terkuat di antara regu itu adalah regu yang kupimpin:","story.map4-dungeon3.028":"Divisi Pembasmi Iblis ke-23, Sky Garden!","story.map4-dungeon3.029":"Pas kamu kira aku nggak bisa lebih hebat<br>lagi, ya kan?","story.map4-dungeon3.030":"Hmm? <wait=40>Bagaimana dengan pasukan Randall<br>dan Federasi Elgaia, katamu?","story.map4-dungeon3.031":"Hah! Summoner mereka digabung pun cuma segelintir. Mereka lebih nggak berguna daripada Pasukan Reguler kita.","story.map4-dungeon3.032":"Sekarang berhenti merecokiku dengan pertanyaan, dan pulang sana ke tempatmu!","story.map4-dungeon3.033":"Monster di sekitar sini bukan<br>monster lembek seperti yang biasa kamu hadapi!","story.map4-dungeon3.034":"Dengar nggak? Pergi sana!","story.map4-dungeon3.035":"*Huh* <wait=40>Salah apa aku sampai<br>ditugaskan jauh-jauh ke sini?","story.map4-dungeon3.036":"Jadi mereka mengirim Pembasmi Iblis Lugina dari Sky Garden, ya...","story.map4-dungeon3.037":"Heh. Mungkin mereka cuma ingin dia<br>berhenti merepotkan mereka sebentar...","story.map4-dungeon3.038":"Tapi tampaknya dia cukup mudah dimanfaatkan untuk tujuanku.","story.map4-dungeon3.039":"Sekarang tinggal menyusun rencana...","story.map4-dungeon4.001":"<size=20>Kamu lagi?! <rep_handlename>!","story.map4-dungeon4.002":"Cukup sudah! Nggak ada lagi Lugina yang baik hati!","story.map4-dungeon4.003":"Semoga kamu suka tempatmu berdiri sekarang, karena di situlah kamu bakal kukubur setelah urusanku selesai!","story.map4-dungeon4.004":"<size=18>(Gemuruh, gemuruh)","story.map4-dungeon4.005":"Lagi...?<br>Gempa-gempa ini jelas nggak normal.","story.map4-dungeon4.006":"Dasar orang-orang tua bodoh di Balai Summoner...<br>Sialan mereka semua!","story.map4-dungeon4.007":"Dengar, <rep_handlename>!","story.map4-dungeon4.008":"Tempat ini terlalu berbahaya buat kita<br>berlama-lama.","story.map4-dungeon4.009":"Aku akan menulis laporan temuanku dan langsung<br>kembali ke Elgaia. <wait=40>Kamu jadi saksiku, kan?","story.map4-dungeon4.010":"Ingat semua yang sudah kuajarkan padamu!<br>Kamu nggak akan mengecewakan teman lama, kan?","story.map4-dungeon4.011":"Omongan yang agak pengecut untuk seseorang yang mengaku petinggi Pembasmi Iblis, bukan begitu?","story.map4-dungeon4.012":"...?!<br><wait=40>Siapa kamu?","story.map4-dungeon4.013":"L-Lambang itu...","story.map4-dungeon4.014":"Nggak mungkin!<br>Anggota Pengawal Kekaisaran?!","story.map4-dungeon4.015":"Benar sekali.<br>Mungkin kamu memang cocok jadi guru.","story.map4-dungeon4.016":"Namaku Paris. Aku berasal dari salah satu<br>pasukan “nggak berguna” yang kamu sebut tadi.","story.map4-dungeon4.017":"Jadi kamu menguping dari tadi?<br>Nggak ada yang pernah mengajarimu sopan santun?","story.map4-dungeon4.018":"Aku bisa menanyakan hal yang sama padamu.","story.map4-dungeon4.019":"Atau menurutmu mengabaikan perintah<br>negaramu, apalagi merendahkan","story.map4-dungeon4.020":"Pasukan Kekaisaran yang bekerja keras<br>demi kemakmuran kerajaan kita, adalah sikap orang terhormat?","story.map4-dungeon4.021":"Cih...<br><wait=40>Oh, maaf sekali! Tolong ampuni aku!","story.map4-dungeon4.022":"Sudah kuduga, kalian anggota<br>Balai Summoner memang sama-sama kasar...","story.map4-dungeon4.023":"Bilang saja ke orang yang peduli,<br>nona!","story.map4-dungeon4.024":"Lagi pula, kalian para dungu Pengawal Kekaisaran<br>tugasnya melindungi Keluarga Kekaisaran, kan?","story.map4-dungeon4.025":"Ngapain kamu jauh-jauh ke sini?","story.map4-dungeon4.026":"Aku nggak punya waktu seharian,<br>jadi cepat buka mulut!","story.map4-dungeon4.027":"Heh...<br>Bersemangat juga untuk ukuran seorang anak buah.","story.map4-dungeon4.028":"Siapa yang kamu sebut anak buah?!","story.map4-dungeon4.029":"Kamu kira aku dan si tolol ini partner? Hah!","story.map4-dungeon4.030":"Terserahlah, nona.<br>Aku punya hal yang lebih penting","story.map4-dungeon4.031":"daripada cari ribut dengan<br>Pengawal Kekaisaran di pelosok begini.","story.map4-dungeon4.032":"Ah, diplomasi khas Pembasmi Iblis yang terkenal itu.<br>Setidaknya kita semua tahu posisi masing-masing.","story.map4-dungeon4.033":"Yah, terus terang aku datang jauh-jauh ke sini untuk meminta bantuanmu.","story.map4-dungeon4.034":"Kami ingin meminta bantuanmu<br>untuk menyelidiki Cordelica.","story.map4-dungeon4.035":"Hah!<wait=40><br>Kamu barusan bilang apa?","story.map4-dungeon4.036":"Aku nggak cari masalah, <wait=40>tapi aku juga nggak sudi menuruti perintahmu!","story.map4-dungeon4.037":"Tempat ini nggak aman buat kita,<br>kalau kamu belum sadar.","story.map4-dungeon4.038":"Rupanya kamu sadar akan bahaya<br>wilayah ini.","story.map4-dungeon4.039":"Tentu saja, memang itu yang kuharapkan<br>dari seseorang yang mengaku pemimpin Pembasmi Iblis.","story.map4-dungeon4.040":"Apa maksudmu, hah?","story.map4-dungeon4.041":"Maksud?<wait=40> Tidak, aku hanya menyatakan fakta.","story.map4-dungeon4.042":"Orang yang takut pada<br>beberapa gempa remeh tak mungkin","story.map4-dungeon4.043":"memimpin regu berbakat seperti yang kamu bilang, bukan?","story.map4-dungeon4.044":"Kurang ajar!<wait=40><br>Jaga mulutmu!","story.map4-dungeon4.045":"Kamu menyebutku pengecut?!","story.map4-dungeon4.046":"Jangan bikin aku ketawa!<wait=40><br>Akan kutunjukkan apa artinya takut!","story.map4-dungeon4.047":"Hei!<wait=40> <rep_handlename>!","story.map4-dungeon4.048":"Sudah waktunya kamu kerja juga di sini!","story.map4-dungeon4.049":"Dari tadi kamu mengabaikan semua<br>yang kukatakan.","story.map4-dungeon4.050":"Kamu pasti merasa dirimu hebat, ya?","story.map4-dungeon4.051":"Kalau memang jagoan, buktikan dengan menyingkirkan si cebol yang sembunyi di benteng sana!","story.map4-dungeon4.052":"Mulai sekarang monster yang kita temui<br>bakal makin kuat,","story.map4-dungeon4.053":"tapi kamu pun seharusnya nggak<br>kesulitan menghadapi yang di sana.","story.map4-dungeon4.054":"Hehe... <wait=40>Ini bakal menarik.","story.map4-dungeon4.055":"...Gimana?! Jangan bengong saja!<wait=40><br>Maju sana dan hajar mereka!","story.map4-dungeon4.056":"Kamu dengar sendiri,<br><rep_handlename>... Hehe.","story.map4-dungeon5.001":"Hmph! <wait=40>Lama sekali kamu<br>sampai ke sini.","story.map4-dungeon5.002":"Pantas saja aku nggak terlalu menghormati<br>kalian anak-anak Pasukan Reguler.","story.map4-dungeon5.003":"Tapi setidaknya kamu sampai lebih dulu daripada Pengawal Kekaisaran yang sok benar itu, lumayanlah.","story.map4-dungeon5.004":"Memangnya siapa yang kamu maksud?","story.map4-dungeon5.005":"Ap-? <wait=20>Kamu?!<wait=40><br>Sejak kapan kamu berdiri di situ!","story.map4-dungeon5.006":"Sejak sebelum kamu datang dan<br>mulai mempermalukan dirimu sendiri.","story.map4-dungeon5.007":"Kurang ajar! <wait=40>Kamu<br>mengawasiku dari tadi!","story.map4-dungeon5.008":"Ah, santai saja, bisa?","story.map4-dungeon5.009":"Aku punya hal yang lebih penting<br>daripada mengamati setiap gerak-gerikmu.","story.map4-dungeon5.010":"Argh, biar kuhajar dia!","story.map4-dungeon5.011":"Inilah sebabnya aku benci kalian Pengawal<br>Kekaisaran, selalu saja sok!","story.map4-dungeon5.012":"Keluhanmu bisa disampaikan nanti.<wait=40><br>Pertama, katakan apa yang kamu lakukan di sini.","story.map4-dungeon5.013":"Hah?<wait=40> <br>Kamu bercanda, ya?","story.map4-dungeon5.014":"Aku di sini untuk menyelidiki reruntuhan, tentu saja.","story.map4-dungeon5.015":"Lihat itu! Pasti sudah ada<br>sejak sebelum Keruntuhan Besar.","story.map4-dungeon5.016":"Pernah lihat tempat yang<br>segitu menggodanya untuk diselidiki?","story.map4-dungeon5.017":"Pokoknya, aku datang untuk memeriksanya,<br>dan yang satu ini terus membuntutiku.","story.map4-dungeon5.018":"Begitu...<wait=40><br>Jadi kamu bisa membaca aksara kuno, rupanya?","story.map4-dungeon5.019":"Kukira akulah yang<br>seharusnya melakukan penyelidikan...","story.map4-dungeon5.020":"Apa itu? Kamu kira aku nggak becus, ya!?","story.map4-dungeon5.021":"Cuma kamu yang mampu<br>berpikir pintar, begitu?","story.map4-dungeon5.022":"Tidak, <wait=40>malah aku cukup terkesan.","story.map4-dungeon5.023":"Mungkin kamu tidak sebodoh<br>penampilan kasarmu itu.","story.map4-dungeon5.024":"...<wait=40>Kuperingatkan kamu,<br>nona.","story.map4-dungeon5.025":"Jangan kira aku bakal diam saja kalau kamu terus memancingku.","story.map4-dungeon5.026":"Dan percayalah, kalau aku marah,<br>aku bisa menghancurkan apa pun jadi debu!","story.map4-dungeon5.027":"Pengawal Kekaisaran atau bukan.","story.map4-dungeon5.028":"Wah, seram sekali.<br>Sebaiknya aku jaga sikap di depanmu.","story.map4-dungeon5.029":"Grrr...<wait=40><br>Sudah kuduga! Kamu mengejekku!","story.map4-dungeon5.030":"Hehe...<wait=40><br>Kamu kira aku sekejam itu?","story.map4-dungeon5.031":"Malah, sebaiknya kamu juga hati-hati jangan sampai membuat Lugina kesal, mengerti?","story.map4-dungeon5.032":"Walau aku tak bisa membayangkan<br>teman Karl","story.map4-dungeon5.033":"takut pada anggota Sky Garden...","story.map4-dungeon5.034":"Hah?<wait=40><br>Karl yang kamu sebut ini... <wait=40>Jangan-jangan Karl dari Nyonne?","story.map4-dungeon5.035":"<size=20>Bwahaha!","story.map4-dungeon5.036":"Oh, sudah lama aku nggak ketawa begini.<wait=40><br>Si dungu ini temannya Karl? Yang benar saja!","story.map4-dungeon5.037":"Sekarang aku benar-benar sudah dengar segalanya...","story.map4-dungeon5.038":"Hei, mau ke mana kamu!","story.map4-dungeon5.039":"Menyelidiki.<wait=40><br>Kita bisa menjangkau lebih banyak kalau berpencar, bukan?","story.map4-dungeon5.040":"Lugina,<wait=40><br>kamu periksa ke sana.","story.map4-dungeon5.041":"T-Tunggu!<wait=40><br>Gimana aku tahu harus ke mana...","story.map4-dungeon5.042":"...Hmph.","story.map4-dungeon5.043":"Kalau mau bohong di depanku,<br>setidaknya buat yang agak masuk akal.","story.map4-dungeon5.044":"Heh, seakan si dungu bego ini<br>benar-benar kenal Karl...","story.map4-dungeon5.045":"Grr... <wait=40>Baru memikirkan<br>si cowok cantik berwajah perempuan itu saja darahku sudah mendidih!","story.map4-dungeon5.046":"Hei, kamu! <wait=40>Jangan bengong kayak orang bodoh! Maju sana dan bereskan monster-monster itu!","story.map4-dungeon6.001":"<size=20>Argh, <wait=40>cukup sudah!","story.map4-dungeon6.002":"Aku muak!<br>Salah apa aku sampai begini, hah?!","story.map4-dungeon6.003":"Kenapa harus aku yang melawan<br>binatang-binatang mengerikan begitu!","story.map4-dungeon6.004":"Nggak adil!<wait=40><br>Aku nggak salah apa-apa!","story.map4-dungeon6.005":"Hiii!!<wait=40><br>...Oh, cuma kamu, <rep_handlename>.","story.map4-dungeon6.006":"Cih... Sejak ketemu kamu<br>aku cuma dapat masalah.","story.map4-dungeon6.007":"Mengeluh seperti biasa, ya?<br>Sungguh, Lugina, itu tidak pantas bagi pria sekelas kamu.","story.map4-dungeon6.008":"Diam kamu!<wait=40><br>Apa maksudmu sih, selalu mengendap-endap di belakangku begitu!","story.map4-dungeon6.009":"Kamu salah satu alasan aku sampai<br>terseret ke urusan konyol ini!","story.map4-dungeon6.010":"Keadaan kita memang jauh dari ideal,<br>itu kuakui.","story.map4-dungeon6.011":"Tapi memaki orang dan mengeluh tidak akan mengubah keadaan.","story.map4-dungeon6.012":"Kamu kira aku nggak tahu<br>itu?!","story.map4-dungeon6.013":"Biar kukasih tahu, aku nggak menyusuri terowongan kotor ini buat senang-senang, oke!","story.map4-dungeon6.014":"Hehe...<wait=40><br>Tidak, aku bisa melihatnya.","story.map4-dungeon6.015":"Tapi tampaknya kamu tahu<br>apa yang harus dilakukan.","story.map4-dungeon6.016":"Benar. <wait=40>Dan justru itu yang kukeluhkan.","story.map4-dungeon6.017":"Baiklah! Ayo cepat lewati<br>terowongan ini dan bergegas ke Reruntuhan Raksasa.","story.map4-dungeon6.018":"Wah, ada yang terburu-buru rupanya...<wait=40> Sebaiknya kamu juga bergegas.","story.map4-dungeon6.019":"Kalau kita tidak bergegas, dewa agung itu akan<br>bangun dan meluluhlantakkan seluruh benua ini.","story.map4-dungeon6.020":"Nggak ada waktu buat menjelaskan ke si bebal itu!","story.map4-dungeon6.021":"Aku yang memimpin jalan.","story.map4-dungeon6.022":"Kamu habisi sisa-sisa musuh yang<br>berhasil lolos dariku!","story.map4-dungeon6.023":"Heh...<wait=40><br>Ucapan seorang pejuang sejati, Lugina.","story.map4-dungeon6.024":"Tapi kamu keliru soal satu hal.","story.map4-dungeon6.025":"<rep_handlename> berhak tahu<br>bahaya yang sedang kita hadapi.","story.map4-dungeon6.026":"Kamu sudah melihat <rep_handlename> bertarung,<br>bukan?","story.map4-dungeon6.027":"Kita harus memanfaatkan semua<br>kekuatan militer yang ada di tangan kita.","story.map4-dungeon6.028":"Hmph! <wait=40>Terserah kamu.<br>Tapi semua penjelasan kuserahkan padamu!","story.map4-dungeon6.029":"Aku sudah muak<br>mengasuh bocah kebesaran ini.","story.map4-dungeon6.030":"Sepertinya dia memutuskan pergi<br>sendiri, ujung-ujungnya.","story.map4-dungeon6.031":"Cih... Dia tak akan pernah punya teman<br>dengan sikap masam begitu.","story.map4-dungeon6.032":"Nah,<wait=40><br>akhirnya tinggal kita berdua!","story.map4-dungeon6.033":"Jadi kamulah yang dibicarakan para Tetua, teman Karl,","story.map4-dungeon6.034":"pemimpin Divisi Pembasmi Iblis ke-24 yang perkasa, Rebluens.","story.map4-dungeon6.035":"Aku sudah mendengar banyak cerita hebat tentangmu,<br><rep_handlename>.","story.map4-dungeon6.036":"Tak perlu terlihat<br>waspada begitu.","story.map4-dungeon6.037":"Santai saja.<wait=40><br>Aku ada di pihakmu, tahu.","story.map4-dungeon6.038":"Melihat ekspresimu, sepertinya masih butuh waktu sebelum aku mendapat kepercayaanmu.","story.map4-dungeon6.039":"Sampai di mana tadi?<wait=40><br>Ah ya, para raksasa.","story.map4-dungeon6.040":"Sebenarnya tidak terlalu rumit.","story.map4-dungeon6.041":"Dahulu kala, ras raksasa pernah tinggal<br>di Cordelica ini.","story.map4-dungeon6.042":"Namun, seluruh ras mereka<br>dimusnahkan oleh kekuatan di luar pemahaman kita.","story.map4-dungeon6.043":"Semuanya, kecuali satu:<br>yang kini dikenal sebagai Dewa Raksasa.","story.map4-dungeon6.044":"Tenggelam dalam amarah dan keputusasaan<br>atas kematian kaumnya, ","story.map4-dungeon6.045":"sang raksasa menyegel dirinya di negeri ini.","story.map4-dungeon6.046":"Begitulah legenda yang terukir di<br>Menara Cahaya. <wait=40>Siapa penulisnya, tak ada yang tahu.","story.map4-dungeon6.047":"Lugina pasti juga menemukan<br>ukiran yang sama.","story.map4-dungeon6.048":"Setelah membacanya, <wait=40>dia pasti<br>sampai pada kesimpulan yang sama denganku...","story.map4-dungeon6.049":"Yaitu, Dewa Raksasa akan segera<br>bangkit dari tidurnya, penuh amarah.","story.map4-dungeon6.050":"Heh...<wait=40> <br>Sepertinya akhirnya aku mendapat perhatian penuhmu.","story.map4-dungeon6.051":"Santai saja.<wait=40><br>Dilihat dari besarnya guncangan,","story.map4-dungeon6.052":"Dewa Raksasa belum sepenuhnya bangun.","story.map4-dungeon6.053":"Menurut ukiran di reruntuhan,<br>saat sang raksasa akhirnya bangun,","story.map4-dungeon6.054":"seluruh pulau ini akan tertelan<br>dalam sekejap.","story.map4-dungeon6.055":"Ayo.<wait=40><br>Kita harus berangkat sekarang.","story.map4-dungeon6.056":"Reruntuhan tempat Dewa Raksasa berbaring seharusnya ada tepat di balik terowongan ini.","story.map4-dungeon7.001":"...Ya. <wait=40>Grantos masih setengah sadar,<br>tapi kini dia sudah bangun.","story.map4-dungeon7.002":"Tidak, Tuan, <wait=40>itu tidak akan<br>jadi masalah.","story.map4-dungeon7.003":"Tentu, Tuan.<wait=40><br>Saya akan mengabari bila ada perkembangan baru.","story.map4-dungeon7.004":"Hei, <wait=40>perempuan!","story.map4-dungeon7.005":"Sudah selesai bergosip<br>di sana?","story.map4-dungeon7.006":"Kamu melaporkanku ke salah satu<br>teman Kekaisaranmu, atau apa?","story.map4-dungeon7.007":"Heh. Tak ada yang luput darimu, ya?","story.map4-dungeon7.008":"Kekaisaran sangat tertarik pada<br>Summoner muda berbakat.","story.map4-dungeon7.009":"Bah!<wait=40><br>Yah, aku sih nggak tertarik balik!","story.map4-dungeon7.010":"...!","story.map4-dungeon7.011":"Hei, <rep_handlename>!<br>Bisa lebih cepat sedikit nggak?","story.map4-dungeon7.012":"Kalau kamu belum sadar, kita<br>lagi dalam keadaan darurat di sini!","story.map4-dungeon7.013":"Kalau memang terburu-buru,<br>kenapa nggak duluan saja tanpa kami?","story.map4-dungeon7.014":"Kalian memang bukan tandingan Lugina yang agung, tapi amatiran seperti kalian pun ada gunanya!","story.map4-dungeon7.015":"Heh...","story.map4-dungeon7.016":"Baiklah, dengarkan.<wait=40><br>Aku akan pergi membasmi Grantos,","story.map4-dungeon7.017":"Dewa Raksasa yang sudah tertidur<br>selama ratusan tahun.","story.map4-dungeon7.018":"Karena aku yang perkasa,<br>akulah yang akan mengerjakan bagian beratnya.","story.map4-dungeon7.019":"Tapi aku nggak mau diganggu<br>antek-antek kecil yang menyebalkan selagi bertarung.","story.map4-dungeon7.020":"Di situlah tugas kalian.<wait=40> Kalian pancing perhatian mereka selagi aku menghadapi si raksasa!","story.map4-dungeon7.021":"Kamu mau melawan monster sebesar<br>itu seorang diri? Sungguh jantan sekali...","story.map4-dungeon7.022":"Nyindir, ya?","story.map4-dungeon7.023":"Seakan kalian punya kemampuan<br>untuk berhadapan langsung dengan raksasa seperti itu!","story.map4-dungeon7.024":"Mending kuhadapi sendiri daripada harus menyelamatkan kalian berdua kalau semuanya kacau.","story.map4-dungeon7.025":"Lihat saja, <wait=40>akan kutunjukkan arti kekuatan sejati.","story.map4-dungeon7.026":"Jadi sudah jelas? <wait=40>Kalian alihkan antek-anteknya selagi aku menyelamatkan dunia!","story.map4-dungeon7.027":"Dan ingat, kalau kalian sampai gagal,<br>kucincang kalian pakai pedang kalian sendiri!","story.map4-dungeon7.028":"Dia memang cukup suka memerintah untuk<br>memimpin resimen Pembasmi Iblis...","story.map4-dungeon7.029":"Nada bicaranya masih jauh dari sopan,","story.map4-dungeon7.030":"tapi setidaknya dia tampak cakap<br>dan cukup berpengetahuan.","story.map4-dungeon7.031":"Belum lagi, data yang dia kumpulkan<br>lebih banyak dari dugaanku.","story.map4-dungeon7.032":"Tapi, berdasarkan temuanku,","story.map4-dungeon7.033":"mustahil dia bisa menghadapi<br>Grantos seorang diri.","story.map4-dungeon7.034":"Kurasa aku harus membantunya.","story.map4-dungeon7.035":"Tentu saja,<wait=40><br>dia juga akan butuh bantuanmu.","story.map4-dungeon7.036":"Sudah waktunya melihat kemampuanmu<br>yang sesungguhnya.","story.map4-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map4-dungeon_ex_clear.002":"Anda berhasil, <rep_handlename>!","story.map4-dungeon_ex_clear.003":"Terima kasih banyak!","story.map4-dungeon_ex_clear.004":"Saya tahu Anda pasti bisa!","story.map4-dungeon_ex_clear.005":"Anda memang yang terbaik!","story.map4-dungeon_ex_clear.006":"Hehe, <wait=20>maaf, saya jadi agak terbawa suasana.","story.map4-dungeon_ex_clear.007":"Omong-omong, kami sudah tahu monster apa itu.","story.map4-dungeon_ex_clear.008":"Sepertinya awalnya monster itu dipelihara para raksasa untuk mengurus sampah.","story.map4-dungeon_ex_clear.009":"Namun, lama-lama ia tumbuh begitu besar sampai para raksasa pun tak bisa mengendalikannya lagi. ","story.map4-dungeon_ex_clear.010":"Akhirnya ia dikurung di tempat itu oleh seorang pahlawan.","story.map4-dungeon_ex_clear.011":"Pahlawan itu pasti luar biasa kuat sampai bisa menaklukkan monster yang bahkan tak sanggup ditangani para raksasa.","story.map4-dungeon_ex_clear.012":"Oh, <wait=20>tapi tentu saja Anda juga kuat!","story.map4-dungeon_ex_clear.013":"Maksud saya, Anda mengalahkan monster raksasa itu sendirian!","story.map4-dungeon_ex_clear.014":"Padahal ia begitu berlendir dan menjijikkan...","story.map4-dungeon_ex_clear.015":"Saya sungguh mengagumi Anda, <rep_handlename>!","story.map4-dungeon_ex_clear.016":"Eh, apa itu?","story.map4-dungeon_ex_clear.017":"Ada sesuatu di bahu Anda. <wait=20>Jangan-jangan...","story.map4-dungeon_ex_clear.018":"<size=21>Kyaaaaahh!</size>","story.map4-dungeon_ex_clear.019":"<size=21>Iih, berlendir semua!!</size>","story.map4-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map4-dungeon_ex_open.002":"Tuan, <wait=20>gawat! <wait=40>Gawat sekali!","story.map4-dungeon_ex_open.003":"Maaf! Saya tidak bermaksud membuat panik...","story.map4-dungeon_ex_open.004":"Saya Lin Merylham dari Dukungan Logistik...","story.map4-dungeon_ex_open.005":"...Biro Investigasi Kantor Survei Grand Gaia, siap melayani Anda.","story.map4-dungeon_ex_open.006":"B-<wait=20>Bagaimana Anda bisa setenang itu di saat seperti ini!?","story.map4-dungeon_ex_open.007":"<rep_handlename>, sebagai anggota Pasukan Summoner Balai Summoner Akras...","story.map4-dungeon_ex_open.008":"...kami meminta Anda menyelidiki Gua Ignia!","story.map4-dungeon_ex_open.009":"Sepertinya ada monster yang tertidur di balik Air Terjun Ignia.","story.map4-dungeon_ex_open.010":"Namun, gempa di Cordelica beberapa hari lalu tampaknya membangunkannya.","story.map4-dungeon_ex_open.011":"Dan soal monsternya sendiri...","story.map4-dungeon_ex_open.012":"Ia basah dan lengket, dan memakan apa saja!","story.map4-dungeon_ex_open.013":"Membayangkan monster sebesar dan semenjijikkan itu saja sudah membuat saya merinding.","story.map4-dungeon_ex_open.014":"<size=21>Kyaaaaaahh! Menjijikkan!!</size>","story.map4-ending.001":"Heh, <wait=40>sesuai dugaanku.","story.map4-ending.002":"Pantas saja Karl begitu menghargaimu.","story.map4-ending.003":"(Hah... <wait=40>hah...)","story.map4-ending.004":"Wah, <wait=40>lihat siapa yang akhirnya datang!","story.map4-ending.005":"...<wait=40>Aduh, mulai lagi.","story.map4-ending.006":"Kamu sudah dengar kabarnya, kan?","story.map4-ending.007":"<rep_handlename> baru saja mengalahkan<br>Grantos.","story.map4-ending.008":"Ternyata jasamu tidak dibutuhkan.<br>Padahal tadi kamu sudah sesumbar begitu...","story.map4-ending.009":"K-Kurang ajar...<wait=40><br>Kalau mau adu omong besar, ayo kuhadapi kamu di sini juga!","story.map4-ending.010":"Hentikan saja lagak beranimu itu.<wait=40><br>Kamu sudah dapat kesempatan, dan kamu menyia-nyiakannya.","story.map4-ending.011":"D-Diam kamu!<wait=40><br>Informasi yang kutemukan itu nggak salah!","story.map4-ending.012":"Raksasa sialan itu pasti pindah posisi atau apa...","story.map4-ending.013":"Kuakui, kamu sampai pada kesimpulan yang sama denganku,","story.map4-ending.014":"dan kamu berhasil menumbangkan beberapa monster tangguh dalam perjalanan ke sini.","story.map4-ending.015":"Meski begitu, kamu tidak berhasil menuntaskan misimu.","story.map4-ending.016":"Apa gunanya hebat kalau kamu gagal di saat yang paling menentukan?","story.map4-ending.017":"Grr...<wait=40> Lihat saja nanti!<br>Memangnya kamu tahu apa?!","story.map4-ending.018":"Cukup sudah! Aku berhenti!","story.map4-ending.019":"Dari awal aku nggak pernah minta mengasuh kalian, dan lihat jadinya!","story.map4-ending.020":"Aku pulang ke Elgaia!","story.map4-ending.021":"Lagi pula, aku harus menyerahkan laporanku<br>ke para tua bangka di Balai Summoner.","story.map4-ending.022":"......","story.map4-ending.023":"Hei!<wait=40> <rep_handlename>!","story.map4-ending.024":"Jangan kira kamu hebat cuma karena beruntung bisa mengalahkan Grantos!","story.map4-ending.025":"Aku bisa mengalahkannya sambil merem<br>dan satu tangan di belakang punggung!","story.map4-ending.026":"Malah, harusnya kamu berterima kasih padaku!","story.map4-ending.027":"Ya, benar! <wait=40>Berterima kasih pada Summoner terkuat di seluruh Balai Summoner Akras karena sudah menjagamu!","story.map4-ending.028":"Ehem.<wait=40> Bukankah Karl dari regu Rebluens yang terkuat di Balai Summoner?","story.map4-ending.029":"Kamu mau mataku bikin<br>lebam atau gimana?","story.map4-ending.030":"Jangan sebut nama itu!","story.map4-ending.031":"Bakat di jari kelingkingku lebih banyak daripada di seluruh tubuh si sok jago itu!","story.map4-ending.032":"Si payah itu cuma kebetulan ada di tempat dan waktu yang tepat, itu saja!","story.map4-ending.033":"Di Randall, katanya dia seorang diri mengalahkan Sagamur, sang Naga Inferno.","story.map4-ending.034":"Setelah itu, katanya dia direkrut langsung untuk Pengawal Kekaisaran.","story.map4-ending.035":"Hah! Dia?!<wait=40><br>Dia mungkin yang memberi pukulan terakhir,","story.map4-ending.036":"tapi resimen lain yang<br>sebenarnya membuat naga itu bertekuk lutut!","story.map4-ending.037":"Dan ya,<wait=40> kalau kamu penasaran,<wait=40>","story.map4-ending.038":"resimen lain itu adalah Sky Garden, asal tahu saja!","story.map4-ending.039":"Ah ya, <wait=40>sekarang aku ingat.","story.map4-ending.040":"Katanya pemimpin Sky Garden pingsan setelah mendengar lolongan di kegelapan...","story.map4-ending.041":"Apa?!","story.map4-ending.042":"B-Bukan begitu kejadiannya!","story.map4-ending.043":"Aku mempertaruhkan nyawa untuk melindungi para lemah itu dari apa pun yang mengintai di sana!","story.map4-ending.044":"Berkat akulah mereka<br>bisa bertarung sama sekali!","story.map4-ending.045":"Kalau aku nggak ada, peluang mereka menang nol besar!","story.map4-ending.046":"Hehe. <wait=40>Kalau begitu, aku<br>harus minta maaf karena meragukan pemimpin agung Sky Garden.","story.map4-ending.047":"Sudah seharusnya!","story.map4-ending.048":"Cih... <wait=40>Nah, inilah sebabnya aku<br>nggak tahan sama si penipu Karl itu.","story.map4-ending.049":"Mana rasa hormatnya?<br>Aku ini atasannya, astaga!","story.map4-ending.050":"Aku nggak peduli kamu<br>atau perempuan Kekaisaran yang tolol itu,","story.map4-ending.051":"siapa pun yang memihak Karl cuma duri dalam dagingku!","story.map4-ending.052":"Dengar baik-baik, <rep_handlename>, karena aku cuma bilang sekali!","story.map4-ending.053":"Lain kali kamu menghalangiku,","story.map4-ending.054":"kuhajar kamu sampai seminggu nggak bisa duduk!","story.map4-ending.055":"Kalau nggak mau begitu, mulai sekarang hormati aku!","story.map4-ending.056":"Akulah Lugina yang agung dan perkasa, jangan lupa itu!","story.map4-ending.057":"Heh...<wait=40> <br>Yah, itu bisa berjalan lebih baik.","story.map4-ending.058":"Ngomong-ngomong,<wait=40><br>sudah waktunya aku juga pergi.","story.map4-ending.059":"Kalau kamu masih bertekad memburu Empat Dewa yang Jatuh,<wait=40> mungkin suatu hari jalan kita akan bertemu lagi.","story.map4-ending.060":"Aku menantikan bertarung bersamamu<br>di masa depan.","story.map4-ending.061":"Semoga beruntung,<br>pejuang pemberani.","story.map4-ending.062":"––Begitu.<wait=40><br>Jadi memang bukan di Cordelica...","story.map4-ending.063":"––Aku sudah menduganya,<wait=40><br>tapi tetap saja sedikit kecewa.","story.map4-ending.064":"––Hmm?<wait=40><br>Kamu tidak perlu minta maaf.","story.map4-ending.065":"––Kalau ada yang harus minta maaf, justru aku<br>karena menyuruhmu mengejar sesuatu yang sia-sia.","story.map4-ending.066":"––Ya, tentu.<wait=40><br>Teruskan kerja bagusmu.","story.map4-ending.067":"––Ingat, aku mengandalkanmu.","story.map4-ending.068":"Hehe...","story.map4-ending.069":"Jadi, <wait=40>Summoner muda itu<br>berhasil mengalahkan Grantos...","story.map4-ending.070":"Persis seperti dugaanku.","story.map4-ending.071":"Dunia tampaknya memang bergerak<br>ke arah yang benar.","story.map4-ending.072":"Sekarang tinggal menunggu Paris segera<br>menemukan apa yang sebenarnya tertidur di Grand Gaia.","story.map4-ending.073":"......","story.map4-ending.074":"Kamu mendengarkan, bukan?","story.map4-ending.075":"Waktu sudah mulai berjalan.<wait=40><br>Tak ada jalan kembali sekarang.","story.map4-ending.076":"Sebaiknya tuanmu bersiap<br>menghadapi apa yang akan datang.","story.map4-ending.077":"......","story.map4-ending.078":"...<wait=40>Hehe.","story.map4-ending.079":"<size=20>Mwahaha!","story.map4-open.001":"(Tok, <wait=20>tok.)","story.map4-open.002":"Permisi, Tuan.","story.map4-open.003":"Menurut sumber kami di pemerintahan,","story.map4-open.004":"Balai Summoner Akras telah menguasai<br>wilayah selatan Mistral.","story.map4-open.005":"...<wait=40>Ya, <wait=40>begitulah yang kudengar.","story.map4-open.006":"Mereka juga mulai menjadi<br>kekuatan yang cukup besar di Grand Gaia.","story.map4-open.007":"Tampaknya begitu...","story.map4-open.008":"Paris,<wait=40><br>aku ingin kamu pergi ke Cordelica.","story.map4-open.009":"Kabari aku tentang setiap<br>perkembangan baru di garis depan.","story.map4-open.010":"...<wait=40>Baik, Tuan.<wait=40><br>...<wait=40>Lalu bagaimana dengan tugas rutin saya?","story.map4-open.011":"Aku akan menjelaskan situasinya kepada Kaisar.","story.map4-open.012":"Terima kasih, Tuan.<wait=40><br>Kalau begitu, saya permisi.","story.map4-open.013":"......","story.map4-open.014":"...Oh,<wait=40><br>aku tak melihatmu di situ.","story.map4-open.015":"Kamu memang tak pernah mengetuk dulu, ya?","story.map4-open.016":"......","story.map4-open.017":"Balai Summoner Akras <wait=40>dan Pemerintah Federasi Elgaia...<wait=60><br>Faksi Abel mulai bergerak...","story.map4-open.018":"......","story.map4-open.019":"...<wait=40>Hehe.","story.map4-open.020":"<size=20>Mwahaha!","story.map4-open.021":"Sepertinya keadaan akan<br>segera menarik...","story.map5-dungeon1.001":"...<wait=40>Tempat ini suram sekali. ","story.map5-dungeon1.002":"Sepertinya pertempuran juga sampai ke sini.","story.map5-dungeon1.003":"Tragis sekali...","story.map5-dungeon1.004":"Kita harus berusaha sekuat tenaga agar ini tidak terulang lagi.","story.map5-dungeon1.005":"Wah, <wait=40><rep_handlename>,<wait=40> wajahmu kelihatan percaya diri sekali!","story.map5-dungeon1.006":"Benar, <wait=40>ayo kita kalahkan Cardes yang nakal itu!","story.map5-dungeon1.007":"Hah? <wait=40>Kamu tanya siapa Cardes?","story.map5-dungeon1.008":"Oh, maaf!<wait=40> <br>Aku belum cerita soal dia, ya!?","story.map5-dungeon1.009":"Ehem, <wait=40>baiklah, <wait=40>saatnya waktu dongeng bersama Tilith!","story.map5-dungeon1.010":"Kepulauan Palmyna ini dikuasai oleh \\"Cardes Sang Keji\\", salah satu dari Empat Dewa yang Jatuh. ","story.map5-dungeon1.011":"Tujuan kita sekarang, <rep_handlename>, adalah mengalahkannya!","story.map5-dungeon1.012":"Dan kamu harus waspada, karena dia jauh lebih kuat daripada Maxwell! ","story.map5-dungeon1.013":"Tapi kamu nggak perlu khawatir!","story.map5-dungeon1.014":"Soalnya, <wait=20>sebagian besar kekuatan Cardes saat ini masih tersegel.","story.map5-dungeon1.015":"Katanya kekuatan itu disegel saat perang besar, jauh di dalam Palmyna, di tempat yang disebut \\"Dunia Roh\\"...","story.map5-dungeon1.016":"Pasti dulu ada manusia hebat lain di sini selain kamu, <rep_handlename>.","story.map5-dungeon1.017":"Tunggu,<wait=40> sebentar...","story.map5-dungeon1.018":"Berarti Cardes tetap menguasai negeri ini bahkan setelah kekuatannya disegel, kan? ","story.map5-dungeon1.019":"Mungkin dia jauh lebih kuat dari yang kubayangkan...","story.map5-dungeon1.020":"...<wait=20>...","story.map5-dungeon1.021":"Pokoknya, <wait=40>kita tetap harus mengalahkannya!","story.map5-dungeon1.022":"Tapi buatmu itu pasti bukan masalah, <rep_handlename>!","story.map5-dungeon1.023":"Aku pergi dulu, ya. <wait=20>Aku harus menyelidiki Cardes lebih lanjut!","story.map5-dungeon1.024":"Semoga berhasil!!","story.map5-dungeon2.001":"<size=14><rep_handlename>!","story.map5-dungeon2.002":"<size=14>Ka-<wait=20>Kamu di mana?","story.map5-dungeon2.003":"<size=20>Aaaah!!","story.map5-dungeon2.004":"...Ja-<wait=40>Jangan mengendap-endap begitu dong!","story.map5-dungeon2.005":"Hah?<wait=40><br>Aku takut apa?","story.map5-dungeon2.006":"Ng-<wait=40>Nggak takut apa-apa!","story.map5-dungeon2.007":"A-<wait=41>Aku nggak takut sama apa pun!","story.map5-dungeon2.008":"Kapal hantu atau semacamnya itu sama sekali nggak menakutkan!","story.map5-dungeon2.009":"Malah, <wait=40>aku bisa saja tinggal di sini, tahu!","story.map5-dungeon2.010":"Ah!<wait=40> Aku tahu!","story.map5-dungeon2.011":"Kamu bilang begitu karena kamu sendiri yang takut, <wait=40>iya kan, <rep_handlename>!?","story.map5-dungeon2.012":"Hehe, <wait=40><rep_handlename> ternyata penakut!","story.map5-dungeon2.013":"Harusnya bilang dari tadi, <wait=40>aku kan bisa melindungimu.","story.map5-dungeon2.014":"Soalnya, <wait=20>sebagai dewi aku bukan cuma cantik, tapi juga tangguh!","story.map5-dungeon2.015":"Ya, <wait=20>betul sekali!","story.map5-dungeon2.016":"Katanya di sekitar sini ada monster yang melahap jiwa manusia, jadi hati-hati, ya!","story.map5-dungeon2.017":"<size=18>*Ciprat*","story.map5-dungeon2.018":"<size=20>Hah?<wait=40> A-Apa itu!","story.map5-dungeon2.019":"Ka-Kamu dengar, <wait=20>suara aneh barusan!?","story.map5-dungeon2.020":"Hah?<wait=40> Itu cuma suara langkah kakimu?","story.map5-dungeon2.021":"...<wait=40>...<wait=40>...","story.map5-dungeon2.022":"<size=20><rep_handlename>, dasar bodoh!","story.map5-dungeon2.023":"Aku bawa informasi penting buatmu, <wait=40>tapi sekarang aku jadi malas memberitahumu!","story.map5-dungeon2.024":"Aku mau pulang!","story.map5-dungeon2.025":"Hehe, <wait=40>kamu percaya, ya?","story.map5-dungeon2.026":"Kaget nggak?","story.map5-dungeon2.027":"Dewi nggak mungkin marah cuma gara-gara itu. ","story.map5-dungeon2.028":"Pokoknya, <wait=40>menurut penyelidikanku, Palmyna, tempat Cardes disegel...","story.map5-dungeon2.029":"...ada di seberang Encervis, <wait=40>yang letaknya tepat setelah Amdahl.","story.map5-dungeon2.030":"Kita harus melewati Kastel Amdahl dulu, <wait=40>baru setelah itu kita bisa menembus Encervis!","story.map5-dungeon2.031":"Jadi ayo cepat lewati daerah ini, <wait=40>tempat ini benar-benar bikin merinding...","story.map5-dungeon2.032":"<size=18>*Ciprat* *Ciprat*","story.map5-dungeon2.033":"Hah?","story.map5-dungeon2.034":"*Becek* *Becek*","story.map5-dungeon2.035":"<size=20>Aaah!!","story.map5-dungeon3.001":"<speed=10>Apa ini...<wait=40><br>Yang satu ini jelas berbeda dari Summoner lainnya.","story.map5-dungeon3.002":"Sudah kuputuskan, <wait=20>akan kuhabisi kamu di sini.","story.map5-dungeon3.003":"Tak perlu khawatir.<wait=50><br>Semuanya akan segera berakhir.","story.map5-dungeon3.004":"Hawa keberadaan ini...<wait=20>...","story.map5-dungeon3.005":"Oh, begitu...","story.map5-dungeon3.006":"Ternyata kamu di sini!","story.map5-dungeon3.007":"Hei, <wait=40>ada apa?<wait=40> Wajahmu kelihatan gelisah.","story.map5-dungeon3.008":"Cuacanya secerah ini, harusnya kamu lebih ceria! Ayo, senyum dong!","story.map5-dungeon3.009":"Kan ada aku di sini juga, <wait=40>jadi ayo semangat lagi!","story.map5-dungeon3.010":"Lagi pula, <wait=40>lihat betapa damainya tempat ini.","story.map5-dungeon3.011":"Aku ingin sekali bersantai di tempat seperti ini bersamamu, <rep_handlename>.","story.map5-dungeon3.012":"Hehe, <wait=40>bercanda kok!","story.map5-dungeon3.013":"Kamu sedang menjalankan misi penting untuk menumpas Empat Dewa yang Jatuh, <rep_handlename>.","story.map5-dungeon3.014":"Kamu nggak punya waktu untuk bermalas-malasan!","story.map5-dungeon3.015":"Hah? <wait=40>Bagaimana denganku?","story.map5-dungeon3.016":"Tentu saja aku juga nggak punya waktu untuk itu...<wait=40> Maksudku...","story.map5-dungeon3.017":"Jangan-jangan menurutmu,<wait=40> aku di sini cuma main-main saja!?","story.map5-dungeon3.018":"Berani sekali kamu!!","story.map5-dungeon3.019":"Aku sudah berusaha sekuat tenaga untuk membantumu, <rep_handlename>!","story.map5-dungeon3.020":"Hah? <wait=40>Contohnya?","story.map5-dungeon3.021":"I-<wait=40>Ini terlalu banyak untuk diucapkan...<wait=40> *G<size=15>u<size=14>m<size=13>a<size=12>m<size=11>* <size=12>*G<size=11>u<size=10>m<size=9>a<size=8>m<size=7>*<size=6>","story.map5-dungeon3.022":"Pokoknya, <wait=40>cukup soal aku!","story.map5-dungeon3.023":"Yang penting sekarang adalah jalan di depan kita!","story.map5-dungeon3.024":"Baiklah, <wait=40>ayo kita menuju Kastel Amdahl!","story.map5-dungeon4.001":"Iih, <wait=20>parah banget! <wait=40>Tempat ini menjijikkan!","story.map5-dungeon4.002":"Graham saja nggak bakal mau menginjakkan kaki di tempat seperti ini!","story.map5-dungeon4.003":"Bukankah aku sudah menjelaskannya padamu?","story.map5-dungeon4.004":"Besar kemungkinan Graham ada di Edila, kota hantu tepat di balik tambang ini.","story.map5-dungeon4.005":"Berhentilah mengeluh! <wait=40> Kita harus terus maju!","story.map5-dungeon4.006":"Bagaimanapun juga, <wait=40>sepertinya Balai Summoner cuma memberi kita informasi palsu!","story.map5-dungeon4.007":"Astaga, Seria, <wait=40>kamu memang wanita paling galak yang kukenal...","story.map5-dungeon4.008":"Hmm?<wait=40> Oh!<wait=40> <rep_handlename>!","story.map5-dungeon4.009":"Hmph...","story.map5-dungeon4.010":"Jadi kamu juga datang ke Kepulauan Palmyna!","story.map5-dungeon4.011":"Sudah kuduga, kalau ada yang bisa sampai ke sini, itu pasti kamu, <rep_handlename>.","story.map5-dungeon4.012":"Kutebak kamu mengincar Cardes?","story.map5-dungeon4.013":"Haha, <wait=40>melihat caramu menghadapi Maxwell, kurasa dia bukan tandinganmu. ","story.map5-dungeon4.014":"Hmph! <wait=40>Jangan terlalu besar kepala, <wait=40>nanti kena batunya.","story.map5-dungeon4.015":"Kamu ini ngomong apa lagi? <wait=50> Kenapa kamu nggak bisa sedikit lebih menghormati <rep_handlename>?<wait=40>","story.map5-dungeon4.016":"*Tuk*","story.map5-dungeon4.017":"<size=18>Ng-<wait=20>Nggak apa-apa! <wait=40>Iya, aku berhenti!","story.map5-dungeon4.018":"Pokoknya, <wait=40>di Kepulauan Palmyna ada bawahan Cardes yang ditakuti bahkan oleh kekuatan terhebat sekalipun...","story.map5-dungeon4.019":"Ragu sedikit saja, tamatlah riwayatmu!","story.map5-dungeon4.020":"Aduh, Seria...","story.map5-dungeon4.021":"Tapi sebenarnya, <wait=40>ada benarnya juga ucapannya. ","story.map5-dungeon4.022":"Kenyataannya, <wait=40>selain Graham yang sedang kami kejar...","story.map5-dungeon4.023":"...ada desas-desus tentang makhluk buas di daerah ini yang sama kuatnya atau bahkan lebih, bernama Zebra. ","story.map5-dungeon4.024":"Kita tak boleh lengah, <wait=40>jadi mari kita semua berhati-hati saat melangkah.","story.map5-dungeon4.025":"Ngomong-ngomong, <wait=40>dewi itu ke mana?","story.map5-dungeon4.026":"Kalian berdua kan biasanya lengket kayak perangko...","story.map5-dungeon4.027":"Oh, aku tahu!<wait=40> Dia akhirnya bosan karena kamu membosankan, ya!?","story.map5-dungeon4.028":"Seria, <wait=40>sudah cukup.","story.map5-dungeon4.029":"...<wait=40>Cuma bercanda sedikit, kok.","story.map5-dungeon4.030":"Kami sedang menuju Edila, tepat di depan sana, untuk mengejar Graham. ","story.map5-dungeon4.031":"Aku ingin kita bertarung bersama sebagai satu tim, <wait=40>tapi dengan rekan yang menyebalkan sepertimu...","story.map5-dungeon4.032":"Aku nggak menyebalkan...","story.map5-dungeon4.033":"Haha... <wait=40>Jadi, kamu berencana maju sendirian?","story.map5-dungeon4.034":"Musuh-musuh yang cukup ganas menantimu di depan,<wait=40> tapi aku yakin kita akan selamat dan bertemu lagi!","story.map5-dungeon4.035":"Karl! <wait=40>Nggak ada waktu untuk bersantai, ayo terus maju!","story.map5-dungeon4.036":"Berusahalah supaya nggak jadi mangsa para iblis itu!","story.map5-dungeon4.037":"He-<wait=40>Hei, <wait=40>tunggu!","story.map5-dungeon4.038":"Astaga... <wait=40>Baiklah, <wait=20>sampai jumpa lagi, <rep_handlename>!","story.map5-dungeon5.001":"Ah, <wait=40>menyenangkan sekali!","story.map5-dungeon5.002":"Oh, <wait=40><rep_handlename>!","story.map5-dungeon5.003":"Kamu sampai di sini dengan selamat. <wait=40>Aku tahu kamu pasti bisa!","story.map5-dungeon5.004":"Meskipun aku percaya padamu, aku tetap lega melihatmu.","story.map5-dungeon5.005":"Hah? <wait=40>Aku sedang apa?","story.map5-dungeon5.006":"Hehe, <wait=40>tentu saja menikmati tempat suci ini!","story.map5-dungeon5.007":"Setiap sudutnya dipenuhi cahaya, <wait=20>tak ada yang mengalahkan tempat suci yang bagus.","story.map5-dungeon5.008":"Suasana khidmat dan cahaya indah ini nggak bisa ditolak oleh dewi sepertiku.","story.map5-dungeon5.009":"Dan di sini nggak ada suara aneh seperti yang kita dengar di kapal hantu!","story.map5-dungeon5.010":"<size=18>*Kresek* *Kresek*","story.map5-dungeon5.011":"Apa itu!?<wait=40> Siapa di sana!?","story.map5-dungeon5.012":"Ho ho ho. <wait=40><br>Apa aku mengagetkanmu?","story.map5-dungeon5.013":"Maafkan aku, <wait=20>nona muda.","story.map5-dungeon5.014":"Aku tak bermaksud menakutimu, <wait=40>hanya saja suaramu begitu merdu. ","story.map5-dungeon5.015":"Ah, <wait=40>a-<wait=40>anu...","story.map5-dungeon5.016":"Kakek siapa?","story.map5-dungeon5.017":"Ho ho ho. <wait=40><br>Maafkan kelancanganku.","story.map5-dungeon5.018":"Namaku Grah. <wait=40><br>Panggil saja aku Elder Grah.","story.map5-dungeon5.019":"Elder Grah, ya...","story.map5-dungeon5.020":"Ho ho ho. <wait=40><br>Nama yang bagus, bukan?","story.map5-dungeon5.021":"Aku sudah menyebutkan namaku, <wait=40>maukah kamu menyebutkan namamu?","story.map5-dungeon5.022":"Anu, <wait=40>namaku Tilith! <wait=40>Aku cuma gadis biasa, sama seperti gadis lain di mana pun.","story.map5-dungeon5.023":"Dan orang hebat di sebelahku ini adalah <rep_handlename>!","story.map5-dungeon5.024":"<rep_handlename> adalah Summoner yang luar biasa kuat!","story.map5-dungeon5.025":"Berani sekali.","story.map5-dungeon5.026":"Jadi, Elder Grah, <wait=40>kenapa Kakek ada di tempat seperti ini?","story.map5-dungeon5.027":"Yah, <wait=40>aku hanya ingin berjalan-jalan ke sebelah sana.","story.map5-dungeon5.028":"Jalan-jalan, katanya...","story.map5-dungeon5.029":"Bukannya daerah ini penuh monster...","story.map5-dungeon5.030":"Hmm, <wait=20>sepertinya mereka tidak menghiraukanku. ","story.map5-dungeon5.031":"Hmm...<wait=40> Kakek masih kelihatan agak mencurigakan...","story.map5-dungeon5.032":"Lihat saja senjata hebat yang Kakek bawa itu...","story.map5-dungeon5.033":"He he he...","story.map5-dungeon5.034":"Sepertinya rahasiaku terbongkar!","story.map5-dungeon5.035":"Sebenarnya, <wait=20>akulah Grah, dewa yang menguasai negeri ini!","story.map5-dungeon5.036":"Dan sekarang akan kulenyapkan kalian berdua dari sini!","story.map5-dungeon5.037":"Apa-apaan!?","story.map5-dungeon5.038":"Aku cuma bercanda.","story.map5-dungeon5.039":"Ho ho ho. <wait=40><br>Kaget, ya?","story.map5-dungeon5.040":"Kamu manis sekali kalau sedang terkejut, nona muda.","story.map5-dungeon5.041":"Huuh!","story.map5-dungeon5.042":"Maafkan aku.","story.map5-dungeon5.043":"Dulu sekali, aku pernah melakukan semacam petualangan. ","story.map5-dungeon5.044":"Aku memakai tombak ini waktu itu, <wait=40>meski sekarang ia tak lebih dari sekadar hiasan.","story.map5-dungeon5.045":"Aku datang untuk menyelidiki legenda Empat Pahlawan Masa Lalu, <wait=40>tapi sepertinya aku tak akan menemukan hal penting di sini.","story.map5-dungeon5.046":"Baiklah, <wait=40>kurasa sudah waktunya aku pamit.","story.map5-dungeon5.047":"Bisa bertemu Summoner semenarik ini, <wait=40>kurasa hari ini hari yang baik. ","story.map5-dungeon5.048":"Nah, <wait=40>aku menantikan pertemuan kita berikutnya.","story.map5-dungeon5.049":"Kakek itu, <wait=40>agak aneh, ya?","story.map5-dungeon5.050":"Orang biasa nggak mungkin bisa berkeliaran begitu saja di sini.","story.map5-dungeon5.051":"Dia pasti menyembunyikan sesuatu<wait=20>.<wait=20>.<wait=20>.","story.map5-dungeon5.052":"Pokoknya, <wait=40>nggak ada gunanya memikirkannya sekarang.","story.map5-dungeon5.053":"Toh itu nggak memengaruhi tujuan kita!","story.map5-dungeon5.054":"Baiklah, <wait=40>ayo cepat lewati tempat ini lalu menuju Kastel Amdahl!","story.map5-dungeon6.001":"Seria!<wait=40> Bagaimana di sana!?","story.map5-dungeon6.002":"Gagal!<wait=40> Nggak ada jejaknya sama sekali...","story.map5-dungeon6.003":"Sial! <wait=40>Dia lolos dari kita lagi!","story.map5-dungeon6.004":"Kalau begini terus, <wait=40>kita nggak akan pernah bisa membalaskan dendam mereka...","story.map5-dungeon6.005":"Karl...","story.map5-dungeon6.006":"<size=18>Hah!?<wait=40> <size=16>Kamu datang dari mana?","story.map5-dungeon6.007":"Ternyata kamu, <rep_handlename>...","story.map5-dungeon6.008":"Hehe, <wait=40>sepertinya kamu datang di saat yang kurang tepat.","story.map5-dungeon6.009":"Sekali lagi, <wait=20>Graham lolos dari genggaman kami.","story.map5-dungeon6.010":"Dibandingkan kamu yang bertarung begitu gagah melawan Empat Dewa yang Jatuh, <wait=20>kami pasti tampak menyedihkan...","story.map5-dungeon6.011":"Kamu ngomong apa, sih!","story.map5-dungeon6.012":"<rep_handlename> cuma beruntung!<wait=40> Karl, kamu sudah mengalahkan musuh yang ratusan kali lebih kuat daripada lawannya!","story.map5-dungeon6.013":"Haha, <wait=40>terima kasih banyak, Seria.","story.map5-dungeon6.014":"Rasanya istimewa sekali dipuji olehmu.","story.map5-dungeon6.015":"Kurasa aku tak punya alasan untuk berkecil hati, ya!","story.map5-dungeon6.016":"Apa maksudmu, \\"istimewa\\"?","story.map5-dungeon6.017":"Haha, <wait=40>aku cuma ingin berterima kasih, itu saja. ","story.map5-dungeon6.018":"Oh, dan <rep_handlename>...","story.map5-dungeon6.019":"Graham lolos lagi bukan hanya karena dia kuat...","story.map5-dungeon6.020":"Waktu kami berhasil menyusulnya kali ini, <wait=40>ada monster lain yang luar biasa kuat bersamanya.","story.map5-dungeon6.021":"Maaf kalau penjelasanku kurang jelas.","story.map5-dungeon6.022":"Sejujurnya, <wait=40>kami tidak benar-benar melihat monster itu.","story.map5-dungeon6.023":"Begitu kami merasakan kekuatannya yang dahsyat, <wait=40>kami langsung terpental.","story.map5-dungeon6.024":"Saat kami sadar, <wait=40>Graham sudah menghilang entah ke mana.","story.map5-dungeon6.025":"Kita pasti sudah menangkapnya kalau nggak diserang begitu...","story.map5-dungeon6.026":"Mungkin kamu benar...","story.map5-dungeon6.027":"Tapi, <wait=40>satu-satunya yang kami yakini adalah tak ada orang biasa yang bisa memiliki kekuatan sebesar itu...","story.map5-dungeon6.028":"Itu benar sekali...","story.map5-dungeon6.029":"Pokoknya, <wait=40>kita beruntung tidak banyak yang jadi korban.","story.map5-dungeon6.030":"Kami akan terus mencari Graham.","story.map5-dungeon6.031":"Kamu menuju Kastel Amdahl di depan sana, benar?","story.map5-dungeon6.032":"Aku juga merasakan hawa berbahaya yang kuat dari sana.","story.map5-dungeon6.033":"Pastikan kamu benar-benar berhati-hati.","story.map5-dungeon6.034":"Kalau kamu bertemu monster itu, tamatlah riwayatmu!","story.map5-dungeon6.035":"Haha, <wait=40>keras pada <rep_handlename> seperti biasa, ya.","story.map5-dungeon6.036":"A-<wait=40>Aku bukan cuma keras pada <rep_handlename>...","story.map5-dungeon6.037":"Ternyata kamu di sini!","story.map5-dungeon6.038":"Kamu ke mana saja! <wait=40>Aku mencarimu ke mana-mana!","story.map5-dungeon6.039":"Hah?<wait=40> Apa ini?<wait=40><br>Aku pernah bertemu kalian semua, kan?","story.map5-dungeon6.040":"...<wait=20>...","story.map5-dungeon6.041":"Halo, dewi.<wait=40> Lama tak berjumpa.","story.map5-dungeon6.042":"Iya, lama sekali!<wait=40> Kamu kelihatan sehat seperti biasa, Karl!","story.map5-dungeon6.043":"Dan kamu, <wait=40>masih suka mengganggu <rep_handlename>-ku seperti biasa?","story.map5-dungeon6.044":"<size=18>Apa maksudmu, \\"mengganggu\\"!","story.map5-dungeon6.045":"Dan seperti yang sudah kubilang, <wait=40><rep_handlename> itu bukan milikmu!","story.map5-dungeon6.046":"Kenapa kamu ribut begitu?<wait=40> Jangan-jangan <wait=20>kamu cemburu? ","story.map5-dungeon6.047":"...<wait=20>...","story.map5-dungeon6.048":"<size=18>*Klang*","story.map5-dungeon6.049":"<size=18>Ti-Tunggu sebentar!","story.map5-dungeon6.050":"Tenang, Seria!","story.map5-dungeon6.051":"A-<wait=20>Ayolah, <wait=40>kita harus kembali mengejar Graham!","story.map5-dungeon6.052":"Be-<wait=40>Benar, kan!?","story.map5-dungeon6.053":"<speed=14>Baiklah, <wait=20><rep_handlename>!","story.map5-dungeon6.054":"<speed=14>Mari kita berjanji untuk berjuang sekuat tenaga di jalan yang menanti!","story.map5-dungeon6.055":"<speed=14>Ayo, kita berangkat! Kamu juga, Seria!","story.map5-dungeon6.056":"Karl! <wait=20> Tunggu!<wait=40> Aku mengerti, <wait=40>nggak usah menarik sekeras itu!","story.map5-dungeon6.057":"Dewi! <wait=40>Jaga sikapmu, ya!","story.map5-dungeon6.058":"Huuh!!","story.map5-dungeon6.059":"Fiuh, <wait=40>akhirnya dia pergi juga.","story.map5-dungeon6.060":"Tapi, <wait=40>semoga mereka berhasil mengalahkan Graham!","story.map5-dungeon6.061":"Kita hampir sampai. <wait=40>Setelah melewati tempat ini, kita akan tiba di gerbang Kastel Amdahl!","story.map5-dungeon6.062":"Aku mengandalkanmu!","story.map5-dungeon7.001":"Akhirnya kita sampai.","story.map5-dungeon7.002":"Lewati Kastel Amdahl, dan jalan menuju Encervis akan terbuka lebar.","story.map5-dungeon7.003":"Dengan begitu kita selangkah lebih dekat ke Cardes dan negeri tempat dia disegel.","story.map5-dungeon7.004":"Hehe, <wait=40>jangan tegang begitu.","story.map5-dungeon7.005":"Aku tahu kamu pasti bisa, <rep_handlename>!","story.map5-dungeon7.006":"Ayo cepat kita lewati kastel ini!","story.map5-dungeon7.007":"Kalian benar-benar mengira semudah itu?","story.map5-dungeon7.008":"Hah-!!","story.map5-dungeon7.009":"Aku mengagetkanmu lagi?","story.map5-dungeon7.010":"Berani-beraninya! <wait=40>Jangan mengendap-endap begitu dong!!","story.map5-dungeon7.011":"Ho ho ho.","story.map5-dungeon7.012":"Kamu masih semanis yang kuingat, nona muda.","story.map5-dungeon7.013":"Hmph, <wait=40>dasar jahat...","story.map5-dungeon7.014":"Ho ho ho.","story.map5-dungeon7.015":"Nah, <wait=40><rep_handlename>...","story.map5-dungeon7.016":"Kamu juga sudah merasakannya, bukan? <wait=40>Hawa jahat di depan sana...","story.map5-dungeon7.017":"Ya, <wait=40>aku bisa melihatnya di wajahmu.","story.map5-dungeon7.018":"Baiklah, <wait=40>biar kuberi tahu apa yang menantimu.","story.map5-dungeon7.019":"Tepat di depan, mantan penguasa kastel ini sedang menunggumu.","story.map5-dungeon7.020":"Kaisar terakhir Kekaisaran Amdahl, yang dihancurkan oleh Palmyna. ","story.map5-dungeon7.021":"Kini sebagai hantu, ia menyimpan dendam besar terhadap manusia.","story.map5-dungeon7.022":"Hantu yang dendam pada manusia...","story.map5-dungeon7.023":"Ho ho ho.","story.map5-dungeon7.024":"Memangnya apa yang kamu harapkan?","story.map5-dungeon7.025":"Tidak semua yang ada di Grand Gaia ini pasti berhubungan dengan para dewa.","story.map5-dungeon7.026":"Mudah dipahami kalau kamu melihat sejarah manusia...","story.map5-dungeon7.027":"Manusia telah saling membunuh jauh lebih banyak daripada yang dihancurkan oleh para dewa.","story.map5-dungeon7.028":"......","story.map5-dungeon7.029":"Ho ho ho.","story.map5-dungeon7.030":"Nah, <wait=40>aku sudah terlalu tua untuk urusan ini, <wait=40>kurasa sebaiknya aku pergi.","story.map5-dungeon7.031":"Tapi sebelum aku pergi, <wait=40>meski dia seorang dewi, dia tetap punya kelemahan.","story.map5-dungeon7.032":"Sebaiknya kamu berusaha sebaik mungkin untuk melindunginya.","story.map5-dungeon7.033":"Hah?<wait=40> Tunggu sebentar!","story.map5-dungeon7.034":"Ho ho ho.","story.map5-dungeon7.035":"Dia menghilang...","story.map5-dungeon7.036":"Kapan aku bilang ke Elder Grah kalau aku ini dewi?","story.map5-dungeon7.037":"Dia tahu banyak sekali, <wait=40>sebenarnya dia itu siapa?","story.map5-dungeon7.038":"Ah, <wait=40>sudahlah!","story.map5-dungeon7.039":"Nggak ada gunanya memikirkannya sekarang! <wait=40>","story.map5-dungeon7.040":"Kita harus melewati tempat ini sebelum bisa menghadapi Cardes!","story.map5-dungeon7.041":"Nah, <rep_handlename>, aku nggak tahu harus berpikir apa soal urusan hantu ini...","story.map5-dungeon7.042":"...tapi apa pun itu, ayo kita hajar! <wait=40>Elder Grah pasti bakal kaget!","story.map5-ending.001":"Kamu berhasil, <rep_handlename>!","story.map5-ending.002":"Ternyata dia lemah sekali!","story.map5-ending.003":"Bahkan hantu para kaisar masa lalu pun bukan tandinganmu, <rep_handlename>!","story.map5-ending.004":"<size=18>Wah!","story.map5-ending.005":"Hah-!!","story.map5-ending.006":"Hei, <wait=40>kenapa Kakek selalu saja mengagetkanku...","story.map5-ending.007":"Maaf, <wait=40>hanya saja aku merasakan hal yang sama denganmu, Tilith...","story.map5-ending.008":"Aku juga terkejut melihat cara <rep_handlename> menghadapi arwah itu.","story.map5-ending.009":"Hmph.","story.map5-ending.010":"Ho ho ho.","story.map5-ending.011":"Tapi, <wait=40><rep_handlename> bisa menumpas hantu seorang kaisar seperti itu...","story.map5-ending.012":"Hehe, <wait=40>terus?","story.map5-ending.013":"Itu artinya <rep_handlename> memang Summoner yang luar biasa, kan?","story.map5-ending.014":"Hmm, <wait=40>pertarungan yang benar-benar menakjubkan.","story.map5-ending.015":"Harus kuakui, <wait=40>kerja bagus.","story.map5-ending.016":"<size=18><rep_handlename>!<wait=40> Kamu masih hidup!!","story.map5-ending.017":"Hah... <wait=40>hah...","story.map5-ending.018":"Tu-<wait=40>Tunggu sebentar...","story.map5-ending.019":"A-<wait=40>Apa yang terjadi dengan hantu itu?","story.map5-ending.020":"<rep_handlename> sudah menghabisinya!","story.map5-ending.021":"...<wait=40>...","story.map5-ending.022":"<size=14>Hmph...<wait=40><br>Karrrrrrl!!","story.map5-ending.023":"Jadi kamu memang mengkhawatirkan <rep_handlename>, kan, Seria!?","story.map5-ending.024":"Ternyata kamu punya sisi perhatian juga.","story.map5-ending.025":"Bu-<wait=40>Bukan begitu!<wait=40> Aku cuma dengar Graham muncul di sekitar sini...","story.map5-ending.026":"Ayolah, <wait=20>nggak perlu berlindung di balik bohong yang kentara begitu.","story.map5-ending.027":"Grr...","story.map5-ending.028":"Ho ho ho.","story.map5-ending.029":"<size=20>!?","story.map5-ending.030":"Sepertinya kita belum berkenalan.","story.map5-ending.031":"Nona Seria, <wait=40>panggil saja aku Elder Grah.","story.map5-ending.032":"Hah!?<wait=40> E-<wait=40>Elder Grah?","story.map5-ending.033":"Benar sekali.","story.map5-ending.034":"Hah, <wait=40>tapi... <wait=40>ma-<wait=40>maksudku...","story.map5-ending.035":"Elder Grah.","story.map5-ending.036":"Ingat baik-baik, <wait=40>Nona Seria.","story.map5-ending.037":"Elder Grah, <wait=40>Kakek ini benar-benar orang tua yang aneh, ya!","story.map5-ending.038":"Selalu muncul tiba-tiba di tempat aneh, <wait=40>dan tahu hal-hal yang paling nggak lazim.","story.map5-ending.039":"Dan Kakek selalu saja mengagetkanku!","story.map5-ending.040":"A-<wait=40>A-<wait=40>Apa yang kamu katakan!?<wait=40> Orang ini adalah...","story.map5-ending.041":"...Elder Grah, hanya seorang kakek yang suka bercanda.","story.map5-ending.042":"Benar, kan, <wait=40>Nona Seria?","story.map5-ending.043":"Hah?<wait=40> O-<wait=40>Oh, <wait=20>benar...","story.map5-ending.044":"Ho ho ho.","story.map5-ending.045":"Hmph, <wait=40>ada yang aneh denganmu, Seria!","story.map5-ending.046":"Te-<wait=40>Terserah! <wait=40>Aku cuma sedang memikirkan beberapa hal!","story.map5-ending.047":"Hal apa?","story.map5-ending.048":"Ka-<wait=40>Kamu nggak perlu tahu!","story.map5-ending.049":"Hmph, <wait=40>kamu ini kenapa sih!","story.map5-ending.050":"Mungkin kamu kesal karena Karl menipumu supaya mengejar kami?","story.map5-ending.051":"Ha-<wait=40>Hah? <wait=20>Dari mana kamu tahu!?","story.map5-ending.052":"Dewi tahu segalanya!","story.map5-ending.053":"Dewi macam apa kamu!?<wait=40> Kamu nggak bisa melakukan apa pun sendirian!","story.map5-ending.054":"Jahat sekali kamu!","story.map5-ending.055":"Hei <rep_handlename>, <wait=40>bantu aku dong, katakan sesuatu!","story.map5-ending.056":"Buat apa?<wait=40> Kamu sudah tahu apa yang akan dikatakan <rep_handlename>, kan?","story.map5-ending.057":"Ho ho ho.","story.map5-ending.058":"Anak muda memang penuh semangat.","story.map5-ending.059":"Nah, <rep_handlename>...","story.map5-ending.060":"Dengan mengalahkan arwah itu, <wait=40>kamu telah mematahkan penghalang yang menyelubungi wilayah ini.","story.map5-ending.061":"Sebentar lagi, jalan menuju Encervis akan terbuka.","story.map5-ending.062":"Zebra pasti sedang menunggumu...","story.map5-ending.063":"...iblis yang kini menguasai Kepulauan Palmyna menggantikan Cardes.","story.map5-ending.064":"Berlatihlah dengan keras, dan jangan biarkan kesombongan menghalangimu.","story.map5-ending.065":"Ah!<wait=40> Padahal aku yang mau bilang begitu!","story.map5-ending.066":"Semua omonganmu itu bodoh, <wait=40>serahkan saja urusan ini pada Grahde...","story.map5-ending.067":"Elder Grah! Serahkan pada Elder Grah!","story.map5-ending.068":"Bodoh, katamu!?","story.map5-ending.069":"Memangnya salah kalau aku bilang apa adanya?","story.map5-ending.070":"Cukup!<wait=40> Akan kutunjukkan kekuatan sejati seorang dewi!","story.map5-ending.071":"Ayo maju!<wait=50> Akan kutunjukkan betapa aku jauh lebih kuat darimu!","story.map5-ending.072":"<size=20>Bersiaplah kamu!!","story.map5-ending.073":"Ho ho ho.","story.map5-ending.074":"Kalian berdua memang nona-nona muda yang berdarah panas, ya.","story.map5-ending.075":"Nah, <wait=40><rep_handlename>...","story.map5-ending.076":"Sebaiknya kita kembali ke Elgaia.","story.map5-ending.077":"<rep_handlename>! <wait=40>Tunggu sebentar!","story.map5-ending.078":"Aku membawa pesan dari Karl!","story.map5-ending.079":"Katanya, \\"Aku percaya pada kekuatanmu.\\"","story.map5-ending.080":"Memangnya ini waktunya untuk itu!?","story.map5-ending.081":"<rep_handlename>!","story.map5-ending.082":"Kita ke Encervis setelah aku memberi Seria sedikit pelajaran soal sopan santun!","story.map5-ending.083":"Kalau kamu pikir bisa mengalahkanku, <wait=40>coba saja!","story.map5-ending.084":"Cukup sudah!!<wait=40> Sekarang saatnya kutunjukkan kekuatan sihirku yang dahsyat!","story.map5-ending.085":"Hmph, <wait=40>sepertinya kamu serius. <wait=40>Oke, <wait=40>ayo kita mulai!","story.map5-ending.086":"<size=20>Rasakan ini!!","story.map5-ending.087":"Baiklah, <wait=40>kurasa kita berangkat...","story.map5-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Kamu, <rep_handlename>,<wait=40> yang telah mengalahkan Maxwell, Dewi Penciptaan…","story.map5-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Krisis yang dibawa Empat Dewa yang Jatuh,<wait=40> masih belum berakhir…","story.map5-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Demi membawa harapan baru ke dunia yang diselimuti kesedihan ini…","story.map5-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Kamu harus percaya pada kekuatanmu, <wait=20>dan terus melangkah maju…","story.map5-open.005":"<size=22>Kamu telat!","story.map5-open.006":"Kenapa lama sekali!?","story.map5-open.007":"Aku sudah menunggumu lama sekali, lama banget, <rep_handlename>!","story.map5-open.008":"Bukankah kamu jadi agak terlalu santai sejak mengalahkan Maxwell?","story.map5-open.009":"<size=20>Hehe, <wait=20>kena kamu!!","story.map5-open.010":"Tadi aku bicara dengan Lucius, <wait=40>aku juga baru sampai kok. ","story.map5-open.011":"Pokoknya, <wait=40>berikutnya adalah Kepulauan Palmyna!","story.map5-open.012":"Setelah melihat betapa kuatnya kamu di St. Lamia...","story.map5-open.013":"...kali ini aku punya harapan besar padamu!","story.map5-open.014":"Ayo kita berjuang sekuat tenaga!","story.map5-open.015":"*Tok* <wait=20>*Tok*","story.map5-open.016":"Maaf mengganggu. ","story.map5-open.017":"Saya membawa informasi baru dari bagian intelijen.","story.map5-open.018":"Tampaknya penghalang yang melindungi Kepulauan Palmyna telah ditembus. ","story.map5-open.019":"...<wait=40>Ya, <wait=40>aku menerima laporannya belum lama ini. ","story.map5-open.020":"Tampaknya mereka semakin berambisi. ","story.map5-open.021":"Saya akan segera menyelidikinya.","story.map5-open.022":"Tidak, <wait=40>lanjutkan tugasmu yang sekarang. ","story.map5-open.023":"Aku tak ingin bawahanku yang berharga terseret dalam rencana apa pun yang sedang mereka susun. ","story.map5-open.024":"Te-<wait=20>Terima kasih...<br>Kalau begitu, <wait=20>saya kembali bekerja. ","story.map5-open.025":"Empat Dewa yang Jatuh...","story.map5-open.026":"Konon mereka punya kekuatan untuk menghancurkan seluruh Grand Gaia. ","story.map5-open.027":"Aku ingin melihat seberapa kuat mereka sebenarnya...","story.map6-dungeon1.001":"Panas, panas, panas!!","story.map6-dungeon1.002":"Kenapa semuanya di sini panas membara begini!","story.map6-dungeon1.003":"Sesekali ada angin sejuk kan enak!","story.map6-dungeon1.004":"Lihat saja, keringatku sampai bercucuran begini!","story.map6-dungeon1.005":"Aku kan sudah bilang, <wait=40>aku benci tempat yang panas!","story.map6-dungeon1.006":"Ingat itu lain kali waktu memilih tempat bertemu, <rep_handlename>!","story.map6-dungeon1.007":"Hmm, <wait=40>tapi bagaimanapun juga, Lord Lucius benar-benar mengandalkanmu, <rep_handlename>...","story.map6-dungeon1.008":"Sepertinya aku sendiri juga harus berusaha lebih keras dari sebelumnya...","story.map6-dungeon1.009":"A-<wait=20>Apa-apaan wajah itu!?","story.map6-dungeon1.010":"A-<wait=40>Apa maksudmu aku nggak pernah kelihatan berusaha!?","story.map6-dungeon1.011":"Grr, <wait=40>jahat sekali kamu.","story.map6-dungeon1.012":"Satu-satunya alasan kamu jarang diserang itu karena aku ada di sisimu!","story.map6-dungeon1.013":"Nggak ada yang berani mendekatiku, <wait=40>mereka semua terlalu takut pada kekuatanku yang hebat!","story.map6-dungeon1.014":"Pasti sekarang pun ada orang jahat di luar sana yang sedang mengincarmu, <rep_handlename>.","story.map6-dungeon1.015":"Hehe, <wait=40>bercanda kok!","story.map6-dungeon1.016":"Mana mungkin aku nggak sadar kalau memang ada orang seperti itu di sekitar sini!","story.map6-dungeon1.017":"Kamu akan menemukan sebuah danau setelah keluar dari tempat yang luar biasa panas ini...","story.map6-dungeon1.018":"Tepat di seberangnya ada kastel yang indah, <wait=40>kita jadikan itu tempat pertemuan berikutnya!","story.map6-dungeon1.019":"Usahakan tetap selamat sampai saat itu, ya.","story.map6-dungeon1.020":"Dan kalau kamu dalam kesulitan, kamu selalu bisa berdoa pada dewimu yang cantik ini!","story.map6-dungeon2.001":"<size=18>*Trang*","story.map6-dungeon2.002":"<speed=10>Heh heh heh...<wait=40> Tak kusangka aku harus memakai kekuatanku seperti itu.","story.map6-dungeon2.003":"Rupanya kau memang orang yang berbahaya.","story.map6-dungeon2.004":"Bagaimanapun, aku akan segera menghabisi siapa pun yang menghalangi rencanaku.","story.map6-dungeon2.005":"Akan kuhapus kau dari dunia ini sebelum kau menyadarinya.","story.map6-dungeon2.006":"Kau sungguh mengira semudah itu?","story.map6-dungeon2.007":"!?","story.map6-dungeon2.008":"Meski seorang dewa, <wait=40>kau masih berniat menyombongkan diri begitu di depan seorang Summoner seorang diri?","story.map6-dungeon2.009":"Ahh...<wait=40> Rupanya kau tahu siapa aku.","story.map6-dungeon2.010":"Sepertinya aku bertemu satu faktor tak terduga lagi.","story.map6-dungeon2.011":"Namun, itu tak penting. <wait=40>Apa pun yang terjadi sekarang, hasilnya tetap sama.","story.map6-dungeon2.012":"Apa yang telah kugerakkan pada akhirnya akan mengakhiri seluruh umat manusia.","story.map6-dungeon2.013":"Apa-!? <wait=40>Maksudmu kau sudah meluncurkan Benteng Langit?","story.map6-dungeon2.014":"...<wait=40>Sebenarnya siapa kau ini?","story.map6-dungeon2.015":"Mungkin sebaiknya kuhabisi saja kau di sini sekarang juga...","story.map6-dungeon2.016":"Ho ho ho.<wait=40> Perlukah kuulangi?","story.map6-dungeon2.017":"Kau sungguh mengira semudah itu?","story.map6-dungeon2.018":"Kekuatan ini...<wait=40>...","story.map6-dungeon2.019":"Begitu. <wait=40>Jadi kau pasti... ","story.map6-dungeon2.020":"Summoner, <wait=40>kau telah membangkitkan rasa ingin tahuku.","story.map6-dungeon2.021":"Sepertinya kau juga punya lebih dari beberapa dewa di pihakmu. ","story.map6-dungeon2.022":"Aku akan mengawasi gerak-gerikmu sedikit lebih lama lagi...","story.map6-dungeon2.023":"Ho ho ho.<wait=40> Sepertinya kita berhasil lolos dari masalah.","story.map6-dungeon2.024":"Namun, <wait=40>keadaannya masih genting. ","story.map6-dungeon2.025":"Itu tadi Zebra, <wait=20>abdi Cardes Sang Keji, <wait=40>salah satu dari Empat Dewa yang Jatuh.","story.map6-dungeon2.026":"Sepertinya entah bagaimana ia berhasil membangkitkan Benteng Langit legendaris milik Kekaisaran Amdahl.","story.map6-dungeon2.027":"Benda seperti itu tak dibutuhkan di dunia ini.","story.map6-dungeon2.028":"Memunculkan benda seperti itu hanya akan membawa lebih banyak pertempuran.","story.map6-dungeon2.029":"Kau berencana pergi ke Palmyna, bukan?","story.map6-dungeon2.030":"Sambil mengejar Zebra, <wait=40>bagaimana kalau kau hancurkan Benteng Langit juga?","story.map6-dungeon2.031":"Ho ho ho.","story.map6-dungeon2.032":"Ada apa?<wait=40> Kau tak perlu khawatir.","story.map6-dungeon2.033":"Kau kan bersama nona muda itu, bukan?","story.map6-dungeon2.034":"Selama kau dilindungi sang dewi, <wait=40>kau pasti baik-baik saja.","story.map6-dungeon2.035":"Aku hanya minta kau menuruti apa katanya!","story.map6-dungeon2.036":"Hmph<wait=40>...","story.map6-dungeon2.037":"Sebenarnya,<wait=40> tampaknya kini tak jelas lagi siapa yang menyelamatkan siapa di antara kalian berdua.","story.map6-dungeon2.038":"Ho ho ho.","story.map6-dungeon2.039":"Aku harus pergi.<wait=40> Sampaikan salamku pada nona muda itu.","story.map6-dungeon3.001":"Hei, <wait=40><rep_handlename>!","story.map6-dungeon3.002":"Aku sudah menunggu.","story.map6-dungeon3.003":"Hah? <wait=40>Ada apa?<wait=40> Kenapa wajahmu muram begitu?","story.map6-dungeon3.004":"Apa katamu!?<wait=40> Zebra membangkitkan Benteng Langit!?","story.map6-dungeon3.005":"Bagaimana bisa dia...","story.map6-dungeon3.006":"Tapi tunggu, <wait=40>Benteng Langit itu apa? Penting, ya?","story.map6-dungeon3.007":"A-<wait=20>Apa-apaan tatapan itu!? <wait=40>Ada hal-hal yang bahkan dewi pun nggak tahu!","story.map6-dungeon3.008":"Ho ho ho.","story.map6-dungeon3.009":"Tentu saja, senjata buatan manusia seperti itu dianggap sepele oleh seorang dewi.","story.map6-dungeon3.010":"Oh, <wait=40>Elder Grah.","story.map6-dungeon3.011":"Hah? <wait=40>Kakek nggak mencoba mengagetkanku kali ini?","story.map6-dungeon3.012":"Oh, <wait=40>maafkan aku.","story.map6-dungeon3.013":"Sepertinya aku telah mengecewakan harapan nona muda.","story.map6-dungeon3.014":"Kalau begitu, <wait=40>izinkan aku mengulang dari awal.","story.map6-dungeon3.015":"Nggak perlu!","story.map6-dungeon3.016":"Ho ho ho.","story.map6-dungeon3.017":"Ngomong-ngomong, <wait=40>ada yang ingin kusampaikan, maukah kalian mendengarkan ceritaku?","story.map6-dungeon3.018":"Ini kisah tentang \\"Benteng Langit\\" legendaris milik Kekaisaran Amdahl.","story.map6-dungeon3.019":"Itu yang dibicarakan <rep_handlename>, <wait=40>benda yang dibangkitkan Zebra, kan?","story.map6-dungeon3.020":"Ya, <wait=40>benar.","story.map6-dungeon3.021":"Dulu manusia juga pernah mencoba membangkitkannya.","story.map6-dungeon3.022":"Tak diketahui siapa pembuatnya, kapan dibuat, bahkan bagaimana cara membuatnya...","story.map6-dungeon3.023":"Tampaknya yang tersisa di Kekaisaran Amdahl hanyalah petunjuk cara memakainya dan penjelasan tentang kemampuannya.","story.map6-dungeon3.024":"Sejak lama, benda itu dianggap terlarang oleh keluarga kekaisaran... ","story.map6-dungeon3.025":"...tapi lalu ada seorang kaisar yang memutuskan untuk melanggarnya.","story.map6-dungeon3.026":"Lama tersegel oleh Kekaisaran Amdahl, turun-temurun dari generasi ke generasi...","story.map6-dungeon3.027":"...kaisar terakhir Kekaisaran Amdahl, Myzelion IV, membuka segelnya...","story.map6-dungeon3.028":"...dan memakai kekuatan Benteng Langit untuk menyerang negeri-negeri tetangga demi menguasai mereka. ","story.map6-dungeon3.029":"Di tengah semua itu, <wait=20>raja Palmyna mendengar kabar tentang rencana sang kaisar.","story.map6-dungeon3.030":"Ia memohon pada Myzelion IV, tapi sang kaisar keras kepala dan menolak mengalah. ","story.map6-dungeon3.031":"Pada akhirnya, <wait=20>raja Palmyna memakai kekuatannya untuk menaklukkan Amdahl...","story.map6-dungeon3.032":"...menghancurkan mereka sebelum sempat membangkitkan Benteng Langit. ","story.map6-dungeon3.033":"Umm, <wait=40>jadi intinya...","story.map6-dungeon3.034":"Benteng Langit itu begitu berbahaya sampai sepadan menghancurkan satu negara demi mencegahnya bangkit?","story.map6-dungeon3.035":"Ya, <wait=40>tepat sekali.","story.map6-dungeon3.036":"Masa sih!?<wait=40> Dan itu yang dihidupkan kembali oleh Zebra!?","story.map6-dungeon3.037":"Tepat.","story.map6-dungeon3.038":"Kalau begitu kita dalam masalah besar!!","story.map6-dungeon3.039":"Tapi, <wait=40>itu nggak ada hubungannya dengan tujuan kita!","story.map6-dungeon3.040":"<rep_handlename>!<wait=40> Ayo terus kejar Cardes!","story.map6-dungeon3.041":"Dan Elder Grah, <wait=40>Kakek saja yang menghancurkan Benteng Langit!","story.map6-dungeon3.042":"Hah!?<wait=40> Nona muda, itu pasti mustahil.","story.map6-dungeon3.043":"Bukankah seharusnya kau yang menghadapi tantangan ini?","story.map6-dungeon3.044":"Ehhh, <wait=40>tapi aku bisa kena masalah kalau kita menyimpang dari jalur...","story.map6-dungeon3.045":"Jangan khawatir!","story.map6-dungeon3.046":"Benteng Langit itu searah dengan jalan kalian ke Palmyna, <wait=40>terus saja lurus ke depan!","story.map6-dungeon3.047":"Jadi maukah kau mengurus ini untukku?<wait=40> Anggap saja permintaan seorang kakek tua di ujung usianya.","story.map6-dungeon3.048":"Hei, <wait=40><rep_handlename>!","story.map6-dungeon3.049":"Maukah kau membantuku kali ini?","story.map6-dungeon3.050":"Baiklah, <wait=40>kurasa aku nggak punya pilihan.","story.map6-dungeon3.051":"Kalau Kakek sampai memohon begitu, kita bisa coba...","story.map6-dungeon3.052":"...tapi Kakek tetap akan membantu kami, kan, Elder Grah?","story.map6-dungeon3.053":"Ho ho ho,<wait=40> kau yakin ingin aku ikut?","story.map6-dungeon3.054":"Hehe, <wait=40>tentu saja!","story.map6-dungeon3.055":"Lagi pula, satu-satunya yang boleh meminta sesuatu pada <rep_handlename> cuma aku!","story.map6-dungeon3.056":"Ahh, <wait=40>begitu rupanya.","story.map6-dungeon3.057":"Ho ho ho. <wait=40>Maafkan kelancanganku.","story.map6-dungeon3.058":"Aku akan berusaha sebisaku, sebagai kakek tua.","story.map6-dungeon3.059":"Sampai jumpa, <rep_handlename>!<wait=40> Kutunggu kau di Benteng Langit!","story.map6-dungeon3.060":"Hmm, <wait=40>kurasa Elder Grah jauh lebih kuat daripada yang dia tunjukkan. <wait=20>Menurutmu bagaimana?","story.map6-dungeon3.061":"Eh, <wait=40>tapi itu nggak ada hubungannya dengan kita!","story.map6-dungeon3.062":"Baiklah!<wait=40> Ayo kita menuju Benteng Langit!","story.map6-dungeon4.001":"......<wait=40>Caramu bertindak selalu berbelit-belit seperti biasa.","story.map6-dungeon4.002":"Ini wilayah Cardes.<wait=40> Aku akan bergerak sesukaku.","story.map6-dungeon4.003":"Heh, <wait=40>aku tak keberatan. <wait=40>Aku ingin melihat kemampuanmu yang sebenarnya, Zebra.","story.map6-dungeon4.004":"Malang sekali Summoner itu dan rombongannya...","story.map6-dungeon4.005":"Mereka tak tahu bahwa dewa yang mereka incar pernah mengubur puluhan ribu manusia.","story.map6-dungeon4.006":"...<wait=40>...<wait=40>Kehadiran ini.","story.map6-dungeon4.007":"Sepertinya mereka sudah tiba.","story.map6-dungeon4.008":"Hmph...","story.map6-dungeon4.009":"Rupanya kau juga sedang sial.","story.map6-dungeon4.010":"Akan kubela kehormatanmu,<wait=40> dan kupastikan mereka pergi dari tempat ini.","story.map6-dungeon4.011":"Ayo, <rep_handlename>!<wait=40> Cepatlah!","story.map6-dungeon4.012":"Hah? <wait=40>Ke mana perginya?","story.map6-dungeon4.013":"Nggak salah lagi, hawa menyeramkan itu berasal dari sekitar sini...","story.map6-dungeon4.014":"<rep_handlename>!<wait=40> Ini semua gara-gara kamu lambat sekali sepanjang jalan ke sini.","story.map6-dungeon4.015":"Omong-omong, tempat ini terasa aneh, kan?<wait=40> Aku sudah nggak merasakan siapa pun lagi...","story.map6-dungeon4.016":"Aku yakin tadi merasakan kehadiran seorang dewa...","story.map6-dungeon4.017":"Mungkin cuma perasaanku saja?","story.map6-dungeon4.018":"Hmm, <wait=40>yah, bagaimanapun kita harus menuju Benteng Langit!","story.map6-dungeon4.019":"Ayo ke Jurang Gadillian!","story.map6-dungeon5.001":"<size=18>Hei!<wait=40> <rep_handlename>!","story.map6-dungeon5.002":"Hah, hah, hah.<wait=40> Akhirnya aku menemukanmu...","story.map6-dungeon5.003":"Seria!<wait=40> Di sini!","story.map6-dungeon5.004":"Hah, hah, hah, hah.<wait=40> Siapa sangka kamu sampai sejauh ini...","story.map6-dungeon5.005":"Dasar bodoh!<wait=40> Lain kali berada di tempat yang lebih gampang ditemukan!","story.map6-dungeon5.006":"Itu jelas mustahil...","story.map6-dungeon5.007":"Fiuh. <wait=40>Tapi jujur saja, kami mencarimu ke mana-mana.","story.map6-dungeon5.008":"Kami kira kamu mungkin masih di sekitar Kastel Avenia...","story.map6-dungeon5.009":"...tapi rupanya kamu juga sudah sampai di Encervis.","story.map6-dungeon5.010":"Kamu benar-benar merepotkan.","story.map6-dungeon5.011":"Kenapa Pembasmi Iblis harus mencari orang bodoh sepertimu.","story.map6-dungeon5.012":"Kita yang dari Balai Summoner seharusnya fokus pada urusan Balai Summoner.","story.map6-dungeon5.013":"Tiba-tiba diminta mendukung <rep_handlename>, apa sih yang mereka pikirkan?","story.map6-dungeon5.014":"Sudahlah.","story.map6-dungeon5.015":"Kita tak bisa berbuat apa-apa dengan keadaan yang kita hadapi.","story.map6-dungeon5.016":"Menghentikan Benteng Langit lebih penting daripada mengurus Graham. <wait=20>Kamu juga tahu itu, kan, Seria?","story.map6-dungeon5.017":"Iya, iya, aku tahu!","story.map6-dungeon5.018":"Aku cuma benci <rep_handlename> ikut terlibat dalam rencana ini!","story.map6-dungeon5.019":"Haha, <wait=40>itu khas kamu sekali, Seria.","story.map6-dungeon5.020":"Tapi biar kuulangi, <wait=40>kami datang ke sini untuk menghentikan Zebra. ","story.map6-dungeon5.021":"Kita tak boleh membiarkannya memakai Benteng Langit untuk menyerang Elgaia.","story.map6-dungeon5.022":"Aku tahu pertarungannya sudah berat sampai sejauh ini, <wait=40>tapi mulai sekarang kita harus berjuang sedikit lebih keras lagi!","story.map6-dungeon5.023":"...Apa itu?","story.map6-dungeon5.024":"Hah? <wait=40>Kamu bilang kamu belum dengar soal itu? <wait=50>Serius??","story.map6-dungeon5.025":"*Hah* <wait=40>Memalukan sekali...","story.map6-dungeon5.026":"Aku pasti kelihatan bodoh sekali, bersemangat sendirian!","story.map6-dungeon5.027":"Sepertinya ada orang di Balai Summoner yang benar-benar teledor!","story.map6-dungeon5.028":"Menyedihkan. <wait=40>Padahal kita seharusnya dalam keadaan siaga tinggi.","story.map6-dungeon5.029":"Kukira kamu pasti menerima informasi yang sama dengan kami...","story.map6-dungeon5.030":"Mungkin dia cuma menerima informasi yang salah?","story.map6-dungeon5.031":"Itu sangat tidak seperti Balai Summoner.","story.map6-dungeon5.032":"Mungkin kamu benar...","story.map6-dungeon5.033":"Pokoknya, <wait=40>sepertinya aku sendiri yang harus memberitahumu.","story.map6-dungeon5.034":"Kamu sedang mengejar Zebra, yang membangkitkan Benteng Langit, <wait=40>benar?","story.map6-dungeon5.035":"Baiklah, <wait=40>setidaknya kamu tahu itu.","story.map6-dungeon5.036":"Soal Benteng Langit, <wait=40>benda itu memang jahat. ","story.map6-dungeon5.037":"Kalau sampai berfungsi sepenuhnya...","story.map6-dungeon5.038":"...<wait=40>Zebra bisa memakainya untuk melewati Gerbang Lucius dan menyerang Elgaia.","story.map6-dungeon5.039":"Karena itu, bahkan para petinggi Balai Summoner mengakui bahwa kita dalam keadaan darurat...","story.map6-dungeon5.040":"Dan mereka meminta bantuan dari semua Summoner yang berada di dekat Benteng Langit...","story.map6-dungeon5.041":"Termasuk kamu, <rep_handlename>.","story.map6-dungeon5.042":"Meski kami Pembasmi Iblis sebenarnya bisa mengurus semua ini sendiri...","story.map6-dungeon5.043":"...sejak kamu mengalahkan Maxwell, Karl bersikeras agar aku juga mengakui kemampuanmu...","story.map6-dungeon5.044":"Kali ini kami akan membantumu, <wait=40>jadi kamu harus berterima kasih!","story.map6-dungeon5.045":"Ha ha ha.","story.map6-dungeon5.046":"Meski begitu, <wait=40>yang perlu kamu lakukan hanyalah terus mengejar Benteng Langit seperti tadi. ","story.map6-dungeon5.047":"Kami akan membantumu maju dengan menyingkirkan rintangan apa pun yang muncul. ","story.map6-dungeon5.048":"Jujur saja, <wait=40>kami yang dapat bagian paling tidak enak di sini.","story.map6-dungeon5.049":"Kamu harus membalas budi nanti!","story.map6-dungeon5.050":"Menurut informasi dari Balai Summoner Akras...","story.map6-dungeon5.051":"...sepertinya kita bisa mencapai Benteng Langit setelah melewati Negeri Orang Mati di depan sana. ","story.map6-dungeon5.052":"Kami akan membukakan jalan untukmu.","story.map6-dungeon5.053":"Kamu terus saja maju dengan mata tertuju pada Benteng Langit!","story.map6-dungeon5.054":"Ayo, Seria!","story.map6-dungeon5.055":"Hei, <wait=40>Karl, <wait=20>tunggu aku!","story.map6-dungeon5.056":"<rep_handlename>!","story.map6-dungeon5.057":"Pastikan dewi itu ikut membantu juga! <wait=40>Mengerti?","story.map6-dungeon5.058":"Sungguh, <wait=40>kenapa aku malah mengkhawatirkan bocah sepertimu...","story.map6-dungeon6.001":"Ah! <wait=40>Itu dia kamu!","story.map6-dungeon6.002":"<rep_handlename>!<wait=40> Di sini!","story.map6-dungeon6.003":"Tempat ini bikin merinding...","story.map6-dungeon6.004":"Kenapa tempat-tempat yang dikuasai Empat Dewa yang Jatuh seram sekali...","story.map6-dungeon6.005":"Kamu harus membawa cahaya ke tempat-tempat ini, <rep_handlename>!","story.map6-dungeon6.006":"Oh, <wait=40>hari ini aku punya informasi istimewa untukmu!","story.map6-dungeon6.007":"Biar kuceritakan bagaimana kita akan sampai ke Benteng Langit. ","story.map6-dungeon6.008":"Dengarkan baik-baik selagi dewimu yang cantik ini menjelaskan!","story.map6-dungeon6.009":"Pertama, <wait=40>nama resmi Benteng Langit itu adalah Solaris. ","story.map6-dungeon6.010":"Aku nggak berhasil tahu sudah berapa lama benteng itu ada di sekitar sini...","story.map6-dungeon6.011":"...tapi sepertinya benteng itu bisa ditemukan melayang di langit tepat setelah Negeri Orang Mati.","story.map6-dungeon6.012":"Haha, <wait=40>sudah kuduga kamu bakal kaget. ","story.map6-dungeon6.013":"Kamu pasti bertanya-tanya, \\"Bagaimana caranya kita naik ke langit?\\", benar, kan?","story.map6-dungeon6.014":"Serahkan saja pada sang dewi!","story.map6-dungeon6.015":"Setelah kamu melewati tempat ini dan menuju Benteng Langit...","story.map6-dungeon6.016":"Aku akan mengirimmu ke atas dengan kekuatan istimewaku!","story.map6-dungeon6.017":"Hehe, <wait=40>apa jadinya kamu tanpa aku?","story.map6-dungeon6.018":"Silakan berterima kasih padaku sebanyak yang kamu mau!","story.map6-dungeon6.019":"Tapi jangan lengah!","story.map6-dungeon6.020":"Katanya di depan sana ada gadis yang super menyeramkan yang suka sekali pembantaian...","story.map6-dungeon6.021":"Aku duluan ke Benteng Langit, <rep_handlename>, <wait=40>jadi jangan lama-lama!","story.map6-dungeon6.022":"A-<wait=40>Aku duluan bukan karena takut, ya, mengerti!?","story.map6-dungeon7.001":"Kita sampai!","story.map6-dungeon7.002":"Sepertinya aku berhasil mengirimmu tepat ke tengah Benteng Langit!","story.map6-dungeon7.003":"Aku hebat sekali, kan?","story.map6-dungeon7.004":"Aduh... <wait=40>Sebenarnya kita ada di mana?","story.map6-dungeon7.005":"Aku merasa <wait=40>pusing...","story.map6-dungeon7.006":"Tadi kita sedang melawan iblis di Negeri Orang Mati, kan?","story.map6-dungeon7.007":"Ah! <wait=40>Karl!","story.map6-dungeon7.008":"Dan teman kecilmu, Seria!","story.map6-dungeon7.009":"Apa maksudmu, \\"teman kecil!?\\"","story.map6-dungeon7.010":"Ternyata <rep_handlename>!","story.map6-dungeon7.011":"Tapi kalau kamu ada di sini, <wait=40>berarti...","story.map6-dungeon7.012":"Kita ada di dalam Benteng Langit!","story.map6-dungeon7.013":"...<wait=40>Sepertinya begitu.","story.map6-dungeon7.014":"<size=18>Kamu ini bodoh sekali, ya!?","story.map6-dungeon7.015":"Kita ada di atas sini sepenuhnya gara-gara kamu, kan!?","story.map6-dungeon7.016":"Kamu nggak lihat semua orang masih bertarung di bawah sana?","story.map6-dungeon7.017":"Seharusnya kamu luangkan waktu untuk memahami situasi sebelum bertindak, dewi!","story.map6-dungeon7.018":"A-<wait=40>Apa maksudmu? <wait=40>Aku nggak berbuat salah apa-apa...","story.map6-dungeon7.019":"Kamu pasti besar kepala sekali sampai bisa bilang begitu!","story.map6-dungeon7.020":"Sudahlah, biarkan saja. Kita punya masalah yang jauh lebih penting, bukan?","story.map6-dungeon7.021":"Lagi pula, sekarang akan lebih mudah bagi kita untuk mendukung <rep_handlename>.","story.map6-dungeon7.022":"Selain itu, <wait=40>kepergian kita berdua tak akan banyak berpengaruh bagi mereka yang masih bertarung di bawah.","story.map6-dungeon7.023":"Mungkin kamu benar, tapi...","story.map6-dungeon7.024":"Bagaimanapun, <wait=40>kamu tetap dewi yang hebat seperti biasa.","story.map6-dungeon7.025":"Kamu membuat segalanya sedikit lebih mudah meski kita sedang dalam situasi genting. ","story.map6-dungeon7.026":"Kalau ada yang bisa melakukannya asal bertekad, <wait=40>aku tahu itu pasti kamu.","story.map6-dungeon7.027":"Kamu salah besar, Karl!<wait=40> Kamu terlalu gampang percaya!","story.map6-dungeon7.028":"Haha...","story.map6-dungeon7.029":"<size=18>!?<wait=40> Siapa di sana!?","story.map6-dungeon7.030":"<speed=10>Ah...","story.map6-dungeon7.031":"<speed=10>Rupanya kalian manusia pun bisa merasakan kehadiranku.","story.map6-dungeon7.032":"Zebra!!","story.map6-dungeon7.033":"Itu Zebra, sang dewa gila... <wait=40>Hati-hati, dia sama berbahayanya dengan penampilannya...","story.map6-dungeon7.034":"Kamu bakal membayar perbuatanmu di Edila!","story.map6-dungeon7.035":"Bersiaplah!","story.map6-dungeon7.036":"Aku tak butuh cacing-cacing menyedihkan seperti kalian.","story.map6-dungeon7.037":"Yang kuincar <wait=40>adalah Tilith, murid Lucius.","story.map6-dungeon7.038":"<size=18>Itu dia kau!","story.map6-dungeon7.039":"<size=18>*Duk*","story.map6-dungeon7.040":"Kyaahh!!","story.map6-dungeon7.041":"Kau tampak kelelahan.<wait=40> Wajar saja, kau sudah memakai begitu banyak kekuatan untuk membawa mereka ke sini.","story.map6-dungeon7.042":"Kau sudah bersusah payah demi cacing-cacing menyedihkan ini.","story.map6-dungeon7.043":"Kalau kamu mau bertarung dengan para dewa, aku yakin Lucius akan menghentikanmu...","story.map6-dungeon7.044":"...tapi kalau kamu berniat menyerang kami sekarang, aku nggak akan bermurah hati!","story.map6-dungeon7.045":"<size=18>Kalian semua, mundur!","story.map6-dungeon7.046":"Kekuatan apa ini...<wait=40> Ugh...<wait=40>Aku tak bisa bergerak...","story.map6-dungeon7.047":"Gyah...<wait=40> Bagaimana kau masih punya kekuatan sebesar ini setelah semua itu...<wait=40> Jangan-jangan...","story.map6-dungeon7.048":"Hah... hah... ","story.map6-dungeon7.049":"Aku mungkin sedang agak lemah...<wait=40> tapi aku nggak mungkin kalah darimu...","story.map6-dungeon7.050":"<size=18>Jangan kira kau bisa mempermainkanku! <wait=40>Kau cuma anjing peliharaan Lucius!!","story.map6-dungeon7.051":"<size=18>Kyaaahh!!","story.map6-dungeon7.052":"<size=20>Tilith!!","story.map6-dungeon7.053":"Nngh... <wait=40>Dia melawan lebih keras dari yang kuduga...","story.map6-dungeon7.054":"Tapi itu tak penting lagi. <wait=40>Aku berhasil menyingkirkan penghalangku. ","story.map6-dungeon7.055":"Tak ada lagi dewa yang tersisa untuk melindungi kalian.","story.map6-dungeon7.056":"Kalian semua akan jadi bahan latihan yang bagus untuk bawahanku. ","story.map6-dungeon7.057":"Kau kira kami akan membiarkanmu kabur begitu saja?","story.map6-dungeon7.058":"Aku tak peduli apa niat kalian.","story.map6-dungeon7.059":"Cacing-cacing menyedihkan seperti kalian bahkan tak mampu melangkah sedikit pun di hadapanku.","story.map6-dungeon7.060":"Aku memakai Benteng Langit ini semata-mata untuk membebaskan Lord Cardes dari belenggunya.","story.map6-dungeon7.061":"Kalau kalian sungguh bertekad menghadapiku, <wait=40>kalian akan menemukanku menunggu jauh di dalam. ","story.map6-dungeon7.062":"Akan kutanamkan rasa takut pada dewa dalam diri kalian semua!","story.map6-dungeon7.063":"<size=18>Tunggu!!","story.map6-dungeon7.064":"Sial! <wait=40>Dia kabur!","story.map6-dungeon7.065":"<size=18>Karl!!","story.map6-dungeon7.066":"<size=18>Apa-apaan ini!?<wait=40> Dari mana semua monster ini datang!?","story.map6-dungeon7.067":"N-<wait=40>Nngh...","story.map6-dungeon7.068":"M-<wait=40>Maaf...<wait=40> <rep_handlename>...","story.map6-dungeon7.069":"Jangan bicara!<wait=40> Kamu harus menyimpan tenagamu!","story.map6-dungeon7.070":"Karl, <wait=40>kamu tahu apa yang harus kita lakukan!","story.map6-dungeon7.071":"Ya! <wait=40><rep_handlename>!","story.map6-dungeon7.072":"Kejar Zebra. <wait=20>Aku dan Seria akan mengurus yang di sini!","story.map6-dungeon7.073":"Aku tak tahu bagaimana dia berencana memakai benteng ini...","story.map6-dungeon7.074":"...tapi kalau dia berhasil membebaskan Cardes, kita dalam masalah besar!","story.map6-dungeon7.075":"Jangan cuma berdiri di situ, <wait=40>cepat bergerak!","story.map6-dungeon7.076":"Kamu pikir monster seperti ini bisa menyulitkan kami?","story.map6-dungeon7.077":"Berani-beraninya kamu meragukan pemimpin Pembasmi Iblis!","story.map6-dungeon7.078":"Kalau kamu punya waktu untuk khawatir yang nggak perlu, <wait=40>berhenti menunda-nunda dan kejar dia!","story.map6-dungeon7.079":"Lagi pula, <wait=40>kamu lebih tahu dari siapa pun bahwa dewi ini masih punya tenaga untuk bertarung, kan?","story.map6-dungeon7.080":"Benar, Seria.","story.map6-dungeon7.081":"Monster-monster ini bukan ancaman bagi kami.","story.map6-dungeon7.082":"Dan jangan khawatirkan sang dewi, sekarang dia dalam perlindungan kami.","story.map6-dungeon7.083":"Jadi pergilah sekarang, <wait=40>dan kalahkan Zebra yang keji itu!","story.map6-dungeon7.084":"Kami mengandalkanmu, <rep_handlename>!","story.map6-dungeon7.085":"Tunjukkan pada kami Summoner macam apa kamu sebenarnya!","story.map6-dungeon7.086":"Seria!!","story.map6-dungeon7.087":"Siap!","story.map6-dungeon7.088":"<speed=20><size=20>Ayo maju!!","story.map6-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map6-dungeon_ex_clear.002":"Anda berhasil, <rep_handlename>!","story.map6-dungeon_ex_clear.003":"Anda mengalahkan makhluk itu bahkan sebelum petugas logistik kami tiba.","story.map6-dungeon_ex_clear.004":"Saya tahu Anda pasti bisa, Tuan!","story.map6-dungeon_ex_clear.005":"Ah, <wait=20>tapi rupanya mereka tetap akan pergi ke reruntuhan ini.","story.map6-dungeon_ex_clear.006":"Sepertinya reruntuhan ini dulunya menyimpan sesuatu yang sangat besar.","story.map6-dungeon_ex_clear.007":"Suasananya seperti galangan kapal atau semacamnya, tapi rupanya hanya ini satu-satunya pilihan.","story.map6-dungeon_ex_clear.008":"Hmm? <wait=40>Apakah Anda menyadari sesuatu sejak masuk ke dalam, Tuan?","story.map6-dungeon_ex_clear.009":"Ngomong-ngomong, rupanya ada catatan yang menyebutkan bahwa Valmodora juga muncul saat pertempuran melawan para dewa.","story.map6-dungeon_ex_clear.010":"Tampaknya bahkan saat itu ia mendiami suatu reruntuhan di suatu tempat.","story.map6-dungeon_ex_clear.011":"Namun, ia juga konon telah dibasmi oleh seorang pejuang.","story.map6-dungeon_ex_clear.012":"Saya yakin perbuatan Anda barusan juga akan tercatat dalam sejarah.","story.map6-dungeon_ex_clear.013":"Tapi tetap saja, <wait=20>lain kali jangan terlalu nekat!","story.map6-dungeon_ex_clear.014":"Tapi bagaimanapun, Anda tetap akan pergi apa pun kata saya, kan?","story.map6-dungeon_ex_clear.015":"Saya benar-benar sangat mengkhawatirkan Anda, tahu!","story.map6-dungeon_ex_clear.016":"......","story.map6-dungeon_ex_clear.017":"Hehe, <wait=20>sudah lama sekali saya tidak melihat wajah bingung Anda itu.","story.map6-dungeon_ex_clear.018":"Pokoknya, silakan lanjutkan penyelidikan Anda ke daerah lain!","story.map6-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map6-dungeon_ex_open.002":"Apa Anda bisa mendengar saya, <wait=40>Tuan?","story.map6-dungeon_ex_open.003":"<size=20><rep_handlename>!</size>","story.map6-dungeon_ex_open.004":"Apa Anda bisa mendengar saya?","story.map6-dungeon_ex_open.005":"Saya Lin Merylham dari Dukungan Logistik...","story.map6-dungeon_ex_open.006":"...Biro Investigasi Kantor Survei Grand Gaia, siap melayani Anda.","story.map6-dungeon_ex_open.007":"Saya menghubungi Anda hari ini dengan informasi baru.","story.map6-dungeon_ex_open.008":"Balai Summoner membuat penemuan mengerikan di reruntuhan kuno di Encervis.","story.map6-dungeon_ex_open.009":"Tampaknya makhluk yang luar biasa berbahaya telah menjadikannya sarang.","story.map6-dungeon_ex_open.010":"Untuk sementara, <wait=20>keadaan tampak tenang.","story.map6-dungeon_ex_open.011":"Namun, tampaknya ia menghimpun kekuatan dari reruntuhan di sekitarnya untuk memperluas wilayahnya.","story.map6-dungeon_ex_open.012":"Kami akan mengirim petugas logistik ke sana lagi, jadi sebelum itu mohon jangan mendekat!","story.map6-dungeon_ex_open.013":"......","story.map6-dungeon_ex_open.014":"A-<wait=20>Apa, Tuan? <wait=40>Anda sudah ada di sana?","story.map6-dungeon_ex_open.015":"Hmph, <wait=40>Tuan, Anda terlalu nekat!","story.map6-dungeon_ex_open.016":"Tapi bagaimanapun, Anda tetap akan pergi apa pun kata saya, kan?","story.map6-dungeon_ex_open.017":"Baiklah!","story.map6-dungeon_ex_open.018":"Saya tidak akan mencoba menghentikan Anda!","story.map6-dungeon_ex_open.019":"Monster yang menunggu Anda di dalam dikenal sebagai Valmodora.","story.map6-dungeon_ex_open.020":"Sepertinya monster itu cukup besar, jadi mohon ekstra hati-hati.","story.map6-dungeon_ex_open.021":"Saya selalu sangat mengkhawatirkan Anda, <wait=20>tahu...","story.map6-ending.001":"<speed=10>D-<wait=40>Dasar bodoh...","story.map6-ending.002":"<speed=10>D-<wait=40>Dasar manusia...","story.map6-ending.003":"Gyah!<wait=40> <speed=10>Sebagai murid...<wait=40> Lord Cardes...","story.map6-ending.004":"<speed=10>A-<wait=40>Aku t-tak mungkin..<wait=40> dikalahkan...<wait=40> semudah ini...","story.map6-ending.005":"<speed=10>Nngh...<wait=40> Apa boleh buat...","story.map6-ending.006":"<speed=10>Akan kujatuhkan Benteng Langit, <wait=40>dan kalian semua ikut bersamaku!!","story.map6-ending.007":"<size=18>*Trang*","story.map6-ending.008":"<size=18>K-<wait=40>Kauuuuuu!!","story.map6-ending.009":"Bahkan dewa pun harus tahu kapan harus berhenti.","story.map6-ending.010":"Kalau tak tahu itu, kau tak lebih dari iblis kelas dua, menurutku.","story.map6-ending.011":"Renungkanlah hal itu baik-baik. ","story.map6-ending.012":"<size=18>Gwaaaahhh!!","story.map6-ending.013":"Hmm!?","story.map6-ending.014":"Kenapa wajahmu kaget begitu?","story.map6-ending.015":"Sudahlah, <wait=40>cepat panggil nona muda itu.","story.map6-ending.016":"Dengan lenyapnya Zebra, <wait=40>Benteng Langit kemungkinan akan tersegel lagi.","story.map6-ending.017":"Hmm!? <wait=40>Cahaya ini...","story.map6-ending.018":"<speed=10>Mungkinkah ini... <wait=40>dari Danau Aldela?","story.map6-ending.019":"<size=18><rep_handlename>!!","story.map6-ending.020":"Aduuuh...<wait=40> Kali ini kita terlempar ke mana lagi?","story.map6-ending.021":"<rep_handlename>!!","story.map6-ending.022":"...<wait=40>...<wait=40>Kamu berhasil!","story.map6-ending.023":"Kamu benar-benar hebat!","story.map6-ending.024":"Nngh, <wait=40>pantatku sakit...","story.map6-ending.025":"Hei kamu!<wait=40> Lain kali mendaratnya pelan-pelan, dong!","story.map6-ending.026":"Ho ho ho.","story.map6-ending.027":"Pantat sebesar itu pasti tak masalah, bukan begitu, Seria?","story.map6-ending.028":"Gr-<wait=40>Grahde...<wait=40> Elder Grah!<wait=40> Kenapa Anda bisa ada di sini!?","story.map6-ending.029":"Elder Grah?<wait=40> Nama apa itu?","story.map6-ending.030":"Tunggu sebentar, <wait=40>bukankah Anda Grahdens?","story.map6-ending.031":"Apa yang dilakukan seorang Tetua Summoner seperti Anda di tempat seperti ini?","story.map6-ending.032":"Berani-beraninya kau, <wait=40>dasar bodoh!","story.map6-ending.033":"Padahal, <wait=40>aku akhirnya berhasil membuat Tilith menganggapku kakek tua yang baik hati...","story.map6-ending.034":"Dan sekarang kau muncul dan merusak segalanya!","story.map6-ending.035":"Hah?<wait=40> Apa maksud Anda, \\"kakek tua yang baik hati?\\"","story.map6-ending.036":"Sebagai salah satu pemimpin Balai Summoner,<wait=40> bukankah seharusnya Anda bekerja di sana!?","story.map6-ending.037":"Hmm, <wait=40>aku nggak begitu paham apa yang terjadi, <wait=40>tapi sepertinya Elder Grah memang orang penting dari awal.","story.map6-ending.038":"Dia bukan sekadar kakek aneh yang selama ini kita kenal...","story.map6-ending.039":"Hei, <wait=40>sekarang kamu tahu siapa Lord Grahdens, kamu harus memperlakukannya dengan lebih hormat!","story.map6-ending.040":"Tapi itu nggak ada hubungannya denganku...","story.map6-ending.041":"Lagi pula, aku nggak tahu bagaimana kalian memandang sesuatu di dunia manusia ini...","story.map6-ending.042":"...tapi kalau harus memilih, bukankah sebagai dewi, aku yang lebih penting?","story.map6-ending.043":"Kamu yang seharusnya lebih menghormatiku, Seria!","story.map6-ending.044":"Kalau kamu merasa begitu, kenapa nggak coba bersikap lebih seperti dewi?","story.map6-ending.045":"Apa maksudmu!?","story.map6-ending.046":"Tenanglah, <wait=40>kalian sungguh mau bertengkar padahal <rep_handlename> baru saja mengalahkan Zebra?","story.map6-ending.047":"Ho ho ho.","story.map6-ending.048":"Seria, <wait=40>benar kata Tilith.","story.map6-ending.049":"Dibandingkan para dewa, <wait=40>keberadaanku cukup tak berarti. ","story.map6-ending.050":"Tilith, <wait=40>aku ingin kau tetap memanggilku Elder Grah saja.","story.map6-ending.051":"Memang itu rencanaku dari awal.","story.map6-ending.052":"Sekarang aku tahu siapa Kakek sebenarnya, Elder Grah.<wait=40> Kakek beda dengan si aneh lain yang kukenal!","story.map6-ending.053":"Siapa yang kamu maksud!?","story.map6-ending.054":"Hmm, siapa ya...","story.map6-ending.055":"Astaga, <wait=40>apa kalian berdua nggak akan pernah berubah?","story.map6-ending.056":"Pokoknya, <wait=40>Grahdens...","story.map6-ending.057":"Kembali ke yang ingin kutanyakan tadi, <wait=40>kenapa Anda ada di sini?","story.map6-ending.058":"Karl...","story.map6-ending.059":"Kau juga seorang Summoner, <wait=40>bagaimana kalau kau sedikit lebih menghormatiku?","story.map6-ending.060":"Jangan begitu. <wait=40>Aku tak akan membiarkan Anda mengalihkan pembicaraan lagi.","story.map6-ending.061":"Aku sudah lama mengenal Anda dan terbiasa dengan cara Anda.","story.map6-ending.062":"Ho ho ho.<wait=40> Blak-blakan seperti biasa, rupanya.","story.map6-ending.063":"Karl, <wait=40>biar kujelaskan detailnya nanti.","story.map6-ending.064":"Pertama, ada yang perlu kubicarakan dengan <rep_handlename>.","story.map6-ending.065":"<rep_handlename>, <wait=40>atas keberhasilanmu mengalahkan Zebra sesuai permintaan...","story.map6-ending.066":"Aku menyampaikan terima kasih sebagai Tetua Summoner Departemen Pertahanan Balai Summoner Akras.","story.map6-ending.067":"Hehe, <wait=40>memangnya kamu mengharapkan yang kurang dari sahabatku ini?","story.map6-ending.068":"Aku tahu kamu pasti bisa, <rep_handlename>-ku!","story.map6-ending.069":"Hei, <wait=20>berhenti menyebutnya milikmu!","story.map6-ending.070":"P-<wait=40>Pokoknya, karena <rep_handlename> sudah memenuhi permintaan Lord Grahdens...","story.map6-ending.071":"Kurasa wajar kalau aku memujimu sebagai sesama Summoner.","story.map6-ending.072":"Terus terang sekali kamu!","story.map6-ending.073":"A-<wait=40>Apa maksudmu!?","story.map6-ending.074":"Ho ho ho.<wait=40> Sepertinya semua orang sangat berterima kasih atas apa yang kau lakukan.","story.map6-ending.075":"Namun, <wait=40>sekuat apa pun dia, <wait=40>jangan lupa bahwa Zebra hanyalah murid Cardes.","story.map6-ending.076":"Kekuatan Zebra bukan apa-apa dibandingkan dewa yang jatuh yang sedang kau kejar. ","story.map6-ending.077":"Pasti, <wait=40>pertempuran yang dahsyatnya tiada tara menantimu di Palmyna.","story.map6-ending.078":"Sekarang, lebih dari sebelumnya, <wait=40>kau harus melangkah dengan hati-hati.","story.map6-ending.079":"Jangan khawatirkan dia. <wait=40>Dia dalam perlindunganku.","story.map6-ending.080":"Apa maksudmu, \\"perlindunganku?\\" <wait=40>Barusan kamu hampir mati, ingat nggak?","story.map6-ending.081":"Seria!","story.map6-ending.082":"A-<wait=40>Apa!?","story.map6-ending.083":"Terima kasih...<wait=40> sudah melindungiku tadi.","story.map6-ending.084":"K-<wait=20>Ke-<wait=10>Kenapa k-<wait=10>kamu tiba-tiba begini?","story.map6-ending.085":"B-<wait=40>Bukan berarti aku mengharapkan terima kasih atau apa...","story.map6-ending.086":"A-<wait=40>Aku cuma... <wait=20>*Gumam* <size=14>*Gumam* <size=12>*Gumam*","story.map6-ending.087":"Haha, <wait=40>jadi malu-malu, ya?","story.map6-ending.088":"Ho ho ho.","story.map6-ending.089":"<rep_handlename>!","story.map6-ending.090":"Akhirnya kita berangkat ke Palmyna, negeri tempat Cardes disegel!","story.map6-ending.091":"Aku percaya padamu...","story.map6-ending.092":"<rep_handlename>, <wait=40>kamulah Summoner yang akan menyelamatkan dunia!","story.map6-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Kau, <rep_handlename>,<wait=39> yang telah membuka Amdahl...","story.map6-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Gunakan kekuatanku saat kau memulai perjalanan di negeri baru ini...","story.map6-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Demi membawa harapan baru ke dunia yang diliputi kesedihan ini…","story.map6-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Kau harus percaya pada kekuatanmu, <wait=20>dan terus melangkah maju…","story.map6-open.005":"Oh, <wait=40>kamu sudah bangun!","story.map6-open.006":"Lihat! <wait=40>Kita ada di Encervis.","story.map6-open.007":"Dengan perairannya yang dalam dan gunung berapinya yang tinggi, <wait=40>tempat ini terkenal dengan lingkungannya yang ekstrem.","story.map6-open.008":"Dahulu kala, <wait=40>pernah terjadi pertempuran antarmanusia di sini...","story.map6-open.009":"...<wait=40>...","story.map6-open.010":"Tapi itu nggak begitu menarik, jadi lupakan saja!","story.map6-open.011":"Lagi pula, <wait=40>masih banyak hal lain yang perlu kamu pelajari!","story.map6-open.012":"Dan itu juga nggak ada hubungannya dengan kita.","story.map6-open.013":"Di tengah Kepulauan Palmyna ini, kita masih cukup jauh dari Palmyna sendiri...","story.map6-open.014":"Tapi jangan lengah, <wait=20>dan selalu tetap fokus!","story.map6-open.015":"Aku mengharapkan hal-hal hebat darimu di sini juga!","story.map6-open.016":"Baiklah, <wait=20>ayo kita berusaha sekuat tenaga untuk mengalahkan Cardes!!","story.map7-dungeon1.001":"<rep_handlename>!","story.map7-dungeon1.002":"Gawat!<wait=40> Gawat banget!!","story.map7-dungeon1.003":"Kyaah!","story.map7-dungeon1.004":"<size=18>*Gedebuk*","story.map7-dungeon1.005":"Aduuuhh...","story.map7-dungeon1.006":"Hei!<wait=40> <rep_handlename>! <wait=40>Jangan bengong saja!","story.map7-dungeon1.007":"Hah? <wait=40>Kamu kira aku seharusnya menunggumu di Kastel Obselion?","story.map7-dungeon1.008":"Sekarang bukan waktunya memusingkan hal sepele begitu!","story.map7-dungeon1.009":"Kita benar-benar dalam masalah besar!","story.map7-dungeon1.010":"Segel yang mengurung Cardes mulai luntur!!","story.map7-dungeon1.011":"Aku tidak tahu kenapa tiba-tiba segelnya mulai luntur...","story.map7-dungeon1.012":"...tapi dia jelas sedang bersiap untuk kabur!","story.map7-dungeon1.013":"Tapi kurasa tidak ada pihak luar yang terlibat.","story.map7-dungeon1.014":"Ya ampun!","story.map7-dungeon1.015":"Kukira kita bakal gampang mengalahkannya, setelah melihat caramu menghadapi Zebra.","story.map7-dungeon1.016":"Huh, <wait=40>sepertinya bakal sibuk lagi nih...","story.map7-dungeon1.017":"Masih banyak tugasku untuk Lord Lucius...","story.map7-dungeon1.018":"Dan sekarang aku juga harus mengurus rencana Cardes...","story.map7-dungeon1.019":"Kenapa aku tidak pernah bisa istirahat!","story.map7-dungeon1.020":"Oh, <wait=40>aku hampir lupa!","story.map7-dungeon1.021":"Aku masih belum menemukan jalan menuju Dunia Roh!","story.map7-dungeon1.022":"Tapi aku janji sudah menemukannya sebelum kamu sampai di Kastel Obselion, <rep_handlename>.","story.map7-dungeon1.023":"Semoga berhasil, <wait=40>dan kali ini kita pasti bertemu di Kastel Obselion!","story.map7-dungeon2.001":"Ho ho ho. <wait=40>Bukankah ini <rep_handlename>?","story.map7-dungeon2.002":"Sedang menuju negeri tempat Cardes disegel, ya?","story.map7-dungeon2.003":"Hmm? <wait=40>Ada apa?<wait=40> Kamu tampak gelisah.","story.map7-dungeon2.004":"Kalau kamu mencari Tilith, aku belum melihatnya di sekitar sini. ","story.map7-dungeon2.005":"Kenapa wajahmu murung begitu? <wait=40>Kamu tidak perlu mengkhawatirkannya, tahu?","story.map7-dungeon2.006":"Dia berada di luar urusan kami, para Summoner biasa. ","story.map7-dungeon2.007":"Meski cara manisnya memandangmu juga akan membuatku gugup. ","story.map7-dungeon2.008":"Ho ho ho.","story.map7-dungeon2.009":"Hmm. <wait=40>Sepertinya sudah lama kita tidak berdua saja. ","story.map7-dungeon2.010":"Selagi ada waktu, <wait=40>bagaimana kalau kuceritakan sebuah kisah.","story.map7-dungeon2.011":"Kisah tentang pertempuran mengerikan antara manusia dan para dewa.","story.map7-dungeon2.012":"Dahulu kala, <wait=40>Kastel Obselion adalah kediaman Keluarga Kerajaan Palmyna. ","story.map7-dungeon2.013":"Awalnya kastel ini indah, <wait=40>dikelilingi kehijauan. ","story.map7-dungeon2.014":"Namun, beginilah jadinya setelah pertempuran melawan para dewa. ","story.map7-dungeon2.015":"Apakah kamu tahu tentang Empat Pahlawan Palmyna?","story.map7-dungeon2.016":"Konon, keempat kesatria itu melawan Cardes demi menyelamatkan negeri ini.","story.map7-dungeon2.017":"Bahkan dikatakan Edea, Putri Palmyna, ada di antara mereka.","story.map7-dungeon2.018":"Jika legenda itu benar, Empat Pahlawan inilah yang menyegel Cardes. ","story.map7-dungeon2.019":"Namun, konon sebagai ganti bisa menyegel Cardes...","story.map7-dungeon2.020":"...Empat Pahlawan harus mengorbankan nyawa mereka sendiri. ","story.map7-dungeon2.021":"Aku penasaran apa yang mereka pikirkan di saat-saat terakhir. ","story.map7-dungeon2.022":"Apakah mereka bahagia karena yakin menyegel Cardes akan menyelamatkan Palmyna? ","story.map7-dungeon2.023":"Itukah sebabnya mereka bisa menghadapi maut tanpa rasa takut?","story.map7-dungeon2.024":"Seberani apa pun mereka mempertaruhkan nyawa untuk melindungi tempat ini...","story.map7-dungeon2.025":"...saat mereka mulai bertempur, tempat ini sudah hilang.","story.map7-dungeon2.026":"Sungguh kisah yang menyedihkan...","story.map7-dungeon2.027":"<rep_handlename>, <wait=40>apakah kamu mengerti maksudku?","story.map7-dungeon2.028":"Ho ho ho. <wait=40>Jangan khawatir.","story.map7-dungeon2.029":"Pasti, <wait=40>suatu hari kamu akan berada dalam situasi tak terbayangkan serupa. ","story.map7-dungeon2.030":"Sampai saat itu, <wait=40>awasi baik-baik sekelilingmu yang terus berubah. ","story.map7-dungeon2.031":"Apa yang kamu temukan akan menjadi bekal di jalanmu ke depan. ","story.map7-dungeon2.032":"Ho ho ho.<wait=40> Maaf ceramahku panjang. ","story.map7-dungeon2.033":"Kalau kamu bertemu Tilith lagi, tolong sampaikan pesan ini padanya.","story.map7-dungeon2.034":"Segel Cardes hampir hancur.","story.map7-dungeon2.035":"Sampai jumpa, dan jaga dirimu.","story.map7-dungeon3.001":"<size=18>*Tebas*","story.map7-dungeon3.002":"Fiuh. <wait=40>Sepertinya monster di daerah ini hampir habis. ","story.map7-dungeon3.003":"Tapi harus kuakui, <wait=40>mereka jauh lebih kuat dari dugaanku.","story.map7-dungeon3.004":"Hmm?","story.map7-dungeon3.005":"Hei! <wait=40><rep_handlename>!","story.map7-dungeon3.006":"Selamat datang di Palmyna!","story.map7-dungeon3.007":"Kita sudah tidak jauh dari tempat Cardes disegel. <wait=40>Ayo kerahkan semua tenaga untuk dorongan terakhir ini!","story.map7-dungeon3.008":"Hei! <wait=40>Seria!<wait=40> <rep_handlename> juga sudah sampai!","story.map7-dungeon3.009":"Tidak perlu kasih tahu aku setiap kali. <wait=40>Lagi pula, aku memang sedang mengabaikan <rep_handlename>.","story.map7-dungeon3.010":"Haha. <wait=40>Seperti biasa, ya, Seria?","story.map7-dungeon3.011":"Ngomong-ngomong, <wait=40>mana dewi yang selalu membuntutimu itu?","story.map7-dungeon3.012":"...Hmm, jadi dia sedang mencari jalan ke Dunia Roh.","story.map7-dungeon3.013":"Sepertinya kita tak punya pilihan selain ke sana kalau mau melawan Cardes...","story.map7-dungeon3.014":"Ada apa?<wait=40> Wajahmu agak pucat.","story.map7-dungeon3.015":"B-<wait=40>Bukan apa-apa!","story.map7-dungeon3.016":"Aku cuma sedikit kesal!","story.map7-dungeon3.017":"Maksudku, <wait=40>kamu tidak lihat apa yang terjadi, Karl!?","story.map7-dungeon3.018":"Tujuan kita sejak awal adalah mengalahkan Graham!","story.map7-dungeon3.019":"Kenapa kita harus buang waktu membantu <rep_handlename>!?","story.map7-dungeon3.020":"Ayolah, <wait=40>tentu mengalahkan Empat Dewa yang Jatuh lebih penting daripada Graham. ","story.map7-dungeon3.021":"Aku tahu, aku tahu!","story.map7-dungeon3.022":"Tapi kamu tahu perasaanku, kan, Karl?","story.map7-dungeon3.023":"Lebih dari apa pun, aku ingin menghabisi Graham!","story.map7-dungeon3.024":"Ya, <wait=40>aku mengerti perasaanmu. <wait=50>Maafkan aku, <wait=40>Seria...","story.map7-dungeon3.025":"Aku tidak bermaksud menyalahkanmu, Karl...","story.map7-dungeon3.026":"Grrr!!<wait=40> Ini semua salahmu!","story.map7-dungeon3.027":"Kenapa kamu tidak melawan Cardes sendirian saja!","story.map7-dungeon3.028":"Agak tidak masuk akal,<wait=40> bukan?","story.map7-dungeon3.029":"Sudah kubilang aku tahu!","story.map7-dungeon3.030":"Karl, <wait=40>belakangan ini susah sekali berdebat denganmu!","story.map7-dungeon3.031":"Bukan, <wait=40>belakangan ini kamu saja yang bicara hal-hal konyol...","story.map7-dungeon3.032":"Aku tidak mengerti maksudmu!","story.map7-dungeon3.033":"<rep_handlename>! <wait=40>Cepat temukan dewi itu...","story.map7-dungeon3.034":"...dan cari tahu bagaimana caranya kita ke Dunia Roh!","story.map7-dungeon3.035":"H-<wait=20>Hei!<wait=40> Tunggu aku!","story.map7-dungeon3.036":"<rep_handlename>! Kami akan membuka jalan di depan.","story.map7-dungeon3.037":"Kamu pastikan saja dirimu siap menghadapi Cardes!","story.map7-dungeon4.001":"...<rep_handlename>.","story.map7-dungeon4.002":"Aku senang bertemu kamu... <wait=40>Sepertinya kamu baik-baik saja...","story.map7-dungeon4.003":"Hah...<wait=40> hah...","story.map7-dungeon4.004":"A-<wait=40>Aku tidak apa-apa...","story.map7-dungeon4.005":"Nngh...<wait=40> Sepertinya aku sedikit ceroboh...","story.map7-dungeon4.006":"Waktu aku mencari cara menuju Dunia Roh <wait=40>terjadi sesuatu yang tak terduga...","story.map7-dungeon4.007":"Maaf sudah membuatmu khawatir.","story.map7-dungeon4.008":"Aku akan baik-baik saja, <wait=20>aku cuma perlu istirahat sebentar.","story.map7-dungeon4.009":"Tapi yang lebih penting, <wait=40>ada yang harus kuberitahukan padamu...","story.map7-dungeon4.010":"<rep_handlename>...","story.map7-dungeon4.011":"Segel Cardes...<wait=40> bukan cuma retak...","story.map7-dungeon4.012":"Cardes... <wait=40>menghancurkannya... <wait=40>dari dalam...","story.map7-dungeon4.013":"Dia sedang lemah karena terlalu lama disegel...","story.map7-dungeon4.014":"Tapi kekuatannya sebagai dewa masih luar biasa...","story.map7-dungeon4.015":"Kekuatannya sudah mulai meluap dari Dunia Roh, <wait=40>menghancurkan apa pun yang dilewatinya...","story.map7-dungeon4.016":"Aku mencoba memperbaiki segelnya, tapi gagal...","story.map7-dungeon4.017":"Hah...<wait=40> hah...","story.map7-dungeon4.018":"T-<wait=40>Tapi... <wait=40>kita masih punya kesempatan.","story.map7-dungeon4.019":"Jalan menuju Dunia Roh sekarang sudah terbuka.","story.map7-dungeon4.020":"Pergilah ke Medan Perang Noera. <wait=40>Pintu masuk Dunia Roh ada tepat di baliknya...","story.map7-dungeon4.021":"Pergilah duluan, <wait=40>dan jangan khawatirkan aku!","story.map7-dungeon4.022":"Sekalian minta bantuan Karl, Seria, dan Elder Grah. ","story.map7-dungeon4.023":"Aku mau istirahat dulu sebelum menyusulmu...","story.map7-dungeon4.024":"Jangan khawatirkan aku...","story.map7-dungeon4.025":"Aku ini dewi yang cantik dan tak terkalahkan!","story.map7-dungeon4.026":"Hanya saja, <wait=40>aku sedikit lelah sekarang...","story.map7-dungeon4.027":"Tapi jangan khawatir... <wait=50>Sampai jumpa di garis depan...","story.map7-dungeon5.001":"Bukankah ini <rep_handlename>.","story.map7-dungeon5.002":"Kenapa wajahmu muram begitu?","story.map7-dungeon5.003":"Apa katamu!?<wait=40> Apa yang terjadi pada Tilith!?","story.map7-dungeon5.004":"Hmm. <wait=40>Situasinya lebih genting dari yang kubayangkan. ","story.map7-dungeon5.005":"Maaf, tapi ada urusan yang harus kuselesaikan di sini, <wait=40>jadi aku tak bisa membantumu. ","story.map7-dungeon5.006":"Aku sudah meminta Karl dan Seria untuk membantumu. ","story.map7-dungeon5.007":"Bekerja samalah untuk mengalahkan Cardes.","story.map7-dungeon5.008":"......<wait=50><rep_handlename>.","story.map7-dungeon5.009":"Ada yang ingin kuberitahukan sebelum kamu berhadapan dengan Dewa yang Jatuh itu.","story.map7-dungeon5.010":"Salah satu dari Empat Pahlawan Palmyna dulu bekerja di Seminari Arlind ini.","story.map7-dungeon5.011":"Namanya Lorand, dan dia seorang guru. ","story.map7-dungeon5.012":"Meski dia sudah lama pensiun dari kehidupan prajurit...","story.map7-dungeon5.013":"...Edea, Putri Palmyna, <wait=40>membujuknya untuk melawan para dewa yang menyerbu. ","story.map7-dungeon5.014":"Akhirnya persis seperti yang kuceritakan sebelumnya. ","story.map7-dungeon5.015":"Empat Pahlawan mengorbankan nyawa mereka untuk menyegel Cardes. ","story.map7-dungeon5.016":"Namun, <wait=40>ada banyak kisah lain tentang orang-orang yang bertempur seperti Empat Pahlawan. ","story.map7-dungeon5.017":"Dahulu kala, <wait=40>banyak manusia melawan para dewa di sini.","story.map7-dungeon5.018":"Sebagian besar dari mereka akhirnya kehilangan nyawa.","story.map7-dungeon5.019":"Menurut legenda, <wait=40>Lucius mengizinkan sebagian penyintas melarikan diri ke Elgaia. ","story.map7-dungeon5.020":"Semua yang tertinggal di Grand Gaia binasa. ","story.map7-dungeon5.021":"<rep_handlename>.<wait=50> Menurutmu kenapa para dewa memusnahkan manusia?","story.map7-dungeon5.022":"Ada banyak sekali teori, <wait=40>tapi jawabannya belum ditemukan.","story.map7-dungeon5.023":"Namun setelah waktu yang lama berlalu, <wait=40>Lucius kembali membuka jalan menuju Grand Gaia.","story.map7-dungeon5.024":"Dia pasti juga membutuhkan kekuatan manusia untuk mengalahkan Empat Dewa yang Jatuh. ","story.map7-dungeon5.025":"Meski begitu, kenapa sebenarnya Empat Dewa yang Jatuh mengamuk?","story.map7-dungeon5.026":"Dan kenapa Kaisar Suci Karna Masta, penguasa para dewa, tidak menanggapi situasi ini?","story.map7-dungeon5.027":"Terlalu banyak hal yang tak akan pernah dipahami kami manusia.","story.map7-dungeon5.028":"Tapi Tilith, sebagai murid Lucius, pasti paham, bukan begitu?","story.map7-dungeon5.029":"Kamu yakin dia tidak tahu? <wait=40>Mungkin dia sengaja menyembunyikan sesuatu darimu.","story.map7-dungeon5.030":"Atau mungkin, <wait=40>dia memang tidak berpikir sama sekali. ","story.map7-dungeon5.031":"Ho ho ho.","story.map7-dungeon5.032":"Tilith gadis yang begitu baik dan cantik, kuharap memang hanya itu. ","story.map7-dungeon5.033":"Bagaimanapun, <wait=40><rep_handlename>.","story.map7-dungeon5.034":"Maaf aku jadi meracau begini, <wait=40>tapi aku yakin kamu mengerti maksudku.","story.map7-dungeon5.035":"Jangan biarkan dirimu terseret oleh semua yang terjadi, <wait=40>bertindaklah sesuai pikiran dan kehendakmu sendiri. ","story.map7-dungeon5.036":"Peranmu dalam hal ini sudah melebihi apa yang sanggup dipikul seorang Summoner. ","story.map7-dungeon5.037":"Sebaiknya kamu berangkat sekarang.","story.map7-dungeon5.038":"Di balik Medan Perang Noera di depan sana ada pintu masuk Dunia Roh.","story.map7-dungeon5.039":"Dan jangan lupa, <wait=20>bukan hanya Tilith dan para dewa yang mengandalkanmu.","story.map7-dungeon6.001":"Yo, <rep_handlename>!<wait=40> Kamu sudah di sini.","story.map7-dungeon6.002":"Lihat!<wait=40> Pintu masuk Dunia Roh ada tepat di depan kita.","story.map7-dungeon6.003":"Hei, <wait=40>dewi itu sudah memberitahumu cara masuk ke Dunia Roh, kan?","story.map7-dungeon6.004":"Lalu di mana dia? <wait=40>Bisa-bisanya dia keluyuran di saat genting begini!?","story.map7-dungeon6.005":"Eh......<wait=50> Oh, begitu......","story.map7-dungeon6.006":"T-<wait=40>Tapi tidak perlu khawatir, kan?<wait=40> Dia kan dewi!?","story.map7-dungeon6.007":"Aku yakin cepat atau lambat dia bakal muncul dengan muka sombongnya itu!","story.map7-dungeon6.008":"Jadi hapus tampang memelasmu itu dan kerjakan tugasmu!","story.map7-dungeon6.009":"Dia melakukan semua itu karena percaya kamu bisa mengalahkan Cardes!","story.map7-dungeon6.010":"Sekarang kamu harus berusaha sekuat tenaga! <wait=40>Jangan sia-siakan semua yang sudah dia lakukan!","story.map7-dungeon6.011":"Dia benar.","story.map7-dungeon6.012":"Aku tahu kamu khawatir, <rep_handlename>, <wait=40>tapi kita harus mengalahkan Cardes lebih dulu.","story.map7-dungeon6.013":"Kalau pintu masuk Dunia Roh memang terbuka...","story.map7-dungeon6.014":"...berarti tidak ada yang menghalangi kami untuk ikut membantumu.","story.map7-dungeon6.015":"Demi sang dewi, <wait=40>kami akan membantu sebisa mungkin!","story.map7-dungeon6.016":"A-<wait=40>Aku cuma menjalankan perintah dari Balai Summoner!","story.map7-dungeon6.017":"Apa yang kulakukan tidak ada hubungannya dengan dewi bodoh itu!","story.map7-dungeon6.018":"Lagi pula, <wait=40>sesekali enak juga membuatnya berutang budi pada kita. ","story.map7-dungeon6.019":"Kurasa kali ini aku akan berusaha sedikit lebih keras dari biasanya.","story.map7-dungeon6.020":"Heh, <wait=40>aku yakin dia pun akan tenang melihatmu bersemangat begini, Seria.","story.map7-dungeon6.021":"A-<wait=40>Apa maksudmu!?","story.map7-dungeon6.022":"Aku cuma bilang sepertinya kami bisa mengandalkanmu, Seria. <wait=40>Benar, kan, <rep_handlename>?","story.map7-dungeon6.023":"Jangan ikut-ikutan dia!","story.map7-dungeon6.024":"Baiklah, <wait=40>ayo kita terobos masuk ke Dunia Roh!","story.map7-dungeon6.025":"<rep_handlename>!<wait=40> Seria!<wait=40> Ayo!","story.map7-dungeon7.001":"Jadi ini Dunia Roh Palmyna...<wait=40> Cukup menyeramkan, harus kuakui.","story.map7-dungeon7.002":"Syukurlah tempatnya jauh lebih luas dari yang kukira.","story.map7-dungeon7.003":"Hah?<wait=40> Bukankah kalau lebih luas, Cardes jadi lebih sulit ditemukan?","story.map7-dungeon7.004":"E-<wait=20>Eh, maksudku...<wait=40> Bukan itu maksudku...","story.map7-dungeon7.005":"Aku cuma berpikir bakal sulit melawan Cardes di tempat sempit. ","story.map7-dungeon7.006":"Ya, <wait=40>kamu benar soal itu.","story.map7-dungeon7.007":"Dengan ruang seluas ini, <wait=40>pilihan kita untuk melawan Cardes tak terbatas. ","story.map7-dungeon7.008":"Ya, <wait=40>sepertinya begitu.","story.map7-dungeon7.009":"<size=16>*Gemuruh*","story.map7-dungeon7.010":"A-<wait=20>Apa itu!<wait=20> Kenapa semuanya bergetar?","story.map7-dungeon7.011":"Sial! <wait=40>Ternyata keadaannya tidak setenang kelihatannya!","story.map7-dungeon7.012":"Padahal kuharap kita punya lebih banyak waktu untuk mencari Cardes...","story.map7-dungeon7.013":"<rep_handlename>!<wait=40> Seria!","story.map7-dungeon7.014":"Ayo berpencar dan cari Cardes!","story.map7-dungeon7.015":"Kamu yakin itu ide bagus di saat seperti ini!?","story.map7-dungeon7.016":"Waktu kita hampir habis.","story.map7-dungeon7.017":"Kalau kita tidak bisa mengalahkan Cardes sebelum dia lepas...","story.map7-dungeon7.018":"...besar kemungkinan kita ikut lenyap bersama Dunia Roh.","story.map7-dungeon7.019":"......<wait=40>Mengerti.","story.map7-dungeon7.020":"Kalau kalian mendengar dentang pedang, <wait=40>pasti di sanalah pertempuran dimulai. ","story.map7-dungeon7.021":"Pasang telinga dan awasi baik-baik sekeliling kalian!","story.map7-dungeon7.022":"<rep_handlename>!","story.map7-dungeon7.023":"Kamu masih anak baru, <wait=40>jadi kalau melihat Cardes, sebaiknya kamu diam dan tunggu kami!","story.map7-dungeon7.024":"Dia benar. <wait=40>Apa pun yang terjadi, jangan ada yang melawannya sendirian!","story.map7-dungeon7.025":"Aku ingin kita semua selamat dan kembali ke Elgaia bersama!","story.map7-ending.001":"Hah...<wait=40> hah...<wait=40> Kita terlambat!","story.map7-ending.002":"<size=20>*Gemuruh*","story.map7-ending.003":"<anchor=center><speed=10>Seria...<wait=40> Pegang tanganku......","story.map7-ending.004":"Halo semuanya! <wait=40>Maaf aku terlambat!!","story.map7-ending.005":"<rep_handlename>! <wait=40>Aku tahu kamu pasti bisa!","story.map7-ending.006":"K-<wait=20>Kamu! <wait=40>Kenapa kamu di sini!?","story.map7-ending.007":"Kukira kamu terluka parah...","story.map7-ending.008":"Aku punya firasat <rep_handlename> dalam bahaya, <wait=40>jadi kutunda pemulihanku untuk datang membantu.","story.map7-ending.009":"Tapi aku masih agak kesakitan, sih.","story.map7-ending.010":"Bodoh sekali kamu melakukan hal begitu hanya karena firasat!","story.map7-ending.011":"Aku senang sempat datang tepat waktu untuk menolongmu juga, <wait=40>Seria.","story.map7-ending.012":"......","story.map7-ending.013":"T-<wait=40>Terima kasih untuk itu...","story.map7-ending.014":"Sama-sama! <wait=40>Aku cuma senang kalian semua selamat!","story.map7-ending.015":"Ya, <wait=40>terima kasih sudah menyelamatkan kami!","story.map7-ending.016":"Sungguh sial kalau kami tamat di tempat seperti ini, <wait=40> setelah berhasil mengalahkan Cardes. ","story.map7-ending.017":"Terima kasih, <wait=40>dewi.","story.map7-ending.018":"Itu baru Karl yang kukenal! <wait=40>Kamu juga boleh berterima kasih lebih banyak, Seria!","story.map7-ending.019":"J-<wait=40>Jangan keterlaluan!","story.map7-ending.020":"Maksudku, <wait=40>kalau kamu memang dewi, kenapa kamu selalu datang di menit terakhir setiap kali!","story.map7-ending.021":"A-<wait=40>Apa-apaan kamu!","story.map7-ending.022":"Satu lagi, kenapa kamu tidak memberi tahu kami cara keluar dari Dunia Roh!?","story.map7-ending.023":"U-<wait=40>Ugh, <wait=20>pasti aku tadi...","story.map7-ending.024":"Sudahlah, biarkan saja begini.","story.map7-ending.025":"Dan biarpun kelihatannya begitu, Seria sungguh berterima kasih atas apa yang kamu lakukan untuknya.","story.map7-ending.026":"Iya, <wait=40>aku tahu.","story.map7-ending.027":"Kelihatan dari wajahnya yang memerah!","story.map7-ending.028":"Aku juga sayang sekali sama Seria!","story.map7-ending.029":"Hentikan! <wait=40>Kamu bikin aku mual!!","story.map7-ending.030":"<size=12>Dasar bodoh...","story.map7-ending.031":"Karl! <wait=40>Aku pergi!","story.map7-ending.032":"Kita sudah melakukan permintaan Balai Summoner!","story.map7-ending.033":"Sekarang saatnya mengejar Graham!","story.map7-ending.034":"T-<wait=20>Tunggu!","story.map7-ending.035":"<rep_handlename>!","story.map7-ending.036":"Aku tak pernah sebangga ini menyebutmu temanku!","story.map7-ending.037":"Begitu keadaan tenang, <wait=20>ayo bertualang bersama di Grand Gaia!","story.map7-ending.038":"Jangan besar kepala cuma karena kamu mengalahkan Cardes!","story.map7-ending.039":"Keberuntunganmu pasti akan habis suatu saat nanti, tahu.","story.map7-ending.040":"Lain kali kita bertemu, akan kutunjukkan kekuatan sejati Summoner yang memimpin Pembasmi Iblis. ","story.map7-ending.041":"Tapi sampai saat itu, <wait=20>kamu harus tetap utuh!","story.map7-ending.042":"Mereka sudah pergi.","story.map7-ending.043":"Kuharap suatu hari kita bisa bertarung bersama lagi!","story.map7-ending.044":"<rep_handlename>! <wait=40>Terima kasih banyak sudah mengalahkan Cardes!","story.map7-ending.045":"Harus kuakui, waktu pertama bertemu aku tak bisa terlalu mengandalkanmu, <wait=40>tapi kamu sudah mengalahkan dua dari Empat Dewa yang Jatuh.","story.map7-ending.046":"Kalian manusia memang menarik!","story.map7-ending.047":"Sejak bertemu Karl, Seria,<wait=40> dan kamu...","story.map7-ending.048":"...aku jadi makin suka pada kalian manusia!","story.map7-ending.049":"Aku menantikan petualangan berikutnya bersamamu, <wait=40><rep_handlename>-ku.","story.map7-ending.050":"......<wait=40>Sepertinya Cardes yang agung telah dikalahkan.","story.map7-ending.051":"Dewa yang Jatuh yang tersisa hanya Zevalhua Sang Agung, <wait=40>dan Dewa Buas Afla Dilith. ","story.map7-ending.052":"Sudah saatnya mereka juga ikut turun tangan.","story.map7-ending.053":"Kita harus mempercepat persiapan.","story.map7-ending.054":"<rep_handlename>...","story.map7-ending.055":"Aku menantikan jalan mana yang akan kamu pilih dalam pertempuran berikutnya...","story.map7-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Kamu, <rep_handlename>,<wait=39> yang telah membuka Encervis...","story.map7-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Gunakan kekuatanku saat kamu maju ke Palmyna, <wait=40>negeri Dewa yang Jatuh yang tersegel...","story.map7-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Demi membawa harapan baru ke dunia yang dipenuhi kesedihan ini...","story.map7-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Kamu harus percaya pada kekuatanmu, <wait=20>dan terus melangkah maju...","story.map7-open.005":"<rep_handlename>!<wait=40> Akhirnya kamu sampai di Palmyna!","story.map7-open.006":"Tidak jauh lagi ke Dunia Roh tempat Cardes dikurung!","story.map7-open.007":"Karena kamu bisa mengalahkan Zebra, aku yakin kamu bakal sampai ke sana tepat waktu, <rep_handlename>.","story.map7-open.008":"Tapi tetap saja, <wait=40>jangan lengah!","story.map7-open.009":"Dahulu kala ada kerajaan bernama Palmyna di sini yang bertempur dengan gagah berani melawan para dewa. ","story.map7-open.010":"Sisa-sisa perang itu masih bisa dilihat sampai sekarang...","story.map7-open.011":"...bersama semua roh dan monster yang masih berkeliaran.","story.map7-open.012":"Baiklah, <wait=40>biar kucarikan jalan ke Dunia Roh. ","story.map7-open.013":"Pelan-pelan saja majunya, <rep_handlename>.","story.map7-open.014":"Aku akan menunggumu di Kastel Obselion di depan sana!","story.map8-dungeon1.001":"Sial! <wait=40>Masih jauh banget.","story.map8-dungeon1.002":"Tapi ya sudahlah, <wait=20>mengeluh juga nggak ada gunanya.","story.map8-dungeon1.003":"Hm? <wait=40>Hei, kamu!","story.map8-dungeon1.004":"Cih, <wait=20>ternyata <rep_handlename> kita tersayang.","story.map8-dungeon1.005":"Ngapain kamu di sini?","story.map8-dungeon1.006":"Jangan-jangan!?","story.map8-dungeon1.007":"Kamu ke sini mau mengklaim hasil kerja kerasku, kan!?","story.map8-dungeon1.008":"Ngomong-ngomong, <wait=20>apa maksudnya kabar soal Cordelica itu? ","story.map8-dungeon1.009":"Aku dengar rumor kalau kamu mengalahkan salah satu Empat Dewa yang Jatuh sendirian?","story.map8-dungeon1.010":"Hmph, <wait=40>atau jangan-jangan, <wait=20>Karl dan Seria yang harus datang menyelamatkanmu, ya?","story.map8-dungeon1.011":"Terserahlah, <wait=20>toh nggak ada bedanya juga.","story.map8-dungeon1.012":"Diam! <wait=40>Aku nggak minta penjelasan atau apa pun!","story.map8-dungeon1.013":"Kalau otakmu masih ada setengah, dengarkan apa yang mau kukatakan!","story.map8-dungeon1.014":"Po<wait=20>kok<wait=20>nya.","story.map8-dungeon1.015":"Jangan sampai kamu menghalangiku! Itu saja!","story.map8-dungeon1.016":"Aku sedang menjalankan misi yang super penting atas nama Balai Summoner.","story.map8-dungeon1.017":"Yah, bukan sesuatu yang nggak bisa ditangani elite sepertiku.","story.map8-dungeon1.018":"Kalau kamu paham maksudku, sebaiknya kamu pergi jauh-jauh sana!","story.map8-dungeon1.019":"Dan aku janji, kalau aku melihatmu berkeliaran di Cordelica, kamu bakal langsung kuhabisi.","story.map8-dungeon1.020":"Mengerti?","story.map8-dungeon2.001":"Fiuh, <wait=40>tempat ini lebih berbahaya dari dugaanku.","story.map8-dungeon2.002":"Kalau begini terus, perjalananku ke menara masih panjang. ","story.map8-dungeon2.003":"Wah, <wait=40>ternyata <rep_handlename>.","story.map8-dungeon2.004":"Sedang apa kamu di sini?","story.map8-dungeon2.005":"Hehe, <wait=40>kurasa aku tidak perlu bertanya.","story.map8-dungeon2.006":"Balai Summoner pasti benar-benar serius sampai mengirimmu sejauh ini.","story.map8-dungeon2.007":"Tapi tetap saja, <wait=20>aku tidak berniat mengalah.","story.map8-dungeon2.008":"Pengawal Kekaisaran akan merebut kekuatan yang tersembunyi di Lizeria.","story.map8-dungeon2.009":"Hehe, <wait=40>tidak perlu memasang wajah seperti itu. ","story.map8-dungeon2.010":"Aku sudah melihat kemampuanmu yang sebenarnya di Cordelica. ","story.map8-dungeon2.011":"Kenapa tidak tinggalkan saja kelompok Akras itu dan bergabung dengan kami?","story.map8-dungeon2.012":"Untuk membangun perdamaian sejati, kamu harus lepas dari kendali para tetua!","story.map8-dungeon2.013":"Ngomong apa kamu, <wait=40>dasar anjing kekaisaran!","story.map8-dungeon2.014":"Apa pun yang kamu katakan pada <rep_handlename> itu percuma.","story.map8-dungeon2.015":"Suara kasar itu...","story.map8-dungeon2.016":"Lama tidak bertemu...","story.map8-dungeon2.017":"Nona Pengawal Kekaisaran.","story.map8-dungeon2.018":"Aku terkejut. <wait=40>Bagaimana caramu sampai ke sini?","story.map8-dungeon2.019":"Bukan apa-apa, kok.","story.map8-dungeon2.020":"Aku cuma kebetulan Summoner yang dipilih khusus oleh Balai Summoner untuk datang ke sini dan melakukan penelitian.","story.map8-dungeon2.021":"Summoner bertampang bodoh di sana itu cuma turis yang cari sensasi murahan.","story.map8-dungeon2.022":"<rep_handlename> sama sekali nggak tahu apa yang terjadi di sini.","story.map8-dungeon2.023":"Maksudku, kamu nggak membagikan informasi penting ke si tolol ini, kan?","story.map8-dungeon2.024":"Nngh...","story.map8-dungeon2.025":"Lagi pula, <wait=20>yang benar-benar bodoh di sini itu orang-orang di Balai Summoner.","story.map8-dungeon2.026":"Bagaimana bisa mereka mengirim Summoner kelas dua sepertimu ke tempat seperti ini?","story.map8-dungeon2.027":"Itu bukti bahwa mereka sama sekali tidak tahu betapa berharganya wilayah ini.","story.map8-dungeon2.028":"Dan kalau memang begitu, <wait=20>aku tidak akan kesulitan mendapatkan kekuatan yang tersembunyi di sini.","story.map8-dungeon2.029":"Hei! <wait=40>Jaga mulutmu!","story.map8-dungeon2.030":"Kamu nggak bakal punya peluang melawanku kalau aku mengerahkan seluruh kekuatanku!","story.map8-dungeon2.031":"Hehe, <wait=40>ekspresimu menarik sekali.","story.map8-dungeon2.032":"Tapi sungguh, <wait=20>kamu tidak perlu berlagak tangguh.","story.map8-dungeon2.033":"Lagi pula aku tidak punya waktu untuk bermain-main denganmu. ","story.map8-dungeon2.034":"Kamu mau kabur?","story.map8-dungeon2.035":"Tidak, <wait=40>aku hanya memilih menghindari pertemuan yang sia-sia demi mencapai tujuanku.","story.map8-dungeon2.036":"<rep_handlename>, <wait=40>pikirkan apa yang kita bicarakan tadi. ","story.map8-dungeon2.037":"Aku yakin itu lebih menguntungkanmu daripada punya sekutu bodoh seperti dia.","story.map8-dungeon2.038":"<size=22>Apa maksudmu!</size>","story.map8-dungeon2.039":"Heh, <wait=40>dia kabur juga akhirnya.","story.map8-dungeon2.040":"Hei! <wait=40><rep_handlename>!","story.map8-dungeon2.041":"Kenapa aku selalu menemukanmu di tempat seperti ini?","story.map8-dungeon2.042":"Maksudmu kamu nggak berniat mendengarkan kata-kataku?","story.map8-dungeon2.043":"Atau jangan-jangan, <wait=20>kamu berencana menerima tawarannya dan mengkhianati Balai Summoner?","story.map8-dungeon2.044":"Yah, apa pun yang kamu lakukan sebenarnya bukan urusanku.","story.map8-dungeon2.045":"Kalau kamu mengabaikan peringatanku lagi, <wait=20>lain kali aku melihatmu...","story.map8-dungeon2.046":"...aku terpaksa membuatmu jadi debu.","story.map8-dungeon2.047":"Heh, <wait=40>merepotkan sekali kamu!","story.map8-dungeon2.048":"Tapi tenang saja, <wait=40>aku nggak sedang mengancammu atau apa.","story.map8-dungeon2.049":"Aku cuma mau kamu tahu kalau aku nggak membiarkan siapa pun menghalangiku!","story.map8-dungeon2.050":"Mengerti?","story.map8-dungeon3.001":"Hei, <wait=40><rep_handlename>.","story.map8-dungeon3.002":"Kelihatannya kamu sedang semangat.","story.map8-dungeon3.003":"Tunggu!","story.map8-dungeon3.004":"Kamu mengabaikan peringatanku dan datang ke sini, berarti kamu berniat mengkhianati Balai Summoner, kan?","story.map8-dungeon3.005":"Syarat apa yang ditawarkan perempuan itu padamu?","story.map8-dungeon3.006":"Hm? <wait=40>Katamu kamu bukan pengkhianat?","story.map8-dungeon3.007":"<size=22>Ha ha ha!</size>","story.map8-dungeon3.008":"Untuk ukuran orang bodoh, pilihanmu menarik juga.","story.map8-dungeon3.009":"Artinya cuma satu...","story.map8-dungeon3.010":"Kamu datang dengan niat merepotkanku, kan?","story.map8-dungeon3.011":"Ha ha ha! <wait=40>Kamu lucu juga!","story.map8-dungeon3.012":"<size=22>Jangan terlalu besar kepala!</size>","story.map8-dungeon3.013":"Perlu kutunjukkan seberapa jauh kamu di bawahku?","story.map8-dungeon3.014":"Dasar tolol.","story.map8-dungeon3.015":"Aku benar-benar nggak tahan sama kamu.","story.map8-dungeon3.016":"Oh iya, aku dengar kamu juga teman si bodoh Karl itu.","story.map8-dungeon3.017":"Sepertinya aku nggak punya pilihan selain memberimu pelajaran dan menunjukkan betapa hebatnya aku.","story.map8-dungeon3.018":"Bagaimana? <wait=20>Aku akan menunggumu di seberang danau beku ini.","story.map8-dungeon3.019":"Aku sendiri yang akan mengajarimu, jadi nantikan saja!","story.map8-dungeon4.001":"T-<wait=20>Tidak mungkin! <wait=40>Itu mustahil.","story.map8-dungeon4.002":"Kamu juga mengalahkan Cardes!?","story.map8-dungeon4.003":"B-<wait=20>Bukan, <wait=40>aku tidak meragukanmu...","story.map8-dungeon4.004":"Baik. <wait=40>Akan kutangani ini dengan sehati-hati mungkin. ","story.map8-dungeon4.005":"Ya. <wait=40>Tidak perlu khawatir soal itu.","story.map8-dungeon4.006":"Aku akan berusaha sebaik mungkin agar tidak mengecewakanmu. ","story.map8-dungeon4.007":"Fiuh... <wait=40>Semuanya terungkap jauh lebih cepat dari dugaanku. ","story.map8-dungeon4.008":"Hm, <wait=20>mungkinkah itu...","story.map8-dungeon4.009":"Hehe, <wait=40>jadi kita bertemu lagi.","story.map8-dungeon4.010":"Jadi kamu sudah mengalahkan Lugina?","story.map8-dungeon4.011":"Mengalahkan Summoner selemah itu tentu bukan masalah bagimu, yang sudah mengalahkan dua dari Empat Dewa yang Jatuh, bukan?","story.map8-dungeon4.012":"Hehe, <wait=20>jangan menatapku seperti itu.","story.map8-dungeon4.013":"Aku paham betapa jauh lebih kuatnya kamu dibanding dia.","story.map8-dungeon4.014":"Jadi, <wait=20>biar kutanya sekali lagi.","story.map8-dungeon4.015":"Maukah kamu meninggalkan Balai Summoner Akras dan bekerja bersama kami?","story.map8-dungeon4.016":"Terakhir kali kita tidak sempat bicara karena diganggu dengan kasar. ","story.map8-dungeon4.017":"Tapi aku serius.","story.map8-dungeon4.018":"Hehe, <wait=20>wajar saja undangan mendadak seperti ini membuatmu bingung. ","story.map8-dungeon4.019":"Biar kuberitahu satu hal. <wait=40>Sistem pemerintahan di Elgaia sudah rusak. ","story.map8-dungeon4.020":"Dan hanya kami yang bisa memperbaikinya.","story.map8-dungeon4.021":"Kamu juga bisa melihat apa yang terjadi, kan?","story.map8-dungeon4.022":"Alih-alih sebuah republik, dunia ini dijalankan oleh organisasi para Summoner. ","story.map8-dungeon4.023":"Dahulu kala, <wait=20>ada segelintir orang yang selamat dari bentrokan tragis dengan para dewa.","story.map8-dungeon4.024":"Mereka memimpin rakyat dan mendirikan Kekaisaran Randall. ","story.map8-dungeon4.025":"Lalu, <wait=20>lama setelah kekaisaran itu berdiri...","story.map8-dungeon4.026":"...beberapa kelompok terbentuk untuk menentang kaum istimewa Kekaisaran Randall.","story.map8-dungeon4.027":"Mereka membentuk Federasi Elgaia.","story.map8-dungeon4.028":"Baru-baru ini, Elgaia-lah yang pertama mulai berubah. ","story.map8-dungeon4.029":"Dalam perubahan itu para Summoner muncul, <wait=20>juga seseorang yang ingin menyatukan mereka semua. ","story.map8-dungeon4.030":"Mereka membentuk Balai Summoner Akras.","story.map8-dungeon4.031":"Para Summoner Zaman Dulu yang mendirikan Balai Summoner Akras...","story.map8-dungeon4.032":"...yang juga dikenal sebagai \\"Summoner Pertama\\" karena merekalah yang pertama kali melewati gerbang...","story.map8-dungeon4.033":"...dengan memakai kekuatan pemanggilan luar biasa yang mereka peroleh...","story.map8-dungeon4.034":"...mendirikan salah satu organisasi terbesar di seluruh Elgaia. ","story.map8-dungeon4.035":"Dengan kekuatan besar para Summoner, organisasi ini perlahan juga menguasai perekonomian.","story.map8-dungeon4.036":"Tanpa ada yang menyadarinya, republik itu tinggal cangkang kosong dari dirinya yang dulu. ","story.map8-dungeon4.037":"Kini, Kekaisaran Randall maupun Federasi Elgaia tak lebih dari kerangka kosong.","story.map8-dungeon4.038":"Hehe, <wait=40>dari raut wajahmu, sepertinya kamu sudah memahami hal ini.","story.map8-dungeon4.039":"Namun, <wait=40>sepertinya kamu tidak mempermasalahkannya.","story.map8-dungeon4.040":"Tentu saja, <wait=20>siapa yang menguasai apa memang tidak ada hubungannya dengan orang biasa. ","story.map8-dungeon4.041":"Tapi dunia ini tidak boleh dianggap remeh. ","story.map8-dungeon4.042":"Aku penasaran apakah kamu masih akan berdiri di pihak Balai Summoner kalau kamu tahu sisi gelap mereka.","story.map8-dungeon4.043":"Kalau kamu berjanji mulai sekarang berpihak pada kami, akan kuceritakan semuanya.","story.map8-dungeon4.044":"Hehe, <wait=20>tapi tidak perlu terburu-buru.","story.map8-dungeon4.045":"Karena apa pun yang terjadi, begitu aku mendapatkan kekuatan yang tersembunyi di sini...","story.map8-dungeon4.046":"...kamu tidak akan punya pilihan selain mengikuti kami di jalan kebenaran.","story.map8-dungeon4.047":"......","story.map8-dungeon4.048":"Nah, <wait=40>aku harus pergi.","story.map8-dungeon4.049":"Aku menantikan bicara denganmu lagi, tanpa diganggu si bodoh kasar itu.","story.map8-dungeon5.001":"<rep_handlename>.","story.map8-dungeon5.002":"Hei, <wait=40>kamu kenapa tiba-tiba begini?","story.map8-dungeon5.003":"Jangan-jangan kamu pikir kamu lebih kuat dariku di pertarungan terakhir itu? ","story.map8-dungeon5.004":"Sepertinya kamu belum sadar betapa aku mengalah padamu waktu itu. ","story.map8-dungeon5.005":"Kelihatannya kamu perlu diingatkan.","story.map8-dungeon5.006":"Hah? <wait=40>Apa aku tahu soal sisi gelap Balai Summoner?","story.map8-dungeon5.007":"Dasar bodoh, <wait=20>cerita gila macam apa yang sudah dijejalkan perempuan itu ke kepalamu?","story.map8-dungeon5.008":"Sudah kubilang jangan dengarkan perempuan itu!","story.map8-dungeon5.009":"Lagi pula, apa yang dilakukan Balai Summoner nggak ada hubungannya dengan kita.","story.map8-dungeon5.010":"Pada dasarnya, yang benar-benar penting cuma siapa yang paling kuat di Elgaia.","story.map8-dungeon5.011":"Apakah Federasi Elgaia dengan rakyatnya yang bersemangat?","story.map8-dungeon5.012":"Atau Kekaisaran Randall dengan militernya yang kuno?","story.map8-dungeon5.013":"Atau mungkin bukan keduanya.","story.map8-dungeon5.014":"Tapi menurutku, Balai Summoner Akras-lah yang terkuat.","story.map8-dungeon5.015":"Elite Balai Summoner adalah elite Elgaia.","story.map8-dungeon5.016":"Cuma itu intinya.","story.map8-dungeon5.017":"Makanya aku harus berusaha sebaik mungkin demi Balai Summoner. ","story.map8-dungeon5.018":"Tapi kamu terus menghalangiku saat aku sedang bekerja keras, dan itu mulai bikin aku kesal.","story.map8-dungeon5.019":"Makanya hari ini aku nggak akan bersikap lunak padamu.","story.map8-dungeon5.020":"Aku akan menunggumu di depan.","story.map8-dungeon5.021":"<size=20>Akan kutunjukkan seberapa beda kita!</size>","story.map8-dungeon5.022":"<size=20>Sebaiknya kamu bersiap!</size>","story.map8-dungeon6.001":"<rep_handlename>. <wait=40>Jadi kamu datang.","story.map8-dungeon6.002":"Lihat. <wait=40>Luar biasa, bukan?","story.map8-dungeon6.003":"Dahulu kala, tempat ini adalah rumah Republik La Veda, tempat orang-orang berdoa kepada Dewa Cahaya.","story.map8-dungeon6.004":"Namun, <wait=20>orang-orang itu justru dihancurkan oleh dewa yang mereka sembah.","story.map8-dungeon6.005":"Pemandangan yang mengerikan. ","story.map8-dungeon6.006":"Ada berbagai catatan tentang pertempuran melawan para dewa.","story.map8-dungeon6.007":"Yang paling utama adalah legenda Enam Pahlawan. ","story.map8-dungeon6.008":"Namun, <wait=20>masih banyak yang belum diketahui.","story.map8-dungeon6.009":"Terutama, <wait=20>hanya sedikit yang diketahui tentang apa yang terjadi di Grand Gaia...","story.map8-dungeon6.010":"...setelah Lucius menyelamatkan umat manusia. ","story.map8-dungeon6.011":"Apa sebenarnya yang dilakukan Lucius...","story.map8-dungeon6.012":"...saat Empat Dewa yang Jatuh melakukan begitu banyak kekejaman?","story.map8-dungeon6.013":"Dan kenapa pemimpin agung para dewa, Carna Masta, belum bergerak juga?","story.map8-dungeon6.014":"Hehe, <wait=20>memikirkan itu benar-benar membuat kita khawatir seberapa aman kita sebenarnya.","story.map8-dungeon6.015":"Aku...","story.map8-dungeon6.016":"Bukan, <wait=20>kami hidup dalam ketakutan akan situasi saat ini.","story.map8-dungeon6.017":"Di masa yang penuh ketidakpastian seperti ini...","story.map8-dungeon6.018":"...siapa yang tahu kapan para dewa akan kembali memutuskan untuk menghancurkan dan membidik Elgaia?","story.map8-dungeon6.019":"Karena itulah kami harus mendapatkan kekuatan besar yang bersemayam di sini.","story.map8-dungeon6.020":"Kekuatan yang konon bersemayam di tanah tempat orang-orang dulu menyembah Dewa Cahaya.","story.map8-dungeon6.021":"Hehe, <wait=40>lagi-lagi kamu memasang wajah bingung itu.","story.map8-dungeon6.022":"Tidak perlu terburu-buru. <wait=40>Silakan luangkan waktu untuk memahami semua ini.","story.map8-dungeon6.023":"Tapi, <wait=20>aku juga ingin kamu memikirkan ke depan.","story.map8-dungeon6.024":"Manakah jalan yang benar untuk menciptakan dunia tempat orang-orang bisa hidup damai?","story.map8-dungeon6.025":"Nah, <wait=20>aku harus pergi.","story.map8-dungeon6.026":"Oh, <wait=20>dan satu hal lagi...","story.map8-dungeon6.027":"Barusan aku melihat Lugina menuju jembatan hitam di depan sana dengan wajah yang sangat mengancam.","story.map8-dungeon6.028":"Hati-hati, ya?","story.map8-dungeon6.029":"Hehehe.","story.map8-dungeon7-2.001":"T-<wait=40>Tidak mungkin...","story.map8-dungeon7-2.002":"Bagaimana mungkin aku kalah dari...","story.map8-dungeon7-2.003":"Nngh...","story.map8-dungeon7-2.004":"<size=18>Ini nggak mungkin benar...</size>","story.map8-dungeon7-2.005":"<size=24>Aku menolak menerimanya!</size>","story.map8-dungeon7-2.006":"Nggak mungkin aku kalah darimu!","story.map8-dungeon7-2.007":"Mustahil...","story.map8-dungeon7-2.008":"<size=20>Nggak! <wait=40>Nggak! <wait=40>Nggak!","story.map8-dungeon7-2.009":"<size=18>Bagaimana bisa aku kalah...</size>","story.map8-dungeon7-2.010":"Hmph, <wait=40>apa yang kamu lihat?","story.map8-dungeon7-2.011":"Pergi sana!","story.map8-dungeon7-2.012":"<size=20>Sialan kamu!!</size>","story.map8-dungeon7-2.013":"Sial...","story.map8-dungeon7.001":"Aku sudah muak menunggu, <rep_handlename>.","story.map8-dungeon7.002":"Aku yakin kamu bakal lewat sini.","story.map8-dungeon7.003":"Benda yang diincar perempuan itu dan aku ternyata ada di menara di depan sana.","story.map8-dungeon7.004":"<size=20>Argh!</size>","story.map8-dungeon7.005":"Wajah menyebalkan itu lagi!","story.map8-dungeon7.006":"Meski wajahmu kelihatan nggak peduli, kamu sama saja seperti dia, rasa penasaranmu menghalangiku.","story.map8-dungeon7.007":"Dengan ketidaktahuanmu itu, kamu benar-benar berniat merebut trofiku?","story.map8-dungeon7.008":"Kamu benar-benar mulai bikin aku kesal.","story.map8-dungeon7.009":"Misi ini kesempatanku untuk menunjukkan kekuatan sejatiku pada para tua bangka itu.","story.map8-dungeon7.010":"Aku nggak bisa membiarkan pemula sepertimu menghalangiku!","story.map8-dungeon7.011":"Aku nggak akan membiarkan prestasi ini jatuh ke tangan orang lain!","story.map8-dungeon7.012":"Akan kuhancurkan siapa pun yang menghalangiku!","story.map8-dungeon7.013":"Nngh, <wait=20>kenapa wajahmu begitu! Jangan takut sekarang!","story.map8-dungeon7.014":"Terserahlah.","story.map8-dungeon7.015":"Ini peringatan terakhirku.","story.map8-dungeon7.016":"Lain kali aku bertemu denganmu...","story.map8-dungeon7.017":"<size=22>Itulah akhir hidupmu!</size>","story.map8-dungeon7.018":"<size=22>Paham?</size>","story.map8-dungeon8.001":"Nngh...","story.map8-dungeon8.002":"Ini di luar dugaan, <wait=20>aku tidak menyangka akan sesulit ini.","story.map8-dungeon8.003":"Tapi tetap saja, <wait=20>luka-luka kecil ini tidak akan membuatku menyerah!","story.map8-dungeon8.004":"Aku harus menemukan gerbang itu demi Eriole.","story.map8-dungeon8.005":"Hei! <wait=40><rep_handlename>!","story.map8-dungeon8.006":"Aku tidak percaya kamu berhasil menyusulku.","story.map8-dungeon8.007":"Karena kamu ada di sini, berarti kamu berhasil mengalahkan Lugina, kan?","story.map8-dungeon8.008":"Dia mungkin agak kasar, <wait=20>tapi sebagai pemimpin Pembasmi Iblis, dia lebih dari sekadar tangguh. ","story.map8-dungeon8.009":"Kamu pasti benar-benar kuat sampai bisa mengalahkannya.","story.map8-dungeon8.010":"Nngh...","story.map8-dungeon8.011":"Hehe, <wait=20>luka ini bukan apa-apa, tidak perlu khawatir. ","story.map8-dungeon8.012":"Hanya ada sedikit masalah tadi. ","story.map8-dungeon8.013":"Sekarang lebih dari sebelumnya, tujuanku adalah mendapatkan kekuatan tersembunyi yang menanti di sini. ","story.map8-dungeon8.014":"Bahkan kamu pun tidak akan kubiarkan menghalangiku. ","story.map8-dungeon8.015":"Haha, <wait=40>ekspresimu menakutkan sekali.","story.map8-dungeon8.016":"Tapi tetap saja, <wait=20>aku serius.","story.map8-dungeon8.017":"Aku percaya kekuatan yang bersemayam di sini bisa mengembalikan dunia seperti seharusnya. ","story.map8-dungeon8.018":"Kamu tahu apa yang menanti kita di sini?","story.map8-dungeon8.019":"Sebuah menara yang konon sudah ada bahkan sebelum La Veda didirikan. ","story.map8-dungeon8.020":"La Veda mungkin bahkan dibangun untuk mengawasi menara itu.","story.map8-dungeon8.021":"Dengan kata lain, <wait=40>apa yang menanti kita di sini teramat penting. ","story.map8-dungeon8.022":"Mungkin juga ada jebakan yang tak terhitung jumlahnya yang dipasang untuk melindunginya. ","story.map8-dungeon8.023":"Kamu mengerti maksudku?","story.map8-dungeon8.024":"Kalau mengerti, <wait=40>sebaiknya kamu tidak maju lebih jauh lagi. ","story.map8-dungeon8.025":"Kamu tidak mau sampai bertarung denganku, bukan?","story.map8-dungeon8.026":"Hehehe.","story.map8-dungeon8.027":"Kuharap kamu mau mengikuti saranku dan berbalik. ","story.map8-dungeon8.028":"Nah, <wait=40>aku pergi dulu. ","story.map8-dungeon8.029":"Kita akan bicara lagi setelah aku berhasil menyelesaikan tujuanku.","story.map8-dungeon8.030":"Jangan kira aku sudah menyerah membujukmu untuk berpihak pada kami.","story.map8-dungeon8.031":"Hehehe.","story.map8-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map8-dungeon_ex_clear.002":"Tuan! <wait=40>Anda baik-baik saja?","story.map8-dungeon_ex_clear.003":"*Huh* <wait=20>Syukurlah.","story.map8-dungeon_ex_clear.004":"Petugas dari Balai Summoner menyelidiki danau bawah tanah itu lebih lanjut setelah Anda pergi.","story.map8-dungeon_ex_clear.005":"Sepertinya dewa Lagzal sedang beristirahat di sana.","story.map8-dungeon_ex_clear.006":"Dia juga muncul di Grand Gaia saat pertempuran besar antara para dewa dan manusia.","story.map8-dungeon_ex_clear.007":"Menurut catatan kami, dia awalnya dikalahkan oleh seorang pahlawan seorang diri.","story.map8-dungeon_ex_clear.008":"Namun, sepertinya dia tidak sepenuhnya musnah, dan malah mundur ke sini.","story.map8-dungeon_ex_clear.009":"Jantung saya serasa berhenti saat kami menemukan informasi ini.","story.map8-dungeon_ex_clear.010":"Maksud saya, dia sudah merenggut nyawa begitu banyak orang dalam pertempuran!","story.map8-dungeon_ex_clear.011":"Saya sangat khawatir begitu tahu Anda akan menghadapinya...","story.map8-dungeon_ex_clear.012":"......","story.map8-dungeon_ex_clear.013":"Sudah terlambat untuk minta maaf!","story.map8-dungeon_ex_clear.014":"......","story.map8-dungeon_ex_clear.015":"*Huh* <wait=40>Tapi Anda memang seorang Summoner.","story.map8-dungeon_ex_clear.016":"Mulai sekarang Anda akan menyelidiki tempat-tempat yang makin berbahaya.","story.map8-dungeon_ex_clear.017":"Kalau saya sungguh ingin mendukung Anda, saya tidak seharusnya mencoba menghentikan Anda.","story.map8-dungeon_ex_clear.018":"Baiklah!","story.map8-dungeon_ex_clear.019":"Saya percaya pada Anda, Tuan!","story.map8-dungeon_ex_clear.020":"Dan Anda selalu bisa mengandalkan saya, Tuan!","story.map8-dungeon_ex_clear.021":"Hehehe.","story.map8-dungeon_ex_clear.022":"Baiklah kalau begitu, saya akan menghubungi Anda bila ada informasi baru!","story.map8-dungeon_ex_clear.023":"Tolong jaga diri Anda sampai saat itu!","story.map8-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map8-dungeon_ex_open.002":"Tuan, <wait=40>Anda bisa mendengar saya?","story.map8-dungeon_ex_open.003":"Bagus, <wait=20>kali ini langsung tersambung.","story.map8-dungeon_ex_open.004":"Saya Lin Merylham dari Dukungan Logistik...","story.map8-dungeon_ex_open.005":"...Biro Investigasi Kantor Survei Grand Gaia, siap melayani Anda.","story.map8-dungeon_ex_open.006":"<rep_handlename>, sebagai anggota Pasukan Summoner Balai Summoner Akras...","story.map8-dungeon_ex_open.007":"...hari ini kami meminta Anda menyelidiki Danau Bawah Tanah Golzo!","story.map8-dungeon_ex_open.008":"Beberapa hari lalu, Balai Summoner merasakan lenyapnya sebuah kekuatan besar di Lizeria.","story.map8-dungeon_ex_open.009":"Lalu tak lama setelah itu, kami merasakan kekuatan yang lebih besar lagi di danau bawah tanah ini.","story.map8-dungeon_ex_open.010":"Kami ingin Anda menyelidiki apa sebenarnya yang terjadi di sini.","story.map8-dungeon_ex_open.011":"Terus terang perasaan saya sangat tidak enak soal ini, jadi tidak apa-apa kalau Anda ingin menolak...","story.map8-dungeon_ex_open.012":"...tapi nada suara Anda berkata lain.","story.map8-dungeon_ex_open.013":"Penuh ambisi seperti biasa!","story.map8-dungeon_ex_open.014":"Baiklah!","story.map8-dungeon_ex_open.015":"Walaupun khawatir, saya akan mendukung Anda seperti biasa!","story.map8-dungeon_ex_open.016":"Jadi tolong, <wait=40>kembalilah dengan selamat!","story.map8-dungeon_ex_open.017":"Mengerti?","story.map8-dungeon_ex_open.018":"Hmph...","story.map8-ending.001":"Bisa menumbangkan sistem pertahanan seperti itu...","story.map8-ending.002":"Kurasa memang beginilah kekuatan orang yang sudah mengalahkan Dewa yang Jatuh.","story.map8-ending.003":"Tapi tetap saja, <wait=20>aku tidak akan menyerahkan apa yang tersegel di balik gerbang di depan!","story.map8-ending.004":"Lihat dirimu, <rep_handlename>.","story.map8-ending.005":"Lukamu bahkan nggak terlalu parah, tapi kamu masih nggak bisa bergerak?","story.map8-ending.006":"Cih, <wait=40>kesal sekali rasanya mengingat aku sampai kerepotan menghadapimu.","story.map8-ending.007":"Hah? <wait=40>Apa maksudmu, cepat ke depan?","story.map8-ending.008":"Heh, <wait=20>kamu belum diberi tahu apa-apa, ya?","story.map8-ending.009":"Ikut aku.","story.map8-ending.010":"Ayo kita lihat masalah menarik macam apa yang menimpa perempuan itu.","story.map8-ending.011":"T-<wait=20>Tunggu. <wait=20>Bagaimana mungkin tidak ada apa-apa?","story.map8-ending.012":"Apa ini berarti kami ditipu?","story.map8-ending.013":"Bagaimana bisa kami...","story.map8-ending.014":"Apa untungnya menuntun kami seperti itu?","story.map8-ending.015":"Hei, <rep_handlename>! <wait=40>Lihat!","story.map8-ending.016":"Persis seperti yang kubilang.","story.map8-ending.017":"Nona Pengawal Kekaisaran kecil kita sepertinya sedang dalam sedikit masalah. ","story.map8-ending.018":"Lugina...","story.map8-ending.019":"Heh he he. <wait=40>Berhentilah pasang wajah seram begitu.","story.map8-ending.020":"Kekuatan yang kamu cari itu nggak ada di sekitar sini. ","story.map8-ending.021":"Kekuatan itu ada di reruntuhan gerbang. ","story.map8-ending.022":"Aku tahu karena aku dikirim oleh para Summoner Tetua untuk menyelidikinya.","story.map8-ending.023":"Tapi aku menikmati mendengar ocehanmu yang menggebu-gebu itu. ","story.map8-ending.024":"Dasar dungu kasar.","story.map8-ending.025":"<size=20>Bwa ha ha ha!</size>","story.map8-ending.026":"Melotot sesukamu saja, gerbangnya nggak bakal terbuka.","story.map8-ending.027":"Nngh...","story.map8-ending.028":"<rep_handlename>.","story.map8-ending.029":"Bagaimana kamu tahan berada di dekat pria sekasar ini begitu lama?","story.map8-ending.030":"Kamu mengerti maksudku, kan?","story.map8-ending.031":"Pria ini benar-benar sampah!","story.map8-ending.032":"Aku hanya menunggu hari kamu menerima undanganku.","story.map8-ending.033":"Ooh, <wait=20>aku iri sekali! <wait=40>Aku juga mau diundang, tahu!","story.map8-ending.034":"Yah, sayang juga kalau waktuku terbuang untuk perjuanganmu yang sia-sia itu. ","story.map8-ending.035":"Nngh.","story.map8-ending.036":"Ingat ini.","story.map8-ending.037":"Suatu hari aku akan membuatmu menyesali semua perbuatanmu.","story.map8-ending.038":"Heh, <wait=20>akhirnya dia pergi juga.","story.map8-ending.039":"Hei, <rep_handlename>.","story.map8-ending.040":"Kenapa kamu tiba-tiba kelihatan tenang begitu?","story.map8-ending.041":"Kamu nggak mengira aku sudah memaafkanmu, kan?","story.map8-ending.042":"Aku bakal jadi jauh lebih kuat daripada sebelumnya. ","story.map8-ending.043":"Dan begitu itu terjadi, aku bakal memanfaatkanmu sebisa mungkin.","story.map8-ending.044":"Jangan lupa itu!","story.map8-ending.045":"Heh.","story.map8-ending.046":"Oh, <wait=20>dan satu hal lagi...","story.map8-ending.047":"Sepertinya kamu benar-benar nggak tahu apa yang kami incar kali ini. ","story.map8-ending.048":"Awalnya kukira kamu cuma berusaha menipuku supaya bisa mendahuluiku. ","story.map8-ending.049":"Tapi ternyata kamu memang sebodoh kelihatannya!","story.map8-ending.050":"<size=20>Bwa ha ha ha!</size>","story.map8-ending.051":"Prestasi berikutnya akan jadi milikku.","story.map8-ending.052":"Dan sebaiknya kamu berterima kasih atas semua yang sudah kulakukan untukmu, aku, Summoner terkuat yang masih hidup!","story.map8-ending.053":"Begitu, <wait=20>jadi gerbangnya sudah lenyap.","story.map8-ending.054":"Tidak apa-apa. <wait=20>Tidak perlu minta maaf. ","story.map8-ending.055":"Kamu sudah berusaha sebaik mungkin dalam tugas yang sulit.","story.map8-ending.056":"Ya, <wait=20>berhati-hatilah dan kembalilah dengan selamat.","story.map8-ending.057":"Hehehe.","story.map8-ending.058":"Sepertinya semuanya persis seperti yang Anda katakan. ","story.map8-ending.059":"Sepertinya kontraknya sudah selesai.","story.map8-ending.060":"Sudah waktunya kami bergerak juga. ","story.map8-ending.061":"Ya, <wait=40>tuanku juga menantikan kedatangan pasukan Anda. ","story.map8-ending.062":"Hehehe.","story.map8-ending.063":"<size=20>Mari kembalikan dunia ke wujud sejatinya!</size>","story.map8-ending.064":"<size=20>Kita akan melihatnya berubah dan berevolusi di depan mata kita!</size>","story.map8-ending.065":"<size=20>Tunggu dan lihat saja!</size>","story.map8-ending.066":"<size=20>Sebentar lagi pahlawan baru akan lahir!</size>","story.map8-open.001":"Randall,<wait=40> ibu kota Kekaisaran Randall.","story.map8-open.002":"Ruang pribadi para pengawal keluarga kekaisaran, <wait=40>Pengawal Kekaisaran.","story.map8-open.003":"*Tok* <wait=20>*tok*","story.map8-open.004":"Masuk.","story.map8-open.005":"Permisi.","story.map8-open.006":"Oh, <wait=40> wajahmu tampak senang sekali. <wait=20>Kurasa kamu membawa kabar baik untukku?","story.map8-open.007":"Ya, <wait=20>dan saya mohon maaf karena butuh waktu begitu lama. ","story.map8-open.008":"Penyelidikan kami menunjukkan bahwa gerbang yang kita cari ada di Lizeria.","story.map8-open.009":"...Lizeria.","story.map8-open.010":"Kalau tidak salah ingat, dulu La Veda konon pernah berdiri di sana.","story.map8-open.011":"Begitu. <wait=20>Sepertinya kita memang tidak dibohongi.","story.map8-open.012":"Benar.","story.map8-open.013":"Meski saya ragu semua informasi yang kita terima akurat, saya rasa setidaknya yang ini benar. ","story.map8-open.014":"......","story.map8-open.015":"Saya ingin pergi ke sana untuk memastikannya sendiri.","story.map8-open.016":"Bolehkah saya mendapat izin untuk itu?","story.map8-open.017":"Setahuku, Pasukan Summoner sudah memulai penyelidikan baru di wilayah itu.","story.map8-open.018":"Baik. <wait=40>Saya akan berusaha menyelesaikannya secepat mungkin. ","story.map8-open.019":"Ini tugas yang cukup berbahaya, kamu tahu?","story.map8-open.020":"Saya rela mengorbankan diri demi perdamaian sejati. ","story.map8-open.021":"Aku mengandalkanmu.","story.map8-open.022":"Anda tidak perlu berkata begitu.","story.map8-open.023":"Saya pastikan semuanya akan beres!","story.map8-open.024":"Semoga berhasil.","story.map8-open.025":"Siapa di sana!?","story.map8-open.026":"Sepertinya ada yang ingin kamu katakan.","story.map8-open.027":"Kamu menguping? <wait=40>Kenapa tidak keluar saja?","story.map8-open.028":"......","story.map8-open.029":"Begitu. <wait=40>Kamu bahkan tidak perlu mengatakannya.","story.map8-open.030":"Tidak ada waktu untuk disia-siakan. <wait=20>Kita harus mengembalikan dunia ke wujud yang semestinya.","story.map8-open.031":"Aku penasaran apakah orang-orang Pasukan Summoner itu akan pernah menyadarinya...","story.map8-open.032":"...Bagaimana dunia ini sebenarnya seharusnya.","story.map9-dungeon1.001":"Hei, <wait=20><rep_handlename>!","story.map9-dungeon1.002":"Jadi kamu juga datang ke Ryvern, <wait=20>gerbang masuk Wilayah Agni. ","story.map9-dungeon1.003":"Kurasa kamu mengejar Zevalhua, <wait=20>Dewa yang Jatuh berikutnya. ","story.map9-dungeon1.004":"Tentu saja kali ini kami akan membantumu lagi, jadi seharusnya nggak ada masalah!","story.map9-dungeon1.005":"Karl! <wait=40>Kita punya tujuan sendiri, ingat!?","story.map9-dungeon1.006":"Aku sama sekali nggak ingin membantu <rep_handlename>, <wait=20>apalagi Balai Summoner bahkan nggak pernah meminta kita.","story.map9-dungeon1.007":"Haha, <wait=20>kamu masih sama seperti biasa ya, Seria.","story.map9-dungeon1.008":"<rep_handlename> sudah mengalahkan dua dari Empat Dewa yang Jatuh. ","story.map9-dungeon1.009":"Bukankah setidaknya kamu harus mengakui itu?","story.map9-dungeon1.010":"Hmph, <wait=20>aku mengakui kekuatan yang dibutuhkan untuk itu.","story.map9-dungeon1.011":"Tapi lihat saja wajah sombongnya itu!","story.map9-dungeon1.012":"Aku cuma memberi peringatan, <wait=20>itu saja!","story.map9-dungeon1.013":"<rep_handlename>! <wait=20>Kamu harus berterima kasih padaku!","story.map9-dungeon1.014":"Ah! <wait=20>Ternyata kamu di sini!","story.map9-dungeon1.015":"<rep_handlename>! <wait=20>Kenapa lama sekali?","story.map9-dungeon1.016":"Oh, <wait=20>Karl dan Seria!","story.map9-dungeon1.017":"Halo, <wait=20>Dewi.","story.map9-dungeon1.018":"Dia muncul juga akhirnya...","story.map9-dungeon1.019":"Hei, kalian berdua!","story.map9-dungeon1.020":"Kalian berdua akan membantu <rep_handlename> lagi kali ini, kan?","story.map9-dungeon1.021":"Kami sedang mengejar Graham!","story.map9-dungeon1.022":"Jangan pikirkan itu sekarang.","story.map9-dungeon1.023":"Toh dia pasti kabur lagi, <wait=20>jadi kenapa kali ini nggak bantu dari awal saja?","story.map9-dungeon1.024":"Jahat sekali kamu bilang begitu.","story.map9-dungeon1.025":"Dasar kamu!","story.map9-dungeon1.026":"Seru sekali bisa bertualang seperti ini bersama kalian semua.","story.map9-dungeon1.027":"Rasanya seberat apa pun pertarungannya, kita pasti bisa melewatinya, ya kan?","story.map9-dungeon1.028":"Haha, <wait=20>kalau sang Dewi sudah bilang begitu, sepertinya kita nggak punya pilihan.","story.map9-dungeon1.029":"Benar kan, <wait=20>Seria?","story.map9-dungeon1.030":"Kamu gampang sekali dibujuk, Karl...","story.map9-dungeon1.031":"Lagi pula, <wait=20>aku yakin Lord Grahdens pasti akan meminta kita juga, jadi ya sudah, kita bantu. ","story.map9-dungeon1.032":"Ternyata kamu manis juga, Seria!","story.map9-dungeon1.033":"A-<wait=20>Apa-apaan kamu!","story.map9-dungeon1.034":"Aku membantu cuma karena nggak ada pilihan lain.","story.map9-dungeon1.035":"Ha ha ha. <wait=20>Sepertinya keputusan sudah diambil.","story.map9-dungeon1.036":"Jadi, kita semua berjuang bersama, <rep_handlename>!","story.map9-dungeon1.037":"Ayo berusaha sebaik mungkin dan hajar Zevalhua itu!","story.map9-dungeon1.038":"Bagus! <wait=40>Semangat, semuanya!","story.map9-dungeon1.039":"*Hah* <wait=20>Aku masih ragu soal ini...","story.map9-dungeon1.040":"Hmm. <wait=40>Menyedihkan sekali...","story.map9-dungeon2.001":"Hei <rep_handlename>. <wait=40>Kamu agak terlambat. ","story.map9-dungeon2.002":"Sang Dewi baru saja ada di sini tadi.","story.map9-dungeon2.003":"Setelah itu, dia bertengkar dengan Seria, <wait=20>lalu mereka berdua pergi duluan. ","story.map9-dungeon2.004":"Ha ha ha. <wait=40>Mereka berdua <wait=40>jadi makin akrab, ya?","story.map9-dungeon2.005":"Ayo saling membantu supaya kita nggak kalah dari mereka!","story.map9-dungeon2.006":"Betapa menyedihkannya kalian, manusia.","story.map9-dungeon2.007":"Siapa di sana?","story.map9-dungeon2.008":"Tidak perlu takut.","story.map9-dungeon2.009":"Namaku Mare.","story.map9-dungeon2.010":"Aku adalah murid Zevalhua yang Agung.","story.map9-dungeon2.011":"Murid Zevalhua?","story.map9-dungeon2.012":"Jadi kamu datang ke sini untuk membunuh kami? ","story.map9-dungeon2.013":"Lancang sekali kalian menghina Lord Zevalhua seperti itu...","story.map9-dungeon2.014":"Itu hanya bukti lain dari kebodohan kalian. Sungguh menyedihkan...","story.map9-dungeon2.015":"Meski begitu, jangan salah paham.","story.map9-dungeon2.016":"Menghabisi kalian berdua bukanlah hal yang perlu kupertaruhkan dengan namaku.","story.map9-dungeon2.017":"Tujuanku bukan kamu, Summoner, <wait=40>tapi si rambut biru. <wait=40>Aku mengincarmu.","story.map9-dungeon2.018":"Aku yang kamu incar?","story.map9-dungeon2.019":"Apa yang kamu inginkan dariku?","story.map9-dungeon2.020":"Kupikir aku akan berperan sebagai dewa dan mengungkapkan kebenaran padamu. ","story.map9-dungeon2.021":"Kebenaran?","story.map9-dungeon2.022":"Kamu membiarkan dirimu ditipu oleh si bodoh Grahdens, dan kini hidupmu berantakan.","story.map9-dungeon2.023":"Kamu... <wait=60>Sebenarnya apa maumu?","story.map9-dungeon2.024":"Kamu tidak perlu waspada. ","story.map9-dungeon2.025":"Para tetuamulah yang menyerahkanmu ke tangan orang lain tak lama setelah menemukanmu.","story.map9-dungeon2.026":"Masa kecilmu begitu menyedihkan, tak pernah mengenal kehangatan orang tua.","story.map9-dungeon2.027":"Karena itulah kepadamu, yang dipungut oleh para orang tua tak bertanggung jawab itu...","story.map9-dungeon2.028":"...aku, dewa yang penuh belas kasih, akan memberitahukan kebenarannya.","story.map9-dungeon2.029":"Jangan main-main!","story.map9-dungeon2.030":"Apa yang kamu tahu tentang Tetua Grahdens!","story.map9-dungeon2.031":"Sebagai salah satu Tetua Summoner, dia selalu sibuk...","story.map9-dungeon2.032":"...Tapi dia selalu peduli padaku!","story.map9-dungeon2.033":"Dia sama sekali bukan orang seperti yang kamu gambarkan, dasar murid Dewa yang Jatuh!","story.map9-dungeon2.034":"Kamu sama pandainya bersilat lidah seperti Grahdens. ","story.map9-dungeon2.035":"Sepertinya kamu sudah dicuci otak dengan baik. ","story.map9-dungeon2.036":"Diam! <wait=40>Takkan kubiarkan kamu menjelekkannya lagi!","story.map9-dungeon2.037":"Kamu memang bodoh dan tidak tahu apa-apa.","story.map9-dungeon2.038":"Akan kutunjukkan jalannya.","story.map9-dungeon2.039":"Aku akan menunggumu di Reruntuhan Azura di depan sana. ","story.map9-dungeon2.040":"Datanglah sendirian jika kamu ingin tahu kebenarannya.","story.map9-dungeon2.041":"<rep_handlename>, <wait=40>aku berutang segalanya pada Tetua Grahdens.","story.map9-dungeon2.042":"Dia mungkin agak aneh, tapi dia orang yang bisa dipercaya dan aku sangat menyayanginya!","story.map9-dungeon2.043":"Aku nggak bisa memaafkan apa yang dia katakan tentangnya. ","story.map9-dungeon2.044":"Maaf, tapi kamu harus melanjutkan tanpa aku.","story.map9-dungeon2.045":"Aku akan ke Reruntuhan Azura untuk menghadapinya.","story.map9-dungeon2.046":"Kuserahkan Zevalhua padamu!","story.map9-dungeon2.047":"Kumohon, <rep_handlename>, <wait=20>tolonglah!","story.map9-dungeon3.001":"<rep_handlename>!","story.map9-dungeon3.002":"Kamu lihat Karl?","story.map9-dungeon3.003":"Dia menyuruhku jalan duluan waktu kami di Khelne, <wait=20>jadi aku menurut, tapi...","story.map9-dungeon3.004":"Dia kelihatan tenang, <wait=20>tapi kurasa sebenarnya dia sangat marah. ","story.map9-dungeon3.005":"Aku belum pernah melihatnya semarah itu.","story.map9-dungeon3.006":"Hah? <wait=40>Murid Zevalhua muncul dan membicarakan dia dan Lord Grahdens?","story.map9-dungeon3.007":"Begitu ya.","story.map9-dungeon3.008":"Lord Grahdens adalah orang yang sangat penting bagi Karl.","story.map9-dungeon3.009":"Kalian sudah berteman sejak kecil, kan? <wait=40>Kamu tahu seluruh ceritanya, kan?","story.map9-dungeon3.010":"Tetap saja, <wait=40>Karl memang nggak suka membicarakan dirinya sendiri, ya...","story.map9-dungeon3.011":"Kalau saja dia mau cerita apa yang terjadi, <wait=20>mungkin kita bisa membantu.","story.map9-dungeon3.012":"Pokoknya, <wait=20>ayo cepat ke Reruntuhan Azura!","story.map9-dungeon3.013":"Aku yakin Karl baik-baik saja, tapi aku tetap khawatir.","story.map9-dungeon3.014":"Perhatian juga kamu, <wait=40>untuk ukuran cacing sepertimu.","story.map9-dungeon3.015":"Dia sudah menjadi milik kami.","story.map9-dungeon3.016":"Dia tidak akan kembali pada kalian lagi. ","story.map9-dungeon3.017":"Jadi kamu Mare!","story.map9-dungeon3.018":"Manusia bodoh. <wait=40>Apa kalian takut melihat kebenaran?","story.map9-dungeon3.019":"Kalau begitu, kalian juga harus datang.","story.map9-dungeon3.020":"Lihatlah dia sekarang, setelah dia menerima kebenaran.","story.map9-dungeon3.021":"Cukup!","story.map9-dungeon3.022":"Tilith!","story.map9-dungeon3.023":"Hehe, <wait=20>itu pertama kalinya kamu memanggilku dengan namaku.","story.map9-dungeon3.024":"D-<wait=20>Dasar bodoh! <wait=40>Sekarang bukan waktunya untuk itu!","story.map9-dungeon3.025":"Kamu benar. <wait=20>Kita harus melakukan sesuatu soal Mare.","story.map9-dungeon3.026":"Apa urusan dewa rendahan sepertimu denganku?","story.map9-dungeon3.027":"Jahat!","story.map9-dungeon3.028":"Aku ini murid hebat Lord Lucius, tahu!","story.map9-dungeon3.029":"Satu hal lagi, Seria. <wait=20>Jangan sampai tertipu.","story.map9-dungeon3.030":"Mare pandai mengacaukan hati orang lain. ","story.map9-dungeon3.031":"Hanya sedikit kebenaran dalam ucapannya.","story.map9-dungeon3.032":"Apa kamu mampu menentukan mana yang benar dan mana yang tidak?","story.map9-dungeon3.033":"Kamu, <wait=20>yang membabi buta menuruti setiap perkataan Lucius, <wait=20>meminjamkan kekuatanmu kepada manusia dan sebagainya.","story.map9-dungeon3.034":"Kamu mau bilang Lord Lucius salah?","story.map9-dungeon3.035":"Tidak penting. <wait=40>Mau bagaimana lagi kalau berurusan dengan dewa sebodoh itu. ","story.map9-dungeon3.036":"Yang kumaksud itu kamu, tahu.","story.map9-dungeon3.037":"Jika kamu ingin tahu kebenarannya, cukup percayai apa yang kukatakan.","story.map9-dungeon3.038":"Dengan begitu, kamu akan bisa bertemu pria itu sekali lagi. ","story.map9-dungeon3.039":"Tunggu sebentar!","story.map9-dungeon3.040":"Ih! <wait=40>Dia memang semenyebalkan yang kudengar!","story.map9-dungeon3.041":"Seria! <wait=20>Aku yakin Karl baik-baik saja!","story.map9-dungeon3.042":"Jadi jangan bertindak gegabah!","story.map9-dungeon3.043":"Aku tahu. <wait=40>Aku sudah tenang sekarang.","story.map9-dungeon3.044":"Tapi tetap saja, aku khawatir pada Karl.","story.map9-dungeon3.045":"Aku tahu ini mungkin jebakan...","story.map9-dungeon3.046":"...tapi Karl pasti sedang menuju ke sana sekarang.","story.map9-dungeon3.047":"<rep_handlename>, aku ingin kamu membuat keributan sebesar mungkin di sekitar sini.","story.map9-dungeon3.048":"Aku butuh pengalih perhatian supaya bisa cepat menyusul Karl. ","story.map9-dungeon3.049":"Ya, <wait=20>kamu memang kelihatan baik-baik saja!","story.map9-dungeon3.050":"Bahkan caramu pura-pura bersikap kejam pada <rep_handlename> juga cocok sekali denganmu!","story.map9-dungeon3.051":"Aku nggak pura-pura apa-apa!","story.map9-dungeon3.052":"*Hah* <wait=40>Pokoknya, sudahlah.","story.map9-dungeon3.053":"Tilith, <wait=20>lindungi <rep_handlename> untukku.","story.map9-dungeon3.054":"Siapa tahu apa yang akan dilakukan murid bernama Mare itu.","story.map9-dungeon3.055":"Aku nggak bisa membayangkan dia membiarkan begitu saja orang yang sudah mengalahkan dua dari Empat Dewa yang Jatuh.","story.map9-dungeon3.056":"Mengerti. <wait=40>Tapi, <wait=20>tolong jangan bertindak nekat.","story.map9-dungeon3.057":"Jangan khawatirkan aku.","story.map9-dungeon3.058":"Aku nggak selemah itu sampai perlu dikhawatirkan dewi bodoh sepertimu.","story.map9-dungeon3.059":"Masih saja nggak tahu sopan santun ya, Seria!","story.map9-dungeon3.060":"Hehe, <wait=40>pokoknya, aku berangkat.","story.map9-dungeon3.061":"<rep_handlename>, <wait=40>kamu juga jaga dirimu baik-baik, ya?","story.map9-dungeon4.001":"<rep_handlename>...","story.map9-dungeon4.002":"Maafkan aku...","story.map9-dungeon4.003":"Mare...<wait=20> Dia menipu kami...","story.map9-dungeon4.004":"Seria! <wait=40>Kamu nggak apa-apa?","story.map9-dungeon4.005":"Aku...<wait=40>baik-baik saja...","story.map9-dungeon4.006":"Tapi...<wait=20>Karl...","story.map9-dungeon4.007":"Jangan memaksakan diri!","story.map9-dungeon4.008":"Mare...<wait=20>dan Karl...<wait=20>seimbang...","story.map9-dungeon4.009":"Kupikir aku akan mencoba membantu...","story.map9-dungeon4.010":"Tapi, <wait=40>ternyata itu...<wait=20>persis yang dia inginkan...","story.map9-dungeon4.011":"Begitu aku memusatkan perhatianku padanya...","story.map9-dungeon4.012":"Dia memanggil anak buahnya yang bersembunyi. <wait=20>Mereka semua menyerangku sekaligus...","story.map9-dungeon4.013":"Lalu saat aku mencoba menghindari serangan mereka...<wait=20>Mare menyerangku dari belakang...","story.map9-dungeon4.014":"Karl...<wait=20>dia melindungiku <wait=20>dari serangannya...","story.map9-dungeon4.015":"Lalu, <wait=20>saat aku mencoba melindungi Karl yang sudah tumbang, <wait=20>jadilah begini...","story.map9-dungeon4.016":"Seria...","story.map9-dungeon4.017":"Dia berkata padaku...","story.map9-dungeon4.018":"\\"Aku membiarkanmu sebagai pesan untuk <rep_handlename>...","story.map9-dungeon4.019":"...Hanya karena itu aku membiarkanmu hidup.\\"","story.map9-dungeon4.020":"Aku benar-benar bodoh!","story.map9-dungeon4.021":"Bukan cuma terjebak perangkapnya, sekarang malah begini. <wait=20>Bagaimana aku bisa hidup menanggung malu seperti ini. ","story.map9-dungeon4.022":"Aku tetap senang mendengarnya.","story.map9-dungeon4.023":"Senang mendengar apa!","story.map9-dungeon4.024":"Kamu masih hidup, kan? <wait=20>Aku senang kamu masih di sini.","story.map9-dungeon4.025":"Tilith...","story.map9-dungeon4.026":"Dan kalau Karl ditangkap, <wait=20>berarti dia juga masih hidup!","story.map9-dungeon4.027":"<rep_handlename>-ku pasti bisa menyelamatkannya!","story.map9-dungeon4.028":"Aku nggak suka caramu menyebut <rep_handlename> milikmu, <wait=20>dan juga caramu percaya begitu saja...","story.map9-dungeon4.029":"Tapi...<wait=20>kamu benar...","story.map9-dungeon4.030":"Sepertinya Karl ditahan di tempat bernama Menara Putih. ","story.map9-dungeon4.031":"Mare bilang dia akan menunggumu di sana.","story.map9-dungeon4.032":"Ini jelas jebakan.","story.map9-dungeon4.033":"Tapi tetap saja, kumohon cobalah.","story.map9-dungeon4.034":"<size=20><rep_handlename>, <wait=40>selamatkan Karl!</size>","story.map9-dungeon4.035":"Hmph, <wait=20>kenapa kamu cuma mengangguk dan sok keren begitu?","story.map9-dungeon4.036":"Kamu pasti akan menyelamatkannya meski aku nggak bilang apa-apa, kan?","story.map9-dungeon4.037":"Ngh...","story.map9-dungeon4.038":"Seria! <wait=20>Jangan memaksakan diri!","story.map9-dungeon4.039":"<rep_handlename>! <wait=40>Serahkan Seria padaku!","story.map9-dungeon4.040":"Aku akan membawanya pulang dengan selamat ke Elgaia. ","story.map9-dungeon4.041":"Jadi kumohon <rep_handlename>, <wait=20>pergilah selamatkan Karl.","story.map9-dungeon4.042":"Aku dan Seria, <wait=20>kami percaya padamu, <rep_handlename>.","story.map9-dungeon4.043":"Aku nggak terlalu percaya padamu...","story.map9-dungeon4.044":"Seria, <wait=20>nggak apa-apa.","story.map9-dungeon4.045":"<rep_handlename>-ku yang paling kuat!","story.map9-dungeon4.046":"Siapa yang kamu sebut milikmu?","story.map9-dungeon4.047":"Eh, <wait=40>terserahlah...","story.map9-dungeon4.048":"<rep_handlename>...","story.map9-dungeon4.049":"Kumohon...<wait=40>bawa Karl kembali untukku...","story.map9-dungeon5.001":"<rep_handlename>. <wait=40>Aku sudah menunggumu.","story.map9-dungeon5.002":"Kupikir kamu akan lewat sini dalam perjalanan ke Menara Putih.","story.map9-dungeon5.003":"Menara Putih ada di seberang Pegunungan Ryvern, <wait=20>tepat setelah kamu keluar dari gua. ","story.map9-dungeon5.004":"Aku ragu akan mudah melewatinya, bahkan dengan kemampuanmu.","story.map9-dungeon5.005":"Namun, <wait=20>jangan takut. ","story.map9-dungeon5.006":"Aku akan menyelamatkan si muda Karl.","story.map9-dungeon5.007":"Bagaimanapun juga, dia putraku tercinta. ","story.map9-dungeon5.008":"Ho ho ho. <wait=40>Kenapa wajahmu kelihatan ragu begitu?","story.map9-dungeon5.009":"Aku tidak tahu apa yang dikatakan murid bernama Mare itu.","story.map9-dungeon5.010":"Tapi akulah yang mengambil bayi terlantar itu dan membesarkannya seperti anakku sendiri.","story.map9-dungeon5.011":"Meski begitu, <wait=20>memang benar pada akhirnya aku menitipkannya pada kenalan yang bisa dipercaya. ","story.map9-dungeon5.012":"Kehidupan seorang Tetua Summoner terlalu sibuk.","story.map9-dungeon5.013":"Tapi kamu sudah tahu kelanjutan ceritanya, kan?","story.map9-dungeon5.014":"Aku berterima kasih karena kamu selalu bermain dengan Karl waktu kalian masih kecil. ","story.map9-dungeon5.015":"Ho ho ho.","story.map9-dungeon5.016":"Namun, sesibuk apa pun aku...","story.map9-dungeon5.017":"...aku tidak pernah begitu saja meninggalkannya pada orang lain.","story.map9-dungeon5.018":"Sesekali aku menyelinap keluar tanpa ketahuan siapa pun untuk menengoknya. ","story.map9-dungeon5.019":"Aku bisa kena masalah besar kalau ada yang tahu bahwa aku, seorang Tetua Summoner, punya anak.","story.map9-dungeon5.020":"Namun, <wait=20>meski aku harus diam-diam begitu, dia tetap menerimaku.","story.map9-dungeon5.021":"Ho ho ho. <wait=40>Sungguh kenangan lama.","story.map9-dungeon5.022":"Nah, <wait=20>sepertinya aku harus segera berangkat.","story.map9-dungeon5.023":"Menjemput anak yang hilang adalah tanggung jawab orang tuanya.","story.map9-dungeon5.024":"Selain itu, <wait=20>aku harus menghukum orang yang berani menipu putra tersayangku.","story.map9-dungeon5.025":"Ho ho ho. <wait=20>Jangan khawatir.","story.map9-dungeon5.026":"Aku memang sudah tua, <wait=20>tapi mungkin aku masih jauh lebih kuat daripada kalian semua.","story.map9-dungeon5.027":"Lagi pula, <wait=20>seandainya terjadi sesuatu padaku...","story.map9-dungeon5.028":"...aku sudah meminta para Tetua Summoner lainnya untuk menjaga kalian semua. ","story.map9-dungeon5.029":"Ho ho ho. <wait=40>Mungkin aku terlalu berhati-hati?","story.map9-dungeon5.030":"Jangan takut, dan pergilah menuju Zevalhua.","story.map9-dungeon5.031":"Aku yakin Karl juga tidak ingin menghambatmu.","story.map9-dungeon5.032":"Tapi meski begitu, kamu tetap berniat menuju Menara Putih, kan?","story.map9-dungeon5.033":"Karl punya teman-teman yang sungguh baik. ","story.map9-dungeon5.034":"Kalau begitu, <wait=20>aku akan menyelamatkan Karl lalu menunggumu di Menara Putih. ","story.map9-dungeon5.035":"Ho ho ho.","story.map9-dungeon6.001":"Sepertinya tinggal satu sekarang. ","story.map9-dungeon6.002":"Kalian manusia memang makhluk yang bodoh. ","story.map9-dungeon6.003":"Akan kuhancurkan kamu seperti para prajurit bodoh lainnya.","story.map9-dungeon6.004":"<size=20>Takkan kubiarkan itu terjadi!</size>","story.map9-dungeon6.005":"Aku akan melindungi <rep_handlename>!","story.map9-dungeon6.006":"Kamu rupanya...","story.map9-dungeon6.007":"Kamu kembali jauh lebih cepat dari dugaanku.","story.map9-dungeon6.008":"Aku ingin menyebutmu bodoh, <wait=20>tapi apa lagi yang bisa diharapkan dari murid Lucius.","story.map9-dungeon6.009":"Pokoknya...","story.map9-dungeon6.010":"Summoner, <wait=40>aku akan menunggumu di Menara Putih.","story.map9-dungeon6.011":"Temanmu juga akan bersamaku.","story.map9-dungeon6.012":"<rep_handlename>, kamu nggak apa-apa?","story.map9-dungeon6.013":"Kalau kamu khawatir soal Seria, nggak perlu.","story.map9-dungeon6.014":"Aku sudah membawanya pulang dengan selamat ke Elgaia, dan sekarang dia sedang beristirahat dengan tenang di Balai Summoner. ","story.map9-dungeon6.015":"Jadi, <wait=20>ayo kita selamatkan Karl bersama!","story.map9-dungeon6.016":"Kamu dan aku pasti bisa, <wait=20>nggak peduli berapa banyak jebakan yang dipasang Mare!","story.map9-dungeon6.017":"Nggak ada musuh yang nggak bisa kita kalahkan selama kita bersama!","story.map9-dungeon6.018":"Karl! Bertahanlah sedikit lagi!","story.map9-dungeon7.001":"Meskipun terang begini, tempat ini benar-benar bikin merinding.","story.map9-dungeon7.002":"Jangan-jangan ini jebakan Mare yang lain?","story.map9-dungeon7.003":"Aku tidak perlu membuang jebakan berhargaku untuk kalian.","story.map9-dungeon7.004":"Itu suara Mare!","story.map9-dungeon7.005":"Aku sudah menyiapkan lawan untuk kalian.","story.map9-dungeon7.006":"Granvalm, penjaga menara ini. <wait=40>Hancurkan para penyusup ini!","story.map9-dungeon7.007":"<size=20>Kyaaaahh! <wait=40>Lihat naga itu!</size>","story.map9-dungeon7.008":"Dia lawan yang pas untuk sepasang orang bodoh seperti kalian.","story.map9-dungeon7.009":"Tunggu!","story.map9-dungeon7.010":"Aku benar-benar marah sekarang! <wait=40><rep_handlename>, mundur!","story.map9-dungeon7.011":"Ha ha ha...","story.map9-dungeon7.012":"Mereka kabur...","story.map9-dungeon7.013":"Tapi, <wait=20>naga itu kelihatannya berlari kembali untuk melindungi sesuatu...","story.map9-dungeon7.014":"Mungkin dia ingin memastikan Karl nggak kabur.","story.map9-dungeon7.015":"<rep_handlename>!","story.map9-dungeon7.016":"Pasti itu dia!","story.map9-dungeon7.017":"Kejar naga itu, aku nggak apa-apa!","story.map9-dungeon7.018":"Aku cuma perlu istirahat sebentar di sini!","story.map9-dungeon7.019":"Kita harus membuktikan kepercayaan Seria pada kita.","story.map9-dungeon7.020":"Itu bukan masalah bagi <rep_handlename>-ku!","story.map9-dungeon7.021":"Tepati janjimu pada Seria dan selamatkan Karl!","story.map9-ending.001":"Summoner. <wait=40>Rupanya kamu masih berdiri.","story.map9-ending.002":"Tenanglah. <wait=40>Akan kupastikan akhirmu cepat dan tanpa rasa sakit.","story.map9-ending.003":"Setelah kamu, tak akan ada lagi yang mengancam Lord Zevalhua. ","story.map9-ending.004":"Kenapa wajahmu terkejut begitu?","story.map9-ending.005":"Sejak awal, aku memang mengincarmu.","story.map9-ending.006":"Kamu, Summoner yang dipilih Lucius.","story.map9-ending.007":"Sekarang setelah aku melenyapkan semua yang dulu melindungimu...","story.map9-ending.008":"...tak ada lagi yang tersisa untuk menyelamatkanmu.","story.map9-ending.009":"Bahkan si orang tua pun kalah saat berjuang menyelamatkan seseorang yang sejak awal tidak ada di sini.","story.map9-ending.010":"Ditambah lagi, <wait=20>kekuatan dewi bodoh yang menaruh kepercayaannya padamu juga sudah habis.","story.map9-ending.011":"Tidak penting berapa banyak murid yang dikirim Lucius.","story.map9-ending.012":"Mereka pasti sadar, selemah itu, naga putih akan membuat mereka tak berkutik.","story.map9-ending.013":"Dia jadi bodoh karena terlalu lama berada di sekitar kalian manusia.","story.map9-ending.014":"Kalian cacing-cacing manusia sungguh menyedihkan.","story.map9-ending.015":"Kalian mudah terbawa emosi, lalu bertindak sendiri.","story.map9-ending.016":"Meski tahu itu jebakan, kalian bilang demi menyelamatkan teman, sambil menyeret orang lain ke dalam masalah. ","story.map9-ending.017":"Bertindak sendiri saat memikul tanggung jawab sebesar itu hanya akan berujung pada kegagalan. ","story.map9-ending.018":"Lagi pula, <wait=20>mereka yang punya tujuan besar tapi sibuk dengan hal kecil, pada akhirnya akan kehilangan segalanya.","story.map9-ending.019":"Sungguh cara hidup yang bodoh.","story.map9-ending.020":"Kamu pasti tidak ada bedanya.","story.map9-ending.021":"Summoner...","story.map9-ending.022":"Hmph, <wait=40>aku mulai bosan.","story.map9-ending.023":"Aku bicara karena kupikir kamu akan melawan, tapi sepertinya kamu sudah mencapai batasmu.","story.map9-ending.024":"Baiklah. <wait=40>Sepertinya aku harus menghabisimu di sini!","story.map9-ending.025":"<size=20>Hentikan sekarang juga!</size>","story.map9-ending.026":"......","story.map9-ending.027":"......","story.map9-ending.028":"Rupanya kamu masih punya sekutu yang tersisa.","story.map9-ending.029":"Tapi itu tidak penting.","story.map9-ending.030":"Pria yang kamu cari ditahan di ibu kota Agni. ","story.map9-ending.031":"Sebaiknya kamu mengejarnya jika ingin menyelamatkannya.","story.map9-ending.032":"Dan kamu tidak punya waktu untuk menunggu teman-temanmu pulih.","story.map9-ending.033":"Jika kamu menunggu, kamu akan terlambat menyelamatkannya.","story.map9-ending.034":"......","story.map9-ending.035":"Hei <rep_handlename>, <wait=20>jangan cuma berdiri saja!","story.map9-ending.036":"Kita bisa bicara nanti. <wait=40>Sekarang, sebaiknya kita mulai menuju ibu kota Agni.","story.map9-ending.037":"Ada yang ingin kusampaikan padamu setelah kita sampai di sana.","story.map9-ending.038":"Kamu harus berterima kasih padaku!","story.map9-ending.039":"<size=20>Ah ha ha ha!</size>","story.map9-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Akulah Lucius...<br><wait=40>Dewa Gerbang ini...","story.map9-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Krisis yang ditimbulkan oleh Empat Dewa yang Jatuh,<wait=40> masih belum berakhir...","story.map9-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Gunakan kekuatanku <wait=40>dan jelajahilah negeri-negeri baru...","story.map9-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Demi membawa harapan baru ke dunia tanpa tatanan ini...","story.map9-open.005":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Percayalah pada kekuatanmu, <wait=20>dan teruslah melangkah maju...","story.map9-open.006":"<rep_handlename>! <wait=40>Maaf membuatmu menunggu!","story.map9-open.007":"Tapi karena aku selalu menunggumu, <rep_handlename>...","story.map9-open.008":"...kupikir kali ini giliran kamu yang menunggu!","story.map9-open.009":"Apa? <wait=20>Katamu kamu nggak menunggu selama itu?","story.map9-open.010":"Nggak adil!","story.map9-open.011":"Padahal aku berharap kamu setidaknya sampai berkeringat menungguku!","story.map9-open.012":"Tapi ya sudahlah! <wait=40>Yang penting kita harus cepat mengalahkan Dewa yang Jatuh berikutnya!","story.map9-open.013":"Empat Dewa yang Jatuh tinggal separuh!","story.map9-open.014":"Dan berikutnya yang harus kamu tantang adalah...","story.map9-open.015":"...sang kaisar agung Zevalhua yang menguasai Wilayah Agni. ","story.map9-open.016":"Katanya dia bermusuhan dengan Afla Dilith, Dewa yang Jatuh lainnya...","story.map9-open.017":"...tapi dia pasti sudah menyadari kedatangan kita di sini.","story.map9-open.018":"Dia mungkin akan mencoba memasang jebakan untuk kita!","story.map9-open.019":"Tapi kamu nggak mungkin terjebak, kan, <rep_handlename>?","story.map9-open.020":"Baiklah, <wait=20>aku akan menuju Milvana tempat Zevalhua menunggu!","story.map9-open.021":"Randall,<wait=40> ibu kota Kekaisaran Randall.","story.map9-open.022":"Kastel Randall, di dalam ruang pribadi para pengawal keluarga kerajaan, <wait=40>Pengawal Kekaisaran.","story.map9-open.023":"*Tok* <wait=20>*tok*","story.map9-open.024":"Permisi.","story.map9-open.025":"......","story.map9-open.026":"Persiapan untuk menuju Wilayah Agni sudah selesai. ","story.map9-open.027":"Begitukah.","story.map9-open.028":"Kalau begitu, mari kita juga berangkat. ","story.map9-open.029":"Menuju Grand Gaia, negeri yang dikuasai para dewa. ","storylog.category.10000.description":"Berkelana di Grand Gaia bersama teman-teman dan seorang dewi yang perkasa, seorang Summoner menghadapi para iblis dalam pertempuran sengit.","storylog.category.10000.name":"Memoar Grand Gaia","storylog.category.10100.description":"Dipandu Tilith, pelayan dewa Lucius, sang Summoner memulai petualangan besar. Empat Dewa yang Jatuh harus dikalahkan, dimulai dari Maxwell.","storylog.category.10100.name":"Mistral","storylog.category.10101.description":"Pulau yang dulu dihuni para raksasa tampaknya menjadi tujuan berikutnya sang Summoner. Namun, Paris dari Pengawal Kekaisaran juga sedang menuju Cordelica...","storylog.category.10101.name":"Cordelica","storylog.category.10102.description":"Sang Summoner tiba di negeri yang ingin dihancurkan Cardes Sang Keji. Pertempuran baru dimulai di tempat 4 Pahlawan Palmyna yang legendaris dulu berdiri.","storylog.category.10102.name":"Palmyna","storylog.category.10103.description":"Paris tiba di pulau bekas Republik La Veda kuno untuk mencari gerbang yang dirumorkan, tapi Balai Summoner sudah memulai penyelidikan.","storylog.category.10103.name":"Lizeria","storylog.category.10104.description":"Zevalhua yang Agung harus dikalahkan sebelum ia menghancurkan segalanya. Konon ia sedang berseteru dengan Afla Dilith, salah satu dari Empat Dewa yang Jatuh.","storylog.category.10104.name":"Wilayah Agni","storylog.category.11001.description":"Sementara Karl memburu iblis Graham, sang Summoner hendak menantang murid Maxwell, Abaddon. Tapi apakah Abaddon benar-benar bisa dikalahkan?","storylog.category.11001.name":"Morgan","storylog.category.11002.description":"Negeri di bawah kekuasaan Sang Pencipta Maxwell menjadi tujuan baru. Sasarannya adalah benteng Maxwell, Istana St. Lamia, bersama Tilith.","storylog.category.11002.name":"St. Lamia","storylog.category.11010.description":"Sang Summoner mendarat di tempat Kekaisaran Amdahl yang agung dulu berjaya. Tilith berharap perjalanan ini berakhir dengan kekalahan Cardes Sang Keji.","storylog.category.11010.name":"Amdahl","storylog.category.11011.description":"Menurut Tilith, negeri ini dulu menjadi saksi perang saudara antarmanusia. Pertempuran sengit mulai pecah di tengah alam liar.","storylog.category.11011.name":"Encervis","storylog.category.11040.description":"Zevalhua yang Agung menjadi target baru. Tilith khawatir ada sebuah rencana jahat yang sedang berjalan.","storylog.category.11040.name":"Ryvern","storylog.category.11041.description":"Sang Summoner mengunjungi negeri tempat sebuah kekaisaran pernah berdiri megah. Grahdens telah memercayakan penyelamatan Karl kepadamu dan Lugina, tapi...","storylog.category.11041.name":"Agni","storylog.category.11042.description":"Setelah akhirnya mencapai benteng Zevalhua, medan perang lama ini menjadi ajang pertarungan baru untuk menyelamatkan Grahdens yang tertangkap.","storylog.category.11042.name":"Mirvana","storylog.category.20000.description":"Sang Summoner diminta menjelajahi negeri misterius yang baru ditemukan. Namun, musuh yang menunggu di sana jauh lebih kuat dari dugaan...","storylog.category.20000.name":"Wilayah Baru","storylog.scenario.10001.description":"Tilith menjelaskan situasi Grand Gaia di Gua Api. Sang Summoner harus memulai perjalanan panjang untuk mengalahkan Empat Dewa yang Jatuh...","storylog.scenario.10001.title":"Awal Perjalanan","storylog.scenario.10002.description":"Di Padang Salju Egor, Tilith menjelaskan pentingnya Elemen bagi Unit. Petir mengalahkan Air, dan seterusnya... Patut diingat untuk pertarungan berikutnya.","storylog.scenario.10002.title":"Kecocokan Unit","storylog.scenario.10003.description":"Sang Summoner tiba di Hutan Buas, tempat musuh memburu binatang liar sebagai makanan. Penggunaan Sphere juga dijelaskan dengan saksama di sini.","storylog.scenario.10003.title":"Perlengkapan Itu Penting","storylog.scenario.10004.description":"Kelembapan di Rawa Magutagal membuat Tilith kesal, tapi ia tetap menjelaskan Spark yang tercipta dari serangan serempak.","storylog.scenario.10004.title":"Teknik Bertarung","storylog.scenario.10005.description":"Tilith terkesan sang Summoner berhasil mencapai Sisa-sisa Mirza dengan selamat. Sebagai hadiah, ia menjelaskan manfaat Skill Leader.","storylog.scenario.10005.title":"Kepemimpinan","storylog.scenario.10006.description":"Kabarnya seorang pendekar pedang misterius bersembunyi di Sarang Monster. Meski Tilith bersumpah ia tidak takut, ia kelihatan sangat ketakutan...","storylog.scenario.10006.title":"Aku Nggak Takut!","storylog.scenario.10007.description":"Kini di Menara Mistral, pembebasan seluruh wilayah tinggal selangkah lagi. Namun, Sang Pencipta Maxwell telah menciptakan lawan yang mengerikan...","storylog.scenario.10007.title":"Mistral Bebas","storylog.scenario.10008.description":"Sang Summoner berhasil mengalahkan Juggernaut dan mendapat pujian Tilith. Lucius kini akan membuka jalan menuju negeri asing Morgan.","storylog.scenario.10008.title":"Menuju Negeri Baru","storylog.scenario.10009.description":"Mencari Tilith, sang Summoner memasuki Gurun Kagan. Pertemuan tak terduga dengan Karl mengungkap bahwa ia sedang memburu iblis Graham.","storylog.scenario.10009.title":"Bertemu Lagi dengan Karl","storylog.scenario.10010.description":"Di Pantai Semilir, Tilith mendengar soal pendekar pedang wanita yang cantik tapi dingin. Namun, ia yakin dirinya jauh lebih cantik daripada si wanita yang dirumorkan itu.","storylog.scenario.10010.title":"Pendekar Pedang Jelita","storylog.scenario.10011.description":"Karl terluka saat mengejar Graham. Hutan Malam konon adalah wilayah salah satu bawahan Graham yang menyerang banyak Summoner.","storylog.scenario.10011.title":"Bawahan Graham","storylog.scenario.10012.description":"Karl berhasil mengusir Graham dari Hutan Malam. Tanpa tempat untuk lari, saatnya menuntaskan semuanya di Tanah Tandus Asekutt.","storylog.scenario.10012.title":"Pengejaran Karl","storylog.scenario.10013.description":"Seria, anggota Pembasmi Iblis, menampakkan diri di Kuil Lystia. Menurutnya, Graham adalah salah satu anak buah kesayangan Abaddon.","storylog.scenario.10013.title":"Abaddon & Graham","storylog.scenario.10014.description":"Seria bersikap bermusuhan pada sang Summoner. Meski Karl ingin melanjutkan ke Katedral Hancur bertiga, Seria tidak mempermudah keadaan...","storylog.scenario.10014.title":"Penolakan","storylog.scenario.10015.description":"Setelah akhirnya mencapai benteng Abaddon di Menara Morgan, Karl dan Seria menghalau musuh yang datang agar sang Summoner bisa terus maju.","storylog.scenario.10015.title":"Demi Kawan-kawanku","storylog.scenario.10016.description":"Abaddon telah dikalahkan. Setelah bertemu Karl dan kembali berpisah, Tilith dan sang Summoner menuju St. Lamia untuk mencari Maxwell.","storylog.scenario.10016.title":"Menuju Markas Musuh","storylog.scenario.10017.description":"Di Gunung Api Eldent, Tilith menegaskan bahwa melalaikan tugas tidak bisa dimaafkan. Katanya ia tidak pernah bermalas-malasan dalam pekerjaannya, tapi...","storylog.scenario.10017.title":"Jangan Bermalas-malasan!","storylog.scenario.10018.description":"Meski Tilith mencoba menjelaskan latar belakang Gunung Suci Craylia, ia tampak kurang sehat. Katanya ia sedang masuk angin...","storylog.scenario.10018.title":"Pertanda Buruk","storylog.scenario.10019.description":"Tilith berusaha keras berpura-pura kondisinya tidak memburuk saat di Hutan Darah. Tapi jelas sekali hal itu membebaninya...","storylog.scenario.10019.title":"Pura-pura Kuat","storylog.scenario.10020.description":"Tilith akhirnya mengaku soal kondisi tubuhnya yang buruk di Gunung Wistorea. Kutukan Maxwell makin memengaruhinya saat ia mendekati Istana St. Lamia.","storylog.scenario.10020.title":"Kutukan","storylog.scenario.10021.description":"Di Suaka Terpencil, Tilith akhirnya tumbang. Menitipkannya pada Seria, sang Summoner menuju Istana St. Lamia seorang diri untuk mematahkan kutukan.","storylog.scenario.10021.title":"Sebuah Janji","storylog.scenario.10022.description":"Setelah diselamatkan Karl, sang Summoner mengejar Maxwell di Istana St. Lamia. Bisakah Tilith benar-benar diselamatkan dari kutukan mengerikan ini?!","storylog.scenario.10022.title":"Sesuatu untuk Dilindungi","storylog.scenario.10023.description":"Setelah kutukan terpatahkan, Tilith kembali seperti biasa, tapi entah kenapa malah terlibat adu mulut dramatis dengan Seria...","storylog.scenario.10023.title":"Jatuhnya Sang Pencipta","storylog.scenario.10100.description":"Begitu Eriole tahu Balai Summoner Akras telah membuka wilayah selatan Mistral, ia mengirim Paris ke Cordelica...","storylog.scenario.10100.title":"Rencana Dimulai","storylog.scenario.10101.description":"Pertemuan dengan Pembasmi Iblis Lugina terjadi di Gua Greskya. Karena tidak menghormati Pasukan Reguler, ia menuntut sang Summoner pergi.","storylog.scenario.10101.title":"Pembasmi Iblis Lugina","storylog.scenario.10102.description":"Di Air Terjun Ignia, Lugina menjelaskan bagaimana Kekaisaran Randall dan Balai Summoner Akras memengaruhi kehidupan di Elgaia.","storylog.scenario.10102.title":"Urusan Elgaia","storylog.scenario.10103.description":"Di Hutan Lomass, Lugina menjelaskan cara kerja Pasukan Summoner. Sebagai elite, ia menuntut sang Summoner menghormati wewenangnya.","storylog.scenario.10103.title":"Pasukan Summoner","storylog.scenario.10104.description":"Paris menampakkan diri di Benteng Valtan. Ia meminta kerja sama sang Summoner dalam survei wilayah Cordelica, tapi...","storylog.scenario.10104.title":"Permintaan Paris","storylog.scenario.10105.description":"Dalam perjalanan ke Menara Cahaya, Paris menyebut bahwa sang Summoner adalah teman Karl, tapi Lugina tidak percaya. Ia tampaknya tidak suka pada Karl.","storylog.scenario.10105.title":"Dasar Sombong!","storylog.scenario.10106.description":"Di Tambang Cordelica, Paris menjelaskan bahwa ras raksasa pernah mendiami pulau ini dahulu kala. Tampaknya dewa para raksasa juga telah bangkit.","storylog.scenario.10106.title":"Dewa Raksasa","storylog.scenario.10107.description":"Sementara Lugina menjalankan misi mengalahkan dewa raksasa Grantos di Reruntuhan Raksasa, Paris meminta sang Summoner menunjukkan kekuatan yang sesungguhnya.","storylog.scenario.10107.title":"Lugina yang Bersemangat","storylog.scenario.10108.description":"Setelah mengetahui sang Summoner mengalahkan Grantos, Eriole tertawa sambil menyatakan bahwa dunia sedang menuju arah yang benar...","storylog.scenario.10108.title":"Motif Eriole","storylog.scenario.10200.description":"Lucius memandu sang Summoner ke Kepulauan Palmyna, sementara seorang pria di Randall diberi tahu bahwa penghalang di atas kepulauan itu telah lenyap.","storylog.scenario.10200.title":"Pengawas Ksatria","storylog.scenario.10201.description":"Target berikutnya adalah Cardes Sang Keji, satu lagi dari Empat Dewa yang Jatuh. Di Desa Julep kamu mendengar bahwa separuh kekuatannya masih tersegel.","storylog.scenario.10201.title":"Cardes Sang Keji","storylog.scenario.10202.description":"Tilith mengaku tidak takut di atas Kapal Hantu Legnia. Namun, ia memberi sedikit informasi tentang Palmyna, tempat Cardes disegel...","storylog.scenario.10202.title":"Jalan Menuju Palmyna","storylog.scenario.10203.description":"Sang Summoner tiba-tiba diserang seorang pria aneh di Dataran Elios. Namun, kehadiran pria misterius itu lenyap secepat ia muncul.","storylog.scenario.10203.title":"Seorang Pria Misterius","storylog.scenario.10204.description":"Pertemuan dengan Seria dan Karl di Tambang Saji mengungkap bahwa mereka masih memburu Graham. Karl memperingatkan sang Summoner tentang seseorang bernama Zebra.","storylog.scenario.10204.title":"Namanya Zebra","storylog.scenario.10205.description":"Tilith dan Summoner-nya bertemu \\"Elder Grah\\" di Kuil Lamellia. Pria tua itu mengaku sedang menyelidiki cerita rakyat tentang Empat Dewa yang Jatuh.","storylog.scenario.10205.title":"Tetua Misterius","storylog.scenario.10206.description":"Karl dan Seria menyudutkan Graham di Kota Hantu Edila, tapi mereka terpental oleh kekuatan dahsyat tak dikenal, sehingga Graham berhasil kabur.","storylog.scenario.10206.title":"Kekuatan Tak Dikenal","storylog.scenario.10207.description":"Muncul di Kastel Amdahl, Elder Grah bercerita tentang arwah pendendam kaisar terakhir Amdahl, yang konon masih bergentayangan di kastel itu.","storylog.scenario.10207.title":"Kaisar Terakhir Amdahl","storylog.scenario.10208.description":"Elder Grah terkesan dengan kemampuan sang Summoner mengalahkan roh jahat itu. Seria bergegas datang, dan tampaknya ia entah bagaimana mengenal sang tetua.","storylog.scenario.10208.title":"Seria & Elder Grah","storylog.scenario.10209.description":"Dipandu Lucius, sang Summoner tiba di Encervis. Menurut Tilith, perang saudara antarmanusia pernah meluluhlantakkan negeri ini dahulu kala.","storylog.scenario.10209.title":"Reruntuhan Masa Lalu","storylog.scenario.10210.description":"Setelah tiba di Kawah Elsta, Tilith bercerita betapa kerasnya ia bekerja selama ini. Namun, entah kenapa klaimnya terdengar meragukan...","storylog.scenario.10210.title":"Tilith si Pekerja Keras","storylog.scenario.10211.description":"Zebra tiba-tiba menyerang di Danau Aldela, tapi bantuan Elder Grah mencegah kerusakan serius. Musuh kuat ini tampaknya tinggal di sebuah benteng terapung.","storylog.scenario.10211.title":"Benteng Langit Pulih","storylog.scenario.10212.description":"Elder Grah menceritakan sejarah Amdahl sambil merenungkan Kastel Avenia. Ia meminta sang Summoner menghancurkan benteng langit, tapi Tilith tampak acuh tak acuh...","storylog.scenario.10212.title":"Sejarah Amdahl","storylog.scenario.10213.description":"Zebra dan Sosok Gelap ditemukan di Jurang Gadillian sedang membicarakan cara menghadapi sang Summoner. Apa sebenarnya hubungan mereka...?","storylog.scenario.10213.title":"Zebra & Sosok Gelap","storylog.scenario.10214.description":"Seria dan Karl mencari sang Summoner di Makam Alman. Keduanya ingin memakai kekuatan mereka untuk membantu menjatuhkan benteng langit.","storylog.scenario.10214.title":"Dukungan yang Menenangkan","storylog.scenario.10215.description":"Di Negeri Orang Mati, Tilith mengungkap bahwa nama resmi benteng langit itu adalah Solaris. Ia berniat memakai kekuatannya untuk membantu menyusup ke sana.","storylog.scenario.10215.title":"Menembus Benteng","storylog.scenario.10216.description":"Berkat kekuatan Tilith, penyusupan ke Benteng Langit Solaris berhasil. Zebra melihat ini sebagai celah untuk menyerang sang dewi yang kelelahan.","storylog.scenario.10216.title":"Zebra vs. Tilith","storylog.scenario.10217.description":"Zebra akhirnya dikalahkan. Namun, ia menghancurkan Solaris demi menyeret sang Summoner bersamanya. Siapa yang bisa mencegah tragedi ini...?","storylog.scenario.10217.title":"Zebra & Grahdens","storylog.scenario.10218.description":"Sang Summoner tiba di Palmyna berkat bimbingan Lucius. Jejak kerajaan yang pernah melawan para dewa masih sangat terlihat di sini.","storylog.scenario.10218.title":"Medan Pertempuran","storylog.scenario.10219.description":"Meski awalnya berada di Kastel Obselion, Tilith bergegas ke Reruntuhan Dejour untuk memperingatkan bahwa segel Cardes mulai melemah.","storylog.scenario.10219.title":"Segel yang Terurai","storylog.scenario.10220.description":"Grahdens ditinggal berdua dengan sang Summoner di Kastel Obselion. Ia menceritakan kisah 4 Pahlawan Palmyna yang menyegel Cardes Sang Keji.","storylog.scenario.10220.title":"4 Pahlawan Palmyna","storylog.scenario.10221.description":"Di Jalan Zamrud, Seria dan Karl mengetahui bahwa mereka harus pergi ke dunia roh untuk mengalahkan Cardes. Tapi Seria bertingkah agak aneh...","storylog.scenario.10221.title":"Seria yang Aneh","storylog.scenario.10222.description":"Saat melewati Reruntuhan Grandelt, Tilith mengungkap bahwa tubuh Cardes perlahan hancur, dan kekuatan dewanya mengamuk tak terkendali.","storylog.scenario.10222.title":"Amukan Para Dewa","storylog.scenario.10223.description":"Di Seminari Arlind, Grahdens mengungkapkan keraguannya tentang tindakan para dewa di masa lalu dan baru-baru ini. Pikirannya tampak memengaruhi sang Summoner.","storylog.scenario.10223.title":"Keraguan Grahdens","storylog.scenario.10224.description":"Karl dan Seria menemani sang Summoner ke gerbang dunia bawah di Medan Perang Noera. Keduanya mengkhawatirkan Tilith.","storylog.scenario.10224.title":"Pintu Masuk Hades","storylog.scenario.10225.description":"Sang Summoner dan yang lainnya berpencar untuk mencari Cardes di Dunia Roh Palmyna. Bisakah ia dikalahkan sebelum menghancurkan segalanya?","storylog.scenario.10225.title":"Melawan Cardes","storylog.scenario.10226.description":"Saat semua orang berusaha kabur dari dunia bawah yang mulai runtuh, Seria terluka. Dalam situasi genting ini, Tilith muncul menyelamatkan keadaan.","storylog.scenario.10226.title":"Sang Dewi Terlahir Kembali","storylog.scenario.10300.description":"Setelah mendengar laporan Paris, Eriole mengirimnya ke Lizeria. Apa sebenarnya yang ia cari?","storylog.scenario.10300.title":"Pencarian","storylog.scenario.10301.description":"Lugina muncul di Dataran Erinecht dan mengaku punya misi yang jauh lebih penting daripada misi sang Summoner. Sikapnya yang galak tidak berubah.","storylog.scenario.10301.title":"Misi Lugina","storylog.scenario.10302.description":"Setibanya di Pegunungan Golzo, terungkap bahwa Paris sedang mencari kekuatan yang terpendam di Lizeria. Dan tampaknya Lugina mengincar hal yang sama.","storylog.scenario.10302.title":"Satu Ambisi untuk Berdua","storylog.scenario.10303.description":"Di Danau Beku Lodan, Lugina salah mengira bahwa Paris telah membuat sang Summoner berkhianat. Semuanya diluruskan, tapi Lugina bersikeras memberi latihan...","storylog.scenario.10303.title":"Latihan Lugina","storylog.scenario.10304.description":"Di Rawa yang Tak Tertembus, Paris membicarakan struktur sosial Elgaia. Tampaknya ia tidak memercayai kekuasaan Balai Summoner.","storylog.scenario.10304.title":"Sisi Gelap Balai","storylog.scenario.10305.description":"Di Hutan Petir Zaljiba, Paris menyinggung sisi gelap Balai Summoner. Lugina lalu ditanya soal itu, dan ia menjawab sesuai pendiriannya.","storylog.scenario.10305.title":"Motivasi Lugina","storylog.scenario.10306.description":"Di Kota Hilang La Veda, Paris mengungkapkan keraguannya terhadap para dewa dan membicarakan ketidakstabilan dunia. Ia ingin bertindak dengan tangannya sendiri.","storylog.scenario.10306.title":"Motivasi Paris","storylog.scenario.10307.description":"Di atas Jembatan Hitam, Lugina berkata ia akan menghancurkan siapa pun yang menghalanginya, dan menyampaikan satu pengakuan terakhir kepada sang Summoner sebelum melangkah maju.","storylog.scenario.10307.title":"Peringatan Terakhir","storylog.scenario.10308.description":"Meski kalah dari sang Summoner, Lugina bersikeras bahwa ia tak mungkin gagal, dan terus menyangkal kekalahannya.","storylog.scenario.10308.title":"Kekalahan Lugina","storylog.scenario.10309.description":"Di Menara Kehancuran, Paris yang terluka tetap menolak menyerah atas kekuatan terpendam di wilayah itu. Ia tak akan memaafkan campur tangan sang Summoner.","storylog.scenario.10309.title":"Tekad Paris","storylog.scenario.10310.description":"Sebuah sistem pertahanan yang mampu menghancurkan para Summoner. Namun, apa pun yang dicari Paris, yang seharusnya sudah dekat, tidak terlihat di mana pun...","storylog.scenario.10310.title":"Kekuatan Penghancur","storylog.scenario.10400.description":"Tilith dan sang Summoner berangkat untuk mengalahkan Zevalhua yang Agung. Tanpa mereka ketahui, Eriole dan Paris juga sedang menuju Agni...","storylog.scenario.10400.title":"Dua Perjalanan","storylog.scenario.10401.description":"Di Lembah Glomore, Karl dan Seria menyatakan ingin membantu mengalahkan Zevalhua, sementara seorang wanita misterius mengamati dengan sinis dari kejauhan.","storylog.scenario.10401.title":"Rekan Seperjuangan","storylog.scenario.10402.description":"Setibanya di Area Salju Khelne, Murid Mare tiba-tiba muncul dan meminta Karl menemuinya sendirian di Reruntuhan Azura untuk mengungkapkan sebuah rahasia.","storylog.scenario.10402.title":"Masa Lalu Karl","storylog.scenario.10403.description":"Seria mencemaskan Karl saat berkelana di Hutan Stokhelna, ketika Mare muncul lagi dan berkata bahwa Karl telah masuk ke dalam perangkapnya...","storylog.scenario.10403.title":"Murid Mare","storylog.scenario.10404.description":"Seria jatuh ke dalam jebakan Mare di Reruntuhan Azura dan terluka. Tilith menyerahkan penyelamatan Karl kepada sang Summoner sementara ia merawat Seria.","storylog.scenario.10404.title":"Seria Terjebak","storylog.scenario.10405.description":"Grahdens menunggu sang Summoner di Pegunungan Ryvern dan berbagi kenangannya tentang Karl. Ia berkata akan membiarkan dirinya ditangkap Mare demi membebaskan Karl.","storylog.scenario.10405.title":"Grahdens & Karl","storylog.scenario.10406.description":"Mare menampakkan diri di hadapan sang Summoner yang sendirian di Gua Jurang. Tepat saat ia bersiap menyerang, Tilith kembali dan mencegahnya.","storylog.scenario.10406.title":"Tilith Diam-diam","storylog.scenario.10407.description":"Mare melepaskan Granvalm untuk menyerang sang Summoner di Menara Putih, lalu kabur. Namun, Tilith tidak akan membiarkannya lolos begitu saja.","storylog.scenario.10407.title":"Granvalm Sang Putih","storylog.scenario.10408.description":"Mare muncul sekali lagi setelah Granvalm dikalahkan, dan di tengah situasi genting ini, seorang sekutu tak terduga menyelamatkan semua orang...","storylog.scenario.10408.title":"Penolong Tak Terduga","storylog.scenario.10409.description":"Lugina menyelamatkan sang Summoner di Ryvern untuk memenuhi permintaan Grahdens. Ia juga bersikeras bahwa ia diminta membantu menyelamatkan Karl.","storylog.scenario.10409.title":"Berterima Kasihlah","storylog.scenario.10410.description":"Di Kekaisaran Agni, Lugina sangat bersemangat dengan misi penyelamatan ini. Katanya ini kesempatan sempurna untuk menyelesaikan misinya sekaligus mengejek Karl.","storylog.scenario.10410.title":"Usaha Terbaik Lugina","storylog.scenario.10411.description":"Bosan menunggu Mare muncul, Lugina meninggalkan sang Summoner di Pesisir Agniria dan pergi mencari Karl sendirian...","storylog.scenario.10411.title":"Bergerak Lagi","storylog.scenario.10412.description":"Mare akhirnya menampakkan diri di Dataran Tinggi Granasta. Tapi ia tidak mau bertarung. Sebaliknya, ia meminta sang Summoner mengikutinya untuk menyelamatkan Karl.","storylog.scenario.10412.title":"Mare Sang Penipu","storylog.scenario.10413.description":"Mare teringat pada seseorang yang bertarung dalam perang melawan para dewa, sementara sang Summoner yang gelisah mengejarnya ke Puncak Petir Navara.","storylog.scenario.10413.title":"Kenangan Mare","storylog.scenario.10414.description":"Sang Summoner maju ke Makam Raja tanpa kehilangan harapan untuk menyelamatkan Karl. Mare tak bisa memahami kegigihan itu, hingga akhirnya ia menyerang.","storylog.scenario.10414.title":"Kekuatan yang Berlawanan","storylog.scenario.10415.description":"Tepat saat Mare hendak memberikan pukulan terakhir di Teluk Lognea, Seria, yang seharusnya terluka parah, datang menyelamatkan sang Summoner.","storylog.scenario.10415.title":"Serangan Balik","storylog.scenario.10416.description":"Segerombolan musuh muncul di Kuil Samudra Albina, membuat Seria dan sang Summoner terdesak. Namun, Lugina datang tepat waktu bersama Karl yang sudah bebas.","storylog.scenario.10416.title":"Penyelamatan","storylog.scenario.10417.description":"Mare akhirnya dikalahkan oleh sang Summoner, tapi tiba-tiba Paris muncul dan melaporkan bahwa Grahdens telah ditawan.","storylog.scenario.10417.title":"Grahdens Ditawan","storylog.scenario.10418.description":"Sang Summoner akhirnya menginjakkan kaki di Mirvana. Tilith menjelaskan bahwa tempat ini adalah lokasi pertempuran paling berdarah dalam perang besar melawan para dewa.","storylog.scenario.10418.title":"Medan Perang Kuno","storylog.scenario.10419.description":"Grahdens telah ditangkap oleh Zevalhua yang Agung. Untuk menyelamatkannya, sang Summoner dan yang lain berpencar menjadi beberapa kelompok di Gua Kegelapan.","storylog.scenario.10419.title":"Tim Pencari Berkumpul","storylog.scenario.10420.description":"Di Padang Salju Arvest, Paris curiga mengapa para dewa menawan Grahdens alih-alih langsung membunuhnya...","storylog.scenario.10420.title":"Tindakan Mencurigakan","storylog.scenario.10421.description":"Saat mencari Grahdens di Lautan Pohon Marleg, Paris kembali mengajak sang Summoner bergabung dengan perjuangannya. Tapi Tilith akhirnya menyela.","storylog.scenario.10421.title":"Summoner Siapa?","storylog.scenario.10422.description":"Lugina memarahi Paris di Rawa Hujan Abadi. Namun, sebelum keadaan memburuk, Seria ikut nimbrung dan malah bertengkar dengan Lugina.","storylog.scenario.10422.title":"Lugina & Seria","storylog.scenario.10423.description":"Lokasi Grahdens dipastikan setelah tiba di Tanjung Narasta, dan Paris mempertanyakan mengapa Lucius tidak mengalahkan sendiri Empat Dewa yang Jatuh.","storylog.scenario.10423.title":"Keraguan Paris","storylog.scenario.10424.description":"Karl berterima kasih pada Tilith saat ia mengungkap informasi lebih lanjut tentang Grahdens di Reruntuhan Mirvana. Sementara itu, Lugina dan Seria terus bertengkar seperti biasa.","storylog.scenario.10424.title":"Tak Pernah Berubah","storylog.scenario.10425.description":"Seluruh kelompok akhirnya tiba di Menara Para Dewa. Mampukah mereka mencapai tujuan mengalahkan Zevalhua yang Agung untuk menyelamatkan Grahdens?","storylog.scenario.10425.title":"Zevalhua yang Agung","storylog.scenario.10426.description":"Grahdens menampakkan diri dan mengungkap rahasia kelahiran Karl. Pada saat yang sama, Eriole tiba-tiba muncul dan menyela untuk berbicara dengan sang tetua.","storylog.scenario.10426.title":"Rahasia Kelahiran","storylog.scenario.20000.description":"Lin dari Biro Kantor Survei meminta sang Summoner menyelidiki Pegunungan Egor. Konon iblis es tertidur di sana.","storylog.scenario.20000.title":"Iblis Gunung","storylog.scenario.20001.description":"Lin membahas masa lalu Skramya. Legenda menyebutkan iblis itu disegel oleh seorang pahlawan setelah mencoba menghancurkan negeri yang ingin mengendalikannya.","storylog.scenario.20001.title":"Masa Lalu Sang Iblis","storylog.scenario.20002.description":"Lin meminta sang Summoner menyurvei Gua Ignia. Tampaknya seekor iblis telah terbangun di sana setelah gempa bumi di Cordelica...","storylog.scenario.20002.title":"Lengket & Berlendir","storylog.scenario.20003.description":"Sang Summoner mengalahkan iblis raksasa yang tak terkendali. Lin memuji sang Summoner, tapi tiba-tiba sikapnya berubah total...","storylog.scenario.20003.title":"Yang Tak Disukai Lin","storylog.scenario.20004.description":"Lin menyampaikan informasi kepada sang Summoner bahwa Sarang Valmodora menyimpan seekor iblis. Ia berharap sang Summoner mengumpulkan detail lebih lanjut.","storylog.scenario.20004.title":"Iblis Raksasa","storylog.scenario.20005.description":"Sang Summoner mengalahkan Valmodora saat menyurvei lokasi itu. Tampaknya reruntuhan itu memang menyimpan sesuatu yang raksasa.","storylog.scenario.20005.title":"Reruntuhan Misterius","storylog.scenario.20006.description":"Sang Summoner bisa merasakan kekuatan dahsyat yang memancar dari dasar Danau Bawah Tanah Golzo. Lin punya firasat buruk, tapi tetap meminta penyelidikan.","storylog.scenario.20006.title":"Firasat Buruk Lin","storylog.scenario.20007.description":"Lagzal, yang tertidur di bawah tanah, adalah dewa yang ingin menghancurkan manusia. Tampaknya Lin sangat mencemaskan sang Summoner selama ekspedisi itu.","storylog.scenario.20007.title":"Dewa Jatuh Lagzal","storylog.scenario.20008.description":"Saat melewati Dungeon Agni, Lin meminta sang Summoner menaklukkan \\"makhluk jahat\\" tertentu yang terkurung di dalamnya.","storylog.scenario.20008.title":"Tersembunyi di Dungeon","storylog.scenario.20009.description":"Menurut Lin, yang terkurung di dalamnya adalah hantu seorang tiran yang ditakuti, yang disegel oleh para pengikutnya sendiri.","storylog.scenario.20009.title":"Akhir Sang Tiran"}')}]);